window.__SUPERCODE_LANG_PACKS__['cs'] = {"index":{"metaTitle":"Editor kódu: SuperCode IDE — Offline IDE pro Python, C, C++, Java, JS, SQL a PHP na Android","metaDesc":"Nativní offline editor kódu a full-stack mobilní IDE pro Android. Upravujte GB soubory, spouštějte Python, C17, C++20, Java 17, JavaScript, Lua, Shell, SQL i lokální weby PHP/WASM s vizuálním Git a SFTP.","hero_tag":"Nativní offline editor kódu &amp; full-stack IDE","hero_h1":"Nativní <span class=\"text-gradient\">editor kódu</span> &amp; full-stack IDE pro Android.","hero_desc":"Navrženo pro softwarové inženýry, studenty informatiky a DevOps týmy na Android. Využijte <strong>chytré doplňování podle AST</strong>, <strong>streamování GB souborů</strong>, offline spouštění pro <strong>Python, C17, C++20, Java 17, JS, SQL, PHP, Lua &amp; Shell</strong> a navíc vizuální <strong>Git</strong> a <strong>SFTP/FTPS</strong>.","table_h2":"Srovnání SuperCode na Android","snippet_p":"<strong>SuperCode IDE</strong> je nativní offline editor kódu a full-stack vývojové prostředí pro Android. Integruje doplňování kódu podle AST, stránkování GB souborů, 30+ formátovačů, offline kompilátory a běhová prostředí pro Python, C17, C++20, Java 17, JavaScript, SQL, PHP, HTML/CSS/WASM, Lua a Shell plus vizuální Git a SFTP/FTPS.","table_caption":"SROVNÁVACÍ MATICE MOBILNÍCH VÝVOJOVÝCH PROSTŘEDÍ PRO ANDROID","faq_lead":"Přímé odpovědi k offline kompilátorům, práci s velkými soubory, podporovaným jazykům a workflow Git/SFTP.","cta_h2":"Jedna nativní aplikace. Čtrnáct inženýrských pracovních prostorů v kapse.","cta_desc":"Stáhněte si SuperCode IDE z Google Play nebo spusťte 13krokového interaktivního průvodce přímo na svém zařízení Android.","th_0":"Funkce","th_1":"SuperCode IDE","th_2":"Cloudová IDE v prohlížeči","th_3":"Jednojazykové aplikace","th_4":"Základní textové editory","tr1_c0":"Offline jazyky","tr1_c1":"Python, C17, C++20, Java 17, JS, SQL, PHP, Web/WASM, Lua &amp; Shell","tr1_c2":"Vyžaduje stálý internet","tr1_c3":"1 jazyk na aplikaci","tr1_c4":"Žádné","tr2_c0":"Inteligence editoru","tr2_c1":"AST doplňování + duální zvýraznění + 30+ formátovačů + Radar chyb","tr2_c2":"Závislé na latenci sítě","tr2_c3":"Základní obarvení syntaxe","tr2_c4":"Prostý text / regex zvýraznění","tr3_c0":"Velké soubory &amp; nahrazení","tr3_c1":"10MB stránkování v měřítku GB + globální streamovací regex nahrazení + 34 kódování","tr3_c2":"Pád paměti karty prohlížeče","tr3_c3":"Selže nad několik MB","tr3_c4":"Zamrzá u velkých logů","tr4_c0":"Web &amp; databázové studio","tr4_c1":"Reálné HTTP + offline PHP + PDO SQLite + DevTools REPL + prohlížeč .db","tr4_c2":"Vyžaduje placený kontejner","tr4_c3":"Nutné samostatné aplikace","tr4_c4":"Pouze statický náhled HTML","tr5_c0":"Git &amp; vzdálený DevOps","tr5_c1":"Vizuální Git Time Machine + Merge UI + SFTP/FTPS AES-256 atomické uložení","tr5_c2":"Pouze cloudový workspace","tr5_c3":"Bez vestavěného Git a SFTP","tr5_c4":"Nutní externí klienti","faq1_q":"Které programovací jazyky běží v SuperCode IDE na Android offline?","faq1_a":"SuperCode spouští lokálně na Android jazyky Python (3.11 &amp; vědecký 3.12), C (GNU C17), C++ (GNU C++20), Java 17, JavaScript (ES2024), SQL, PHP, HTML5/CSS3/WebAssembly, Lua 5.4 a linuxové skripty Shell, s volitelnou cloudovou podporou pro Kotlin, MySQL 8.0 a náročné serverové frameworky.","faq2_q":"Dokáže SuperCode otevřít gigabajtové logy a SQL dumpy bez zamrznutí?","faq2_a":"Ano. Soubory větší než 30 MB automaticky aktivují streamovací pager v měřítku GB, který dělí soubory o stovkách MB či GB na diskové bloky po 10M znacích s okamžitým skokem na stránku, detekcí 34 znakových sad a globálním streamovacím regex nahrazením.","faq3_q":"Mají C a C++, případně SQL a Web/PHP, vlastní oddělená prostředí?","faq3_a":"Ano. C17 a C++20 mají vlastní standardy, hlavičky a šablony; SQL má vlastní 9režimovou konzoli a binární inspektor .db; a Web Studio provozuje reálný lokální náhledový server HTTP + PHP + PDO SQLite + WebAssembly s vestavěnými DevTools.","faq4_q":"Obsahuje SuperCode vestavěného klienta Git a vzdálený editor SFTP/FTPS?","faq4_a":"Ano. Obsahuje samostatného vizuálního klienta Git (klonování s PAT, větvení, unifikované diffy v Commit Time Machine a řešení konfliktů sloučení) plus pracovní prostor SFTP, FTPS (TLS 1.3) a FTP šifrovaný pomocí AES-256 s 3fázovým atomickým vzdáleným ukládáním.","faq5_q":"Je SuperCode optimalizovaný pro telefony i tablety Android?","faq5_a":"Ano. Na telefonech jsou lišty v dosahu palce s výsuvným menu od pravého okraje a automaticky skrývanou dělenou konzolí; na skládacích zařízeních a tabletech se lišta ukotví svisle a terminál se otevře v rozdělené pracovní ploše 55 % / 45 %.","wb_eyebrow":"Phoenix Global Studios · 14 specializovaných inženýrských modulů","sec1_eyebrow":"13 SPECIALIZOVANÝCH INŽENÝRSKÝCH PROSTORŮ","sec1_title":"Každý jazyk, databáze &amp; vzdálený nástroj — vyhrazené &amp; nativní","sec1_lead":"Prozkoumejte všech 13 účelových modulů v jedné lehké 40,2 MB aplikaci pro Android.","bc1_title":"Chytrý editor kódu, AST doplňování &amp; Radar chyb","bc1_desc":"Kontextové doplňování na ., -&gt;, :: a :, duální zvýraznění syntaxe, 30+ offline formátovačů, živý skok na řádek z Radaru chyb, holografické statistiky, export do A4 PDF a 29 adaptivních akcí lišty.","bc1_foot":"AST doplňování · 30+ formátovačů · 8 motivů","bc2_title":"Prohlížeč GB souborů &amp; globální streamovací nahrazení","bc2_desc":"Otevírejte logy či SQL dumpy o stovkách MB a GB okamžitě při 120 Hz přes 10MB diskové stránkování, spouštějte globální streamovací regex nahrazení a dekódujte bezeztrátově 34 znakových sad.","bc2_foot":"GB pager · Streamovací nahrazení · 34 kódování","bc3_title":"Vyhrazený offline kompilátor C17","bc3_desc":"Čistý standardní toolchain GNU C17 s &lt;math.h&gt;, vícesouborové linkování .c/.h bez konfigurace, šablony ukazatelů/struktur a interaktivní živý vstup scanf/fgets stdin.","bc3_foot":"GNU C17 · Vícesouborové .c/.h · Živý stdin","bc4_title":"Python 3.11 / 3.12 IDE &amp; vizuální správce PIP","bc4_desc":"Spouštějte vícesouborové projekty Python offline, automaticky instalujte balíčky z PyPI, requirements.txt nebo lokálních archivů .whl a generujte grafy NumPy/Pandas/Matplotlib přímo do své složky.","bc4_foot":"Python 3.11/3.12 · Auto-PIP · Data Science","bc5_title":"Moderní kompilátor C++20 &amp; soutěžní STL IDE","bc5_desc":"Kompilujte vícesouborové C++20 STL, šablony, chytré ukazatele a soutěžní algoritmy offline s přírůstkovým hash cachováním a konzolí std::cin na rozdělené obrazovce.","bc5_foot":"C++20 · STL kontejnery · Dělená konzole","bc6_title":"Offline Java 17 IDE, vícetřídní OOP &amp; JDBC","bc6_desc":"Sestavujte Java 17 records, sealed classes, streamy a vícepříbalové OOP projekty offline s 0ms cache bajtkódu, vestavěným ovladačem SQLite JDBC a podporou vlastních .jar.","bc6_foot":"Java 17 · Okamžitá cache · Vestavěné JDBC","bc7_title":"Samostatný JavaScript (ES2024) &amp; spouštěč modulů","bc7_desc":"Spouštějte ES2024 async/await, ESM import/export a moduly CommonJS v izolovaném worker vláknu mimo UI s &lt;1ms ochranou proti nekonečné smyčce a cloudovým bundlováním Node.js.","bc7_foot":"ES2024 · ESM + CommonJS · Worker Sandbox","bc8_title":"Full-stack Web, lokální PHP &amp; živé studio WASM","bc8_desc":"Reálný lokální HTTP náhledový server podporující HTML5, CSS3, ES moduly, WebAssembly (.wasm), offline PHP + databáze PDO SQLite, viewporty Mobil/Tablet/Desktop, DevTools JS REPL a živý náhled přes SFTP.","bc8_foot":"HTML/CSS/JS · WASM · Offline PHP · DevTools","bc9_title":"Offline SQL IDE &amp; vizuální prohlížeč databází","bc9_desc":"Spouštějte moderní SQL s okenními funkcemi, CTE, JSONB cestami a fulltextovým hledáním v 9 výstupních režimech, kontrolujte soubory .db/.sqlite jedním klepnutím, importujte CSV/JSON nebo spouštějte cloudové MySQL 8.0.","bc9_foot":"Offline SQL · Inspektor .db · CSV / JSON","bc10_title":"Offline Lua 5.4 skriptování &amp; IDE herní logiky","bc10_desc":"Submilisekundové nativní spouštění Lua 5.4.7 s korutinami, metatabulkami, bitovými operacemi, vícesouborovým require() a interaktivní konzolí io.read().","bc10_foot":"Lua 5.4.7 · Korutiny · Více souborů","bc11_title":"Spouštěč Linux Shell (.sh) &amp; Kotlin Studio","bc11_desc":"Spouštějte nativní linuxové shellové pipeline na Android (grep, awk, sed, sort, find) synchronizované se složkou projektu, plus cloudové Ubuntu Bash 5.2 a kompilaci Kotlin.","bc11_foot":"Nativní Shell · Bash 5.2 · Kotlin","bc12_title":"Vizuální klient Git, Time Machine &amp; řešení konfliktů","bc12_desc":"Klonujte HTTPS repozitáře s PAT tokeny, automaticky ukládejte stash při Pull, kontrolujte barevné unifikované diffy napříč 120 commity, přepínejte větve a řešte konflikty sloučení vedle sebe.","bc12_foot":"Git Clone · Time Machine Diff · Merge UI","bc13_title":"Vzdálený pracovní prostor SFTP, FTPS (TLS 1.3) &amp; FTP","bc13_desc":"Připojte se heslem nebo soukromými klíči OpenSSH/PEM/Ed25519 v trezoru AES-256 v Android KeyStore. Upravujte vzdálené karty serveru s 3fázovým atomickým uložením (nulové poškození 0 bajtů) a spouštějte 4proudé fronty přenosů s navázáním na bajtový offset.","bc13_foot":"SFTP (22) · FTPS TLS 1.3 · SSH trezor klíčů · Atomické vzdálené uložení","sec2_eyebrow":"NAVRŽENO PRO RYCHLOST DOTYKU JEDNOU RUKOU","sec2_title":"Hmatová přesnost od nástrojové lišty po dělený terminál","sec2_lead":"Každé gesto, klávesa a panel se automaticky přizpůsobí telefonům, skládacím zařízením i tabletům na šířku.","keystrip_left":"21KLÁVESOVÁ DUÁLNÍ LIŠTA SYMBOLŮ (6 PROFILŮ)","keystrip_right":"KLEPNUTÍ · LUPA PŘI SWIPE NAHORU · ZÁMEK KURZORU","craft_foot":"8 optických studiových motivů + Auto Den/Noc · 32 jazyků UI · Dvoupanelová konzole na šířku","pil1_sub":"5 KONTEXTOVÝCH REŽIMŮ NÁSTROJOVÉ LIŠTY","pil1_title":"Adaptivní lišta, swipe z pravého okraje &amp; 5 rychlých slotů","pil1_desc":"Automaticky přepíná mezi režimy Kód, Prostý text, Výběr, Hledání a Mega-soubor, na tabletech se ukotví svisle a spolupracuje se 120Hz menu tažením od pravého okraje.","pil2_sub":"10MB STRÁNKOVÁNÍ · 34 ZNAKOVÝCH SAD","pil2_title":"Okamžitý pager velkých souborů &amp; streamovací regex nahrazení","pil2_desc":"Otevírejte obří serverové logy a databázové dumpy plynule při 120 Hz, spouštějte globální streamovací regex nahrazení přes diskové bloky a kopírujte až 15 MB přes virtuální schránku.","pil3_sub":"VIZUÁLNÍ DIFF · TREZOR AES-256","pil3_title":"Produkční správa verzí &amp; atomická vzdálená synchronizace","pil3_desc":"Přejděte plynule od lokální offline kompilace k vizuálnímu řešení Git konfliktů a 3fázovému atomickému nasazení na servery SFTP/FTPS."},"code_editor":{"metaTitle":"Editor kódu pro Android — AST automatické doplňování, 30+ formátovačů & Radar chyb | SuperCode","metaDesc":"Profesionální nativní editor kódu pro Android s offline chytrým doplňováním AST, duálním zvýrazněním syntaxe pro 40+ typů souborů, formátováním jedním klepnutím, Radarem chyb v reálném čase, holografickou statistikou slov/bajtů, 29nástrojovou adaptivní lištou a 8 studiovými motivy.","hero_tag":"CHYTRÝ EDITOR KÓDU &amp; INTELIGENCE AST","hero_h1":"Hmatově přesný <span class=\"text-gradient\">editor kódu s AST</span> nativně navržený pro Android.","hero_desc":"Překonejte holé mobilní textové boxy. SuperCode spojuje <strong>offline kontextové doplňování AST</strong>, <strong>duální zvýraznění syntaxe</strong>, <strong>30+ formátovačů jedním klepnutím</strong>, <strong>diagnostiku Radar chyb</strong> a <strong>29nástrojovou adaptivní lištu</strong> vyladěnou pro 120Hz dotyk.","table_h2":"SuperCode Editor vs. běžné mobilní textové editory","snippet_p":"<strong>SuperCode Code Editor</strong> je nativní editor zdrojového kódu pro Android, který kombinuje offline kontextové automatické doplňování AST, duální zvýraznění syntaxe pro 40+ typů souborů, offline formátování jedním klepnutím pro 30+ jazyků, diagnostiku Radar chyb v reálném čase, holografické statistiky UTF-8 a 29nástrojovou adaptivní dotykovou lištu.","table_caption":"SROVNÁNÍ SCHOPNOSTÍ EDITORŮ ZDROJOVÉHO KÓDU PRO ANDROID","faq_lead":"Odpovědi k offline formátování, jazykům automatického doplňování, úpravě lišty a nástrojům pro PDF/obrázky.","cta_h2":"Zažijte úpravu kódu na úrovni desktopu přímo na Android.","cta_desc":"Nainstalujte SuperCode z Google Play a přizpůsobte si 8 studiových motivů, 21klávesovou lištu symbolů a adaptivní nástrojovou lištu.","th_0":"Funkce editoru","th_1":"SuperCode Editor","th_2":"Editory v obálce WebView","th_3":"Základní textové aplikace pro Android","tr1_c0":"Chytré doplňování","tr1_c1":"Offline AST rozpoznání typů/členů (., -&gt;, ::, :)","tr1_c2":"Nutné pluginy nebo cloudový LSP","tr1_c3":"Žádné nebo jen základní seznam slov","tr2_c0":"Offline formátování kódu","tr2_c1":"30+ typů souborů + rekurzivní HTML/JS/CSS + kotva výběru","tr2_c2":"Omezeno na JS/HTML/CSS","tr2_c3":"Nepodporováno","tr3_c0":"Kontrola syntaxe chyb","tr3_c1":"Živý Radar chyb V2.0 se skokem na řádek/sloupec jedním klepnutím","tr3_c2":"Často hlučné nebo offline nedostupné","tr3_c3":"Žádná","tr4_c0":"Dotyková ergonomie","tr4_c1":"29nástrojová 5režimová lišta + 21klávesová swipe lupa + menu z pravého okraje","tr4_c2":"Statický přeplněný spodní pruh","tr4_c3":"Pouze systémová klávesnice","tr5_c0":"Schránka &amp; export","tr5_c1":"15 MB virtuální schránka + nativní A4 PDF + prohlížeč obrázků (10 formátů)","tr5_c2":"Pád schránky Android nad 800 KB","tr5_c3":"Pouze sdílení prostého textu","faq1_q":"Funguje chytré doplňování kódu a formátování 100% offline?","faq1_a":"Ano. Doplňování kódu podle AST, duální zvýraznění syntaxe, kontrola Radarem chyb v reálném čase i všech 30+ jazykových formátovačů běží zcela offline přímo ve vašem zařízení Android bez jakékoli závislosti na síti.","faq2_q":"Jak 21klávesová lišta symbolů zrychluje psaní kódu na telefonu?","faq2_a":"Automaticky načte jeden ze 6 jazykových profilů (C/C++, Python, Java/Kotlin, JS/TS, Web, Shell/SQL), obaluje vybraný text závorkami či uvozovkami, podporuje sekundární symboly tažením nahoru se zvětšovací lupou a obsahuje režim Zámek kurzoru, který při navigaci potlačí systémovou klávesnici.","faq3_q":"Mohu změnit pořadí tlačítek na spodní liště a v rychlém menu?","faq3_a":"Ano. Otevřete Nastavení -&gt; Přizpůsobit lišty a menu a přetažením změňte pořadí hlavní spodní/boční lišty i všech 5 zlatých slotů rychlých akcí, nebo jedním klepnutím obnovte výchozí rozložení.","faq4_q":"Mohu exportovat zdrojový kód do PDF nebo si v IDE prohlížet PDF a obrázky?","faq4_a":"Ano. Pomocí Tisk nebo Uložit jako .pdf vygenerujete ostré neproporcionální A4 PDF a přímo uvnitř SuperCode si zobrazíte projektová PDF (zoom 1x–5x, skok na stránku) a 10 obrazových formátů (včetně WEBP, HEIC, AVIF, ICO).","wb_eyebrow":"INTERAKTIVNÍ UKÁZKA INTELIGENCE EDITORU","sec_cap_title":"Navrženo od nástrojové lišty výš pro reálné softwarové projekty","sec_cap_lead":"Každá mikrointerakce — od přeskoku závorek po formátování ukotvené na výběr — je ověřena pro rychlost palce a vizuální čistotu.","f1_title":"Hybridní kontextové doplňování kódu podle AST","f1_desc":"Spouští se automaticky na ., -&gt;, :: a : napříč C/C++, Python, Java, Kotlin, JS/TS, HTML, CSS, PHP, Lua, Shell a SQL — offline vyhodnocuje lokální typy, členy struct/class, API STL/DOM a snippety kódu.","f1_badge":"Operátory: . · -&gt; · :: · :  |  10 jazykových rodin","f2_title":"Duální zvýraznění &amp; chytrá detekce nepojmenovaných souborů","f2_desc":"Okamžitě zvýrazňuje viditelné řádky viewportu při 120 Hz se zachováním vnitřních formátovacích tokenů (\\n, %d, {0}) a značek @param/TODO. Automaticky rozpozná jazyk u souborů bez přípony pomocí #! Shebang a lexikálního skórování.","f2_badge":"40+ přípon · Shebang detekce · 0 ztracených snímků","f3_title":"30+ offline formátovačů kódu &amp; chytré komentování","f3_desc":"Čistě formátuje C/C++, Java, Kotlin, JS/TS, Python (PEP 8), JSON, CSS, PHP, SQL, Lua, Shell a HTML/Vue (rekurzivně formátuje i &lt;script&gt; a &lt;style&gt;!) se zachováním základního odsazení výběru v jediném kroku Zpět.","f3_badge":"Atomické v 1 kroku Zpět · Rekurzivní HTML/JS/CSS","f4_title":"Radar chyb V2.0 &amp; holografické statistiky dokumentu","f4_desc":"Odhaluje nespárované závorky, neuzavřené řetězce/tagy, Python TabError/chybějící dvojtečky a neplatné čárky v JSON se skokem jedním klepnutím na Řádek X, Sloupec Y — spolu s globálními i výběrovými počty řádků, slov, znaků a přesných bajtů UTF-8.","f4_badge":"Skok Řádek/Sloupec · Globální a výběrové bajty UTF-8","f5_title":"29nástrojová 5režimová lišta &amp; swipe menu z pravého okraje","f5_desc":"Automaticky se mění v režimech Kód, Prostý text, Výběr, Hledání a Mega-soubor; na šířku se ukotví svisle a doplňuje ji 120Hz menu tažením palce od pravého okraje s 5 upravitelnými trvale otevřenými sloty.","f5_badge":"5 auto režimů · 5 rychlých slotů · 15MB virtuální schránka","f6_title":"21klávesová swipe lišta symbolů, 8 motivů &amp; export A4 PDF","f6_desc":"Přepínejte mezi 6 jazykovými profily symbolů s klepnutím + zvětšovací lupou při swipe nahoru a režimem zámku kurzoru. Pište v 8 optických motivech WCAG AAA (s Auto Den/Noc), v režimu Zen nebo exportujte čistá neproporcionální A4 PDF.","f6_badge":"6 profilů symbolů · AMOLED #000000 · Nativní prohlížeče PDF/obrázků","workflow_title":"Jak si přizpůsobit &amp; ovládnout pracovní prostor editoru","workflow_lead":"Nastavte si personalizovaný mobilní vývojový tok na úrovni desktopu za méně než dvě minuty.","wf_foot_note":"Vodorovným tažením karet změníte pořadí · Hot Exit automaticky zálohuje neuložené karty","wf1_title":"Vytvořte nebo otevřete libovolný zdrojový soubor","wf1_desc":"Otevírejte soubory ve více kartách z interního úložiště, SD/USB OTG, Git nebo SFTP. I nepojmenované poznámky automaticky rozpoznají syntaxi jazyka a při chytrém uložení doporučí správnou příponu.","wf2_title":"Pište rychleji s duálními klávesami &amp; AST","wf2_desc":"Klepnutím vložte párové oddělovače nebo obalte výběr; tažením nahoru na libovolné klávese zadejte sekundární operátory (===, /**/, předsazení) a vyvolejte 0ms AST doplňování členů.","wf3_title":"Naformátujte kód &amp; zkontrolujte Radar chyb","wf3_desc":"Klepněte na Formátovat pro čisté zarovnání odsazení, poté klepněte na Počet pro zobrazení živých souřadnic Radaru chyb spolu se statistikami UTF-8 pro výběr i celý dokument.","wf4_title":"Táhněte od pravého okraje pro 5 slotů rychlých akcí","wf4_desc":"Jednou rukou zatáhněte dovnitř od pravého okraje displeje a opakovaně klepejte na Zpět/Znovu/Motiv/Zalamování bez zavření menu, přepněte režim Zen nebo exportujte A4 PDF."},"large_file":{"metaTitle":"Otevírání velkých textových a GB logů na Androidu — Proudové nahrazování a 34 kódování | SuperCode","metaDesc":"Otevírejte stovky MB i GB logů, SQL dumpů a CSV datasetů na Androidu okamžitě a bez sekání. Nabízí 10MB diskové stránkování, globální proudové regex nahrazování, 15MB virtuální schránku a 34 kódování znaků.","hero_tag":"PROHLÍŽEČ GB SOUBORŮ &amp; PROUDOVÉ NAHRAZOVÁNÍ","hero_h1":"Otevírejte <span class=\"text-gradient\">GB logy &amp; dumpy</span> okamžitě s globálním proudovým nahrazováním.","hero_desc":"Běžné mobilní editory u souborů nad pár megabajtů zamrznou nebo spadnou. SuperCode připojuje <strong>soubory o velikosti stovek MB až GB</strong> přes diskové stránkování po 10M znacích při <strong>120Hz</strong>, provádí <strong>proudové regex nahrazování</strong> přímo na disku a bezpečně dekóduje <strong>34 kódování znaků</strong>.","table_h2":"Srovnání práce s velkými soubory &amp; kódováním na Androidu","snippet_p":"<strong>Editor velkých souborů SuperCode</strong> umožňuje uživatelům na Androidu okamžitě otevírat textové, logovací, CSV a SQL soubory o stovkách MB až GB bez zamrzání. Kombinuje diskové stránkování po 10M znacích, globální proudové vyhledávání a nahrazování pomocí regexů, 15 MB virtuální schránku a bezeztrátovou autodetekci 34 znakových sad.","table_caption":"MATICE ENGINU PRO VELKÉ TEXTOVÉ SOUBORY &amp; KÓDOVÁNÍ · ANDROID","faq_lead":"Časté dotazy k otevírání GB souborů, regex nahrazování, USB diskům a opravě poškozených CJK či starších textů.","cta_h2":"Otevírejte obří logy, dumpy &amp; starší soubory bez pádů.","cta_desc":"Stáhněte si SuperCode IDE na Google Play — vaše 120Hz studio pro práci s GB texty, logy a kódem na Androidu.","th_0":"Funkce","th_1":"Engine velkých souborů SuperCode","th_2":"Běžné editory kódu","th_3":"Systémové prohlížeče","tr1_c0":"Soubory 500 MB – 2 GB+","tr1_c1":"Okamžité 10MB diskové stránkování + skok na stránku 1..N","tr1_c2":"Pád pro nedostatek paměti při otevření","tr1_c3":"Odmítne otevřít (&gt;2 MB–10 MB)","tr2_c0":"Globální hledání &amp; nahrazení","tr2_c1":"Proudové nahrazení všeho na disku + regex skupiny $1..$99","tr2_c2":"Nahrazování pouze v RAM","tr2_c3":"Jen pro čtení nebo bez nahrazování","tr3_c0":"Minifikované jednořádkové soubory","tr3_c1":"Auto základní režim (&gt;4 000 znaků) · 0 sekání","tr3_c2":"UI zamrzne u minifikovaného JS/JSON","tr3_c3":"Zamrzne při zalamování řádků","tr4_c0":"Velké kopírování &amp; vkládání","tr4_c1":"15 MB procesní virtuální schránka (100k+ řádků)","tr4_c2":"Pád při limitu OS ~800 KB","tr4_c3":"Ořízne text nebo selže","tr5_c0":"Starší kódování","tr5_c1":"34 znakových sad (GB18030, Shift_JIS, EUC-KR, Win-125x) + ochrana UTF-8","tr5_c2":"Pouze UTF-8 (rozsypané CJK/azbuka)","tr5_c3":"Bez výběru kódování","faq1_q":"Jak může telefon s Androidem upravit 1 GB soubor, aniž by došla RAM?","faq1_a":"Místo načtení celého gigabajtu do paměti streamuje SuperCode soubor po stránkách o 10 000 000 znacích (~10 MB) uložených na disku. V editoru je aktivní vždy jen aktuální stránka a Globální proudové nahrazení zpracovává bloky sekvenčně přímo na disku.","faq2_q":"Opraví SuperCode rozsypané čínské, japonské, korejské nebo ruské textové soubory?","faq2_a":"Ano. Jeho 5stupňová detekce kódování rozpozná 34 znakových sad včetně GB18030, GBK, Big5, Shift_JIS, EUC-JP, EUC-KR, KOI8-R, Windows-1251/1252 a UTF-16 bez BOM a umožní soubor znovu načíst nebo bezeztrátově převést do UTF-8.","faq3_q":"Co se stane, když soubor obsahuje jediný 500 KB minifikovaný řádek JSON nebo JS?","faq3_a":"Řádky delší než 4 000 znaků se automaticky přepnou do rychlého základního režimu O(1) bez zalamování slov, takže se minifikované balíky i řádky logů posouvají plynule bez zamrzání.","faq4_q":"Mohu otevírat velké soubory přímo z USB flash disku nebo SD karty?","faq4_a":"Ano. SuperCode podporuje interní úložiště, externí SD karty i za provozu připojené USB OTG disky přímo z Průzkumníka pracovního prostoru.","wb_eyebrow":"CENTRUM PRO VELKÉ SOUBORY &amp; PROUDOVÝ ENGINE","sec_cap_title":"Navrženo pro produkční logy, databázové dumpy &amp; starší kódování","sec_cap_lead":"Víceúrovňová ochrana paměti udržuje posouvání, vyhledávání i ukládání svižné i u obřích jednořádkových JSONů nebo multi-GB serverových logů.","f1_title":"Automatické 10MB diskové stránkování pro GB soubory","f1_desc":"Soubory nad 30 MB automaticky aktivují proudové stránkování na pozadí I/O — rozdělí obří logy, CSV a SQL zálohy na stránky po 10 000 000 znacích a bez prodlevy zvládnou i minifikované řádky &gt;4 000 znaků.","f1_badge":"10M znaků / str. · Plynulých 120Hz · Bezpečné pro minifikovaný kód","f2_title":"Ovládací lišta velkých souborů &amp; atomické sloučení","f2_desc":"Pohybujte se pomocí Předchozí stránky, Další stránky nebo přímého skoku na stránku 1..N (s automatickým uložením úprav aktivního bloku) a klepnutím na Sloučit vše a uložit celý GB soubor atomicky sestavte na disku.","f2_badge":"Skok na stránku [1/N] · Zápis změn · Atomické uložení","f3_title":"Globální proudové nahrazení &amp; regex skupiny","f3_desc":"Spusťte Globální proudové nahrazení napříč všemi stránkami na disku bez načtení celého souboru do paměti. Podporuje záchytné skupiny $1..$99 a ${name}, sekvence \\n/\\t, hledání ve výběru a 1 200ms pojistku proti zacyklení regexu.","f3_badge":"Proudové nahrazení · Regex $1..$99 · Buffer 50 000+ shod","f4_title":"15 MB virtuální mega schránka (100k+ řádků)","f4_desc":"Nativní schránka Androidu selhává kolem 800 KB. Procesní virtuální schránka v SuperCode umožňuje bez problémů kopírovat, vyjímat a proudově vkládat až 15 MB logů či SQL příkazů mezi kartami.","f4_badge":"Obchází 800 KB limit OS · Vkládání až 15 MB","f5_title":"34 kódování znaků &amp; ochrana před poškozením při uložení","f5_desc":"5stupňová autodetekce pro UTF-8/16/32, GB18030/GBK/Big5, Shift_JIS/EUC-JP, EUC-KR, KOI8-R, 11 sad ISO-8859 a 9 kódových stránek Windows. Před uložením upozorní na nemapovatelné znaky Unicode, aby se text nikdy nezměnil v ?.","f5_badge":"34 znakových sad · Bezpečné odstranění BOM · LF / CRLF / CR","f6_title":"Fuzzy hledání v 50k souborech &amp; binární firewall","f6_desc":"Najděte jakýkoli soubor v lokálním úložišti, Git, na SD/USB OTG či SFTP pomocí 7úrovňového řazení CamelCase/cesty (s automatickým vynecháním node_modules/.git) a 4 KB inspekcí magic-bytů, která bezpečně zablokuje binární soubory.","f6_badge":"50k uzlů · Podpora USB OTG · 4 KB kontrola magic-bytů","workflow_title":"Jak prohlížet &amp; hromadně upravovat soubory o stovkách MB či GB","workflow_lead":"Upravujte obří logy, CSV exporty a soubory se starším kódováním bezpečně na jakémkoli telefonu nebo tabletu s Androidem.","wf_foot_note":"Podporuje interní úložiště, externí SD karty &amp; za provozu připojené USB OTG disky","wf1_title":"Otevřete jakýkoli obří log, CSV nebo SQL dump","wf1_desc":"Vyberte soubor z interního úložiště nebo připojené SD/USB OTG jednotky. SuperCode automaticky rozpozná kódování a okamžitě připojí stránky po 10M znacích.","wf2_title":"Skočte přímo na libovolnou stránku","wf2_desc":"Klepněte na tlačítko Stránka v přehledné 7prvkové liště pro velké soubory a přejděte na libovolnou stránku, přepněte Textový režim nebo spusťte nerušený Zen režim.","wf3_title":"Hledejte nebo spusťte globální proudové nahrazení","wf3_desc":"Sbalte vyhledávání do plovoucí mini pilulky při procházení shod nebo spusťte Globální proudové nahrazení pro hromadnou úpravu vzorů na všech stránkách na disku.","wf4_title":"Zapište změny atomicky na disk","wf4_desc":"Klepnutím na Sloučit vše a uložit bezpečně zapíšete všechny upravené bloky zpět do původního souboru při plném zachování kódování znaků."},"python_ide":{"metaTitle":"Aplikace pro Python na Android — Offline Python IDE, PIP, NumPy a více souborů | SuperCode","metaDesc":"Bezplatná offline aplikace pro Python a Python 3.11/3.12 IDE pro Android. Spouštějte vícesouborové Python projekty, instalujte PIP a offline .whl balíčky, používejte NumPy/Pandas/Matplotlib, interaktivní input() a vizuální Git.","hero_tag":"OFFLINE PYTHON 3.11 / 3.12 APLIKACE &amp; VIZUÁLNÍ PIP STUDIO","hero_h1":"Offline <span class=\"text-gradient\">Python aplikace &amp; IDE</span> pro Android.","hero_desc":"Proměňte telefon nebo tablet s Androidem v samostatnou pracovní stanici pro Python. Spouštějte <strong>vícesouborové skripty Python 3.11 &amp; 3.12</strong> offline, instalujte přes 250 knihoven pomocí <strong>vizuálního PIP nebo lokálních <code>.whl</code> souborů</strong> a vykreslujte grafy <strong>NumPy, Pandas &amp; Matplotlib</strong> přímo do složky projektu.","table_h2":"SuperCode Python IDE vs. ostatní Python aplikace pro Android","snippet_p":"<strong>SuperCode Python IDE</strong> je offline aplikace pro vývoj v jazycích Python 3.11 a 3.12 na Androidu. Nabízí spouštění vícesouborových skriptů, vizuálního správce balíčků PIP a offline .whl, lokálně kešované NumPy, Pandas a export grafů Matplotlib, interaktivní konzoli pro input(), formátování PEP 8 a vizuální integraci Git/SFTP.","table_caption":"SROVNÁNÍ VÝVOJOVÝCH PROSTŘEDÍ PRO PYTHON NA ANDROIDU","faq_lead":"Odpovědi k offline spouštění Pythonu, instalaci knihoven pip/.whl, NumPy/Matplotlib a vícesouborovým importům.","cta_h2":"Programujte v Pythonu kdekoli — i offline.","cta_desc":"Stáhněte si SuperCode IDE zdarma na Google Play a mějte Python, PIP, NumPy a Git v jediném 40,2 MB studiu pro Android.","th_0":"Funkce Pythonu","th_1":"SuperCode Python IDE","th_2":"Samostatné Python aplikace","th_3":"Online Python interprety","th_4":"Emulátory terminálu","tr1_c0":"Offline spouštění","tr1_c1":"Python 3.11 + kešovaný vědecký 3.12 offline","tr1_c2":"Jen základní offline Python","tr1_c3":"Vyžaduje internet","tr1_c4":"Ruční instalace v CLI","tr2_c0":"Správa balíčků","tr2_c1":"Auto-PIP + requirements.txt + UI pro lokální .whl/.zip","tr2_c2":"Placený plugin nebo CLI pip","tr2_c3":"Pevné balíčky na serveru","tr2_c4":"Chyby při ruční kompilaci","tr3_c0":"Data Science &amp; grafy","tr3_c1":"NumPy/Pandas/Matplotlib -&gt; Auto uložení do složky","tr3_c2":"Nutný samostatný plugin","tr3_c3":"Bez lokální synchronizace souborů","tr3_c4":"Složité nastavení X11/headless","tr4_c0":"Více jazyků &amp; Git","tr4_c1":"Zahrnuje C/C++, Java, JS, SQL, PHP, Git &amp; SFTP","tr4_c2":"Aplikace jen pro Python","tr4_c3":"Jen sandbox v prohlížeči","tr4_c4":"Bez vizuálního Git merge UI","tr5_c0":"Inteligence editoru","tr5_c1":"AST doplňování + formát PEP 8 + radar chyb","tr5_c2":"Základní automatické doplňování","tr5_c3":"Síťová latence","tr5_c4":"Vyžaduje konfiguraci Vim/Nano","faq1_q":"Mohu na Androidu psát a spouštět kód v jazyce Python zcela offline?","faq1_a":"Ano. Vícesouborové skripty Python 3.11, moduly standardní knihovny, lokálně nainstalované balíčky PIP/.whl i kešované vědecké knihovny Python 3.12 (NumPy, Pandas, Matplotlib, SciPy, scikit-learn) běží 100% offline.","faq2_q":"Jak nainstaluji knihovny třetích stran jako requests, bs4 nebo offline .whl soubory?","faq2_a":"Otevřete vizuální správce balíčků PIP (nebo skript prostě spusťte a nechte Auto-PIP odhalit chybějící importy). Můžete instalovat z PyPI, klepnout na nalezený čip requirements.txt nebo importovat balíčky .whl, .tar.gz a .zip z lokálního úložiště.","faq3_q":"Kam se ukládají grafy Matplotlib nebo soubory vytvořené pomocí open('data.csv', 'w')?","faq3_a":"Každý obrázek, PDF, CSV nebo JSON soubor zapsaný vaším skriptem se automaticky synchronizuje do aktivní složky projektu a můžete jej ihned zobrazit ve vestavěné galerii obrázků nebo editoru souborů v SuperCode.","faq4_q":"Podporuje SuperCode interaktivní smyčky s funkcí input() v jazyce Python?","faq4_a":"Ano. Kdykoli skript zavolá input(), konzole na rozdělené obrazovce zvýrazní vstupní řádek, abyste mohli interaktivně zadávat odpovědi v reálném čase.","wb_eyebrow":"INTERAKTIVNÍ PRACOVIŠTĚ PRO PYTHON &amp; DATA SCIENCE","sec_cap_title":"Tříúrovňové spouštění Pythonu od čistých skriptů po Data Science","sec_cap_lead":"Každý pracovní postup — od školních úloh z informatiky po vědecké grafy a web scraping — funguje plynule bez nutnosti ručního nastavování v terminálu.","f1_title":"Offline vícesouborový Python 3.11 &amp; chytré směrování","f1_desc":"Spouštějte vícemodulové projekty se soubory .py, .json, .csv, .yaml a .toml 100% offline. Stisknutí Spustit v pomocném modulu automaticky najde a spustí hlavní vstupní skript projektu.","f1_badge":"Vícesouborové importy · Neuložené karty · Synchronizace","f2_title":"Lokálně kešované NumPy, Pandas &amp; Matplotlib","f2_desc":"Import knihoven numpy, scipy, pandas, matplotlib nebo scikit-learn zapojí lokální vědecký runtime — kešuje wheel balíčky v zařízení, aby analýza dat i generování grafů přes plt.savefig() běžely offline.","f2_badge":"NumPy · Pandas · Matplotlib · Auto uložení PNG/SVG/PDF","f3_title":"Vizuální správce PIP, Auto-PIP &amp; offline import .whl","f3_desc":"Chybí knihovna jako bs4 nebo yaml? Auto-PIP namapuje aliasy (bs4 -&gt; beautifulsoup4), nainstaluje je z PyPI a automaticky restartuje skript — nebo hromadně nainstaluje requirements.txt a lokální soubory .whl/.zip offline.","f3_badge":"Auto-PIP · requirements.txt · Offline importér .whl","f4_title":"Skutečné interaktivní input() &amp; nastavitelná konzole","f4_desc":"Podporuje více po sobě jdoucích výzev input() v reálném čase. Konzole se elegantně ukotví pod kód (při psaní se sama sbalí) nebo vedle sebe v režimu na šířku 55 %/45 % na tabletu.","f4_badge":"Živý Stdin · ANSI TrueColor · Lupa 7sp–26sp","f5_title":"Formátovač PEP 8, AST doplňování &amp; radar chyb","f5_desc":"Pište čistý Python s 21klávesovou lištou symbolů, offline AST doplňováním členů, formátováním odsazení dle PEP 8 a živou detekcí TabError či chybějících dvojteček ještě před spuštěním.","f5_badge":"Autoformát PEP 8 · Ochrana TabError · 8 šablon","f6_title":"Volitelný cloudový cluster pro PyTorch, TensorFlow &amp; OpenCV","f6_desc":"Potřebujete náročné frameworky pro deep learning (torch, tensorflow, keras, cv2) nebo spuštění # @cloud? SuperCode zabalí vaše lokální moduly a vrátí tracebacky s přesnými čísly řádků 1:1 v editoru.","f6_badge":"PyTorch · TensorFlow · OpenCV · Tracebacky 1:1","workflow_title":"Jak psát kód &amp; spravovat balíčky Python v SuperCode","workflow_lead":"Přejděte od prázdné složky k vícesouborovému projektu v Pythonu a Matplotlib na čtyři klepnutí.","wf_foot_note":"120s CPU hlídač · 250KB ochrana výstupu · Trvalý správce balíčků na disku","wf1_title":"Vytvořte skript nebo načtěte vestavěnou ukázku Pythonu","wf1_desc":"Začněte od nuly s 21klávesovou lištou symbolů Pythonu nebo si vyberte jednu z 8 vestavěných šablon v knihovně Ukázky kódu.","wf2_title":"Nainstalujte knihovny z PyPI nebo offline .whl archivy","wf2_desc":"Klepnutím na requirements.txt spusťte hromadnou instalaci jedním dotykem, vyberte doporučené čipy (requests, rich, bs4, flask) nebo importujte balíčky .whl ze Stažených souborů pro offline výuku.","wf3_title":"Spouštějte offline &amp; pracujte se živým input()","wf3_desc":"Sledujte okamžitý výstup, návratové kódy, časování v milisekundách a změnu paměti v konzoli na rozdělené obrazovce při živém zadávání odpovědí na výzvy input().","wf4_title":"Prohlížejte vygenerované grafy, CSV &amp; JSON výstupy","wf4_desc":"Jakýkoli soubor zapsaný přes open() nebo plt.savefig('plot.png') se ihned synchronizuje do složky projektu a otevře ve vestavěném prohlížeči obrázků či PDF ve vysokém rozlišení."},"c_compiler":{"metaTitle":"Aplikace pro C a offline kompilátor C pro Android — GNU C17, ukazatele a více souborů | SuperCode","metaDesc":"Dedikovaný offline kompilátor C17 a aplikace pro programování v C na Androidu. Kompilujte vícesouborové projekty .c/.h i CMake/Makefile offline, testujte ukazatele a struktury a využijte nebufferovaný vstup scanf/fgets a hlavičky POSIX.","hero_tag":"DEDIKOVANÝ OFFLINE KOMPILÁTOR GNU C17","hero_h1":"Čistý, dedikovaný <span class=\"text-gradient\">offline kompilátor C17</span> pro systémové programování a studium informatiky.","hero_desc":"Navržen speciálně pro jazyk C — bez režie běhového prostředí C++. Kompilujte programy <strong>GNU C17 (<code>-std=gnu17</code>)</strong> offline s automatickým <strong>linkováním více souborů <code>.c/.h</code></strong>, podporou <strong><code>&lt;math.h&gt;</code></strong>, živým vstupem <strong><code>scanf</code> / <code>fgets</code></strong> a mikrosekundovou telemetrií.","table_h2":"Kompilátor SuperCode C17 vs. běžné mobilní kompilátory","snippet_p":"<strong>SuperCode C Compiler</strong> je dedikované offline vývojové prostředí GNU C17 pro Android. Nabízí čistou kompilaci C17 s linkováním matematické knihovny, automatické sestavování projektů s více soubory .c a .h bez nutnosti Makefile, živý vstup konzole scanf/fgets, synchronizaci souborových I/O v pracovním prostoru a doplňování struktur pomocí AST.","table_caption":"SROVNÁNÍ KOMPILÁTORŮ JAZYKA C PRO ANDROID","faq_lead":"Dotazy k offline kompilaci C17, vícesouborovým hlavičkám, &lt;math.h&gt; a vstupu scanf na Androidu.","cta_h2":"Ovládněte programování v C kdekoli na Androidu.","cta_desc":"Nainstalujte si SuperCode IDE z Google Play a získejte dedikovaný offline kompilátor GNU C17, šablony ukazatelů a vícesouborový pracovní prostor.","th_0":"Funkce jazyka C","th_1":"SuperCode C17 Studio","th_2":"Sloučené C/C++ hříčky","th_3":"Online kompilátory C","th_4":"CLI terminálové prostředí","tr1_c0":"Standard C &amp; linkování","tr1_c1":"Dedikovaný GNU C17 (-std=gnu17) + -lm","tr1_c2":"Vynucuje C++ kompilátor na souborech .c","tr1_c3":"Závislé na serveru","tr1_c4":"Ruční příznaky gcc","tr2_c0":"Více souborů .c / .h","tr2_c1":"Automatické vyhledání bez konfigurace + přírůstková mezipaměť","tr2_c2":"Pouze jeden soubor main.c","tr2_c3":"Ruční nahrání po souborech","tr2_c4":"Vyžaduje Makefile","tr3_c0":"Interaktivní vstup","tr3_c1":"Živý stream scanf / fgets + ovládání [EOF]","tr3_c2":"Pouze textové pole před spuštěním","tr3_c3":"Pouze dávkový stdin","tr3_c4":"Podporováno","tr4_c0":"Ochrana smyček &amp; výstupu","tr4_c1":"15s CPU watchdog + pojistka výstupu 250K","tr4_c2":"Aplikace zamrzne při while(1)","tr4_c3":"Chyba vypršení limitu serveru","tr4_c4":"Ruční Ctrl+C","tr5_c0":"Editor &amp; nástroje Git","tr5_c1":"AST doplňování -&gt;/. + formátovač C + vizuální Git","tr5_c2":"Prosté textové pole","tr5_c3":"Textové pole v prohlížeči","tr5_c4":"Bez dotykového GUI","faq1_q":"Je kompilátor C v SuperCode oddělený od C++?","faq1_a":"Ano. Otevřením souboru .c se aktivuje dedikovaná konzole GNU C17 (-std=gnu17) a čisté linkování standardní knihovny C, místo aby se váš kód v C kompiloval jako C++.","faq2_q":"Musím psát Makefile, abych mohl zkompilovat více souborů .c a .h?","faq2_a":"Ne. SuperCode automaticky prohledá hlavičky #include \"...\" a související soubory .c ve vašem pracovním prostoru i otevřených kartách editoru, přírůstkově zkompiluje změněné soubory a automaticky přilinkuje &lt;math.h&gt; (-lm).","faq3_q":"Fungují scanf() a fgets() na Androidu interaktivně?","faq3_a":"Ano. Terminál v rozdělené obrazovce pozastaví provádění, kdykoli váš C program čte ze stdin, umožní vám zadávat více řádků vstupu živě a při odeslání prázdného řádku pošle signál EOF.","faq4_q":"Co když můj C kód používá linuxové hlavičky POSIX, jako je &lt;pthread.h&gt; nebo &lt;sys/socket.h&gt;?","faq4_a":"SuperCode automaticky rozpozná hlavičky specifické pro OS/POSIX a plynule zkompiluje váš vícesouborový projekt v cloudovém toolchainu POSIX při zachování přesné lokální diagnostiky názvu souboru a čísla řádku.","wb_eyebrow":"DEDIKOVANÉ PRACOVIŠTĚ KOMPILÁTORU GNU C17","sec_cap_title":"Proč je dedikovaná architektura C17 důležitá pro C programátory","sec_cap_lead":"Čistá sémantika C17, přísná hygiena hlaviček a nulové zdržování s Makefile pro vysokoškolská cvičení, embedded prototypy a algoritmy.","f1_title":"Čistý standard GNU C17 &amp; &lt;math.h&gt; ihned po vybalení","f1_desc":"Kompiluje přísně pod -std=gnu17 proti čisté standardní knihovně C a matematické knihovně (-lm) bez C++ name-manglingu nebo zbytečné režie běhového prostředí — ideální pro kurzy ANSI/ISO C a základy systémového programování.","f1_badge":"-std=gnu17 · &lt;stdio.h&gt; · &lt;stdlib.h&gt; · &lt;math.h&gt;","f2_title":"Bezkonfigurační linker více souborů .c / .h &amp; hash cache","f2_desc":"Automaticky vyhledá hlavičky #include \"...\" a související soubory .c ve složce a otevřených kartách — bez potřeby Makefile. Přírůstková hashovací mezipaměť přeskočí opětovnou kompilaci nezměněných překladových jednotek .c.","f2_badge":"Auto detekce .c/.h · Rozlišení hlavička -&gt; main.c","f3_title":"Skutečně interaktivní konzole scanf / fgets / getchar","f3_desc":"Testujte interaktivní C programy přirozeně: terminál se zvýrazní vždy, když scanf nebo fgets čeká na vstup, a odeslání prázdného řádku vyšle [EOF] pro čisté ukončení smyček while(scanf(...) != EOF).","f3_badge":"Živý stdin · Signál [EOF] · Statistiky μs + KB","f4_title":"Synchronizace souborových I/O fopen / fwrite v pracovním prostoru","f4_desc":"Binární a textové soubory zapsané pomocí fopen(), fprintf() a fwrite() se synchronizují přímo do složky projektu s automatickým obnovením Průzkumníka, abyste si mohli výstupy okamžitě prohlédnout.","f4_badge":"Reálné souborové I/O · Auto synchronizace stromu projektu","f5_title":"Pojistka nekonečných smyček &amp; diagnostika ukazatelů","f5_desc":"Neúmyslná smyčka while(1) nebo neřízený printf? 15sekundový CPU watchdog sledující nečinnost a ochrana proti zahlcení při 250 000 znacích proces čistě zastaví bez zamrznutí telefonu.","f5_badge":"15s watchdog · 250K pojistka zahlcení · Diagnostika řádků","f6_title":"6 vestavěných šablon C &amp; cloudový záložní režim POSIX","f6_desc":"Začněte se učit rychle se 6 připravenými ukázkami v C (Ukazatele a paměť, Struktury, Bitové operace, Sinusovka, Echo Stdin) a automatickou cloudovou kompilací POSIX (&lt;pthread.h&gt;, &lt;sys/socket.h&gt;, fork) v případě potřeby.","f6_badge":"6 šablon C · Formátovač C · Podpora cloudu POSIX","workflow_title":"Jak sestavovat &amp; ladit vícesouborové programy v C na Androidu","workflow_lead":"Pište jednosouborová cvičení i vícemodulové C projekty s nulovou konfigurací sestavovacích skriptů.","wf_foot_note":"Jednorázové stažení offline toolchainu · Přírůstková mezipaměť sestavení po souborech","wf1_title":"Vytvořte zdrojové soubory .c a hlavičky .h","wf1_desc":"Použijte 21klávesovou lištu symbolů C/C++ (-&gt;, *, &amp;, {}, ;, #include) a AST doplňování členů struktur pro psaní modulárního kódu C17.","wf2_title":"Zkontrolujte direktivy &amp; formátujte odsazení offline","wf2_desc":"Error Radar okamžitě zachytí chybné direktivy #include a nespárované závorky; klepnutím na Formátovat zarovnáte bloky K&amp;R/Allman i makra od 0. sloupce.","wf3_title":"Kompilujte &amp; linkujte offline z jakékoli karty projektu","wf3_desc":"I když máte kurzor uvnitř utils.h, klepnutí na Spustit automaticky vyhledá main.c, zkompiluje upravené jednotky, přilinkuje -lm a spustí binární soubor.","wf4_title":"Zadávajte živý vstup scanf &amp; kontrolujte výstupní soubory","wf4_desc":"Zadávejte testovací hodnoty interaktivně v ukotveném nebo postranním terminálu a sledujte návratový kód, dobu běhu v ms, využití paměti a vygenerované soubory."},"cpp_ide":{"metaTitle":"C++ IDE a offline aplikace pro C++20 na Android — STL, 21 šablon a rychlý cin | SuperCode","metaDesc":"Kompilujte a spouštějte moderní C++20 offline na Androidu. Plné kontejnery a rozsahy STL, 21 vícesouborových šablon C++ CMake projektů, AST doplňování std::, konzole std::cin 55:45 pro soutěžní programování a vizuální Git.","hero_tag":"MODERNÍ OFFLINE STUDIO PRO C++20 &amp; STL","hero_h1":"Moderní <span class=\"text-gradient\">offline C++20 &amp; STL IDE</span> pro algoritmy a OOP.","hero_desc":"Od olympiád a grafových algoritmů na LeetCode po objektovou architekturu s více třídami: sestavujte a spouštějte <strong>GNU C++20 (<code>-std=gnu++2a</code>)</strong> offline s <strong>plnou STL</strong>, <strong>AST doplňováním <code>std::</code></strong> a responzivní <strong>konzolí <code>std::cin</code> v rozdělené obrazovce</strong>.","table_h2":"SuperCode C++20 IDE vs. jiné mobilní C++ aplikace","snippet_p":"<strong>SuperCode C++ IDE</strong> je nativní offline kompilátor GNU C++20 a vývojové studio pro Android. Spojuje plnou podporu kontejnerů a algoritmů STL, bezkonfigurační kompilaci více souborů .cpp/.hpp s přírůstkovou mezipamětí, offline AST automatické doplňování std::, živý terminál std::cin v rozdělené obrazovce a vestavěný vizuální Git.","table_caption":"SROVNÁNÍ KOMPILÁTORŮ A IDE PRO C++20 NA ANDROIDU","faq_lead":"Odpovědi k podpoře C++20, soutěžnímu programování se STL, vícesouborovým hlavičkám a offline použití.","cta_h2":"Kompilujte moderní C++20 offline na telefonu i tabletu.","cta_desc":"Stáhněte si SuperCode IDE z Google Play a získejte dedikovanou kompilaci C++20 STL, AST automatické doplňování a vizuální Git.","th_0":"Možnosti C++","th_1":"SuperCode C++20 IDE","th_2":"Zastaralé mobilní C++ aplikace","th_3":"Webové C++ sandboxy","th_4":"Terminálové kompilátory","tr1_c0":"Standard jazyka","tr1_c1":"Moderní GNU C++20 (-std=gnu++2a) offline","tr1_c2":"Starší C++11/14 nebo objemné pluginy","tr1_c3":"Vyžaduje internet","tr1_c4":"Ruční nastavení CLI toolchainu","tr2_c0":"Vícesouborové OOP","tr2_c1":"Auto linker .cpp/.hpp + přírůstková hash cache","tr2_c2":"Jeden soubor nebo ruční nastavení projektu","tr2_c3":"Vložení jen jednoho souboru","tr2_c4":"Ruční CMake/Make","tr3_c0":"Inteligence kódu","tr3_c1":"Offline AST doplňování std:: / -&gt; / :: + formátovač","tr3_c2":"Základní zvýraznění klíčových slov","tr3_c3":"Vysoká latence sítě","tr3_c4":"Externí konfigurace LSP","tr4_c0":"Rozdělený terminál UX","tr4_c1":"Auto-sbalení na výšku + 55:45 na šířku + telemetrie","tr4_c2":"Přepínání na celou obrazovku","tr4_c3":"Stísněné mobilní rozvržení","tr4_c4":"Žádné karty editoru kódu","tr5_c0":"Správa verzí","tr5_c1":"Vestavěné vizuální UI pro Git diff, větve &amp; konflikty","tr5_c2":"Žádná","tr5_c3":"Žádná","tr5_c4":"Pouze CLI git","faq1_q":"Kompiluje SuperCode C++20 a kontejnery STL offline bez internetu?","faq1_a":"Ano. Jakmile se při prvním použití inicializuje offline balíček toolchainu pro C++, GNU C++20 (-std=gnu++2a) a plná STL (vektory, mapy, prioritní fronty, rozsahy, chytré ukazatele, lambdy) se kompilují i spouštějí 100% offline.","faq2_q":"Hodí se SuperCode pro soutěžní programování (Codeforces, LeetCode, olympiády) na telefonu nebo tabletu?","faq2_a":"Ano. Rychlá kompilace s přírůstkovou mezipamětí, živý víceřádkový vstup std::cin, telemetrie běhu v milisekundách a KB a rozdělená obrazovka 55 % / 45 % na šířku z něj dělají ideální nástroj pro trénink algoritmů kdekoli.","faq3_q":"Jak fungují vícesouborové projekty .cpp a .hpp?","faq3_a":"Jednoduše umístěte soubory .hpp a .cpp do stejné složky projektu (nebo otevřených karet). SuperCode automaticky vyhledá lokální direktivy include, přilinkuje všechny implementační soubory a najde main(), i když klepnete na Spustit z karty hlavičky.","faq4_q":"Mohu v C++ používat &lt;thread&gt; nebo síťová API?","faq4_a":"Ano. Při detekci systémových hlaviček pro vlákna nebo sokety SuperCode automaticky zkompiluje váš vícesouborový projekt přes cloudový C++ cluster s podporou -pthread.","wb_eyebrow":"INTERAKTIVNÍ PRACOVIŠTĚ C++20 &amp; STL","sec_cap_title":"Vytvořeno pro soutěžní programátory, studenty informatiky &amp; C++ vývojáře","sec_cap_lead":"Pište moderní C++20 bez boje s mobilními klávesnicemi, pomalými cloudovými frontami nebo ručním CMake boilerplate kódem.","f1_title":"Plná offline standardní knihovna C++20 (STL)","f1_desc":"Používejte std::vector, map, unordered_map, set, priority_queue, string_view, optional, unique_ptr/shared_ptr, std::ranges::sort, lambdy a šablony zcela offline.","f1_badge":"-std=gnu++2a · Kontejnery STL · Rozsahy &amp; šablony","f2_title":"Hluboké AST doplňování pro std::, -&gt; a ::","f2_desc":"Napište v., ptr-&gt; nebo std:: a získejte okamžité offline doplňování členů a metod napříč kontejnery STL, iterátory, proudy, chytrými ukazateli i vlastními třídami.","f2_badge":"AST odvozování typů · 21klávesový profil symbolů C++","f3_title":"Nástroj pro více souborů .cpp / .hpp &amp; hash cache","f3_desc":"Podporuje soubory .cpp, .cc, .cxx, .hpp, .hh, .hxx a .inl napříč podsložkami. Nezměněné překladové jednotky se ukládají do mezipaměti podle hashe pro blesková iterační sestavení.","f3_badge":"Vícesouborové OOP · Auto-spuštění hlavička -&gt; main.cpp","f4_title":"Rozdělená konzole pro soutěže &amp; živý std::cin","f4_desc":"Vkládejte víceřádkové soutěžní testovací vstupy do živého std::cin, kontrolujte přesnou dobu běhu (ms) a špičkovou paměť (KB) a kódujte vedle sebe v zobrazení 55 % / 45 % na tabletu na šířku.","f4_badge":"Rychlé I/O · Auto-sbalení při klávesnici · Palety 12x12","f5_title":"Synchronizace souborů ofstream &amp; ochrana před zacyklením","f5_desc":"Soubory vytvořené přes std::ofstream se synchronizují přímo do stromu projektu, zatímco 15s CPU watchdog a limit výstupu 250K chrání relaci před nekonečnou rekurzí nebo smyčkami.","f5_badge":"Synchronizace ofstream · 15s watchdog · 8 šablon C++","f6_title":"Plynulé vícevláknové cloudové rozšíření C++","f6_desc":"Používáte &lt;thread&gt;, std::async nebo síťování POSIX? SuperCode automaticky směruje vícesouborové zdroje do cloudového C++ clusteru (-pthread) s přesnou diagnostikou řádků 1:1.","f6_badge":"Podpora &lt;thread&gt; · Přesná diagnostika řádků v editoru","workflow_title":"Jak řešit algoritmy &amp; sestavovat C++ projekty na Androidu","workflow_lead":"Optimalizováno pro rychlé iterace v soutěžích a přehledné vícetřídní univerzitní projekty.","wf_foot_note":"Podporuje .cpp · .cc · .cxx · .hpp · .hh · .hxx · .h · .inl","wf1_title":"Začněte ze šablony nebo vícesouborové složky","wf1_desc":"Otevřete jednu z 8 vestavěných ukázek v C++ nebo uspořádejte hlavičky (.hpp) a implementace (.cpp) v lokální složce či složce sledované přes Git.","wf2_title":"Pište STL kód rychle pomocí kláves :: a -&gt;","wf2_desc":"Dedikované klávesy symbolů C++ jedním klepnutím vloží ::, -&gt;, &lt;&lt;, &gt;&gt;, {} a &lt;&gt; a zároveň vyvolají offline AST doplňování členů STL.","wf3_title":"Kompilujte offline &amp; zadávejte soutěžní testovací případy","wf3_desc":"Klepnutím na Spustit sestavíte kód offline během milisekund, zadáte nebo vložíte ukázkové vstupy do std::cin a ověříte telemetrii času běhu a paměti.","wf4_title":"Formátujte &amp; odešlete řešení na GitHub","wf4_desc":"Naformátujte své řešení v C++20 jedním klepnutím a proveďte commit přímo do svého repozitáře algoritmů na GitHubu pomocí vestavěného vizuálního Git klienta."},"java_ide":{"metaTitle":"Java IDE a offline aplikace pro Java 17 na Android — Records, OOP a SQLite JDBC | SuperCode","metaDesc":"Kompilujte a spouštějte Java 17 offline na Androidu — moderní alternativa k aplikacím s Java 11. Podporuje records, sealed třídy, Streams, vícetřídní OOP, 0ms cache bajtkódu, vestavěné SQLite JDBC a vlastní soubory .jar.","hero_tag":"OFFLINE JAVA 17 · VÍCETŘÍDNÍ OOP &amp; JDBC","hero_h1":"Kompilujte a spouštějte <span class=\"text-gradient\">Java 17 a vícetřídní OOP</span> offline na Androidu.","hero_desc":"Navrženo pro vysokoškolské kurzy Javy, AP Computer Science, prototypování backendu i pohovory. Pište <strong>Java 17 records, sealed třídy a Streams</strong> offline s <strong>0ms opakovaným spuštěním z cache</strong>, <strong>vestavěným SQLite JDBC</strong> a živým <strong><code>Scanner(System.in)</code></strong>.","table_h2":"SuperCode Java 17 IDE vs. zastaralé Java kompilátory pro Android","snippet_p":"<strong>SuperCode Java IDE</strong> je offline kompilátor Java 17 a prostředí pro vícetřídní OOP na Androidu. Podporuje moderní Java 17 records, sealed třídy, výrazy switch, Streams, kompaktní void main(), 0ms spuštění z cache, vestavěné offline SQLite JDBC, vlastní knihovny .jar a interaktivní konzolový vstup Scanner(System.in).","table_caption":"SROVNÁNÍ JAVA IDE A KOMPILÁTORŮ PRO ANDROID","faq_lead":"Časté dotazy k funkcím Java 17, vícesouborovému OOP, vlastním .jar souborům a offline vstupu Scanner.","cta_h2":"Pište a spouštějte moderní Java 17 kdekoli na Androidu.","cta_desc":"Stáhněte si SuperCode IDE na Google Play — s offline Java 17, SQLite JDBC, AST doplňováním a vizuálním Git.","th_0":"Funkce Javy","th_1":"SuperCode Java 17 IDE","th_2":"Starší mobilní Java aplikace","th_3":"Online Java kompilátory","th_4":"Vzdálená desktopová IDE","tr1_c0":"Verze Javy","tr1_c1":"Offline Java 17 + Cloud Java 21+","tr1_c2":"Uvízlé na Java 7 nebo Java 8","tr1_c3":"Vyžaduje internet","tr1_c4":"Vyžaduje vzdálené PC","tr2_c0":"Více tříd &amp; .jar","tr2_c1":"Auto-spuštění více balíčků + libs/*.jar + Cache","tr2_c2":"Ruční nastavení hlavní třídy","tr2_c3":"Vložení jediného souboru","tr2_c4":"Náročný Gradle build","tr3_c0":"Připojení k databázi","tr3_c1":"Vestavěný offline ovladač jdbc:sqlite","tr3_c2":"Není součástí","tr3_c3":"Pouze dočasná paměť","tr3_c4":"Ruční nastavení Mavenu","tr4_c0":"Ergonomie pro studenty","tr4_c1":"Kompaktní void main() + čisté stack traces","tr4_c2":"Pouze zdlouhavý boilerplate","tr4_c3":"Bez offline přístupu","tr4_c4":"Nepřizpůsobeno dotyku","tr5_c0":"Integrovaný workflow","tr5_c1":"Java + SQL Explorer + Vizuální Git + SFTP","tr5_c2":"Izolovaný Java sandbox","tr5_c3":"Jen záložka prohlížeče","tr5_c4":"Vysoká spotřeba baterie a dat","faq1_q":"Jakou verzi Javy kompiluje SuperCode offline na Androidu?","faq1_a":"SuperCode kompiluje a spouští Java 17 offline — včetně records, sealed tříd, výrazů switch, pattern matchingu pro instanceof, textových bloků a Streams — s automatickým směrováním na Cloud Java pro funkce Java 21+.","faq2_q":"Mohu spustit Java projekt s více třídami a balíčky?","faq2_a":"Ano. SuperCode vyřeší všechny soubory .java napříč složkami projektu i otevřenými kartami editoru, automaticky určí třídu s metodou main() a synchronizuje veškeré zapsané soubory zpět do pracovního prostoru.","faq3_q":"Mohu Javu připojit k lokální databázi SQLite nebo přidat externí soubory .jar?","faq3_a":"Ano! Offline ovladač jdbc:sqlite:... JDBC je vestavěn přímo v aplikaci a jakékoli kompatibilní knihovny .jar umístěné ve složce libs/ vašeho projektu se automaticky přidají do classpath.","faq4_q":"Funguje Scanner(System.in) interaktivně?","faq4_a":"Ano. Program se čistě pozastaví, kdykoli Scanner nebo BufferedReader čeká na vstup, a umožní vám psát více řádků v rozděleném terminálu.","wb_eyebrow":"INTERAKTIVNÍ PRACOVIŠTĚ JAVA 17 &amp; JDBC","sec_cap_title":"Síla moderní Java 17 bez zátěže desktopu","sec_cap_lead":"Vše od prvních kompaktních metod main() až po vícebalíčkové databázové JDBC projekty běží přímo na vašem zařízení Android.","f1_title":"Moderní offline syntaxe Java 17 &amp; kompaktní main()","f1_desc":"Používejte třídy record, rozhraní sealed, výrazy switch -&gt;, pattern matching pro instanceof, textové bloky (\"\"\"\"), Streams, java.time a stručné metody void main() 100% offline.","f1_badge":"Records · Sealed · Switch -&gt; · Textové bloky · Streams","f2_title":"Vícebalíčkové OOP &amp; 0ms cache bajtkódu","f2_desc":"Kompiluje vícesouborové balíčky napříč otevřenými kartami a složkami projektu, automaticky najde vstupní třídu s main() a ukládá bajtkód podle hashe pro okamžité ⚡ Cache spuštění.","f2_badge":"Vícebalíčkové třídy · Auto-výběr main() · ⚡ Cache","f3_title":"Vestavěné offline SQLite JDBC &amp; vlastní libs/*.jar","f3_desc":"Připojte se přímo k lokálním databázím přes DriverManager.getConnection(\"jdbc:sqlite:app.db\") bez stahování ovladačů, nebo vložte vlastní knihovny .jar do složky libs/ projektu.","f3_badge":"jdbc:sqlite připraveno · Vlastní .jar Classpath","f4_title":"Živý Scanner(System.in) &amp; čisté stack traces","f4_desc":"Podporuje interaktivní smyčky Scanner a BufferedReader s ovládáním [EOF], bezpečně zachytává System.exit() bez zavření aplikace a odstraňuje interní šum ze stack traces výjimek.","f4_badge":"Živý System.in · Bezpečný System.exit() · Čistá diagnostika","f5_title":"AST doplňování Javy, formátovač &amp; 8 šablon","f5_desc":"Pište kód rychle s 21klávesovou lištou symbolů Java/Kotlin, offline AST doplňováním, formátováním jedním klepnutím a 8 vestavěnými šablonami OOP a datových struktur.","f5_badge":"AST doplňování · Java formátovač · 8 Java ukázek","f6_title":"Automatické směrování na Cloud Java 21+ &amp; SE","f6_desc":"Testujete syntaxi Java 21+ nebo balíčky Standard Edition nedostupné na mobilu? SuperCode automaticky zabalí vaše třídy a spustí je na Cloud Java.","f6_badge":"Záložní Java 21+ · Vícesouborový Cloud Bundler","workflow_title":"Jak vytvářet vícetřídní Java projekty v SuperCode","workflow_lead":"Ideální pro výuku OOP, datové struktury a databázové Java aplikace.","wf_foot_note":"15s Watchdog · Ochrana kvóty vláken · Vestavěné SQLite JDBC","wf1_title":"Vytvořte Java třídy &amp; volitelné knihovny .jar","wf1_desc":"Uspořádejte třídy .java do balíčků (a volitelné soubory .jar do libs/) s offline AST doplňováním a automatickými závorkami i importy.","wf2_title":"Formátujte bloky Javy &amp; ověřte syntaxi","wf2_desc":"Klepnutím na Formátovat čistě zarovnejte třídy, metody a Javadoc komentáře a v Error Radaru zkontrolujte neuzavřené závorky či literály.","wf3_title":"Kompilujte offline do bajtkódu v cache","wf3_desc":"SuperCode zkompiluje vaše zdrojové kódy Java 17 přímo v zařízení (offline Java SDK stáhne jen při prvním spuštění) a uloží bajtkód do cache pro okamžité opakované spuštění.","wf4_title":"Interagujte přes System.in &amp; synchronizujte soubory","wf4_desc":"Zadávejte konzolové vstupy živě, dotazujte lokální databáze SQLite přes JDBC a prohlížejte vygenerované soubory automaticky synchronizované do pracovního prostoru."},"js_ide":{"metaTitle":"JavaScript IDE a offline aplikace Node/ES2024 pro Android — fs, Crypto a ESM | SuperCode","metaDesc":"Spouštějte samostatný ES2024 JavaScript a 29+ základních modulů Node.js (fs, path, crypto, stream, zlib) offline na Androidu. Podporuje ESM a CommonJS, Web Crypto AES-GCM, <1ms ochranu proti smyčkám a Cloud Node.js.","hero_tag":"SAMOSTATNÉ STUDIO ES2024 JAVASCRIPT &amp; MODULY","hero_h1":"Spouštějte samostatný <span class=\"text-gradient\">ES2024 JavaScript a moduly</span> offline v izolaci bez zamrzání.","hero_desc":"Pro testování logiky v JavaScriptu už nemusíte obalovat skripty do HTML. Spouštějte <strong>ES2024 <code>async/await</code></strong>, <strong>vícesouborové moduly ESM a CommonJS</strong> i <strong>algoritmy</strong> přímo v izolované konzoli workeru s <strong>ochranou proti smyčkám pod &lt;1ms</strong>.","table_h2":"SuperCode JavaScript IDE vs. provizorní konzole prohlížeče","snippet_p":"<strong>SuperCode JavaScript IDE</strong> je specializovaný offline spouštěč ES2024 JavaScriptu a modulární editor kódu pro Android. Spouští vícesouborové skripty ES Modules a CommonJS v izolovaném vlákně workeru mimo UI s podmilisekundovou ochranou proti nekonečným smyčkám, strukturovaným výstupem konzole, AST doplňováním a podporou Cloud Node.js.","table_caption":"MATICE SPUŠTĚNÍ JAVASCRIPTU A EDITORŮ PRO ANDROID","faq_lead":"Odpovědi ke spouštění souborů .js bez HTML, ES modulům, nekonečným smyčkám a modulům Node.js.","cta_h2":"Pište a spouštějte moderní ES2024 JavaScript kdekoli.","cta_desc":"Nainstalujte si SuperCode IDE z Google Play pro samostatné offline JS moduly, AST doplňování a full-stack Web DevTools.","th_0":"Funkce JS","th_1":"SuperCode JS IDE","th_2":"Pouze HTML webové editory","th_3":"Online JS sandboxy","th_4":"CLI Node instalace","tr1_c0":"Samostatný běh JS","tr1_c1":"Přímé spuštění .js / .mjs / .cjs offline","tr1_c2":"Vyžaduje prázdný HTML soubor","tr1_c3":"Vyžaduje internet","tr1_c4":"100MB+ CLI instalace","tr2_c0":"Systém modulů","tr2_c1":"Lokální ESM import/export + CommonJS + .json","tr2_c2":"Často selhává na file:// CORS","tr2_c3":"Jeden soubor nebo pomalé CDN","tr2_c4":"Podporováno","tr3_c0":"Ochrana nekonečných smyček","tr3_c1":"Izolovaný Worker (&lt;1ms ukončení, 0 záseků)","tr3_c2":"Zamrzne celé UI WebView","tr3_c3":"Zasekne kartu mobilního prohlížeče","tr3_c4":"Ruční ukončení","tr4_c0":"Formátování JS/TS","tr4_c1":"100% offline formátovač JS/TS/JSX/JSON","tr4_c2":"Základní nebo vyžaduje pluginy","tr4_c3":"Pouze online","tr4_c4":"Vyžaduje npm prettier","tr5_c0":"Node.js API","tr5_c1":"Automaticky zabalí lokální moduly pro Cloud Node.js","tr5_c2":"Pouze API prohlížeče","tr5_c3":"Pouze API prohlížeče","tr5_c4":"Pouze lokální CLI","faq1_q":"Mohu na Androidu spustit soubor .js přímo bez vytváření HTML stránky?","faq1_a":"Ano! Klepnutím na Spustit u libovolného souboru .js, .mjs nebo .cjs se okamžitě otevře samostatná JavaScript konzole SuperCode — zcela offline.","faq2_q":"Mohu rozdělit JavaScript kód do více souborů pomocí import/export nebo require()?","faq2_a":"Ano. Jak ES Modules (import / export), tak CommonJS (require / module.exports) i importy .json fungují napříč lokálními soubory projektu a neuloženými kartami.","faq3_q":"Zamrzne editor při nechtěné smyčce while(true) nebo přijdu o neuložený kód?","faq3_a":"Nikdy. Skripty běží v izolovaném workeru na pozadí pod dohledem 15sekundového watchdogu a pojistky proti zahlcení výstupu, takže zacyklený kód ukončí pod 1 milisekundu bez dopadu na vlákno UI.","faq4_q":"Co když chci vytvořit vizuální DOM web s HTML, CSS a WebAssembly?","faq4_a":"SuperCode umí obojí! Použijte samostatné JavaScript IDE pro čisté moduly JS/Node a algoritmy, a Full-Stack Web &amp; PHP Studio, kdykoli chcete živé HTTP DOM vykreslování, responzivní viewporty a Web DevTools.","wb_eyebrow":"SAMOSTATNÁ KONZOLE JAVASCRIPT WORKERU","sec_cap_title":"Skutečný samostatný JavaScript runtime oddělený od karet prohlížeče","sec_cap_lead":"Testujte datové struktury, asynchronní pipeline, transformace JSON a modulární balíčky s okamžitou odezvou a diagnostikou přesně na řádek.","f1_title":"Plná offline podpora jazyka ES6–ES2024","f1_desc":"Spouštějte async/await, Promise.allSettled/any, generátory, privátní pole tříd (#), optional chaining (?.), nullish coalescing (??), BigInt, structuredClone, časovače a performance.now() offline.","f1_badge":"ES2024 · BigInt · Privátní #Pole · structuredClone","f2_title":"Vícesouborové propojování ES Modules &amp; CommonJS","f2_desc":"Importujte lokální moduly .js, .mjs, .cjs a .json volně pomocí import/export nebo require()/module.exports — včetně neuložených otevřených karet a chytrého výběru vstupního souboru.","f2_badge":"import / export · require() · Importy modulů .json","f3_title":"Izolace workeru mimo UI &amp; &lt;1ms ukončení smyček","f3_desc":"Běží na vyhrazeném vlákně workeru na pozadí místo na vlákně UI. I těsná nekonečná smyčka while(true){} je čistě ukončena pod 1ms bez jakéhokoli záseku editoru.","f3_badge":"Nulové zamrzání UI · 15s Watchdog · Chyby 1:1 na řádek","f4_title":"Strukturovaná konzole &amp; interaktivní Stdin","f4_desc":"Prohlížejte přehledně vnořené objekty, pole, úrovně console.warn/error i přesné časovače a přijímejte živý interaktivní vstup pro CLI cvičení v JavaScriptu.","f4_badge":"Strukturované objekty · Živý vstup · Rozdělená konzole","f5_title":"AST doplňování JS/TS &amp; formátování ve stylu Prettier","f5_desc":"Obsahuje vyhrazený 21klávesový profil symbolů JS/TS (=&gt;, ?., ===, ``, ${}), offline AST doplňování pro Array/Promise/JSON/Math/DOM a atomické formátování JS/TS/JSON.","f5_badge":"Lišta symbolů JS/TS · AST doplňování · Validátor JSON","f6_title":"Automatický vícesouborový bundler Cloud Node.js","f6_desc":"Importujete základní API Node.js (http, fs, crypto, child_process) nebo používáte // @cloud? SuperCode automaticky zabalí vaše lokální moduly do jednotného balíčku Node.js.","f6_badge":"Detekce Node.js API · Vícemodulový Cloud Bundle","workflow_title":"Jak vytvářet a testovat modulární JavaScript v SuperCode","workflow_lead":"Ideální pro LeetCode v JS, modulární utility, modelování API payloadů a testování frontendové logiky.","wf_foot_note":"6 vestavěných JavaScript ukázek · Podporuje .js · .mjs · .cjs · .ts · .json","wf1_title":"Vytvořte samostatné soubory .js, .mjs, .cjs nebo .json","wf1_desc":"Pište čistý JavaScript nebo modulární balíčky přímo — bez nutnosti obalu index.html.","wf2_title":"Pište čisté async a arrow funkce","wf2_desc":"Používejte =&gt;, ?., === a zpětné apostrofy template literálů jedním klepnutím s offline AST doplňováním a rychlým formátováním JS.","wf3_title":"Spusťte okamžitě v izolované konzoli workeru","wf3_desc":"Klepněte na Spustit pro propojení lokálních modulů, prohlédnutí strukturovaného výstupu konzole a ověření času běhu v milisekundách.","wf4_title":"Přepněte na živý náhled DOM nebo odešlete do Git","wf4_desc":"Potřebujete plný DOM/Canvas/WASM prohlížeče? Spárujte skripty se souborem .html ve Web Studiu nebo commitujte přímo přes Vizuální Git."},"lua_ide":{"metaTitle":"Lua IDE a offline aplikace Lua 5.4 pro Android — herní skriptování, cjson a SQLite | SuperCode","metaDesc":"Pište a spouštějte nativní skripty Lua 5.4.7 offline na Androidu v řádu mikrosekund. Obsahuje 11+ vestavěných modulů (cjson, lsqlite3, lfs, crypto, socket), metatabulky, korutiny, bitové operace a AST doplňování . vs :.","hero_tag":"NATIVNÍ OFFLINE STUDIO PRO LUA 5.4.7 SKRIPTOVÁNÍ","hero_h1":"Submilisekundové <span class=\"text-gradient\">offline Lua 5.4 IDE</span> pro herní logiku &amp; skriptování.","hero_desc":"Ať už prototypujete herní stavové automaty, vestavěné skripty nebo automatizační pravidla, spouštějte <strong>nativní Lua 5.4.7</strong> offline v <strong>mikrosekundách</strong> se <strong>vícesouborovým <code>require()</code></strong>, <strong>AST doplňováním <code>.</code> vs <code>:</code></strong> a živým vstupem <strong><code>io.read()</code></strong>.","table_h2":"SuperCode Lua 5.4 Studio vs. běžné mobilní editory","snippet_p":"<strong>SuperCode Lua IDE</strong> je nativní offline studio pro skriptování v Lua 5.4.7 na Androidu. Nabízí submilisekundové spouštění s telemetrií mikrosekund a paměti, vícesouborové řešení require(), AST našeptávání rozlišující metody (. vs :), formátování Lua jedním klepnutím a interaktivní vstup konzole io.read().","table_caption":"SROVNÁNÍ IDE PRO SKRIPTOVÁNÍ V LUA 5.4 NA ANDROIDU","faq_lead":"Dotazy k offline syntaxi Lua 5.4, vícesouborovému require() a hernímu skriptování.","cta_h2":"Spouštějte nativní Lua 5.4 skripty na Androidu v mikrosekundách.","cta_desc":"Stáhněte si SuperCode IDE na Google Play pro offline Lua 5.4.7, AST doplňování a vícesouborové workspace.","th_0":"Funkce Lua","th_1":"SuperCode Lua 5.4 IDE","th_2":"Obyčejné textové editory Lua","th_3":"Webové Lua ukázky","tr1_c0":"Verze runtime","tr1_c1":"Nativní offline Lua 5.4.7 (~400 µs)","tr1_c2":"Bez vestavěného spouštění","tr1_c3":"Pouze online","tr2_c0":"Řešení modulů","tr2_c1":"Vícesouborové require() + neuložené karty","tr2_c2":"Žádné","tr2_c3":"Jen jeden snippet","tr3_c0":"Inteligence pro Lua","tr3_c1":"Rozlišuje . funkce vs : metody + formátovač","tr3_c2":"Základní zvýraznění klíčových slov","tr3_c3":"Prosté textové pole","tr4_c0":"Interaktivní I/O","tr4_c1":"Živé io.read() + synchronizace souborů workspace","tr4_c2":"Žádné","tr4_c3":"Statický výstup","tr5_c0":"Interop &amp; cloud","tr5_c1":"luajava.* Interop + cloud lpeg/socket/lfs","tr5_c2":"Žádné","tr5_c3":"Žádné","faq1_q":"Jaká verze Lua běží v SuperCode offline?","faq1_a":"SuperCode nativně integruje Lua 5.4.7 pro 100% offline běh s podporou celočíselného dělení (//), bitových operátorů, atributů &lt;const&gt; a &lt;close&gt;, korutin, metatabulek a utf8.","faq2_q":"Mohu rozdělit Lua skripty do více souborů a používat require()?","faq2_a":"Ano. require() automaticky prohledává adresář projektu i otevřené karty editoru a všechny soubory vytvořené pomocí io.open() se synchronizují zpět do stromu Průzkumníka.","faq3_q":"Umí SuperCode formátovat Lua kód offline?","faq3_a":"Ano. Formátování jedním klepnutím offline přehledně odsadí function, if/then/else, for/do, repeat/until i konstruktory tabulek.","wb_eyebrow":"INTERAKTIVNÍ PRACOVNÍ PROSTŘEDÍ LUA 5.4.7","sec_cap_title":"Blesková rychlost a plná inteligence IDE pro Lua","sec_cap_lead":"Špičková editace, formátování a spouštění více modulů Lua přímo v kapse.","f1_title":"Nativní Lua 5.4.7 s mikrosekundovou telemetrií","f1_desc":"Podporuje // celočíselné dělení, bitové operátory (&amp; | ~ &lt;&lt; &gt;&gt;), proměnné &lt;const&gt; a &lt;close&gt;, korutiny, metatabulky, string.pack/unpack a utf8 — s přesným výpisem času v µs a paměti v KB.","f1_badge":"Lua 5.4.7 · Měření v µs · Telemetrie paměti v KB","f2_title":"Vícesouborové require() &amp; synchronizace souborů workspace","f2_desc":"Organizujte herní entity a utility do podsložek; require('modules.vec2') plynule najde uložené soubory i neuložené karty a zápisy io.open() se synchronizují zpět do stromu.","f2_badge":"Vícesouborové require() · Řízení vstupního bodu · Synchronizace souborů","f3_title":"AST doplňování (. vs :) podle metod &amp; formátovač","f3_desc":"SuperCode rozlišuje funkce tabulek (string., table., math.) od metod s dvojtečkou (str:, customObj:), doplněné o vyhrazený offline formátovač Lua a komentování `--` / `--[[ ]]`.","f3_badge":"Doplňování . vs : · Offline formátovač Lua","f4_title":"Interaktivní konzole io.read() &amp; bezpečnostní limity","f4_desc":"Testujte interaktivní textové hry a CLI nástroje s živými výzvami io.read(), chráněné adaptivním limitem paměti VM a časovým limitem CPU.","f4_badge":"Živé io.read() · 8 Lua ukázek · Cloud podpora C modulů","workflow_title":"Jak prototypovat vícemodulové Lua skripty na Androidu","workflow_lead":"Rychlé iterace od jednoho souboru k modulární herní logice.","wf_foot_note":"Podporuje nativní Lua 5.4.7 · Java luajava.* Interop · Cloud Lua moduly","wf1_title":"Vytvořte Lua skripty nebo načtěte ukázku","wf1_desc":"Vyberte si z 8 vestavěných Lua ukázek nebo vytvořte vícesouborové moduly v Průzkumníku.","wf2_title":"Upravujte s doplňováním tabulek &amp; formátujte","wf2_desc":"Napište : nebo . u standardních knihoven a vlastních tabulek pro okamžité offline návrhy a pak klepněte na Formátovat.","wf3_title":"Spouštějte offline v mikrosekundách","wf3_desc":"Spouštějte ihned s živým vstupem io.read() a sledujte přesnou telemetrii v mikrosekundách a kilobajtech.","wf4_title":"Synchronizujte skripty do herních enginů nebo na servery","wf4_desc":"Odešlete Lua moduly do repozitářů Git nebo na vzdálené servery přes SFTP jediným klepnutím."},"shell_ide":{"metaTitle":"Spouštěč Shell skriptů (.sh bez rootu) a Kotlin aplikace pro Android — Bash & awk | SuperCode","metaDesc":"Spouštějte linuxové .sh shell skripty bez rootu a kompilujte Kotlin (.kt/.kts) na Androidu. Provádějte roury awk, sed, grep, curl a bc offline, přepněte na Ubuntu Bash 5.2 a nasazujte přes SFTP a Visual Git.","hero_tag":"NATIVNÍ LINUX SHELL (.SH) &amp; KOTLIN STUDIO","hero_h1":"Automatizujte pomocí <span class=\"text-gradient\">linuxových Shell rour &amp; Kotlinu</span> na Androidu.","hero_desc":"Pište, formátujte a spouštějte <strong><code>.sh</code> shell skripty</strong> lokálně s nativními rourami <strong><code>grep</code>, <code>awk</code>, <code>sed</code>, <code>sort</code> &amp; <code>find</code></strong> synchronizovanými s vaší složkou — navíc s plynulým cloudovým spouštěním <strong>Ubuntu Bash 5.2</strong> a <strong>Kotlin (<code>.kt</code>)</strong>.","table_h2":"Srovnání SuperCode Shell &amp; Kotlin Studia","snippet_p":"<strong>SuperCode Shell &amp; Kotlin Studio</strong> umožňuje vývojářům na Androidu lokálně upravovat, formátovat a spouštět linuxové shellové (.sh) roury pomocí grep, awk, sed a sort s automatickou synchronizací složky projektu a plynulou cloudovou kompilací GNU Bash 5.2 a Kotlin (.kt).","table_caption":"MATICE PRO SHELL SKRIPTOVÁNÍ &amp; KOTLIN WORKSPACE NA ANDROIDU","faq_lead":"Odpovědi ke spouštění souborů .sh v úložišti Androidu, rourám awk/sed a běhu Kotlinu.","cta_h2":"Spouštějte Shell skripty &amp; Kotlin odkudkoli z telefonu.","cta_desc":"Nainstalujte si SuperCode IDE z Google Play pro nativní linuxové shell roury, běh Kotlinu a serverové nástroje SFTP.","th_0":"Funkce","th_1":"SuperCode Shell + Kotlin","th_2":"Holé terminálové aplikace","th_3":"Základní prohlížeče skriptů","tr1_c0":"Běh .sh ve sdíleném úložišti","tr1_c1":"Běží spolehlivě i přes noexec omezení Androidu","tr1_c2":"Permission denied na /sdcard","tr1_c3":"Nelze spustit","tr2_c0":"Editor skriptů &amp; formátování","tr2_c1":"AST nápověda + offline formátovače Shell a Kotlin","tr2_c2":"Jen malý CLI nano/vi","tr2_c3":"Pouze zvýraznění syntaxe","tr3_c0":"GNU Bash 5 &amp; Kotlin","tr3_c1":"Vestavěný cloudový Ubuntu Bash 5.2 + Kotlin runner","tr3_c2":"Těžkopádný ruční rootfs/JDK","tr3_c3":"Nepodporováno","tr4_c0":"Nasazení na server","tr4_c1":"Přímé atomické uložení přes SFTP + Visual Git","tr4_c2":"Ruční příkazy scp","tr4_c3":"Žádné","faq1_q":"Proč dokáže SuperCode spouštět .sh skripty v běžných složkách projektu, když Android blokuje chmod +x ve sdíleném úložišti?","faq1_a":"SuperCode transparentně připraví skript a zarovná $PWD s nativním shellovým prostředím Androidu a všechny vytvořené nebo upravené výstupní soubory synchronizuje zpět do složky projektu.","faq2_q":"Mohu v SuperCode psát a spouštět kód v jazyce Kotlin (.kt)?","faq2_a":"Ano! SuperCode nabízí kompletní zvýraznění syntaxe Kotlin &amp; Gradle (.kt, .kts, .gradle.kts), offline AST doplňování, offline formátování kódu a cloudovou kompilaci i spuštění Kotlinu jedním klepnutím.","faq3_q":"Co se stane, když můj skript používá asociativní pole GNU Bash 5, která ve výchozím sh na Androidu chybí?","faq3_a":"SuperCode rozpozná syntaxi specifickou pro Bash nebo direktivy # @cloud a automaticky přesměruje skripty vašeho workspace do prostředí Ubuntu GNU Bash 5.2.","wb_eyebrow":"INTERAKTIVNÍ PROSTŘEDÍ PRO SHELL ROURY &amp; KOTLIN","sec_cap_title":"Čisté psaní skriptů, lokální textové roury &amp; podpora Kotlinu","sec_cap_lead":"Spojte dotykově přívětivou editaci a formátování skriptů se skutečným spouštěním rour — bez přepínání do externích terminálů.","f1_title":"Nativní běh OS Shellu &amp; Toybox roury","f1_desc":"Spouštějte .sh skripty lokálně pomocí grep, awk, sed, sort, uniq, wc, cut, tr, find, cat a přesměrování souborů — i ve sdíleném úložišti Androidu, kde běžný chmod +x selhává.","f1_badge":"grep · awk · sed · sort · uniq · find · Roury","f2_title":"Načítání více skriptů &amp; synchronizace artefaktů workspace","f2_desc":"Vkládejte pomocné .sh skripty přes source napříč složkou, přijímejte živý interaktivní vstup read a sledujte, jak se nové sestavy nebo upravené soubory automaticky objevují v Průzkumníku.","f2_badge":"Vícesouborový source · Živý read Stdin · Synchronizace souborů","f3_title":"GNU Bash 5.2 &amp; cloudové studio Kotlin (.kt) jedním klepnutím","f3_desc":"Potřebujete asociativní pole GNU Bash 5 nebo chcete kompilovat datové třídy, korutiny a funkcionální kód v Kotlinu? SuperCode je čistě směruje do vyhrazených cloudových běhových prostředí.","f3_badge":"Ubuntu Bash 5.2 · Běh Kotlin .kt / .kts","f4_title":"AST doplňování pro Shell &amp; Kotlin + offline formátovače","f4_desc":"Obsahuje nápovědu expanze ${var:-default} v shellu, AST doplňování pro Kotlin, offline formátovače pro Shell i Kotlin/Gradle a 6 vestavěných šablon Shellu.","f4_badge":"Formátovače Shell + Kotlin · Zvýraznění Dockerfile/Makefile","workflow_title":"Jak spouštět Shell automatizace &amp; snippety v Kotlinu","workflow_lead":"Uhlazený postup pro DevOps skripty, zpracování logů a procvičování Kotlinu.","wf_foot_note":"6 vestavěných Shell ukázek · 120s watchdog stromu procesů · Zachování oprávnění přes SFTP","wf1_title":"Vytvořte Shell skript nebo soubor Kotlin","wf1_desc":"Pište soubory .sh, .bash, Makefile, Dockerfile nebo .kt s vyhrazenými klávesami symbolů a zvýrazněním syntaxe.","wf2_title":"Automaticky formátujte cykly, větvení &amp; bloky Kotlinu","wf2_desc":"Naformátujte shellové if/fi, case/esac a třídy Kotlinu offline jediným klepnutím.","wf3_title":"Spouštějte lokálně nebo v cloudovém Bash / Kotlinu","wf3_desc":"Spouštějte POSIX shellové roury lokálně přímo v zařízení, nebo plynule běžte kód GNU Bash 5.2 a Kotlin.","wf4_title":"Nasazujte skripty přímo na produkční servery","wf4_desc":"Nahrávejte ověřené shell skripty přes SFTP (se zachováním POSIX oprávnění!) nebo je commitujte přes Visual Git."},"web_ide":{"metaTitle":"Web & PHP 8.2 IDE pro Android — Offline HTML, CSS, JS, PDO SQLite a WASM server | SuperCode","metaDesc":"Full-stack offline Web & PHP 8.2 IDE pro Android. Skutečný lokální HTTP server pro HTML5, CSS3, ES moduly, WebAssembly (.wasm), PHP $_SESSION + databáze PDO SQLite, DevTools REPL se 3 náhledy a SFTP nasazení.","hero_tag":"FULL-STACK WEB · PHP · WASM · SQL · SFTP STUDIO","hero_h1":"Full-stack <span class=\"text-gradient\">Web, offline PHP &amp; WASM</span> studio s vestavěnými DevTools.","hero_desc":"Žádný statický prohlížeč <code>file://</code> — kompletní full-stack webový server v kapse. Spouštějte <strong>HTML5, CSS3, ES moduly a WebAssembly (<code>.wasm</code>)</strong> spolu s <strong>offline dynamickým PHP</strong>, <strong>databázemi PDO SQLite</strong>, <strong>responzivními DevTools</strong> a přímým <strong>FTP/SFTP publikováním</strong>.","table_h2":"SuperCode Web &amp; PHP Studio vs. mobilní prohlížeče HTML","snippet_p":"<strong>SuperCode Web &amp; PHP Studio</strong> je full-stack offline IDE pro vývoj webu na Androidu. Obsahuje skutečný lokální HTTP server s podporou HTML5, CSS3, ES modulů, WebAssembly (.wasm), dynamického PHP s databázemi PDO SQLite, přepínače 3 responzivních náhledů, Web DevTools s JS REPL a živého nasazení přes SFTP.","table_caption":"MATICE FULL-STACK VÝVOJE WEBU A PHP NA ANDROIDU","faq_lead":"Odpovědi k offline PHP + SQLite, ES modulům / fetch() / WASM, Web DevTools a nasazení přes FTP/SFTP.","cta_h2":"Mějte full-stack HTML, WASM, PHP a SQL server vždy v kapse.","cta_desc":"Stáhněte si SuperCode IDE z Google Play a vytvářejte, laďte i nasazujte kompletní webové aplikace přímo z Androidu.","th_0":"Webová funkce","th_1":"SuperCode Web + PHP Studio","th_2":"Základní mobilní HTML editory","th_3":"Cloudová vývojová prostředí","tr1_c0":"Původ serveru a WASM","tr1_c1":"Skutečné lokální HTTP + ES moduly + .wasm streaming","tr1_c2":"file:// CORS blokuje fetch a moduly","tr1_c3":"Vyžaduje internet","tr2_c0":"Backend PHP a SQL","tr2_c1":"100% offline PHP + $_SESSION + PDO SQLite","tr2_c2":"Pouze statický frontend HTML/JS","tr2_c3":"Placený cloudový kontejner","tr3_c0":"Responzivita a DevTools","tr3_c1":"Mobil/Tablet/Desktop + síťový log + živý JS REPL","tr3_c2":"Jen základní alert() nebo textový log","tr3_c3":"Stísněné desktopové UI na telefonu","tr4_c0":"Média a exporty","tr4_c1":"Nahrávání z kamery/souborů + Canvas/Blob + 2560px PNG","tr4_c2":"Nefunkční &lt;input type=file&gt; a blob:","tr4_c3":"Nutné stažení ze serveru","tr5_c0":"Vzdálený hosting","tr5_c1":"Živý náhled SFTP/FTPS + 3fázové atomické uložení","tr5_c2":"Ruční externí FTP klient","tr5_c3":"Uzamčeno v cloudu","faq1_q":"Mohu na Androidu spouštět dynamické PHP weby a připojovat se k SQL databázím offline?","faq1_a":"Ano! SuperCode spouští .php stránky, REST JSON endpointy, session, nahrávání formulářů i vícesouborové include příkazy zcela offline, s vestavěnou podporou databází PDO('sqlite:...') a SQLite3.","faq2_q":"Fungují ES6 moduly (&lt;script type=\"module\"&gt;), fetch() a WebAssembly (.wasm)?","faq2_a":"Ano. Protože SuperCode servíruje projekt přes skutečný lokální HTTP server s více než 65 MIME typy (včetně application/wasm), fungují fetch(), ES moduly, WebGL 3D modely i WebAssembly.instantiateStreaming() ihned bez nastavování.","faq3_q":"Jak na telefonu ladit chyby JavaScriptu, síťové požadavky a desktopová rozvržení?","faq3_a":"Klepnutím na přetahovatelný prvek Dynamic Island v režimu náhledu přepínáte mezi náhledy Mobil, Tablet (768dp) a Desktop, případně otevřete posuvný panel Web DevTools pro filtrování logů Error/Warn/Net a spouštění živého JavaScriptu v REPL.","faq4_q":"Mohu si prohlížet a upravovat weby hostované na vzdáleném FTP nebo SFTP serveru?","faq4_a":"Ano. Připojte server v pracovním prostoru SFTP/FTPS/FTP, upravujte vzdálené karty HTML/CSS/JS/PHP přímo s 3fázovým atomickým ukládáním a klepnutím na Spustit zobrazte náhled vzdálených stránek s kešováním assetů na vyžádání.","wb_eyebrow":"FULL-STACK HTTP, OFFLINE PHP, WASM &amp; DEVTOOLS PROSTŘEDÍ","sec_cap_title":"Šest propojených vrstev moderního webového vývoje na Androidu","sec_cap_lead":"Frontendové ES moduly, binární WebAssembly, backendové PHP session, relační SQL databáze, inspekce v DevTools a vzdálené SFTP nasazení — vše v jednom.","f1_title":"Skutečný lokální HTTP původ pro HTML5, CSS3, JS a WASM","f1_desc":"Servíruje projekty přes skutečný lokální HTTP/1.1 původ místo nefunkčních URL file:// — odemyká tak fetch(), &lt;script type=\"module\"&gt;, WebAssembly.instantiateStreaming() (.wasm), WebGL assety .glb/.gltf, IndexedDB i HTTP 206 přetáčení videa a audia.","f1_badge":"65+ MIME typů · ES moduly · application/wasm · HTTP 206","f2_title":"100% offline dynamický PHP backend engine","f2_desc":"Spouštějte vícestránkové .php šablony, OOP třídy, uzávěry, match a include/require zcela offline s podporou $_GET, $_POST, perzistentní $_SESSION, nahrávání $_FILES, JSON REST hlaviček a password_hash().","f2_badge":"$_GET / $_POST / $_SESSION · JSON API · Offline PHP","f3_title":"Integrované SQL databáze přes PDO a SQLite3","f3_desc":"Vytvářejte datově řízené PHP aplikace offline pomocí new PDO('sqlite:app.db') nebo SQLite3 s parametrizovanými dotazy (? a :pojmenované vazby), ACID transakcemi a okamžitou inspekcí tabulek v SQL IDE.","f3_badge":"PDO('sqlite:...') · Prepared Statements · ACID transakce","f4_title":"Plovoucí konzole DevTools, síťový log a JS REPL","f4_desc":"Sledujte živé HTTP požadavky (GET /api.php -&gt; 200 · 3ms · 1,2 KB), filtrujte logy All / Error / Warn / Net, procházejte strukturované stromy DOM/objektů a vyhodnocujte výrazy živě v REPL &gt; Spustit JavaScript...","f4_badge":"Časování sítě · Odznak chyb · Interaktivní JS REPL","f5_title":"Přepínač 3 náhledů a snímek stránky v 2560px","f5_desc":"Přepínejte okamžitě mezi rozvržením Mobil, Tablet (768dp) a Desktop z přetahovatelného Dynamic Island, testujte nahrávání z kamery/galerie přes &lt;input type=\"file\"&gt; a exportujte ostré 2560px PNG snímky.","f5_badge":"Mobil / Tablet / Desktop · Export 2560px PNG","f6_title":"Živý vzdálený náhled a nasazení přes FTP / FTPS / SFTP","f6_desc":"Upravujete produkční web přes SFTP nebo FTPS? Klepnutím na Spustit zobrazíte náhled vzdálených stránek lokálně (s načítáním relativních CSS, JS a obrázků na vyžádání) a úpravy uložíte atomicky zpět na webhosting.","f6_badge":"Živý vzdálený náhled · Atomické publikování SFTP / FTPS","workflow_title":"Jak vytvořit, odladit a nasadit full-stack web na Androidu","workflow_lead":"Od lokálního prototypování v HTML/CSS/WASM a PHP+SQL až po ostré nasazení na server.","wf_foot_note":"Přejetím od levého okraje se vrátíte do Průzkumníku · Reset mezipaměti a session jedním klepnutím","wf1_title":"Pište soubory HTML5, CSS3, JS, WASM a PHP","wf1_desc":"Upravujte vícesouborové webové projekty s AST doplňováním kódu pro HTML/CSS/JS/PHP a rekurzivním formátováním jedním klepnutím, které zároveň odsadí vložené bloky &lt;script&gt; a &lt;style&gt;.","wf2_title":"Propojte offline PHP formuláře a API s SQL","wf2_desc":"Dotazujte lokální databáze .db SQLite z PHP pomocí PDO prepared statements nebo naplňte tabulky přímo v SQL Studiu v SuperCode.","wf3_title":"Náhled pro Mobil, Tablet a Desktop + DevTools","wf3_desc":"Přepínejte velikosti obrazovek za běhu, kontrolujte síťové stavy a chyby JS v posuvném panelu DevTools nebo testujte úpravy DOM živě v JS REPL.","wf4_title":"Publikujte změny přímo na hosting nebo GitHub Pages","wf4_desc":"Odešlete statické a WASM buildy na GitHub Pages přes Visual Git nebo nasaďte PHP a webové soubory přímo na svůj VPS přes SFTP/FTPS."},"sql_ide":{"metaTitle":"SQL IDE, prohlížeč SQLite .db a offline procvičování SQL pro Android — MySQL a JSON | SuperCode","metaDesc":"Offline SQL IDE, editor databází .db/.sqlite a aplikace pro procvičování SQL na Androidu. Okenní funkce, CTE, hledání FTS5, přes 50 funkcí MySQL/Postgres, 9 režimů výstupu, import CSV/JSON a cloudové MySQL 8.0.","hero_tag":"SPECIALIZOVANÉ OFFLINE SQL IDE &amp; PRŮZKUMNÍK .DB","hero_h1":"Spouštějte <span class=\"text-gradient\">moderní SQL a prohlížejte databáze .db</span> offline na Androidu.","hero_desc":"Navrženo pro databázové inženýry, datové analytiky a studenty SQL. Spouštějte <strong>okenní funkce, CTE, JSONB a fulltextové vyhledávání</strong> offline v <strong>9 formátovaných režimech výstupu</strong>, otevírejte binární <strong>soubory <code>.db/.sqlite</code></strong> jedním klepnutím a importujte <strong>datové sady CSV/JSON</strong>.","table_h2":"SuperCode SQL IDE vs. mobilní prohlížeče databází","snippet_p":"<strong>SuperCode SQL IDE</strong> je specializované offline prostředí pro spouštění SQL dotazů a správu databází na Androidu. Podporuje okenní funkce, rekurzivní CTE, cesty JSONB, fulltextové hledání, přes 60 statistických a regex funkcí, 9 výstupních formátů (Box, Markdown, CSV, JSON), inspekci .db/.sqlite jedním klepnutím, import CSV/JSON i cloudové MySQL 8.0.","table_caption":"SROVNÁNÍ SQL IDE A PROHLÍŽEČŮ DATABÁZÍ PRO ANDROID","faq_lead":"Odpovědi k offline procvičování SQL, otevírání souborů .db/.sqlite, importu CSV/JSON a syntaxi MySQL.","cta_h2":"Ovládněte SQL a spravujte databáze offline na Androidu.","cta_desc":"Nainstalujte si SuperCode IDE z Google Play a získejte kompletní offline spouštěč SQL, prohlížeč .db a datové studio pro CSV/JSON.","th_0":"Funkce SQL","th_1":"SuperCode SQL Studio","th_2":"Jednoduché prohlížeče tabulek .db","th_3":"Online SQL hřiště","tr1_c0":"Offline SQL engine","tr1_c1":"Okenní funkce + CTE + JSONB + FTS offline","tr1_c2":"Jen základní SELECT nebo GUI prohlížení","tr1_c3":"Vyžaduje internet","tr2_c0":"Režimy výstupu a exportu","tr2_c1":"9 režimů (Box, Markdown, CSV, JSON, INSERT...)","tr2_c2":"Jen pevná GUI tabulka","tr2_c3":"Jen webová HTML tabulka","tr3_c0":"Import dat a synchronizace","tr3_c1":"Import CSV, TSV a JSON polí + synchronizace projektu","tr3_c2":"Placená funkce nebo chybí","tr3_c3":"Ruční vkládání INSERT","tr4_c0":"Kompatibilita s MySQL","tr4_c1":"Lokální DDL kompatibilita + cloudové procedury MySQL 8.0","tr4_c2":"Pouze striktní syntaxe SQLite","tr4_c3":"Dočasná relace","tr5_c0":"Full-stack integrace","tr5_c1":"Sdílí .db soubory s lokálním PHP PDO a Java JDBC","tr5_c2":"Izolovaná prohlížecí aplikace","tr5_c3":"Izolovaná karta prohlížeče","faq1_q":"Mohu procvičovat SQL dotazy offline bez nastavování databázového serveru?","faq1_a":"Ano! Vytvořte libovolný soubor .sql a klepnutím na Spustit vykonejte vícepříkazové dotazy CREATE, INSERT, JOIN, CTE i okenní funkce 100% offline s formátovanými tabulkami Unicode Box Grid.","faq2_q":"Umí SuperCode otevřít existující soubory .db a .sqlite v mém telefonu?","faq2_a":"Ano. Klepnutím nebo spuštěním souboru .db, .sqlite, .sqlite3 či .db3 zobrazíte všechny tabulky, pohledy, indexy a schémata a jakýkoli .sql skript ve stejné složce projektu se na tuto databázi může přímo dotazovat.","faq3_q":"Podporuje syntaxi MySQL jako AUTO_INCREMENT, SHOW TABLES, DESCRIBE nebo uložené procedury?","faq3_a":"Běžné příkazy a DDL z MySQL/PostgreSQL (AUTO_INCREMENT, ENUM, SHOW TABLES, DESCRIBE, ILIKE) běží lokálně offline, zatímco serverové uložené procedury a triggery MySQL 8.0 se automaticky směrují do cloudu MySQL 8.0.","faq4_q":"Jak exportuji výsledky SQL dotazu do formátu CSV, Markdown nebo JSON?","faq4_a":"Před svůj dotaz SELECT přidejte `.mode csv` (nebo `.mode markdown` / `.mode json`) a `.once output.csv` — SuperCode zapíše exportovaný soubor přímo do složky projektu.","wb_eyebrow":"INTERAKTIVNÍ OFFLINE SQL &amp; DATABÁZOVÉ PROSTŘEDÍ","sec_cap_title":"SQL analytika desktopové třídy, inspekce souborů a flexibilita dialektů","sec_cap_lead":"Dotazujte sandboxy v paměti nebo trvalé vícetabulkové databázové soubory s přesným zarovnáním tabulek.","f1_title":"Moderní offline SQL: okenní funkce, CTE a JSONB","f1_desc":"Podporuje ROW_NUMBER/RANK/DENSE_RANK/LAG/LEAD OVER(...), WITH RECURSIVE CTE, RETURNING, UPSERT, dotazy JSON cest pomocí -&gt; a -&gt;&gt;, json_each() a fulltextové vyhledávání BM25 100% offline.","f1_badge":"Okenní funkce · Rekurzivní CTE · JSONB &amp; FTS","f2_title":"9 režimů vykreslování výsledků a exportní pipeline","f2_desc":"Ve výchozím nastavení prohlížejte výsledky v Unicode tabulkách (┌──┬──┐) se zarovnáním i pro CJK, nebo pomocí .mode přepněte na table, markdown, csv, tsv, json, line, list či SQL insert — a exportujte přímo přes .once.","f2_badge":"box · markdown · csv · json · table · insert","f3_title":"Inspektor .db / .sqlite na jedno klepnutí a auto-připojení","f3_desc":"Otevřete libovolný soubor .db, .sqlite, .sqlite3 nebo .db3 a okamžitě si prohlédněte metadata stránek, tabulky, pohledy, indexy a kompletní schémata CREATE. Dotazy ve stejné složce vaši databázi automaticky připojí!","f3_badge":"Přímé otevření .db / .sqlite3 · ATTACH DATABASE","f4_title":"Import CSV / TSV / JSON a přes 60 analytických funkcí","f4_desc":"Importujte CSV, TSV a JSON pole objektů přímo do automaticky typovaných tabulek (.import --csv / --json) a využijte přes 60 vestavěných funkcí jako SHA256, REGEXP_EXTRACT, MEDIAN, STDDEV, PERCENTILE a UUID.","f4_badge":".import CSV/JSON · SHA256 · REGEXP · MEDIAN/STDDEV","f5_title":"Kompatibilita syntaxe MySQL / PostgreSQL a READ_STDIN()","f5_desc":"Pište běžné dotazy s AUTO_INCREMENT, SERIAL, ENUM, SHOW TABLES, DESCRIBE a ILIKE lokálně bez zdlouhavého přepisování a vyžádejte si živé vstupy z konzole přímo v SQL pomocí READ_STDIN().","f5_badge":"SHOW TABLES / DESCRIBE · Interaktivní READ_STDIN()","f6_title":"Vícesouborové SQL pipeline a cloudové MySQL 8.0","f6_desc":"Řetězte automaticky 01_schema.sql -&gt; 02_seed.sql -&gt; 03_report.sql nebo spouštějte uložené procedury MySQL 8.0 (DELIMITER, CREATE PROCEDURE, CALL, JSON_TABLE) v cloudovém clusteru MySQL.","f6_badge":"Vícesouborový topologický běh · Cloudové MySQL 8.0","workflow_title":"Jak dotazovat databáze a importovat datasety v SuperCode","workflow_lead":"Čisté databázové workflow řízené skripty, které se ukládají přímo do pracovního prostoru v Androidu.","wf_foot_note":"6 vestavěných SQL ukázek · Přímá spolupráce s PHP PDO a Java 17 JDBC","wf1_title":"Otevřete databázi .db nebo vytvořte skript .sql","wf1_desc":"Klepnutím na libovolný lokální soubor .db/.sqlite zobrazíte jeho schéma, nebo vytvořte .sql skript s offline AST doplňováním klíčových slov a funkcí SQL i formátováním.","wf2_title":"Naplňte tabulky nebo importujte soubory CSV a JSON","wf2_desc":"Načtěte datové sady CSV, TSV nebo JSON ze složky projektu do typovaných relačních tabulek jediným příkazem.","wf3_title":"Spouštějte vícepříkazové dotazy offline","wf3_desc":"Prohlížejte si tabulky Unicode Box Grid, Markdown nebo výstup JSON v rozdělené konzoli s živými výzvami pro parametry READ_STDIN(), kdykoli je potřeba.","wf4_title":"Exportujte čisté reporty a synchronizujte .db do PHP/Javy","wf4_desc":"Ukládejte aktualizované soubory .db nebo reporty .csv/.json přímo do složky projektu — připravené k dotazování z pracovních prostorů PHP PDO nebo Java JDBC v SuperCode!"},"git_client":{"metaTitle":"Vizuální Git klient pro Android — Klonování, Time Machine diff a sloučení | SuperCode","metaDesc":"Kompletní vizuální Git klient přímo v SuperCode IDE pro Android. Klonujte repozitáře GitHub/GitLab/Gitee přes PAT, prohlížejte barevné diffy commitů, přepínejte větve, využijte auto-stash při Pull a řešte merge konflikty vizuálně.","hero_tag":"SAMOSTATNÁ VIZUÁLNÍ PRACOVNÍ STANICE GIT V2.0","hero_h1":"Kompletní <span class=\"text-gradient\">vizuální Git, Time Machine diff a řešení konfliktů</span> na Androidu.","hero_desc":"Bez nutnosti externích balíčků v terminálu. Klonujte repozitáře <strong>GitHub, GitLab, Gitee a Bitbucket</strong> přes HTTPS tokeny, kontrolujte <strong>barevný Unified Diff</strong>, stahujte pomocí <strong>auto-stash a hot-reloadu karet</strong> a řešte <strong>merge konflikty jedním klepnutím</strong>.","table_h2":"SuperCode Visual Git vs. ostatní Git workflow na Androidu","snippet_p":"<strong>SuperCode Visual Git Client</strong> je samostatný Git klient nativně integrovaný do SuperCode IDE pro Android. Podporuje klonování přes HTTPS + PAT, přepínání více repozitářů, správu větví, chytrý Pull s auto-stashem, Time Machine pro 120 commitů s barevným unified diffem a vizuální řešení merge konfliktů.","table_caption":"SROVNÁNÍ WORKFLOW SPRÁVY VERZÍ GIT NA ANDROIDU","faq_lead":"Praktické odpovědi k tokenům GitHub PAT, soukromým repozitářům, merge konfliktům a historii commitů.","cta_h2":"Spravujte repozitáře, diffy a merge pohodlně na Androidu.","cta_desc":"Stáhněte si SuperCode IDE z Google Play a získejte samostatného klienta Visual Git spolu s více než 10 offline vývojovými prostředími.","th_0":"Git workflow","th_1":"SuperCode Visual Git V2","th_2":"Základní mobilní Git pluginy","th_3":"CLI terminálový Git","tr1_c0":"Nastavení a závislosti","tr1_c1":"Vestavěný engine bez nastavování + obnova zámku","tr1_c2":"Chyby pluginů nebo rozbitá autentizace","tr1_c3":"Ruční instalace pkg + konfigurace SSH/PAT","tr2_c0":"Pull s lokálními úpravami","tr2_c1":"Auto-Stash + obnova + reload karty na místě","tr2_c2":"Selže s chybou checkoutu","tr2_c3":"Ruční git stash / pop","tr3_c0":"Historie a diffy kódu","tr3_c1":"Time Machine (120 commitů) + 2D barevný Unified Diff","tr3_c2":"Pouze prostý text logu commitů","tr3_c3":"Špatné posouvání na displeji telefonu","tr4_c0":"Merge konflikty","tr4_c1":"Vizuální karty: Ponechat aktuální / příchozí / obě","tr4_c2":"Ruční úprava značek &lt;&lt;&lt;&lt;&lt;&lt;&lt; v textu","tr4_c3":"Ruční úprava značek ve vimu","tr5_c0":"Bezpečnost Detached HEAD","tr5_c1":"Záchranný banner jedním klepnutím (+ Nová větev / Návrat)","tr5_c2":"Snadná ztráta commitů","tr5_c3":"Matoucí stav v CLI","faq1_q":"Jak se přihlásím k soukromým repozitářům na GitHub, GitLab nebo Gitee?","faq1_a":"Vygenerujte si na GitHub/GitLab/Gitee HTTPS Personal Access Token (PAT) s oprávněním repo a vložte jej do pole Token při akcích Klonovat, Commit &amp; Push nebo Pull. SuperCode jej bezpečně uloží, takže jej nemusíte zadávat pokaždé znovu.","faq2_q":"Co se stane, když klepnu na Pull a mám neuložené karty nebo necommitnuté změny?","faq2_a":"SuperCode nejprve uloží neuložené karty na disk, automaticky odloží (stash) vaše sledované necommitnuté změny, stáhne nejnovější vzdálené commity, znovu aplikuje vaši lokální práci a obnoví otevřené karty přesně na řádku s kurzorem.","faq3_q":"Jak zobrazím změny v předchozím commitu nebo vrátím stav zpět?","faq3_a":"Otevřete Git Time Machine z Git Dashboardu a klepněte na libovolný commit na časové ose. Zvolte Zobrazit změny kódu (Commit Diff) pro barevný unified diff, Checkout (pouze zobrazení) pro bezpečné prohlédnutí snímku, nebo Hard Reset pro vrácení větve.","faq4_q":"Mohu commitovat změny offline bez připojení k internetu?","faq4_a":"Ano! Staging, lokální commity, vytváření větví, prohlížení historie, unified diffy i řešení konfliktů fungují offline; lokální commity pak odešlete (push) na origin, až se znovu připojíte.","wb_eyebrow":"INTERAKTIVNÍ GIT DASHBOARD, DIFF &amp; MERGE PRACOVNÍ PLOCHA","sec_cap_title":"Každá klíčová operace Git — navržená přímo pro dotykové ovládání","sec_cap_lead":"Chráněno zámky repozitáře, automatickým ukládáním změněných karet a záchrannými bannery Detached HEAD, aby byla správa verzí na mobilu bez stresu.","f1_title":"Přehledný Git Dashboard a přepínač repozitářů","f1_desc":"Na první pohled uvidíte připojený repozitář, aktivní větev, krátký hash commitu, živé počty ↑ Napřed / ↓ Pozadu oproti remote i počty Upravených / Přidaných / Smazaných / Konfliktních souborů — a přepnete repozitář jedním klepnutím.","f1_badge":"Přepínač repozitářů · ↑Napřed ↓Pozadu · Připojit existující","f2_title":"Klonování přes HTTPS + PAT a šifrované uložení údajů","f2_desc":"Klonujte veřejné i soukromé repozitáře z GitHub, GitLab, Gitee, Bitbucket nebo vlastních Git serverů pomocí Personal Access Tokenů (PAT). Názvy cílových složek se doplní automaticky a tokeny se bezpečně uloží pro další pushe.","f2_badge":"GitHub / GitLab / Gitee PAT · Živý průběh přenosu","f3_title":"Auto-uložení karet, náhled změn a nastavení autora","f3_desc":"Před commitem SuperCode automaticky uloží všechny upravené otevřené karty v editoru, aby žádná změna nezůstala pozadu, zobrazí náhled až 80 změněných souborů se štítky [M]/[A]/[U]/[D] a umožní nastavit vlastní Jméno a E-mail autora.","f3_badge":"Žádné zapomenuté úpravy · Vlastní autor · Auto-vazba upstreamu","f4_title":"Chytrý Pull s auto-stashem a zachováním pozice kurzoru","f4_desc":"Máte při stahování necommitnuté lokální úpravy? SuperCode je automaticky uloží do stashe bez falešných commitů, stáhne vzdálené aktualizace, znovu aplikuje vaše změny a provede hot-reload otevřených karet přesně na řádek a sloupec kurzoru!","f4_badge":"Čistý Auto-Stash · Hot-Reload karet na místě","f5_title":"Git Time Machine, tvorba větví a prohlížeč Unified Diff","f5_desc":"Procházejte až 120 commitů, otevřete 2D posuvný +zelený / -červený Unified Diff u libovolného commitu, vytvářejte a přepínejte lokální či vzdálené větve, bezpečně prohlížejte historické snímky nebo proveďte potvrzený Hard Reset.","f5_badge":"Prohlížeč Unified Diff · + Nová větev · Záchrana Detached HEAD","f6_title":"Vizuální řešení merge konfliktů napříč soubory","f6_desc":"Už žádné ruční upravování značek &lt;&lt;&lt;&lt;&lt;&lt;&lt;. Projděte konfliktní soubory (1 / N) a na přehledných kartách Lokální vs. Vzdálený klepněte na Ponechat aktuální, Ponechat příchozí nebo Ponechat obě — s automatickým přidáním do stage pro okamžitý Commit &amp; Push.","f6_badge":"Ponechat aktuální / příchozí / obě · Fronta Auto-Stage","workflow_title":"Kompletní 6krokový průvodce: Jak používat Git v SuperCode IDE","workflow_lead":"Postupujte podle tohoto workflow přímo v SuperCode a klonujte, větvěte, porovnávejte, slučujte a pushujte z telefonu nebo tabletu.","wf_foot_note":"Automatická obnova zastaralého index.lock · Podporuje lokální commity offline","wf1_title":"Naklonujte vzdálený repozitář nebo připojte lokální projekt","wf1_desc":"Vložte svou HTTPS URL (např. https://github.com/user/repo.git) a volitelný PAT token a klepněte na KLONOVAT — nebo klepněte na Připojit existující repozitář, pokud složka již obsahuje adresář .git.","wf2_title":"Přepněte nebo vytvořte feature větev","wf2_desc":"Otevřete Git Time Machine, klepněte na horní přepínač větví nebo na + Vytvořit novou větev… (např. feature/mobile-ui) s automatickou kontrolou platnosti názvu větve.","wf3_title":"Upravujte kód napříč soubory s plnou inteligencí IDE","wf3_desc":"Upravujte, formátujte a testujte kód offline. I když zapomenete uložit otevřenou kartu, operace Git před spuštěním automaticky zapíší neuložené karty na disk.","wf4_title":"Stáhněte bezpečně vzdálené týmové aktualizace","wf4_desc":"Před pushem klepněte na Pull. Necommitnuté lokální úpravy se automaticky odloží do stashe a obnoví, a otevřené karty se aktualizují na místě bez ztráty pozice kurzoru.","wf5_title":"Vyřešte případné merge kolize vizuálně","wf5_desc":"Pokud dojde k překryvu úprav, klepněte na Otevřít řešení konfliktů, porovnejte lokální a vzdálené bloky vedle sebe, vyberte Ponechat aktuální / příchozí / obě a klepněte na Použít řešení.","wf6_title":"Zkontrolujte čekající soubory, napište zprávu a pushněte","wf6_desc":"Ověřte štítky [M]/[A]/[D] v seznamu čekajících změn, potvrďte identitu autora a commit zprávu a klepnutím na COMMIT proveďte stage, commit i push na origin."},"sftp_client":{"metaTitle":"SFTP, FTPS a FTP editor kódu pro Android — Trezor SSH klíčů a atomické ukládání | SuperCode","metaDesc":"Připojte se k serverům SFTP, FTPS (TLS 1.3) a FTP přímo v SuperCode IDE na Androidu. Ověřujte se pomocí Ed25519/RSA/PEM SSH klíčů v trezoru AES-256, upravujte vzdálený kód s 3fázovým atomickým uložením a navazujte přerušené přenosy.","hero_tag":"SFTP · FTPS TLS 1.3 · FTP VZDÁLENÉ SERVEROVÉ PROSTŘEDÍ","hero_h1":"Upravujte produkční servery přes <span class=\"text-gradient\">SFTP, FTPS a FTP</span> s jistotou atomického ukládání.","hero_desc":"Navrženo pro cloudové inženýry, sysadminy a webové vývojáře v pohotovosti. Připojte se přes <strong>SFTP (SSH 22), FTPS Explicit/Implicit (TLS 1.3) nebo FTP</strong> pomocí <strong>klíčů Ed25519/RSA/PEM</strong> v <strong>hardwarovém trezoru AES-256</strong> a upravujte vzdálené soubory s <strong>atomickým uložením bez poškození dat</strong>.","table_h2":"SuperCode SFTP / FTPS Workspace vs. samostatné aplikace pro přenos souborů","snippet_p":"<strong>SuperCode SFTP &amp; FTPS Client</strong> je integrovaný editor kódu na vzdálených serverech pro Android s podporou SFTP (SSH), Explicit/Implicit FTPS (TLS 1.3) a FTP. Spojuje trezor SSH klíčů v Android KeyStore s AES-256, ověření otisku TOFU, 3fázové atomické vzdálené ukládání a 4proudé přenosy s navázáním po bajtech.","table_caption":"SROVNÁNÍ VZDÁLENÉ ÚPRAVY KÓDU PŘES SFTP / FTPS NA ANDROIDU","faq_lead":"Odpovědi k soukromým klíčům SSH (.pem / Ed25519), FTPS TLS 1.3, prevenci poškození vzdálených souborů při ukládání a navázání velkých stahování.","cta_h2":"Spravujte produkční VPS a webhostingy bezpečně z Androidu.","cta_desc":"Nainstalujte si SuperCode IDE z Google Play pro úpravy přes SFTP/FTPS s AES-256, přihlášení SSH klíčem a 3fázové atomické nasazení.","th_0":"Vzdálené možnosti","th_1":"SuperCode SFTP/FTPS Studio","th_2":"Samostatné FTP aplikace","th_3":"Základní pluginy editorů","tr1_c0":"Podporované protokoly","tr1_c1":"SFTP (22) + FTPS Explicit TLS 1.3 + FTPS 990 + FTP","tr1_c2":"Pouze přenos souborů (bez IDE)","tr1_c3":"Jen základní FTP/SFTP","tr2_c0":"Zabezpečení klíčů a MITM","tr2_c1":"Ed25519/RSA/PEM + AES-256 KeyStore + TOFU SHA256","tr2_c2":"Různé; bez AST editoru kódu","tr2_c3":"Konfigurace v prostém textu nebo slabé klíče","tr3_c0":"Bezpečí uložení při výpadku sítě","tr3_c1":"3fázové atomické uložení + zachování POSIX práv","tr3_c2":"Ruční stažení a opětovné nahrání","tr3_c3":"Přímý stream hrozí 0bajtovým souborem","tr4_c0":"Přerušené přenosy","tr4_c1":"4 paralelní proudy + přesné navázání podle bajtového offsetu","tr4_c2":"Podporováno v placených aplikacích","tr4_c3":"Restartuje od 0 %","tr5_c0":"Živý náhled webu","tr5_c1":"Živý vzdálený náhled HTML/CSS/JS/PHP jedním klepnutím","tr5_c2":"Žádný","tr5_c3":"Žádný","faq1_q":"Které formáty soukromých klíčů SSH fungují pro AWS EC2, DigitalOcean nebo linuxové VPS servery?","faq1_a":"SuperCode podporuje soukromé klíče OpenSSH, PEM (.pem), RSA (id_rsa), Ed25519 (id_ed25519) a ECDSA — s heslem (passphrase) i bez něj — a nabízí rychlý výběr složek Stažené soubory a .ssh.","faq2_q":"Jak SuperCode zabraňuje vzniku poškozených 0bajtových souborů na serveru při výpadku mobilního signálu během ukládání?","faq2_a":"Každé uložení vzdálené karty používá 3fázovou atomickou transakci: nejprve nahraje do dočasného souboru, dotáže se serveru přes STAT/SIZE pro ověření přesného počtu přenesených bajtů a teprve poté atomicky přejmenuje cílový soubor při zachování linuxových oprávnění.","faq3_q":"Podporuje SuperCode kromě SSH SFTP také FTPS (FTP přes SSL/TLS)?","faq3_a":"Ano! Nativně jsou podporovány jak Explicit FTPS (AUTH TLS 1.2/1.3 na portu 21 se šifrovanými pasivními datovými kanály PROT P), tak Implicit FTPS (port 990) i standardní pasivní FTP s UTF-8.","faq4_q":"Mohu navázat stahování nebo nahrávání velké zálohy, pokud se spojení přeruší?","faq4_a":"Ano. Při přenosu na existující částečný soubor SuperCode rozpozná jeho velikost a jedním klepnutím nabídne navázání částečného přenosu přesně od bajtového offsetu bez opakovaného odesílání již přenesených dat.","wb_eyebrow":"INTERAKTIVNÍ SFTP TREZOR, ATOMICKÉ UKLÁDÁNÍ A CENTRUM PŘENOSŮ","sec_cap_title":"Podnikové vzdálené zabezpečení a práce se soubory bez poškození dat","sec_cap_lead":"Navrženo speciálně pro nestabilní mobilní sítě — kde běžný FTP editor při výpadku 5G nebo Wi-Fi zkrátí produkční konfigurace na 0 bajtů.","f1_title":"Všechny 4 protokoly: SFTP, FTPS Explicit, FTPS Implicit a FTP","f1_desc":"Podporuje SSH SFTP (port 22), Explicit FTPS přes TLS 1.2/1.3 se šifrovanými pasivními datovými kanály (PBSZ 0 + PROT P), Implicit FTPS (port 990) a pasivní FTP s UTF-8 (port 21).","f1_badge":"SFTP (22) · FTPS TLS 1.3 (21) · FTPS (990) · FTP","f2_title":"Výběr soukromého klíče SSH, trezor AES-256 a ochrana TOFU","f2_desc":"Importujte klíče OpenSSH, PEM, RSA, Ed25519 nebo ECDSA (.pem, .key, id_rsa, id_ed25519) včetně hesel (passphrase). Všechna tajemství jsou šifrována pomocí Android KeyStore AES-256-GCM a chráněna upozorněním na neshodu SHA256 klíče hostitele.","f2_badge":"Ed25519 / RSA / PEM · AES-256-GCM · MITM ochrana hostitele","f3_title":"3fázové atomické vzdálené uložení (žádné 0bajtové poškození)","f3_desc":"Otevřením vzdáleného souboru vznikne trvalá lokální zrcadlová karta (☁️). Stisknutím Uložit se soubor nahraje do dočasného souboru, ověří se přesná velikost v bajtech přes STAT/SIZE a atomicky přejmenuje na cíl při zachování POSIX oprávnění!","f3_badge":"Dočasný upload -&gt; Ověření velikosti -&gt; Atomické přejmenování + chmod","f4_title":"Živá diagnostická konzole handshake a samoopravný pool","f4_desc":"Ověřte TCP, vyjednání TLS/SSH a autentizaci klíčem ve vestavěné diagnostické konzoli ještě před uložením serveru. Tříkanálový pool spojení automaticky obnoví zastaralé sockety po přepnutí mezi Wi-Fi a 5G.","f4_badge":"⚡ Test Handshake · 3kanálový samoopravný pool","f5_title":"4proudá fronta přenosů a navázání podle bajtového offsetu","f5_desc":"Nahrávejte nebo stahujte celé adresářové stromy ve 4 paralelních proudech s panelem rychlosti MB/s při 20 fps. Přerušené velké přenosy navážou přesně od bajtového offsetu přes SFTP RESUME nebo FTP REST!","f5_badge":"4 paralelní proudy · Živé MB/s · Navázání po bajtech","f6_title":"Vzdálené fuzzy hledání a živý vzdálený náhled webu","f6_desc":"Vyhledávejte názvy souborů napříč vzdálenými složkami serveru, znovu načtěte vzdálené karty v kterémkoli z 34 kódování znaků a stiskněte Spustit na vzdálených souborech HTML/PHP pro živý náhled stránek před úpravou i po ní.","f6_badge":"Vzdálené fuzzy hledání · 34 kódování · Živý náhled webu","workflow_title":"Jak se připojit a bezpečně upravovat živé servery z Androidu","workflow_lead":"Nastavte jednou v hardwarově šifrovaném trezoru a nasazujte hotfixy odkudkoli během několika sekund.","wf_foot_note":"Zachovává vzdálená linuxová POSIX oprávnění · Přežije restart aplikace offline","wf1_title":"Zvolte protokol a zadejte heslo nebo importujte SSH klíč","wf1_desc":"Vyberte SFTP, FTPS (TLS), FTPS (990) nebo FTP, zadejte hostitele/uživatele a buď vyplňte heslo, nebo vyberte soubor soukromého klíče .pem / id_ed25519.","wf2_title":"Ověřte diagnostiku handshake a důvěřujte otisku hostitele","wf2_desc":"Klepněte na Test Handshake pro ověření TCP/TLS/SSH autentizace v reálném čase, zkontrolujte SHA256 otisk serveru a uložte profil do trezoru AES-256.","wf3_title":"Procházejte vzdálený strom a upravujte s plným AST a formátováním","wf3_desc":"Otevírejte konfigurace Nginx, backendové soubory Python/PHP nebo shellové skripty přímo v kartách editoru s doplňováním AST, Radarem chyb a formátováním na jedno klepnutí.","wf4_title":"Ukládejte atomicky nebo synchronizujte složky s řízením konfliktů","wf4_desc":"Klepnutím na Uložit provedete 3fázové atomické nasazení, případně označte více složek a nahrávejte/stahujte s pravidly Přepsat, Navázat od offsetu, Ponechat obě nebo Přeskočit."},"py_pip_manager":{"metaTitle":"Instalace PIP balíčků na Androidu — Průvodce offline .whl, PyPI & requirements.txt | SuperCode","metaDesc":"Kompletní průvodce instalací Python PIP balíčků na Androidu v SuperCode. Využijte Auto-PIP překlad aliasů, dávkovou instalaci requirements.txt nebo import offline .whl/.zip ze Stažených bez internetu.","hero_tag":"VIZUÁLNÍ PIP &#183; PEP 440 &#183; OFFLINE INSTALÁTOR .WHL ARCHIVŮ","hero_h1":"Instalujte <span class=\"text-gradient\">Python PIP balíčky &amp; offline .whl soubory</span> na Androidu.","hero_desc":"Rozlučte se s chybami mobilní kompilace v CLI. V naší <strong>Python aplikaci pro Android</strong> spravujte knihovny vizuálně: spusťte <strong><code>requirements.txt</code></strong> jedním klepnutím, nechte <strong>Auto-PIP</strong> vyřešit 35+ aliasů modulů nebo importujte <strong>offline <code>.whl</code> archivy</strong> přímo ze složky Stažené.","pip_s1":"Mapy aliasů importů","pip_s2":"Kontrola verzí","pip_s3":"Offline importér","pip_s4":"Vizuální správce UI","wb_eyebrow":"VIZUÁLNÍ PIP, AUTO-ALIAS &amp; OFFLINE WHEEL WORKBENCH","sec_cap_title":"Čtyři snadné způsoby přidání Python knihoven v telefonu","sec_cap_lead":"Ať máte rychlou Wi-Fi nebo jste ve škole bez internetu, SuperCode udržuje vaše Python závislosti přehledné a trvale uložené.","f1_title":"Auto-PIP detektor chybějících importů &amp; 35+ map aliasů","f1_desc":"Napište import bs4, import yaml, import dotenv, import jwt nebo import telebot a stiskněte Spustit. SuperCode automaticky namapuje název importu na oficiální PyPI balíček (beautifulsoup4, pyyaml, python-dotenv, PyJWT, pyTelegramBotAPI), nainstaluje jej a znovu spustí skript.","f1_badge":"bs4 -&gt; beautifulsoup4 &#183; yaml -&gt; pyyaml &#183; 35+ aliasů","f2_title":"Detekce requirements.txt bez nastavování","f2_desc":"Naklonujte Git repozitář nebo otevřete složku projektu s requirements.txt. Vizuální správce PIP prohledá až 6 nadřazených složek, zpracuje zalomení řádků (\\) i značky platforem a zobrazí banner pro dávkovou instalaci na 1 klepnutí.","f2_badge":"Sken nadřazených složek &#183; Značky platforem &#183; Dávková fronta","f3_title":"100% offline lokální importér .whl, .tar.gz &amp; .zip","f3_desc":"Učíte se v letadle, vlaku nebo na omezené školní Wi-Fi? Stáhněte si předem pure-Python distribuce .whl, .tar.gz nebo .zip do složky Stažené v Androidu a nainstalujte je zcela offline s plnou validací verzí PEP 440.","f3_badge":"Instalace v režimu letadlo &#183; .whl / .tar.gz / .zip","f4_title":"Verzování PEP 440 &amp; parser příkazů","f4_desc":"Vložte celé příkazy pip install (např. pip install requests&gt;=2.31.0 flask~=3.0) přímo do pole. SuperCode odstraní CLI omáčku, vyhodnotí operátory ==, &gt;=, &lt;=, != a ~= vůči Python 3.11 a stáhne kompatibilní verze.","f4_badge":"Podpora PEP 440 &#183; Vkládání celých příkazů pip","f5_title":"Inspektor místa na disku &amp; úklid 1 klepnutím","f5_desc":"Přepněte na kartu Správa pro filtrování nainstalovaných knihoven v reálném čase, zkontrolujte přesné verze i zabrané kB/MB na disku a odstraňte nepoužívané balíčky jediným klepnutím.","f5_badge":"Živý filtr &#183; Přesná velikost na disku &#183; Čistá odinstalace","f6_title":"Chytrá ochrana vědeckých &amp; nativních rozšíření","f6_desc":"Zadání numpy, pandas, matplotlib, scipy nebo scikit-learn v PIP nevyvolá selhání C/Fortran kompilátoru v telefonu &#8212; SuperCode je automaticky přesměruje na předpřipravené vědecké wheely v lokální cache.","f6_badge":"Nulové chyby gcc &#183; Předpřipravené vědecké wheely","workflow_title":"Krok za krokem: Jak používat PIP &amp; offline wheely v SuperCode","workflow_lead":"Nainstalujte PyPI balíčky online nebo nahrajte .whl soubory offline za méně než 30 sekund.","wf1_title":"Otevřete vizuální správce PIP balíčků","wf1_desc":"Otevřete libovolný .py soubor a klepněte na ikonu PIP v hlavičce Python konzole &#8212; nebo jednoduše spusťte skript s nenainstalovaným importem pro aktivaci Auto-PIP.","wf2_title":"Vyberte štítek, vložte pip install nebo vyberte requirements.txt","wf2_desc":"Klepněte na rychlé štítky (requests, rich, beautifulsoup4, pyyaml, flask, telebot, colorama), zadejte specifikaci verzí nebo klepněte na automaticky zjištěný banner requirements.txt.","wf3_title":"Nebo vyberte offline .whl / .zip ze Stažených","wf3_desc":"V offline prostředí klepněte v dialogu PIP na Místní archiv a vyhledejte .whl, .tar.gz a .zip balíčky ve Stažených nebo ve složce projektu.","wf4_title":"Importujte ihned napříč vícesouborovými skripty","wf4_desc":"Nainstalované knihovny zůstávají v izolovaném adresáři site-packages i po restartu aplikace a okamžitě fungují s AST automatickým doplňováním.","wf_foot_note":"Trvalé site-packages v zařízení &#183; Neblokující 50ms log instalace","table_h2":"Vizuální PIP SuperCode vs. tradiční mobilní instalátory","snippet_p":"<strong>Vizuální správce PIP balíčků v SuperCode</strong> umožňuje vývojářům na Androidu instalovat Python knihovny třetích stran bez složitostí v terminálu. Spojuje vyhledávání na PyPI, 35+ automatických mapování aliasů importů, dávkovou instalaci requirements.txt v projektu a offline import .whl/.tar.gz/.zip archivů.","table_caption":"SROVNÁNÍ SPRÁVY PYTHON BALÍČKŮ NA ANDROIDU","th_0":"Funkce PIP","th_1":"SuperCode Python Studio","th_2":"Základní Python aplikace","th_3":"Terminál CLI pip","th_4":"Online notebooky","tr1_c0":"Mapování aliasů importů","tr1_c1":"35+ automatických map (bs4, yaml, pil, dotenv, jwt)","tr1_c2":"Nutné ruční dohledání","tr1_c3":"Nutné ruční dohledání","tr1_c4":"Ruční `!pip install`","tr2_c0":"Offline .whl / .zip","tr2_c1":"Vestavěný skener úložiště (bez internetu)","tr2_c2":"Zřídka podporováno","tr2_c3":"Ruční cesty v přepínačích","tr2_c4":"Vyžaduje internet","tr3_c0":"requirements.txt","tr3_c1":"Autodetekce až 6 nadřazených složek + spuštění 1 klepnutím","tr3_c2":"Nepodporováno","tr3_c3":"Ruční `cd` + `pip -r`","tr3_c4":"Resetuje se každou relaci","tr4_c0":"Vědecká C rozšíření","tr4_c1":"Automaticky přesměrováno na předpřipravené wheely v cache","tr4_c2":"Selhává bez placeného pluginu","tr4_c3":"Selhává při kompilaci C/Fortranu","tr4_c4":"Pouze v cloudu","tr5_c0":"Audit disku &amp; verzí","tr5_c1":"Vizuální karta Správa s velikostí &amp; okamžitým filtrem","tr5_c2":"Skryté adresáře","tr5_c3":"Pouze textový výpis `pip list`","tr5_c4":"Dočasný kontejner","faq_lead":"Časté dotazy k instalaci PyPI balíčků, offline .whl wheelů a requirements.txt na Androidu.","faq1_q":"Mohu do SuperCode vložit celý příkaz `pip install requests beautifulsoup4`?","faq1_a":"Ano. Parser vstupu PIP automaticky odstraní úvodní `pip install`, `pip3 install` nebo `python -m pip install`, bezpečně ignoruje nepodporované CLI přepínače a zařadí všechny balíčky včetně jejich omezení PEP 440.","faq2_q":"Jak nainstaluji Python balíčky na Androidu bez připojení k internetu?","faq2_a":"Stáhněte si předem pure-Python archiv `.whl` (např. `*-py3-none-any.whl`), `.tar.gz` nebo `.zip` do telefonu, otevřete v SuperCode správce PIP balíčků a klepněte na Místní archiv pro instalaci přímo ze složky Stažené.","faq3_q":"Proč nemusím ručně spouštět `pip install numpy` nebo `matplotlib`?","faq3_a":"Knihovny s náročnými nativními C/Fortran rozšířeními jako NumPy, Pandas, SciPy, Matplotlib a Scikit-Learn jsou předpřipravené ve vědeckém runtime SuperCode. Stačí do skriptu napsat `import numpy as np` a stisknout Spustit.","faq4_q":"Zůstanou nainstalované PIP balíčky v telefonu i po zavření aplikace?","faq4_a":"Ano. Každý nainstalovaný balíček je trvale uložen v lokálním úložišti `python_site_packages` v SuperCode, takže vaše skripty poběží kdykoli offline bez nutnosti reinstalace.","cta_h2":"Spravujte Python balíčky vizuálně na Androidu.","cta_desc":"Získejte SuperCode IDE zdarma na Google Play &#8212; s Auto-PIP, dávkovou instalací requirements.txt a podporou offline .whl."},"py_libraries":{"metaTitle":"Podporované Python knihovny na Androidu — 250+ offline, PyPI & Data Science balíčků | SuperCode","metaDesc":"Prozkoumejte kompletní seznam Python knihoven podporovaných na Androidu v SuperCode IDE: 200+ standardních modulů Python 3.11, pure-Python PyPI wheely, 60+ předpřipravených knihoven NumPy/Pandas/OpenCV/Scikit-Learn a PyTorch.","hero_tag":"200+ STDLIB &#183; PURE-PYTHON PYPI &#183; 60+ VĚDECKÝCH &amp; AI BALÍČKŮ","hero_h1":"250+ <span class=\"text-gradient\">Python knihoven připravených ke spuštění</span> na vašem Androidu.","hero_desc":"Než si vyberete <strong>aplikaci pro programování v Pythonu</strong>, ověřte si, co v mobilu skutečně naimportujete. SuperCode spojuje <strong>200+ standardních modulů Python 3.11</strong>, <strong>pure-Python PyPI wheely</strong>, <strong>60+ předpřipravených vědeckých &amp; nativních balíčků</strong> a volitelnou cloudovou akceleraci <strong>PyTorch/TensorFlow</strong>.","lib_s1":"Moduly Stdlib","lib_s2":"Vědecké &amp; nativní","lib_s3":"Pure-Python wheely","lib_s4":"Chytré směrování vrstev","wb_eyebrow":"KOMPATIBILITA VÍCEVRSTVÝCH PYTHON KNIHOVEN WORKBENCH","sec_cap_title":"Kompletní přehled podporovaných kategorií Python balíčků","sec_cap_lead":"SuperCode analyzuje příkazy import ve vašem skriptu a automaticky směruje spuštění &#8212; žádné virtuální prostředí ani kompilátory k nastavování.","f1_title":"200+ vestavěných modulů Python 3.11 Stdlib","f1_desc":"Všechny základní moduly fungují ihned offline: sqlite3, json, csv, re, pathlib, os, sys, math, statistics, collections, itertools, heapq, bisect, dataclasses, typing, asyncio, urllib, hashlib, hmac, tomllib, unittest, decimal, fractions, zipfile a tarfile.","f1_badge":"sqlite3 &#183; asyncio &#183; dataclasses &#183; tomllib &#183; unittest","f2_title":"Numerické výpočty, DataFrame &amp; sloupcové SQL analýzy","f2_desc":"Provádějte seriózní datové analýzy v mobilu pomocí numpy, scipy, sympy, mpmath, numexpr, pandas, polars, pyarrow, duckdb, fastparquet, h5py, netcdf4, xarray a zarr &#8212; s lokální cache pro offline běh.","f2_badge":"numpy &#183; pandas &#183; polars &#183; duckdb &#183; scipy &#183; sympy","f3_title":"Grafy, vizualizace &amp; geoprostorové knihovny","f3_desc":"Generujte grafy ve vysokém DPI a geoprostorové mapy pomocí matplotlib, seaborn, bokeh, plotly, wordcloud, shapely, geopandas, pyproj a cartopy. Každé uložené PNG, SVG nebo PDF se synchronizuje přímo do složky projektu.","f3_badge":"matplotlib &#183; seaborn &#183; plotly &#183; wordcloud &#183; geopandas","f4_title":"Strojové učení, počítačové vidění, NLP &amp; grafy","f4_desc":"Vytvářejte a vyhodnocujte modely pomocí scikit-learn (sklearn), xgboost, lightgbm, statsmodels, joblib, opencv-python (cv2), Pillow (PIL), scikit-image, nltk, tiktoken, networkx a biopython.","f4_badge":"scikit-learn &#183; xgboost &#183; opencv-python &#183; Pillow &#183; nltk","f5_title":"Web scraping, API, kryptografie, ORM &amp; dokumenty","f5_desc":"Kombinujte PIP wheely a nativní parsery: requests, beautifulsoup4 (bs4), lxml, orjson, ujson, pydantic, regex, sqlalchemy, cryptography, bcrypt, pycryptodome, pynacl, flask, telebot, python-docx a python-pptx.","f5_badge":"requests &#183; bs4 &#183; lxml &#183; pydantic &#183; cryptography &#183; flask","f6_title":"Náročný Deep Learning &amp; distribuované cloudové frameworky","f6_desc":"Když skript importuje torch (PyTorch), torchvision, tensorflow, keras, jax, onnxruntime nebo pyspark, SuperCode zabalí vícesouborový projekt do cloudového clusteru a vrátí klikatelné lokální řádky tracebacku.","f6_badge":"PyTorch &#183; TensorFlow &#183; Keras &#183; JAX &#183; ONNX Runtime","workflow_title":"Jak SuperCode automaticky směruje Python knihovny","workflow_lead":"Pište standardní Python importy &#8212; SuperCode vybere správné běhové prostředí na pozadí.","wf1_title":"Standardní &amp; PIP balíčky běží za &lt;30 ms offline","wf1_desc":"Skripty využívající standardní knihovnu Python 3.11 nebo nainstalované pure-Python PIP wheely běží okamžitě v lokálním nativním sandboxu.","wf2_title":"Vědecké &amp; nativní moduly aktivují wheely 3.12 v cache","wf2_desc":"Import kterékoli z 60+ vědeckých, obrazových nebo kryptografických knihoven spustí vědecký runtime v zařízení a uloží potřebné wheely do lokální cache.","wf3_title":"Deep Learning frameworky využijí cloudový cluster","wf3_desc":"Rozsáhlé několikagigabajtové frameworky jako PyTorch nebo TensorFlow běží vzdáleně bez zaplnění úložiště telefonu, přičemž zachovávají lokální importy modulů.","wf4_title":"Výstupy &amp; artefakty se uloží zpět do vaší složky","wf4_desc":"Grafy, CSV soubory, SQLite databáze a serializované .pkl modely vytvořené při běhu se objeví přímo v adresáři vašeho projektu na Androidu.","wf_foot_note":"Nulové nastavování virtualenv &#183; Automatický skener tranzitivních importů","table_h2":"Matice úrovní podpory Python knihoven","snippet_p":"<strong>SuperCode IDE pro Android</strong> podporuje přes 250 vestavěných a předpřipravených Python knihoven plus tisíce pure-Python PyPI balíčků: standardní moduly Python 3.11, offline PIP/.whl knihovny, 60+ vědeckých balíčků v cache (NumPy, Pandas, Polars, DuckDB, Matplotlib, Scikit-Learn, OpenCV, Pydantic) a cloudový PyTorch/TensorFlow.","table_caption":"ÚROVNĚ KOMPATIBILITY PYTHON BALÍČKŮ V SUPERCODE PRO ANDROID","th_0":"Oblast knihoven","th_1":"Hlavní balíčky","th_2":"Režim běhu","th_3":"Připraveno offline?","th_4":"Synchronizace výstupů","tr1_c0":"Python 3.11 Stdlib","tr1_c1":"sqlite3, asyncio, json, csv, pathlib, tomllib, unittest","tr1_c2":"Lokální Python 3.11","tr1_c3":"100% offline vestavěné","tr1_c4":"Přímé I/O složky","tr2_c0":"Web, boti &amp; dokumenty","tr2_c1":"requests, bs4, flask, rich, pyyaml, telebot, python-docx","tr2_c2":"Vizuální PIP / Lokální .whl","tr2_c3":"100% offline po instalaci","tr2_c4":"Přímé I/O složky","tr3_c0":"Data &amp; grafy","tr3_c1":"numpy, pandas, polars, duckdb, scipy, matplotlib, seaborn","tr3_c2":"Lokální vědecký 3.12","tr3_c3":"Offline po prvním uložení do cache","tr3_c4":"Auto synchronizace PNG/SVG/CSV","tr4_c0":"ML, vidění &amp; krypto","tr4_c1":"scikit-learn, xgboost, cv2, Pillow, pydantic, cryptography","tr4_c2":"Lokální vědecký 3.12","tr4_c3":"Offline po prvním uložení do cache","tr4_c4":"Auto synchronizace .pkl &amp; obrázků","tr5_c0":"Deep Learning","tr5_c1":"torch (PyTorch), tensorflow, keras, jax, onnxruntime","tr5_c2":"Cloudový Python cluster","tr5_c3":"Vyžaduje síť","tr5_c4":"1:1 mapování tracebacku","faq_lead":"Odpovědi ohledně konkrétních Python balíčků, GUI toolkitů a kompatibility C rozšíření na Androidu.","faq1_q":"Fungují Polars, DuckDB, Pydantic v2 a Cryptography na Androidu v SuperCode?","faq1_a":"Ano. Na rozdíl od běžných mobilních pip instalátorů, které selhávají při pokusu o kompilaci Rust nebo C rozšíření v telefonu, SuperCode obsahuje předpřipravenou binární podporu pro polars, duckdb, pydantic, orjson, lxml a cryptography.","faq2_q":"Mohu na Androidu používat SQLite databáze s Pythonem?","faq2_a":"Ano &#8212; `sqlite3` je zabudováno přímo v offline standardní knihovně Python 3.11 a podporovány jsou i `sqlalchemy` + `apsw`. Navíc si stejný `.db` soubor můžete vizuálně prohlížet v SQL IDE aplikace SuperCode.","faq3_q":"Co když balíček vyžaduje desktopová X11 okna jako Tkinter?","faq3_a":"Bezhlavé generování grafů (`matplotlib`, `seaborn`, `Pillow`, `opencv-python`) funguje bez problémů a ukládá obrázky přímo do složky projektu pro zobrazení v HD prohlížeči obrázků SuperCode, zatímco webová rozhraní lze tvořit pomocí `flask` nebo Web IDE v SuperCode.","faq4_q":"Jak poznám, zda je PyPI balíček pure Python pro offline instalaci `.whl`?","faq4_a":"Na PyPI.org -&gt; Download files je každý wheel končící na `-py3-none-any.whl` univerzální pure-Python wheel, který se přes importér Místní archiv v SuperCode nainstaluje 100% offline.","cta_h2":"Spouštějte reálné Python knihovny na svém Androidu.","cta_desc":"Stáhněte si SuperCode IDE zdarma z Google Play a odemkněte 250+ modulů stdlib, PyPI, Data Science a ML."},"py_data_science":{"metaTitle":"Python Data Science aplikace pro Android — Offline NumPy, Pandas, DuckDB & Matplotlib | SuperCode","metaDesc":"Analyzujte data a vykreslujte grafy offline na Androidu se SuperCode. Spouštějte NumPy, Pandas, Polars, DuckDB, SciPy, SymPy, Matplotlib a Seaborn v telefonu či tabletu s automatickou synchronizací PNG/SVG/PDF do složky.","hero_tag":"OFFLINE NUMPY &#183; PANDAS &#183; POLARS &#183; DUCKDB &#183; MATPLOTLIB","hero_h1":"Kapesní studio <span class=\"text-gradient\">Python Data Science, Pandas &amp; Matplotlib</span> pro Android.","hero_desc":"Analyzujte reálné CSV, JSON a SQLite datové sady kdekoli bez spouštění cloudových notebooků. SuperCode ukládá <strong>NumPy, Pandas, Polars, DuckDB, SciPy a Matplotlib</strong> přímo do cache vašeho Androidu a synchronizuje každý graf z <strong><code>plt.savefig()</code></strong> rovnou do vašeho pracovního prostoru.","ds_s1":"&amp; SciPy / SymPy","ds_s2":"Polars &amp; DuckDB","ds_s3":"PNG &#183; SVG &#183; PDF","ds_s4":"Uloženo offline v cache","wb_eyebrow":"INTERAKTIVNÍ DATAFRAME, DUCKDB &amp; MATPLOTLIB WORKBENCH","sec_cap_title":"Navrženo pro datové analytiky, výzkumníky &amp; studenty STEM","sec_cap_lead":"Vše od symbolických výpočtů v SymPy přes vícetabulkové SQL dotazy v DuckDB až po publikační grafy v Matplotlib funguje nativně na Androidu.","f1_title":"Pandas, Polars &amp; DuckDB nad reálnými lokálními daty","f1_desc":"Vložte soubory .csv, .tsv, .json, .db nebo .sqlite3 do složky projektu a dotazujte se jich přímo přes pd.read_csv(), polars, pyarrow nebo duckdb.sql(). Vyčištěná CSV nebo SQLite tabulky exportujte zpět na disk.","f1_badge":"pandas &#183; polars &#183; duckdb &#183; pyarrow &#183; fastparquet","f2_title":"Vědecké výpočty v NumPy, SciPy &amp; SymPy","f2_desc":"Provádějte lineární algebru, FFT zpracování signálu, numerickou integraci, optimalizaci a symbolické derivace offline pomocí numpy, scipy, sympy, mpmath, numexpr a pywavelets.","f2_badge":"Maticová algebra &#183; FFT &#183; Symbolický počet &#183; .npy/.npz","f3_title":"Synchronizace grafů Matplotlib &amp; Seaborn bez nastavování","f3_desc":"Volejte plt.savefig('figure.png', dpi=200) nebo exportujte vektorové grafy .svg a .pdf &#8212; i když savefig() zapomenete, otevřené grafy lze zachytit a synchronizovat přímo do adresáře projektu pro okamžitou kontrolu.","f3_badge":"matplotlib &#183; seaborn &#183; wordcloud &#183; Vestavěný HD prohlížeč","f4_title":"Plynulé propojení s GB soubory &amp; SQL studiem SuperCode","f4_desc":"Máte 500MB surový CSV log nebo vícetabulkovou SQLite databázi? Předčistěte obří soubory pomocí globálního proudového Regex nahrazování, prohlédněte schémata v SQL IDE a spusťte Python Pandas pipeline ve stejném projektu.","f4_badge":"Čištění GB logů + SQL Explorer + Python Pandas","f5_title":"Geoprostorové &amp; vědecké formáty souborů v základu","f5_desc":"Pracujte na Android tabletech a telefonech se specializovanými výzkumnými formáty pomocí geopandas, shapely, pyproj, h5py, netcdf4, xarray a zarr.","f5_badge":"geopandas &#183; shapely &#183; h5py &#183; xarray &#183; zarr","f6_title":"Rozdělení 55:45 na šířku tabletu &amp; AST doplňování","f6_desc":"Na tabletech a skládacích telefonech s Androidem pište transformace DataFrame v levém 55% panelu s AST doplňováním metod a sledujte široké tabulkové výpisy v pravé 45% konzoli.","f6_badge":"Zoom konzole 7sp&#8211;26sp &#183; Čitelnost širokých tabulek","workflow_title":"Jak analyzovat data &amp; exportovat grafy offline na Androidu","workflow_lead":"Kompletní lokální datová smyčka bez timeoutů Jupyter serveru nebo výpadků prohlížeče.","wf1_title":"Vložte CSV, JSON nebo SQLite soubory do projektu","wf1_desc":"Otevřete libovolnou složku v úložišti Androidu se soubory `.csv`, `.json`, `.sqlite3` nebo `.npy` &#8212; SuperCode automaticky připojí doprovodné datové soubory.","wf2_title":"Pište skripty v NumPy, Pandas, DuckDB nebo SymPy","wf2_desc":"První import vědeckých knihoven uloží jejich binární wheely do lokální cache telefonu; každé další spuštění probíhá 100% offline.","wf3_title":"Spusťte &amp; synchronizujte grafy ve vysokém DPI na disk","wf3_desc":"Klepněte na Spustit &#9654; pro zobrazení tabulkových přehledů v konzoli a automatický zápis PNG, SVG, PDF nebo vyčištěných CSV výstupů do složky.","wf4_title":"Prohlédněte si grafy ve vestavěném HD &amp; PDF prohlížeči","wf4_desc":"Klepněte na vygenerované PNG nebo PDF ve stromu souborů pro ostré zvětšení prsty nebo přímé sdílení s kolegy a do protokolů.","wf_foot_note":"Offline cache wheelů &#183; Automatické obnovení stromu projektu po každém běhu","table_h2":"SuperCode Data Science Studio vs. cloudové notebooky v mobilu","snippet_p":"<strong>SuperCode IDE</strong> přináší offline Python data science na Android se spouštěním NumPy, SciPy, SymPy, Pandas, Polars, DuckDB, Matplotlib a Seaborn z lokální cache, přímým přístupem k lokálním CSV/SQLite a automatickou synchronizací grafů ve vysokém DPI.","table_caption":"SROVNÁNÍ MOBILNÍCH NÁSTROJŮ PRO PYTHON DATA SCIENCE","th_0":"Postup Data Science","th_1":"SuperCode Android Studio","th_2":"Mobilní cloudové notebooky","th_3":"Základní Python aplikace","th_4":"Pouze notebook/PC","tr1_c0":"Offline spuštění","tr1_c1":"NumPy, Pandas, DuckDB &amp; Matplotlib v cache","tr1_c2":"Odpojí se bez signálu","tr1_c3":"Pouze stdlib math","tr1_c4":"Offline","tr2_c0":"Moderní datové enginy","tr2_c1":"Pandas + Polars + DuckDB + PyArrow","tr2_c2":"Liší se dle kontejneru","tr2_c3":"Nepodporováno","tr2_c4":"Podporováno","tr3_c0":"Synchronizace souborů &amp; grafů","tr3_c1":"Přímé čtení/zápis do složky Androidu + HD prohlížeč","tr3_c2":"Ruční nahrávání/stahování","tr3_c3":"Skrytý dočasný sandbox","tr3_c4":"Přímé","tr4_c0":"Příprava obřích CSV dat","tr4_c1":"Vestavěný GB stránkovač &amp; proudové Regex nahrazování","tr4_c2":"Pády karty prohlížeče","tr4_c3":"Padá při &gt;20 MB","tr4_c4":"Vyžaduje další nástroje","tr5_c0":"SQL databázové GUI","tr5_c1":"Integrované 9režimové SQL Studio v ceně","tr5_c2":"Žádné","tr5_c3":"Žádné","tr5_c4":"Samostatný DB klient","faq_lead":"Otázky ke spouštění NumPy, Pandas, Polars a Matplotlib offline na telefonech a tabletech s Androidem.","faq1_q":"Opravdu běží NumPy a Pandas offline v mém Android telefonu?","faq1_a":"Ano. Jakmile se vědecký runtime inicializuje a uloží wheel balíčku (například `numpy`, `pandas` nebo `matplotlib`) do cache zařízení, všechna další spuštění probíhají 100% offline bez internetu.","faq2_q":"Jak na Androidu zobrazím grafy z `matplotlib.pyplot`?","faq2_a":"Uložte graf pomocí `plt.savefig('plot.png', dpi=180)` (nebo `.svg` / `.pdf`). SuperCode soubor synchronizuje přímo do aktivního adresáře projektu a umožní jej ihned otevřít ve vestavěném HD prohlížeči obrázků nebo PDF.","faq3_q":"Dokáže můj Pandas skript číst `.csv` nebo `.sqlite` soubor ve stejné složce?","faq3_a":"Ano. Relativní cesty jako `pd.read_csv('sales.csv')` nebo `sqlite3.connect('app.db')` se vyhodnocují přímo vůči pracovnímu prostoru projektu a všechny upravené či nově vytvořené soubory se po dokončení běhu synchronizují zpět.","faq4_q":"Jsou kromě Pandas podporovány také Polars a DuckDB?","faq4_a":"Ano &#8212; jak `polars`, tak `duckdb` (spolu s `pyarrow` a `fastparquet`) jsou v mobilu podporovány pro bleskové analytické dotazy.","cta_h2":"Analyzujte data &amp; vykreslujte grafy kdekoli na Androidu.","cta_desc":"Nainstalujte si SuperCode IDE zdarma z Google Play a spouštějte NumPy, Pandas, DuckDB a Matplotlib přímo v kapse."},"py_machine_learning":{"metaTitle":"Python aplikace pro strojové učení na Androidu — Scikit-Learn, OpenCV, XGBoost & PyTorch | SuperCode","metaDesc":"Vytvářejte a testujte projekty strojového učení a počítačového vidění v Pythonu na Androidu. Spouštějte Scikit-Learn, XGBoost, LightGBM, OpenCV (cv2), Pillow a NLTK offline a využijte cloudový burst pro PyTorch a TensorFlow.","hero_tag":"SCIKIT-LEARN &#183; XGBOOST &#183; OPENCV (CV2) &#183; PYTORCH CLOUD BURST","hero_h1":"Tvořte pipeline pro <span class=\"text-gradient\">strojové učení a OpenCV vidění</span> na Androidu.","hero_desc":"Proměňte svůj telefon v agilní centrum pro automatizaci. Extrahujte HTML/XML pomocí <strong>Requests, BeautifulSoup4 a lxml</strong>, validujte API přes <strong>Pydantic a orjson</strong>, prototypujte <strong>Telegram boty a routy ve Flasku</strong> a nasazujte rovnou do produkce přes <strong>SFTP nebo Visual Git</strong>.","ml_s1":"XGBoost &amp; LightGBM","ml_s2":"OpenCV &amp; Pillow","ml_s3":"Synchronizace modelů Joblib","ml_s4":"Cloud Tensor Burst","wb_eyebrow":"OFFLINE PRACOVNÍ PROSTŘEDÍ PRO SCIKIT-LEARN, OPENCV A PYTORCH","sec_cap_title":"Hybridní architektura zařízení + cloud pro AI inženýry a studenty","sec_cap_lead":"Trénujte klasické ML a obrazové pipeline 100% offline a na vícegigabajtové frameworky hlubokého učení škálujte jen tehdy, když je váš kód importuje.","f1_title":"Offline Scikit-Learn, XGBoost &amp; LightGBM","f1_desc":"Spouštějte klasifikaci, regresi, shlukování, PCA, křížovou validaci a gradientní boosting zcela offline pomocí scikit-learn, xgboost, lightgbm, statsmodels a patsy.","f1_badge":"RandomForest &#183; XGBoost &#183; LightGBM &#183; Křížová validace","f2_title":"OpenCV (cv2), Pillow &amp; Scikit-Image Vision Studio","f2_desc":"Načítejte PNG/JPEG obrázky ze složky pracovního prostoru, aplikujte prahování, Cannyho detekci hran, kontury, morfologické filtry nebo kompozice v Pillow a ihned si prohlédněte výstup.","f2_badge":"opencv-python (cv2) &#183; Pillow (PIL) &#183; scikit-image","f3_title":"NLP tokenizery, grafové ML a bioinformatika","f3_desc":"Experimentujte s počítáním LLM tokenů přes tiktoken, zpracováním textu v nltk a regex, centralitou grafů v networkx a analýzou sekvencí v biopython.","f3_badge":"tiktoken &#183; nltk &#183; networkx &#183; biopython","f4_title":"Serializace modelů Joblib &amp; Pickle do složky","f4_desc":"Ukládejte natrénované estimátory a předzpracovaná pole přes joblib.dump('model.pkl') nebo np.save('features.npy') přímo do lokálního adresáře v Androidu pro znovupoužití napříč skripty.","f4_badge":"joblib.dump &#183; perzistence .pkl / .npy / .npz","f5_title":"Cloudový burst pro PyTorch, TensorFlow &amp; JAX bez zbytečného objemu","f5_desc":"Importování torch, tensorflow, keras, jax nebo onnxruntime (případně přidání `# @cloud` na začátek souboru) zabalí váš vícesouborový projekt do cloudového clusteru &#8212; ušetříte tak 4+ GB místa v telefonu.","f5_badge":"PyTorch &#183; TensorFlow &#183; Keras &#183; ONNX &#183; # @cloud","f6_title":"Verzování experimentů přes Visual Git &amp; SFTP","f6_desc":"Commitujte notebooky pro feature engineering a Python moduly přes vestavěného klienta Visual Git, nebo upravujte vzdálené trénovací skripty přímo na linuxové GPU stanici přes SFTP s AES-256 SSH klíči.","f6_badge":"Visual Git commity + přímé zrcadlení GPU serveru přes SFTP","workflow_title":"Jak prototypovat ML a Vision modely na Androidu","workflow_lead":"Přejděte plynule od lokálního zkoumání datasetů k ukládání modelů a vzdáleným GPU serverům.","wf1_title":"Připravte příznaky a obrázky v pracovním prostoru","wf1_desc":"Načtěte tabulkové CSV soubory pomocí Pandas nebo čtěte lokální obrázky přes `cv2.imread()` a `PIL.Image.open()` přímo ze složky projektu.","wf2_title":"Natrénujte a validujte klasické ML modely offline","wf2_desc":"Natrénujte pipeline ve Scikit-Learn nebo modely XGBoost offline, vypište klasifikační reporty a exportujte ROC křivky či matice záměn přes Matplotlib.","wf3_title":"Otestujte architektury neuronových sítí přes Cloud Burst","wf3_desc":"Ověřte dimenze tenzorů, vlastní forward průchody `nn.Module` a ztrátové funkce s 1:1 trasováním chyb na konkrétní lokální soubory a řádky.","wf4_title":"Odešlete čistý kód na GitHub nebo na svůj GPU server","wf4_desc":"Nahrajte ověřené experimenty na GitHub přes Visual Git nebo je synchronizujte přímo na vzdálený linuxový trénovací server přes SFTP.","wf_foot_note":"Offline klasické ML a vidění &#183; Trezor SSH klíčů SFTP pro vzdálené GPU servery","table_h2":"Workflow SuperCode AI/ML vs. jiné mobilní vývojářské aplikace","snippet_p":"<strong>SuperCode IDE</strong> umožňuje vývoj strojového učení a počítačového vidění v Pythonu na Androidu a podporuje offline Scikit-Learn, XGBoost, LightGBM, OpenCV (`cv2`), Pillow, NLTK a Tiktoken spolu s cloudově akcelerovaným spouštěním PyTorch a TensorFlow a vzdálenou úpravou na GPU přes SFTP.","table_caption":"SROVNÁNÍ IDE PRO STROJOVÉ UČENÍ A POČÍTAČOVÉ VIDĚNÍ NA ANDROIDU","th_0":"Funkce AI / ML","th_1":"SuperCode Python Studio","th_2":"Běžné kódovací aplikace","th_3":"Colab v mobilním prohlížeči","th_4":"Pouze SSH terminál","tr1_c0":"Klasické ML offline","tr1_c1":"Scikit-Learn, XGBoost, LightGBM &amp; Joblib","tr1_c2":"Nepodporováno","tr1_c3":"Vyžaduje stálé připojení","tr1_c4":"Nutný vzdálený server","tr2_c0":"Počítačové vidění","tr2_c1":"Offline OpenCV (cv2), Pillow &amp; Scikit-Image","tr2_c2":"Nepodporováno","tr2_c3":"Pomalé nahrávání obrázků","tr2_c4":"Bez náhledu obrázků","tr3_c0":"Hluboké učení","tr3_c1":"PyTorch &amp; TensorFlow Cloud Burst (0 GB navíc)","tr3_c2":"Nedostupné nebo několik GB","tr3_c3":"Karta prohlížeče se resetuje","tr3_c4":"Vyžaduje vlastní GPU server","tr4_c0":"Nástroje pro LLM a NLP","tr4_c1":"tiktoken, nltk, regex, pydantic, orjson","tr4_c2":"Chybějící Rust/C wheel balíčky","tr4_c3":"Ruční `!pip install`","tr4_c4":"Ruční nastavení","tr5_c0":"Vzdálené úpravy na GPU","tr5_c1":"Nativní zrcadlení karet přes SFTP + Visual Git","tr5_c2":"Žádné","tr5_c3":"Žádné","tr5_c4":"CLI Vim/Nano se zpožděním","faq_lead":"Odpovědi k používání Scikit-Learn, OpenCV, PyTorch a vzdálených GPU workflow z Androidu.","faq1_q":"Mohu spouštět Scikit-Learn, XGBoost a OpenCV (`cv2`) bez internetu?","faq1_a":"Ano. Jakmile jsou balíčky uloženy v mezipaměti vědeckého runtime SuperCode v zařízení, `scikit-learn`, `xgboost`, `lightgbm`, `opencv-python` (`cv2`), `Pillow` a `scikit-image` běží zcela offline.","faq2_q":"Jak spustím kód v PyTorch nebo TensorFlow bez zaplnění úložiště telefonu?","faq2_a":"Stačí napsat `import torch` nebo `import tensorflow as tf` (případně dát `# @cloud` na 1. řádek). SuperCode zabalí vaše lokální `.py` moduly, spustí je na cloudovém Python clusteru a případné tracebacky namapuje přímo na řádky v lokálním editoru.","faq3_q":"Mohu upravovat a spouštět skripty na vlastní linuxové GPU stanici?","faq3_a":"Ano. Připojte svou stanici přes SFTP pracovní prostor v SuperCode (s podporou Ed25519/RSA SSH klíčů šifrovaných pomocí AES-256) a upravujte vzdálené `.py` a `.yaml` konfigurace s plným AST doplňováním a 3fázovým atomickým ukládáním.","faq4_q":"Uloží funkce `cv2.imwrite()` zpracované obrázky do mé složky?","faq4_a":"Ano &#8212; každý obrázek zapsaný přes `cv2.imwrite()` nebo `Image.save()` se okamžitě synchronizuje do adresáře projektu a pohodlně se otevře ve vestavěném prohlížeči obrázků v SuperCode.","cta_h2":"Prototypujte ML a Vision modely kdekoli.","cta_desc":"Stáhněte si SuperCode IDE zdarma na Google Play pro Scikit-Learn, OpenCV, PyTorch burst a SFTP GPU workflow."},"py_automation":{"metaTitle":"Python aplikace pro web scraping, API a Telegram boty na Androidu | SuperCode","metaDesc":"Vytvářejte web scrapery v Pythonu, REST API klienty, Telegram boty a skripty pro automatizaci dokumentů na Androidu. Podporuje Requests, BeautifulSoup4, lxml, Pydantic, Flask, Telebot, SQLite3 a python-docx.","hero_tag":"REQUESTS &#183; BEAUTIFULSOUP4 &#183; LXML &#183; PYDANTIC &#183; TELEBOT &#183; FLASK","hero_h1":"Automatizujte <span class=\"text-gradient\">web scraping, REST API a boty</span> v Pythonu na Androidu.","hero_desc":"Proměňte svůj telefon v agilní centrum pro automatizaci. Extrahujte HTML/XML pomocí <strong>Requests, BeautifulSoup4 a lxml</strong>, validujte API přes <strong>Pydantic a orjson</strong>, prototypujte <strong>Telegram boty a routy ve Flasku</strong> a nasazujte rovnou do produkce přes <strong>SFTP nebo Visual Git</strong>.","au_s1":"Requests &amp; lxml","au_s2":"orjson &amp; .env","au_s3":"Telebot &amp; WebSocket","au_s4":"Nasazení na Linux VPS","wb_eyebrow":"PRACOVNÍ PROSTŘEDÍ PRO WEB SCRAPING, PYDANTIC API A SQLITE AUTOMATIZACI","sec_cap_title":"Praktické skriptování v Pythonu a prototypování backendu na mobilu","sec_cap_lead":"Nainstalujte automatizační knihovny jedním klepnutím, testujte na živých API či lokálních souborech a nasaďte na cloudový VPS bez otevírání notebooku.","f1_title":"Requests, BeautifulSoup4 &amp; nativní parsování v lxml","f1_desc":"Stahujte webové stránky a XML/RSS kanály pomocí requests a urllib, parsujte složité DOM selektory přes beautifulsoup4 (bs4) a předkompilované lxml a exportujte strukturovaná JSON nebo CSV data přímo do své složky.","f1_badge":"requests &#183; beautifulsoup4 &#183; lxml &#183; CSS selektory","f2_title":"Pydantic v2, orjson, PyJWT &amp; bezpečná práce s .env tajemstvími","f2_desc":"Validujte přísná schémata webhooků a REST API pomocí pydantic, serializujte miliony JSON záznamů přes orjson/ujson, podepisujte tokeny s PyJWT a cryptography a načítajte přístupy čistě z .env souborů přes python-dotenv.","f2_badge":"pydantic &#183; orjson &#183; PyJWT &#183; cryptography &#183; dotenv","f3_title":"Telegram boti, WebSockets &amp; Rich CLI nástroje","f3_desc":"Čipy pro PIP na jedno klepnutí okamžitě nainstalují telebot (pyTelegramBotAPI), rich a colorama &#8212; stavějte interaktivní handlery botů, DNS diagnostiku (dnspython) a TrueColor terminálové dashboardy v telefonu.","f3_badge":"telebot &#183; websocket-client &#183; dnspython &#183; rich","f4_title":"SQLite3, SQLAlchemy &amp; skripty pro Word / PowerPoint / PDF","f4_desc":"Automatizujte rutinní práci s dokumenty přímo na Androidu: generujte .docx reporty přes python-docx, prezentace přes python-pptx, parsujte PDF soubory a dotazujte se do lokálních databází SQLite.","f4_badge":"sqlite3 &#183; sqlalchemy &#183; python-docx &#183; python-pptx","f5_title":"Multi-formátový API formátovač &amp; Error Radar","f5_desc":"Kontrolujete surové API payloady? SuperCode formátuje Python, JSON, XML, YAML, TOML, SQL a HTML offline jedním klepnutím, zatímco Error Radar zachytává syntaktické chyby v reálném čase.","f5_badge":"Offline formátovač JSON / YAML / XML / Python","f6_title":"Plynulé nasazení na VPS přes SFTP &amp; Visual Git","f6_desc":"Jakmile váš bot nebo Flask služba funguje lokálně, commitněte `.env.example` a `requirements.txt` přes Visual Git nebo nahrajte projekt rovnou na Ubuntu/Debian VPS přes SFTP.","f6_badge":"Test v telefonu -&gt; Nasazení na produkční VPS přes SFTP","workflow_title":"Od mobilního prototypu scraperu či bota k nasazení na VPS","workflow_lead":"Vytvářejte, testujte, kontrolujte výstupy a publikujte produkční Python skripty z jediného sjednoceného Android IDE.","wf1_title":"Klepněte na rychlé čipy ve Visual PIP Manageru","wf1_desc":"Nainstalujte `requests`, `beautifulsoup4`, `rich`, `pyyaml`, `flask` nebo `telebot` během pár sekund pomocí vestavěných čipů pro rychlou instalaci.","wf2_title":"Uložte API klíče bezpečně do .env a spusťte skript","wf2_desc":"Uchovávejte API tokeny v lokálním souboru `.env` (automaticky připojeném do pracovního prostoru) a sledujte formátované Rich/ANSI logy v konzoli.","wf3_title":"Ověřte exportovaná data v JSON, CSV nebo SQLite","wf3_desc":"Otevřete vygenerované soubory `.json` nebo `.csv` s hezkým formátováním jedním klepnutím, nebo procházejte tabulky `.db` v SQL Exploreru v SuperCode.","wf4_title":"Commitněte na GitHub nebo zrcadlete na vzdálený server","wf4_desc":"Odešlete aktualizace do repozitáře nebo upravujte skripty systemd/botů přímo na vzdáleném serveru přes šifrované SFTP.","wf_foot_note":"120s okno spuštění přizpůsobené síti &#183; Vykreslování ANSI TrueColor v konzoli","table_h2":"SuperCode Automation Studio vs. základní spouštěče skriptů","snippet_p":"<strong>SuperCode IDE</strong> je kompletní aplikace pro automatizaci v Pythonu, web scraping a vývoj botů na Androidu, která spojuje instalaci přes PIP jedním klepnutím (`requests`, `bs4`, `flask`, `telebot`, `rich`), nativní podporu `lxml`/`pydantic`/`orjson`, integraci `.env` a SQLite a vestavěné nasazení přes SFTP/Git.","table_caption":"SROVNÁNÍ NÁSTROJŮ PRO WEB SCRAPING A AUTOMATIZACI V PYTHONU NA ANDROIDU","th_0":"Automatizační funkce","th_1":"SuperCode Python Studio","th_2":"Aplikace pro spouštění snippetů","th_3":"Cloudová webová IDE","th_4":"Čistý SSH klient","tr1_c0":"HTML/XML parsery","tr1_c1":"BeautifulSoup4 + předkompilované nativní lxml","tr1_c2":"Pouze Regex/html.parser","tr1_c3":"Blokováno cílovými IP adresami","tr1_c4":"Pouze na straně serveru","tr2_c0":"Rychlý JSON a schémata","tr2_c1":"Pydantic v2 + orjson + ujson + PyJWT","tr2_c2":"Selhává na Rust wheel balíčcích","tr2_c3":"Podporováno","tr2_c4":"Ruční nastavení venv","tr3_c0":"Knihovny pro boty a CLI","tr3_c1":"Čipy na 1 klepnutí: telebot, requests, flask, rich","tr3_c2":"Ručně nebo nepodporováno","tr3_c3":"Kontejner se uspává","tr3_c4":"Podporováno","tr4_c0":"Kontrola payloadů","tr4_c1":"Vestavěný formátovač JSON/YAML/XML + SQL GUI","tr4_c2":"Čistý neformátovaný text","tr4_c3":"Oddělené karty","tr4_c4":"CLI jq/sqlite3","tr5_c0":"Nasazení na VPS","tr5_c1":"Integrovaný klient SFTP/FTPS + Visual Git","tr5_c2":"Kopírování kódu ven","tr5_c3":"Ruční git v CLI","tr5_c4":"Bez lokálního offline testu","faq_lead":"Odpovědi k web scrapingu, souborům `.env`, Telegram botům a nasazování Python skriptů z Androidu.","faq1_q":"Fungují `lxml` a `pydantic` společně s `requests` a `beautifulsoup4`?","faq1_a":"Ano. Podporovány jsou jak čistě pythonové knihovny (`requests`, `beautifulsoup4`, `telebot`, `rich`), tak kompilované parsery (`lxml`, `pydantic`, `orjson`, `cryptography`).","faq2_q":"Může můj Python skript načítat proměnné ze souboru `.env` nebo `config.yaml`?","faq2_a":"Ano. Resolver pracovního prostoru v SuperCode automaticky připojuje soubory `.env`, `.yaml`, `.yml`, `.toml`, `.ini` a `.json` vedle vašich `.py` modulů.","faq3_q":"Jak dlouho může web scraper nebo polling bota běžet v interaktivní konzoli?","faq3_a":"Interaktivní skripty běží až v 120sekundovém okně na jedno lokální spuštění (s možností okamžitého zastavení/přerušení kdykoli), takže můžete bezpečně testovat API volání, scrapery i webhook handlery botů bez nekontrolovaného vybíjení baterie na pozadí.","faq4_q":"Jak spustím Telegram bota 24/7 po otestování v SuperCode?","faq4_a":"Vytvořte a odlaďte handlery bota lokálně v SuperCode a poté použijte vestavěného klienta SFTP nebo Visual Git v SuperCode k odeslání projektu přímo na váš linuxový VPS nebo cloudový host pro nepřetržitý provoz 24/7.","cta_h2":"Stavějte scrapery, API a boty přímo z telefonu.","cta_desc":"Získejte SuperCode IDE zdarma na Google Play s PIP čipy na 1 klepnutí, podporou Pydantic/lxml a nasazením přes SFTP."},"py_workspace":{"metaTitle":"Vícesouborové Python IDE pro Android — Projektové složky, interaktivní input(), PEP 8 & Git | SuperCode","metaDesc":"Vyvíjejte skutečné vícesouborové Python projekty na Androidu. Chytré směrování vstupního bodu main.py, balíčky PEP 420, živé překrytí neuložených karet, dělená konzole pro interaktivní input(), AST doplňování, formátovač PEP 8 a Visual Git.","hero_tag":"VÍCESOUBOROVÉ BALÍČKY &#183; CHYTRÉ SMĚROVÁNÍ VSTUPU &#183; PEP 8 &#183; VISUAL GIT","hero_h1":"Skutečná <span class=\"text-gradient\">vícesouborová architektura Pythonu</span> a Git na Androidu.","hero_desc":"Přerůstejte jednosouborové zápisníky. SuperCode automaticky vyřeší <strong>balíčky v <code>src/</code>, relativní importy a kořeny <code>pyproject.toml</code></strong> &#8212; můžete upravovat pomocné moduly s <strong>AST doplňováním</strong>, z libovolné karty klepnutím na Spustit odpálit <strong><code>main.py</code></strong> a odesílat commity přes <strong>Visual Git</strong>.","ws_s1":"Soubory / Pracovní prostor","ws_s2":"Určení main.py","ws_s3":"AST &amp; Error Radar","ws_s4":"&amp; vestavěné SFTP","wb_eyebrow":"PRACOVNÍ PROSTOR PRO VÍCE MODULŮ V PYTHONU A UNITTESTY","sec_cap_title":"Ergonomie Python projektů na úrovni desktopu přepracovaná pro dotyk","sec_cap_lead":"Každý detail resolveru pracovního prostoru Pythonu v SuperCode byl navržen tak, aby odstranil tření při správě souborů na mobilu.","f1_title":"Chytré určení vstupního bodu z jakékoli otevřené karty","f1_desc":"Upravujete `services/ledger.py` nebo `models/user.py` bez spouštěcího kódu na nejvyšší úrovni? Klepnutí na Spustit automaticky vyhledá kořen projektu (`pyproject.toml`, `requirements.txt`, `.git`) a spustí `main.py`, `app.py`, `run.py` nebo `src/main.py`.","f1_badge":"Úprava modulu -&gt; Klepnutí na Spustit -&gt; Spustí main.py","f2_title":"Živé překrytí neuložených karet v paměti &amp; jmenné prostory PEP 420","f2_desc":"Upravte tři otevřené `.py` karty a ihned klepněte na Spustit &#8212; SuperCode překryje vaše neuložené buffery editoru v paměti, aniž by zaplavoval složky `src/` nechtěnými prázdnými soubory `__init__.py`.","f2_badge":"Okamžité spuštění &#183; Implicitní jmenné balíčky PEP 420","f3_title":"Skutečné interaktivní input() &amp; dělená konzole s [EOF]","f3_desc":"Testujte CLI aplikace se sekvenčním voláním `input()` a `sys.stdin.readline()`. Konzole se na telefonech automaticky ukotví pod kódem a na tabletech se rozdělí v poměru 55 % / 45 % vedle sebe s okamžitým zastavením/přerušením.","f3_badge":"Neblokující fronta Stdin &#183; Signál [EOF] &#183; Dělení 55:45","f4_title":"Offline AST doplňování, formátovač PEP 8 &amp; Error Radar","f4_desc":"Napište `.` u tříd a modulů pro submilisekundové offline AST doplňování, naformátujte rozházené odsazení podle PEP 8 jedním klepnutím a odhalte smíšené tabulátory a mezery (`TabError`) či chybějící dvojtečky přes Error Radar ještě před spuštěním.","f4_badge":"AST Scope Engine &#183; PEP 8 na 1 klepnutí &#183; TabError Radar","f5_title":"Plnohodnotný Visual Git &amp; Time Machine pro 120 commitů","f5_desc":"Klonujte soukromé GitHub/GitLab Python repozitáře přes HTTPS PAT, vytvářejte feature větve, prohlížejte barevně zvýrazněné diffy, řešte merge konflikty vizuálně a pushujte commity bez opuštění editoru.","f5_badge":"Clone &#183; Branch &#183; Vizuální Merge &#183; Commit &amp; Push","f6_title":"Fuzzy vyhledávač pro 50 000 uzlů &amp; globální Regex vyhledávání","f6_desc":"Skočte na jakýkoli `.py` modul v obřích monorepozitářích během milisekund pomocí fuzzy vyhledávače souborů, nebo refaktorujte názvy funkcí v celém projektu streamovaným regex vyhledáváním a nahrazováním.","f6_badge":"Fuzzy skok na soubor &#183; Celoprojektový Regex refaktoring","workflow_title":"Jak naklonovat, refaktorovat, otestovat a pushnout Python repozitář na Androidu","workflow_lead":"Kompletní životní cyklus softwarového inženýrství přímo na vašem telefonu nebo tabletu Android.","wf1_title":"Naklonujte GitHub repozitář nebo otevřete lokální strom projektu","wf1_desc":"Klonujte přes HTTPS Personal Access Token nebo otevřete libovolnou složku v úložišti zařízení &#8212; balast jako `.git`, `venv` a `__pycache__` je při skenování automaticky ignorován.","wf2_title":"Upravujte moduly s AST doplňováním a 21klávesovou lištou symbolů","wf2_desc":"Přejeďte prstem nahoru po 21klávesové liště symbolů pro `:`, `-&gt;`, `_`, `()`, `[]` a `INDENT` a klepnutím na Formátovat získejte čisté 4mezerníkové zarovnání PEP 8.","wf3_title":"Spouštějte vstupní skripty nebo sady jednotkových testů offline","wf3_desc":"Spouštějte `main.py` nebo sady `unittest` offline s okamžitým měřením v milisekundách a klikatelnou navigací ve stack-trace.","wf4_title":"Zkontrolujte sjednocené diffy, commitněte a pushněte do upstreamu","wf4_desc":"Prohlédněte si změny řádek po řádku v Git Time Machine, připravte soubory ke commitu a čistě je pushněte zpět na GitHub, GitLab nebo Bitbucket.","wf_foot_note":"Podporuje až 250 souborů pracovního prostoru na jedno spuštění &#183; Automatická obnova bytecode cache za 2,5 s","table_h2":"Vícesouborový Python Workspace SuperCode vs. mobilní zápisníky","snippet_p":"<strong>SuperCode IDE</strong> přináší na Android podporu vícesouborových Python projektů na desktopové úrovni, včetně automatického rozpoznání kořenů `pyproject.toml`/`src/`, chytrého určení vstupu `main.py`, paměťových překryvů neuložených karet, formátování PEP 8, AST doplňování a vestavěného Visual Gitu.","table_caption":"SROVNÁNÍ IDE PRO VÍCESOUBOROVÉ PYTHON PROJEKTY NA ANDROIDU","th_0":"Inženýrská funkce","th_1":"SuperCode Python Studio","th_2":"Jednosouborové Python aplikace","th_3":"Cloudová IDE v prohlížeči","th_4":"CLI terminálové editory","tr1_c0":"Kořen projektu a src/","tr1_c1":"Automaticky řeší pyproject.toml, src/ a PEP 420","tr1_c2":"Pouze plochý jednotlivý skript","tr1_c3":"Podporováno (pouze online)","tr1_c4":"Ruční PYTHONPATH","tr2_c0":"Spuštění ze submodulu","tr2_c1":"Chytré směrování vstupu -&gt; Spustí main.py/app.py","tr2_c2":"Spustí chybný pomocný soubor","tr2_c3":"Ruční launch.json","tr2_c4":"Ruční příkaz v CLI","tr3_c0":"Neuložené karty","tr3_c1":"Živé překrytí v paměti napříč všemi otevřenými kartami","tr3_c2":"Nutno nejprve uložit každý soubor","tr3_c3":"Prodleva automatického ukládání","tr3_c4":"Pouze buffer","tr4_c0":"Nástroje kvality kódu","tr4_c1":"AST doplňování + formátování PEP 8 + TabError Radar","tr4_c2":"Základní seznam klíčových slov","tr4_c3":"Podporováno","tr4_c4":"Vyžaduje LSP plugin","tr5_c0":"Správa verzí","tr5_c1":"Visual Git Time Machine &amp; řešič konfliktů","tr5_c2":"Žádná","tr5_c3":"Webové Git rozhraní","tr5_c4":"Textový CLI git merge","faq_lead":"Dotazy ke struktuře `src/`, relativním importům, `unittest` a integraci Gitu pro Python na Androidu.","faq1_q":"Co se stane, když stisknu Spustit při úpravě pomocného modulu jako `utils/helpers.py`?","faq1_a":"Pokud `helpers.py` pouze definuje funkce nebo třídy bez spouštěcího kódu na nejvyšší úrovni, SuperCode automaticky vyhledá vstupní skript projektu (`main.py`, `app.py`, `run.py`, `__main__.py` nebo `src/main.py`) a spustí celou aplikaci.","faq2_q":"Podporuje SuperCode syntaxi Pythonu 3.12, jako je `match/case` a aliasy `type`?","faq2_a":"Strukturální `match/case` a `tomllib` fungují offline v Pythonu 3.11+ a soubory využívající generickou syntaxi aliasů `type` podle PEP 695 automaticky aktivují podporu Pythonu 3.12.","faq3_q":"Potřebuji `__init__.py` v každé složce, aby fungovaly importy napříč složkami?","faq3_a":"Ne. SuperCode respektuje implicitní jmenné balíčky PEP 420 a čistě připojí kořen projektu, aniž by do vašeho repozitáře vkládal nechtěné soubory `__init__.py`.","faq4_q":"Mohu klonovat soukromé GitHub repozitáře a spouštět jejich Python testy offline?","faq4_a":"Ano. Naklonujte repozitář přes HTTPS + Personal Access Token ve Visual Gitu, nainstalujte jednorázově `requirements.txt` a upravujte i spouštějte sady `unittest` zcela offline kdekoli.","cta_h2":"Stavějte skutečné vícesouborové Python projekty na Androidu.","cta_desc":"Stáhněte si SuperCode IDE zdarma na Google Play pro vícemodulový Python, nástroje PEP 8 a Visual Git."},"py_learn":{"metaTitle":"Aplikace pro programování v Pythonu pro začátečníky a studenty — Učte se Python offline na Androidu | SuperCode","metaDesc":"Procvičujte a učte se Python offline na Androidu bez nutnosti přihlášení. SuperCode obsahuje 8 spustitelných šablon v Pythonu, živou konzoli input(), 21klávesovou lištu symbolů pro Python, Error Radar a PIP/NumPy.","hero_tag":"BEZ PŘIHLÁŠENÍ &#183; 100% REŽIM LETADLO &#183; 8 STARTOVACÍCH ŠABLON","hero_h1":"<span class=\"text-gradient\">Aplikace pro Python</span> stvořená pro učení a praxi kdekoli.","hero_desc":"Neklikejte jen na kvízy s výběrem odpovědí &#8212; pište a spouštějte <strong>skutečný kód v Python 3</strong> přímo v telefonu. SuperCode se spustí za milisekundy, <strong>bez registrace</strong>, se <strong>100% offline během</strong>, <strong>8 spustitelnými šablonami</strong>, <strong>21klávesovou lištou symbolů</strong> a okamžitou kontrolou <strong>Error Radar</strong>.","ln_s1":"Okamžitý offline start","ln_s2":"Spustitelné šablony","ln_s3":"Výsuvná lišta symbolů","ln_s4":"Jazyky pro informatiku v 1 appce","wb_eyebrow":"INTERAKTIVNÍ PROSTŘEDÍ PRO PYTHON OD ZAČÁTEČNÍKŮ PO ZÁKLADY INFORMATIKY","sec_cap_title":"Proč studenti a samouci volí skutečné programování před hravými kvízy","sec_cap_lead":"Všechno, co vás při psaní Pythonu na obrazovce mobilu brzdilo, je vyřešeno přímo na úrovni nativního UI.","f1_title":"100% offline praxe v režimu letadlo bez nutnosti účtu","f1_desc":"Otevřete aplikaci v metru, autobuse, na koleji nebo v letadle a ihned spouštějte Python. Žádná nucená registrace e-mailem, žádné čekání na cloud a nulová spotřeba mobilních dat.","f1_badge":"Funguje offline kdekoli &#183; Okamžitý studený start","f2_title":"21klávesová lišta symbolů pro Python s tažením nahoru","f2_desc":"Běžné mobilní klávesnice schovávají `:`, `_`, `[]`, `{}`, `=` a `Tab` do třetí vrstvy. Ergonomická lišta SuperCode dává chytré 4mezerové odsazení INDENT, dvojtečky, závorky, uvozovky i šipky kurzoru přímo nad klávesnici.","f2_badge":"Klepnutí + sekundární znaky tahem nahoru &#183; Chytré 4mezerové odsazení","f3_title":"Živý Error Radar odhalí začátečnické překlepy včas","f3_desc":"Zapomněli jste dvojtečku `:` za `if` nebo `def`? Smíchali mezery a tabulátory (`TabError`)? Nechali neuzavřenou `(`? Error Radar zvýrazní přesný řádek ještě před spuštěním a formátování PEP 8 jedním klepnutím opraví chaotické odsazení.","f3_badge":"Hlídání chybějící dvojtečky &#183; Ochrana před TabError &#183; PEP 8 jedním klepnutím","f4_title":"8 vestavěných šablon pro Python a interaktivní input()","f4_desc":"Načtěte z lišty hotové spustitelné ukázky proměnných, vstupů `input()`, funkcí, OOP s `@dataclass`, čtení/zápisu souborů a algoritmů &#8212; pak kód upravte a ihned znovu spusťte.","f4_badge":"8 vybraných ukázek &#183; Živý vícenásobný vstup input()","f5_title":"Nativní export kódu do PDF A4 pro odevzdání úkolů","f5_desc":"Potřebujete odevzdat formátovaný zdrojový kód do školního cvičení nebo portálu? Exportujte jakýkoli skript v Pythonu přímo z menu editoru do čistého PDF A4 se zvýrazněním syntaxe a čísly řádků.","f5_badge":"Export do PDF A4 se zvýrazněním syntaxe &#183; Připraveno pro výuku","f6_title":"Jedna 40,2 MB aplikace pokryje celé studium informatiky","f6_desc":"Začněte dnes základy Pythonu a pokračujte k ukazatelům v C17, datovým strukturám v C++20 STL, OOP v Java 17, SQL databázím, webovým cvičením HTML/CSS/JS/PHP, Linux Shell a Git bez instalace sedmi různých aplikací.","f6_badge":"Python + C17 + C++20 + Java 17 + SQL + Web + Git","workflow_title":"Jak začít psát Python v telefonu do 60 sekund","workflow_lead":"Žádná složitá konfigurace &#8212; nainstalujte, vyberte šablonu nebo prázdný soubor a spusťte.","wf1_title":"Vytvořte skript `.py` nebo načtěte vestavěnou ukázku","wf1_desc":"Nainstalujte SuperCode z Google Play, vytvořte `hello.py` nebo otevřete menu Ukázky a načtěte jednu z 8 spustitelných šablon pro Python.","wf2_title":"Pište snadno díky chytrému odsazení a doplňování","wf2_desc":"Používejte 21klávesovou lištu pro `:`, `()` a `Tab`, zatímco offline návrhy z AST vám za běhu napoví metody v Pythonu.","wf3_title":"Spouštějte offline a zadávejte vstupy pro input()","wf3_desc":"Klepněte na Spustit &#9654; a sledujte výstup během milisekund, zadávejte živé testovací vstupy v ukotvené konzoli a čtěte přehledná hlášení chyb po řádcích.","wf4_title":"Přejděte na knihovny PIP, datovou vědu a GitHub","wf4_desc":"S rostoucími dovednostmi instalujte balíčky z PyPI, kreslete grafy v Matplotlib, exportujte úkoly do PDF A4 nebo nahrajte své projekty na GitHub.","wf_foot_note":"8 šetrných studiových motivů (tmavých i světlých) &#183; 32 jazyků rozhraní","table_h2":"SuperCode vs. herní kvízové aplikace a online kompilátory","snippet_p":"<strong>SuperCode</strong> je bezplatná offline aplikace pro Python na Android určená začátečníkům, studentům a samoukům. Na rozdíl od kvízových aplikací nebo online kompilátorů závislých na internetu nabízí skutečný offline runtime Python 3.11/3.12, živou konzoli `input()`, 21klávesovou lištu symbolů, Error Radar a nativní export úkolů do PDF A4.","table_caption":"UČENÍ PYTHONU NA ANDROIDU: SROVNÁNÍ APLIKACÍ","th_0":"Požadavek na učení","th_1":"SuperCode Coding App","th_2":"Kvízové aplikace","th_3":"Webové kompilátory","th_4":"Pouze stolní PC","tr1_c0":"Skutečné spouštění kódu","tr1_c1":"Plný offline Python 3.11/3.12 + více souborů","tr1_c2":"Kvízy s doplňováním mezer","tr1_c3":"Online okno pro jeden soubor","tr1_c4":"Plné","tr2_c0":"Práce bez Wi-Fi","tr2_c1":"100% offline (metro, autobus, učebna)","tr2_c2":"Vyžaduje předplatné/internet","tr2_c3":"Offline nefunguje","tr2_c4":"Offline","tr3_c0":"Rychlost psaní na mobilu","tr3_c1":"21klávesová lišta + AST + PEP 8 jedním klepnutím","tr3_c2":"Minimum psaní","tr3_c3":"Výchozí klávesnice telefonu","tr3_c4":"Fyzická klávesnice","tr4_c0":"Možnosti dalšího růstu","tr4_c1":"PIP, NumPy, Pandas, OpenCV, SQL a Git","tr4_c2":"Narazí na limit po základech","tr4_c3":"Bez lokálních souborů a Git","tr4_c4":"Plné","tr5_c0":"Další jazyky pro studium IT","tr5_c1":"Zahrnuje C, C++, Java 17, JS, PHP a SQL","tr5_c2":"Samostatné placené kurzy","tr5_c3":"Karty prohlížeče","tr5_c4":"Více těžkopádných IDE","faq_lead":"Časté dotazy začátečníků, studentů informatiky a vyučujících.","faq1_q":"Hodí se SuperCode i pro úplné začátečníky, kteří se učí Python na telefonu?","faq1_a":"Ano. Nemusíte nastavovat kompilátory, cesty ani účty &#8212; stačí vytvořit soubor `.py` (nebo vybrat jednu z 8 vestavěných ukázek Pythonu) a klepnout na Spustit. Error Radar a formátování PEP 8 jedním klepnutím pomohou začátečníkům ihned opravit překlepy.","faq2_q":"Mohu offline procvičovat úlohy typu LeetCode a algoritmy nad datovými strukturami?","faq2_a":"Ano. Všechny standardní algoritmické moduly (`collections`, `heapq`, `bisect`, `itertools`, `functools`, `math`, `typing`) běží 100% offline s měřením času běhu v milisekundách a spotřeby paměti.","faq3_q":"Mohou učitelé používat SuperCode v učebnách bez studentské Wi-Fi?","faq3_a":"Rozhodně. Základní Python 3.11 běží offline ihned po instalaci, offline archivy `.whl` lze sdílet lokálně bez internetu a studenti mohou hotové úkoly exportovat přímo jako PDF A4 se zvýrazněním syntaxe.","faq4_q":"Podporuje SuperCode kromě tmavého režimu i světlý režim pro čtení ve dne?","faq4_a":"Ano &#8212; SuperCode nabízí 8 optických studiových motivů (ostré světlé i tmavé motivy s nízkým oslněním) a plynulé přiblížení písma editoru i konzole.","cta_h2":"Začněte svou cestu s Pythonem offline ještě dnes.","cta_desc":"Stáhněte si SuperCode IDE zdarma na Google Play &#8212; bez přihlášení, včetně 8 šablon pro Python."},"c_pointers_lab":{"metaTitle":"Učte se programování v C offline na Androidu — Laboratoř ukazatelů, struktur a malloc | SuperCode","metaDesc":"Učte se ANSI/GNU C17 offline na Androidu bez zastaralých chyb Turbo C . Procvičujte ukazatele, struktury, malloc/free, bitové operace a  s 6 šablonami C a exportem do PDF A4.","hero_tag":"ČISTÉ GNU C17 &#183; LABORATOŘ UKAZATELŮ A HALDY &#183; 6 VESTAVĚNÝCH ŠABLON","hero_h1":"Učte se <span class=\"text-gradient\">ukazatele v C, struktury a dynamickou paměť</span> offline na Androidu.","hero_desc":"Přestaňte bojovat s aplikacemi Turbo C <code>&lt;conio.h&gt;</code> z 90. let, které učí neplatnou syntaxi. SuperCode dává studentům informatiky skutečnou <strong>offline laboratoř GNU C17 (<code>-std=gnu17</code>)</strong> s automatickým linkováním <strong><code>&lt;math.h&gt;</code> (<code>-lm</code>)</strong>, <strong>6 spustitelnými šablonami C</strong>, <strong>doplňováním struktur AST <code>-&gt;</code></strong> a exportem úkolů do <strong>PDF A4</strong> jedním klepnutím.","cp1_s1":"Čisté -std=gnu17","cp1_s2":"Cvičebních šablon C","cp1_s3":"Auto linkování math.h","cp1_s4":"Export úkolů do PDF","wb_eyebrow":"INTERAKTIVNÍ PRACOVNÍ PROSTŘEDÍ PRO C17: UKAZATELE, STRUKTURY A MATH.H","sec_cap_title":"Navrženo přímo pro základy informatiky, systémové programování a cvičení","sec_cap_lead":"Každý detail je vyladěn tak, aby studenti psali čisté, na univerzitách uznávané ISO/GNU C17 na telefonu či tabletu&#8212;i v přednáškovém sále bez Wi-Fi.","f1_title":"Moderní GNU C17 &#8212; žádné zastaralé pasti Turbo C","f1_desc":"Řada aplikací pro C na Google Play emuluje Turbo C z éry DOS (void main(), clrscr(), getch(), 16bitový int), které neprojdou univerzitními testy. SuperCode kompiluje pravé 64bitové GNU C17 (-std=gnu17) shodné se školními Linux servery.","f1_badge":"-std=gnu17 &#183; 64bitové ukazatele &#183; Kompatibilní s autogradery","f2_title":"6 spustitelných C šablon přímo na liště nástrojů","f2_desc":"Spusťte hotová cvičení jedním klepnutím: pointers.c (adresy a dereference), structs.c (složené záznamy), bitwise.c (masky a bitové posuny), sinewave.c (trigonometrické DSP), echo.c (stdin) a hello.c.","f2_badge":"pointers.c &#183; structs.c &#183; bitwise.c &#183; sinewave.c &#183; echo.c","f3_title":"AST doplňování členů struktur přes -&gt; a .","f3_desc":"Tvoříte jednosměrné či obousměrné spojové seznamy, binární stromy nebo hlavičky paketů? Napište node-&gt; nebo record. a zobrazte přesné položky struct a union offline bez nutnosti pamatovat si všechny názvy polí.","f3_badge":"node-&gt;next &#183; record.field &#183; Offline AST engine","f4_title":"Automatické linkování -lm (&lt;math.h&gt;) a standardních knihoven","f4_desc":"Používejte sin(), cos(), sqrt(), pow(), hypot() a fma() z &lt;math.h&gt; společně s &lt;stdlib.h&gt;, &lt;stdint.h&gt;, &lt;stdbool.h&gt; a &lt;inttypes.h&gt;, aniž byste museli ručně zadávat příznak gcc -lm.","f4_badge":"Auto-linkování &lt;math.h&gt; &#183; &lt;stdint.h&gt; &#183; &lt;stdlib.h&gt;","f5_title":"21klávesová lišta symbolů pro C a Error Radar v reálném čase","f5_desc":"Vložte -&gt;, *, &amp;, {}, [], ;, #include a != jediným tažením nahoru. Error Radar během psaní hlásí nespárované závorky, zapomenuté znaky a chybné hlavičky #include ještě před kompilací.","f5_badge":"21klávesová výsuvná lišta &#183; Živý Error Radar &#183; Formátování jedním klepnutím","f6_title":"Export domácích úkolů do PDF A4 se zvýrazněním syntaxe","f6_desc":"Dokončili jste úkol se spojovým seznamem nebo dynamickou pamětí? Exportujte zdrojový kód .c přímo do ostrého PDF A4 se zvýrazněním syntaxe a čísly řádků pro Canvas, Moodle nebo Google Učebnu.","f6_badge":"Nativní PDF A4 &#183; Čísla řádků &#183; Bez vodoznaků","workflow_title":"Jak offline procvičovat ukazatele v C a laboratorní úkoly","workflow_lead":"Od prázdné obrazovky k ověřené binárce C17 a formátovanému PDF protokolu ve čtyřech krocích.","wf1_title":"Vyberte vestavěnou šablonu C17 nebo nový soubor .c","wf1_desc":"Otevřete pointers.c, structs.c, bitwise.c nebo sinewave.c z lišty C&#8212;bez registrace účtu či připojení k internetu.","wf2_title":"Pište logiku ukazatelů a struktur rychlostí desktopu","wf2_desc":"Využijte vyhrazené klávesy *, &amp; a -&gt; spolu s offline AST doplňováním členů struktur pro alokaci a procházení uzlů na haldě.","wf3_title":"Kompilujte offline a sledujte telemetrii paměti","wf3_desc":"Klepněte na Spustit pro kompilaci striktně jako C17 (nikdy přes C++) a zkontrolujte výstup, návratový kód, čas v &#181;s/ms i špičku paměti v KB.","wf4_title":"Naformátujte styl K&amp;R/Allman a exportujte PDF A4","wf4_desc":"Upravte odsazení jediným klepnutím a vygenerujte tisknutelný protokol PDF A4 přímo ze svého zařízení Android.","wf_foot_note":"100% C17 v režimu letadlo &#183; Odděleno od name-manglingu C++ &#183; 8 šetrných motivů","table_h2":"SuperCode C17 Laboratoř vs. zastaralé mobilní C aplikace","snippet_p":"<strong>Offline C17 programovací laboratoř SuperCode</strong> pomáhá studentům učit se na Androidu ukazatele v C, struktury, dynamickou alokaci paměti (<code>malloc</code> a <code>free</code>) a bitové operace bez zastaralých kliček z Turbo C. Spojuje čisté GNU C17 a linkování <code>math.h</code> se šesti startovacími šablonami, AST doplňováním struktur a exportem úkolů do PDF A4.","table_caption":"SROVNÁNÍ KOMPILÁTORŮ PRO VÝUKU A ÚKOLY V C NA ANDROIDU","th_0":"Požadavek výuky","th_1":"SuperCode C17 Studio","th_2":"Zastaralé Turbo C appky","th_3":"Webové kompilátory","th_4":"Holý terminál","tr1_c0":"Standard jazyka C","tr1_c1":"Čisté 64bitové GNU C17 (-std=gnu17)","tr1_c2":"Nestandardní 16bit &lt;conio.h&gt;","tr1_c3":"Liší se dle serveru","tr1_c4":"Ruční nastavení příznaků","tr2_c0":"Linkování &lt;math.h&gt;","tr2_c1":"Automatické -lm ihned po spuštění","tr2_c2":"Nefunkční či chybějící C99/C17 math","tr2_c3":"Často vyžaduje zaškrtnutí","tr2_c4":"Selže bez ručního `-lm`","tr3_c0":"Pomoc s ukazateli a struct","tr3_c1":"AST doplňování -&gt; / . + 21klávesová lišta","tr3_c2":"Obyčejné psaní na klávesnici","tr3_c3":"Textové pole prohlížeče","tr3_c4":"Bez dotykové lišty symbolů","tr4_c0":"Startovací šablony","tr4_c1":"6 vestavěných spustitelných cvičení C","tr4_c2":"Zastaralé útržky `clrscr()`","tr4_c3":"Jediná ukázka hello-world","tr4_c4":"Žádné","tr5_c0":"Odevzdání úkolů","tr5_c1":"Nativní PDF A4 se zvýrazněním syntaxe","tr5_c2":"Pouze snímky obrazovky","tr5_c3":"Kopírování na počítač","tr5_c4":"Jen prostý text `.c`","faq_lead":"Odpovědi pro studenty přecházející z Turbo C, procvičující malloc/free nebo odevzdávající školní cvičení z C.","faq1_q":"Proč bych při studiu C neměl používat `&lt;conio.h&gt;`, `clrscr()` ani `getch()`?","faq1_a":"`&lt;conio.h&gt;` byla nestandardní hlavička pro MS-DOS z 80. let a každý moderní Linux, macOS i univerzitní hodnoticí server ji odmítne. SuperCode kompiluje standardní ISO/GNU C17 (`&lt;stdio.h&gt;`, `&lt;stdlib.h&gt;`, `getchar()`, `fgets()`), takže vše, co se naučíte, využijete přímo u zkoušek i v praxi.","faq2_q":"Kompiluje SuperCode soubory `.c` skutečným kompilátorem C místo C++?","faq2_a":"Ano. V C vrací `malloc()` typ `void *`, který se implicitně převádí na typovaný ukazatel bez přetypování, zatímco C++ to zakazuje. SuperCode kompiluje soubory `.c` ve vyhrazeném režimu GNU C17 (`-std=gnu17`), takže platné idiomy C17 fungují čistě.","faq3_q":"Musím při použití `sqrt()`, `pow()` nebo `sin()` ručně zadávat `-lm`?","faq3_a":"Ne. SuperCode automaticky linkuje standardní matematickou knihovnu (`-lm`) u každého sestavení C17, takže funkce z `&lt;math.h&gt;` fungují okamžitě.","faq4_q":"Co se stane, když omylem dereferencuji neplatný ukazatel nebo napíšu nekonečnou smyčku `while(1)`?","faq4_a":"Relace editoru zůstane zcela v bezpečí: izolované spuštění v podprocesu čistě nahlásí návratový kód pádu a 20sekundový CPU hlídač zastaví nekonečné smyčky, aniž by telefon zamrzl.","cta_h2":"Procvičujte pravé ISO/GNU C17 offline na Androidu.","cta_desc":"Stáhněte si SuperCode IDE zdarma na Google Play &#8212; včetně 6 startovacích cvičení C, AST -&gt; doplňování a exportu do PDF A4."},"c_multifile":{"metaTitle":"Vícesouborový C kompilátor pro Android — Auto-linker .c/.h, Makefile a CMake | SuperCode","metaDesc":"Kompilujte vícesouborové projekty .c a .h až do 350 souborů offline na Androidu. SuperCode automaticky parsuje CMakeLists.txt a Makefile—nebo linkuje hlavičky #include bez konfigurace s inkrementální cache.","hero_tag":"AŽ 350 SOUBORŮ &#183; CMAKELISTS.TXT A MAKEFILE &#183; INKREMENTÁLNÍ CACHE","hero_h1":"Kompilujte <span class=\"text-gradient\">vícesouborové projekty .c a .h</span> offline na Androidu.","hero_desc":"Posuňte se za hranice jednoho souboru <code>main.c</code>. SuperCode prohledá až <strong>350 souborů v pracovním prostoru</strong>, nativně parsuje grafy cílů <strong><code>CMakeLists.txt</code></strong> a <strong><code>Makefile</code></strong>&#8212;nebo automaticky linkuje projekty s <strong><code>#include &quot;...&quot;</code></strong> bez konfigurace a s <strong>cacheováním objektů po souborech</strong>.","cp2_s1":"Max souborů projektu","cp2_s2":"Parser i pro Makefile","cp2_s3":"Spuštění z .h -&gt; main()","cp2_s4":"Inkrementální cache","wb_eyebrow":"VÍCESOUBOROVÉ PROSTŘEDÍ PRO .C / .H, CMAKE A INKREMENTÁLNÍ LINKER","sec_cap_title":"Skutečný modulární vývoj v C bez trápení se skripty sestavení","sec_cap_lead":"Ať už vložíte dva soubory `.c`/`.h` do složky, nebo naklonujete strukturovaný repozitář CMake z GitHubu, SuperCode sestaví graf kompilace automaticky.","f1_title":"Linker grafu #include \"...\" bez nutnosti konfigurace","f1_desc":"Nechcete psát Makefile pro projekt datových struktur o 5 souborech? Prostě vytvořte main.c, list.h a list.c. SuperCode projde relativní direktivy #include až přes 350 souborů (16 MB) a automaticky přilinkuje odpovídající implementace .c.","f1_badge":"Bez skriptů sestavení &#183; Podpora vnořených src/ a include/","f2_title":"Nativní parser grafu cílů CMakeLists.txt","f2_desc":"Otevřete existující repozitář CMake a klepněte na Spustit. SuperCode vyhodnotí proměnné set(), add_executable(), add_library() a target_include_directories(), aby sestavil přesné cesty hlaviček a překladové jednotky.","f2_badge":"add_executable &#183; add_library &#183; target_include_directories","f3_title":"Extrakce zdrojů z Makefile a GNUmakefile","f3_desc":"Pracujete na školním projektu dodaném s Makefile nebo GNUmakefile? Analyzátor sestavení vyčte SRCS, OBJS, CFLAGS a závislosti cílů, takže se projekt zkompiluje offline jedním klepnutím.","f3_badge":"Makefile &#183; GNUmakefile &#183; Řešení grafu SRCS / OBJS","f4_title":"Chytré prořezání mrtvých větví #if 0 a #ifdef podle platformy","f4_desc":"Multiplatformní C repozitáře často skrývají &lt;windows.h&gt; či hlavičky macOS do bloků #ifdef _WIN32 nebo #if 0. SuperCode odstraní komentáře a před vyhodnocením hlaviček vyřadí neaktivní větve preprocesoru.","f4_badge":"Přeskakuje #if 0 a #ifdef _WIN32 &#183; Čisté multiplatformní buildy","f5_title":"Chytré nalezení vstupu main() při spuštění z hlavičky .h","f5_desc":"Nechte kurzor v include/parser.h nebo src/lexer.c a klepněte přímo na Spustit. SuperCode zkontroluje graf cílů, odliší aktivní definice main() od pomocných modulů a spustí správnou binárku.","f5_badge":"Spuštění z jakékoli karty .h nebo .c &#183; Podpora více cílů","f6_title":"Inkrementální cache objektů pro každou překladovou jednotku","f6_desc":"Každý soubor .c a jeho tranzitivní závislosti .h mají otisk podle hashe obsahu. Úprava main.c znovu využije uložené objektové soubory .o pro všechny nezměněné moduly, což na mobilu výrazně zrychlí rebuild.","f6_badge":"Cache .o podle hashe obsahu &#183; Okamžité iterativní rebuildy","workflow_title":"Jak sestavovat vícesouborové projekty C a CMake na Androidu","workflow_lead":"Organizujte čistá rozhraní `.h` a implementace `.c` přesně jako na linuxové pracovní stanici.","wf1_title":"Vytvořte složky src/ + include/ nebo naklonujte repozitář","wf1_desc":"Uspořádejte hlavičky .h a jednotky .c lokálně nebo naklonujte školní C repozitář z GitHubu vestavěným klientem Visual Git v SuperCode.","wf2_title":"Nechte jednotky vyřešit automaticky nebo přes CMakeLists.txt","wf2_desc":"Spolehněte se na automatické vyhledání #include \"...\", nebo ponechte stávající CMakeLists.txt / Makefile beze změny.","wf3_title":"Kompilujte inkrementálně z jakéhokoli otevřeného souboru","wf3_desc":"Klepněte na Spustit i při úpravě hlavičky .h; SuperCode určí main(), zkompiluje změněné TU, přilinkuje -lm a program spustí.","wf4_title":"Zkontrolujte sjednocené diffy a commitujte čisté moduly","wf4_desc":"Prohlédněte si změny v souborech .c a .h v barevném zobrazení unified diff a odešlete commity přímo na GitHub nebo GitLab.","wf_foot_note":"Sken až 350 souborů / 16 MB projektu &#183; Překrytí neuloženými buffery otevřených karet","table_h2":"Vícesouborový C Builder SuperCode vs. jednosouborové mobilní kompilátory","snippet_p":"<strong>Vícesouborový nástroj pro sestavení C v SuperCode</strong> kompiluje modulární projekty <code>.c</code> a <code>.h</code> až do 350 souborů offline na Androidu. Automaticky parsuje grafy cílů <code>CMakeLists.txt</code> a <code>Makefile</code>, linkuje stromy hlaviček bez konfigurace, prořezává neaktivní větve preprocesoru, vyhledá <code>main()</code> z otevřených hlaviček a cacheuje nezměněné objektové soubory.","table_caption":"MOŽNOSTI VÍCESOUBOROVÝCH PROJEKTŮ V C NA ANDROIDU","th_0":"Funkce sestavení","th_1":"SuperCode C17 Builder","th_2":"Základní mobilní C appky","th_3":"Webové sandboxy","th_4":"Ruční Make v CLI","tr1_c0":"Rozsah projektu","tr1_c1":"Až 350 souborů / 16 MB ve vnořených složkách","tr1_c2":"Pouze jeden soubor main.c","tr1_c3":"2–3 ručně vložené karty","tr1_c4":"Neomezený (ruční nastavení)","tr2_c0":"CMake &amp; Makefile","tr2_c1":"Nativně parsuje CMakeLists.txt a Makefile","tr2_c2":"Nepodporováno","tr2_c3":"Zřídka podporováno","tr2_c4":"Vyžaduje balíčky pro CLI","tr3_c0":"Linkování bez konfigurace","tr3_c1":"Auto-průchod #include \"...\" + související .c","tr3_c2":"Selže s `undefined reference`","tr3_c3":"Ruční skript kompilace","tr3_c4":"Ruční `gcc *.c`","tr4_c0":"Spuštění z hlavičky .h","tr4_c1":"Chytré vyhledání vstupu najde main()","tr4_c2":"Chyba (`no main in .h`)","tr4_c3":"Spustí jen aktivní kartu","tr4_c4":"Ruční příkaz","tr5_c0":"Inkrementální cache","tr5_c1":"Cache objektů (.o) dle hashe obsahu TU","tr5_c2":"Plná rekompilace pokaždé","tr5_c3":"Plná vzdálená rekompilace","tr5_c4":"Podle časových razítek","faq_lead":"Časté dotazy k chybám `undefined reference`, cestám `#include`, Makefile a CMake na Androidu.","faq1_q":"Proč jiné aplikace pro C na Androidu hlásí `undefined reference`, když použiji `#include \"helper.h\"`?","faq1_a":"Jednosouborové mobilní aplikace předávají kompilátoru jen aktivní soubor a nikdy nepřilinkují `helper.c`. SuperCode prohledá vaši složku (i podsložky `src/` a `include/`), zkompiluje `helper.c` společně s `main.c` a všechny objektové soubory automaticky slinkuje.","faq2_q":"Musím pro malé projekty v C psát `CMakeLists.txt` nebo `Makefile`?","faq2_a":"Vůbec ne. Pokud `CMakeLists.txt` ani `Makefile` neexistují, bezkonfigurační vyhledávač závislostí `#include \"...\"` v SuperCode sám najde a přilinkuje vaše soubory `.c` a `.h`. Když `CMakeLists.txt` nebo `Makefile` v projektu je, SuperCode respektuje jeho graf cílů.","faq3_q":"Co když mám před stisknutím Spustit neuložené úpravy v otevřené kartě `.h`?","faq3_a":"SuperCode automaticky překryje snímek sestavení projektu živými neuloženými buffery z editoru, takže úpravy napříč otevřenými kartami `.h` a `.c` se projeví okamžitě.","faq4_q":"Jak si SuperCode poradí s projektem, který obsahuje dva samostatné testovací programy s `main()`?","faq4_a":"Pokud spustíte soubor, který definuje vlastní `main()`, použije se tento `main()`. Při spuštění ze sdílené hlavičky `.h` zkontroluje SuperCode cíle v `CMakeLists.txt`/`Makefile` a lokální vazby `#include`, aby vybral odpovídající spustitelný soubor bez kolizí duplicitních symbolů.","cta_h2":"Sestavujte skutečné vícesouborové projekty v C na telefonu.","cta_desc":"Získejte SuperCode IDE zdarma na Google Play &#8212; linkování .c/.h bez konfigurace, parsování CMake/Makefile a Visual Git v jednom studiu."},"c_scanf_io":{"metaTitle":"C kompilátor se vstupem uživatele na Androidu — živý scanf, @args a fopen I/O | SuperCode","metaDesc":"Spouštějte interaktivní C programy na Androidu s nebufferovanými výzvami stdout před scanf/fgets, ukončením cyklu [EOF], CLI přepínači // @args argc/argv a obousměrnou synchronizací fopen/fwrite.","hero_tag":"NEBUFFEROVANÝ STDOUT &#183; ŽIVÝ SCANF &amp; [EOF] &#183; // @ARGS &#183; SYNCHRONIZACE FOPEN","hero_h1":"Interaktivní <span class=\"text-gradient\">C konzole pro scanf, argc/argv a souborové I/O</span> pro Android.","hero_desc":"Už žádné zadávání všech vstupů naslepo před spuštěním programu. SuperCode automaticky vypne bufferování <code>stdout</code>, takže výzvy před <strong><code>scanf()</code> / <code>fgets()</code></strong> vidíte okamžitě, doručí <strong><code>[EOF]</code></strong> na klepnutí, předá <strong>CLI přepínače <code>// @args</code></strong> a synchronizuje soubory <strong><code>fopen()</code></strong> přímo do vaší složky.","cp3_s1":"Okamžité výzvy","cp3_s2":"Ukončení cyklu jedním klepnutím","cp3_s3":"CLI přepínače // @args","cp3_s4":"fopen / fwrite I/O","wb_eyebrow":"INTERAKTIVNÍ C STDIN, // @ARGS A PRACOVNÍ PROSTOR PRO SOUBOROVÉ I/O","sec_cap_title":"Každý vstupní i výstupní kanál v C funguje jako v nativním terminálu","sec_cap_lead":"Konzolové aplikace s menu, parsery příkazového řádku i úlohy s binárními záznamy se chovají stejně jako v desktopovém terminálu.","f1_title":"Automatický nebufferovaný stdout před scanf a fgets","f1_desc":"V mnoha mobilních a webových spouštěčích zůstane printf(\"Zadejte věk: \"); bez koncového odřádkování neviditelné až do dokončení scanf()! SuperCode automaticky vypne bufferování stdout, takže se výzvy zobrazí vždy před zadáním vstupu.","f1_badge":"Bez nutnosti fflush(stdout) &#183; Přirozené cykly menu","f2_title":"Vícekrokový živý stdin a signál [EOF] na jedno klepnutí","f2_desc":"Předávejte interaktivní vstupy krok za krokem za běhu programu. Testujete while (scanf(\"%d\", &amp;x) != EOF) nebo while (fgets(buf, sizeof buf, stdin))? Odešlete prázdný řádek a pošlete čistý signál EOF.","f2_badge":"scanf &#183; fgets &#183; getchar &#183; Čisté ukončení [EOF]","f3_title":"Direktiva // @args pro CLI programy s argc / argv","f3_desc":"Přidejte na začátek souboru .c řádek // @args -i \"input data.csv\" --verbose a předejte až 32 parsovaných tokenů příkazového řádku přímo do main(int argc, char *argv[]), včetně mezer v uvozovkách.","f3_badge":"// @args &#183; Řetězce v uvozovkách &#183; Až 32 tokenů argv","f4_title":"Automatické připojení datasetů .txt / .csv / .dat / .in","f4_desc":"Vložte input.in, students.csv nebo records.dat do složky projektu a otevřete je přes standardní relativní cesty jako fopen(\"students.csv\", \"r\")&#8212;bez natvrdo zapsaných cest /storage/emulated/0 na Androidu.","f4_badge":"Relativní cesta fopen() &#183; .txt / .csv / .dat / .in","f5_title":"Obousměrná synchronizace fopen, fprintf a fwrite s projektem","f5_desc":"Textové sestavy i binární struktury zapsané přes fopen(..., \"w\" / \"wb\"), fprintf() a fwrite() se automaticky synchronizují do stromu projektu na Androidu a ihned obnoví Průzkumník souborů.","f5_badge":"Synchronizace textových i binárních souborů &#183; Okamžitý refresh Průzkumníka","f6_title":"20sekundový CPU watchdog s pozastavením při čekání na vstup","f6_desc":"Na promyšlené zadávání vstupů do konzole máte neomezený čas&#8212;20sekundový watchdog se při čekání na stdin pozastaví, ale okamžitě zasáhne, pokud chybná smyčka po vstupu zacyklí CPU.","f6_badge":"Watchdog s detekcí nečinnosti &#183; Ochrana proti zahlcení výstupu","workflow_title":"Jak testovat stdin, CLI argumenty a souborové I/O v SuperCode","workflow_lead":"Spouštějte na mobilu plynule školní úlohy s menu, unixové CLI nástroje i cvičení se zpracováním souborů.","wf1_title":"Volitelně deklarujte CLI přepínače na začátku souboru","wf1_desc":"Kdykoli vaše úloha čte argc a argv[], přidejte na 1. řádek komentář například // @args input.txt output.csv.","wf2_title":"Umístěte vstupní datasety do složky projektu","wf2_desc":"Vytvořte nebo importujte soubory .txt, .csv, .in nebo .dat ve stejné složce, aby je relativní volání fopen() našla automaticky.","wf3_title":"Reagujte na výzvy živě a po dokončení odešlete [EOF]","wf3_desc":"Sledujte nebufferované výzvy printf v reálném čase, zadávejte hodnoty v liště konzole nebo klepněte na Odeslat s prázdným polem pro [EOF].","wf4_title":"Otevřete vygenerované výstupní soubory přímo v editoru","wf4_desc":"Klepněte na libovolný nově vytvořený .txt, .csv nebo log soubor ve stromu projektu a ověřte přesný výstup na disk.","wf_foot_note":"Rozdělená konzole 55:45 na šířku &#183; Nastavitelný zoom písma terminálu &#183; Vymazat a kopírovat výstup","table_h2":"Živý stdin a souborové I/O v SuperCode vs. dávkové mobilní spouštěče","snippet_p":"<strong>Interaktivní C konzole v SuperCode</strong> přináší na Android standardní vstup, argumenty příkazového řádku a práci se soubory na úrovni desktopu. Automaticky zobrazuje nebufferované výzvy před <code>scanf</code> a <code>fgets</code>, podporuje ukončení EOF jedním klepnutím, předává až 32 přepínačů <code>argc/argv</code> přes <code>// @args</code> a synchronizuje výstupy <code>fopen</code> zpět do vaší složky.","table_caption":"SROVNÁNÍ C KONZOLE A PRÁCE SE SOUBORY NA ANDROIDU","th_0":"I/O funkce","th_1":"SuperCode C17 konzole","th_2":"Aplikace s dialogem před spuštěním","th_3":"Webové online kompilátory","th_4":"Desktopový terminál","tr1_c0":"Výzva před scanf","tr1_c1":"Automaticky nebufferovaný stdout (okamžitě)","tr1_c2":"Výzvy se vypíší až po skončení běhu","tr1_c3":"Bufferováno do odřádkování/konce","tr1_c4":"Okamžitě","tr2_c0":"Interaktivní cykly menu","tr2_c1":"Skutečný živý vícekrokový stdin + [EOF]","tr2_c2":"Nutnost odhadnout všechny vstupy předem","tr2_c3":"Dávkové textové pole pro stdin","tr2_c4":"Podporováno","tr3_c0":"Argumenty argc / argv","tr3_c1":"Vestavěná direktiva `// @args` (32 argumentů)","tr3_c2":"Nepodporováno","tr3_c3":"Skrytý panel nastavení","tr3_c4":"Ruční CLI přepínače","tr4_c0":"Soubory fopen / fwrite","tr4_c1":"Automaticky připojí vstupy a synchronizuje výstupy do složky","tr4_c2":"Dočasná složka smazaná při ukončení","tr4_c3":"Smazáno po skončení relace","tr4_c4":"Lokální složka","tr5_c0":"Ochrana proti nekonečné smyčce","tr5_c1":"20s CPU watchdog pozastavený při nečinnosti","tr5_c2":"Zamrzne UI nebo vyprší čas při psaní","tr5_c3":"Tvrdé ukončení podle reálného času","tr5_c4":"Ruční Ctrl+C","faq_lead":"Řešení potíží s výzvami `scanf`, odřádkováním u `fgets`, signálem `EOF` a cestami `fopen` na Androidu.","faq1_q":"Proč se `printf(\"Zadejte číslo: \");` v SuperCode zobrazí ihned i bez `fflush(stdout)`?","faq1_a":"Standardní proudy v C jsou při přesměrování přes rouru často blokově bufferované, což skrývá výzvy nekončící znakem `\\\\n`. SuperCode automaticky nastaví nebufferované standardní proudy, takže se interaktivní výzvy zobrazí ještě před čekáním `scanf`, `fgets` nebo `getchar`.","faq2_q":"Jak na dotykové klávesnici Androidu odeslat `Ctrl+D` (`EOF`)?","faq2_a":"Kdykoli je vstupní pole konzole aktivní a prázdné, klepnutí na tlačítko Odeslat předá běžícímu C procesu čistý signál `EOF` (`[EOF]`)&#8212;čímž ukončí cykly `while (scanf(...) != EOF)` i `getchar() != EOF`.","faq3_q":"Jak předám argumenty příkazového řádku s mezerami do `char *argv[]`?","faq3_a":"Napište na začátek souboru `.c` komentář `// @args \"My Report.txt\" -n 10`. Tokenizer argumentů v SuperCode zachová řetězce v uvozovkách jako jeden prvek `argv[i]` a podporuje až 32 argumentů.","faq4_q":"Kam se ukládají soubory vytvořené pomocí `fopen(\"output.txt\", \"w\")`?","faq4_a":"Synchronizují se přímo do stejné složky projektu na Androidu jako váš zdrojový soubor `.c`, takže zůstanou trvale uložené a můžete je otevřít přímo v editoru SuperCode.","cta_h2":"Spouštějte interaktivní C úlohy a práci se soubory na Androidu.","cta_desc":"Stáhněte si SuperCode IDE zdarma na Google Play &#8212; živý nebufferovaný scanf, CLI přepínače // @args a skutečná synchronizace fopen."},"c_posix_sys":{"metaTitle":"POSIX C kompilátor pro Android — unistd.h, pthread, sokety a systémové úlohy | SuperCode","metaDesc":"Pište na Androidu kód pro operační systémy a POSIX C. Používejte offline unistd.h, fcntl.h, dirent.h, getopt.h, regex.h a stdatomic.h a plynule kompilujte pthread, semafory, fork/pipe i sokety.","hero_tag":"OFFLINE POSIX HLAVIČKY &#183; PTHREAD A SEMAFORY &#183; UNIX SOKETY A IPC","hero_h1":"POSIX <span class=\"text-gradient\">systémové C, pthreads a sokety</span> na vašem zařízení Android.","hero_desc":"Navrženo pro předměty Operační systémy a Počítačové sítě. Kompilujte <strong><code>unistd.h</code>, <code>fcntl.h</code>, <code>dirent.h</code>, <code>getopt.h</code>, <code>regex.h</code> a <code>stdatomic.h</code></strong> offline&#8212;a pro úlohy s <strong><code>pthread</code>, <code>fork/pipe</code> a <code>sys/socket.h</code></strong> plynule využijte <strong>POSIX Cloud C (<code>-pthread -lm</code>)</strong>.","cp4_s1":"unistd &#183; fcntl &#183; dirent","cp4_s2":"stdatomic &amp; complex","cp4_s3":"Vlákna a semafory","cp4_s4":"Diagnostika souborů 1:1","wb_eyebrow":"PROSTŘEDÍ PRO POSIX HLAVIČKY, SOUBĚŽNOST PTHREAD A SOKETOVÉ IPC","sec_cap_title":"Spojte offline systémové hlavičky s plnou linuxovou souběžností a IPC","sec_cap_lead":"SuperCode analyzuje direktivy `#include` a systémová volání ve vašem projektu, takže cvičení z OS fungují čistě bez ručního nastavování křížové kompilace.","f1_title":"Široké pokrytí POSIX hlaviček plně offline","f1_desc":"Kompilujte běžné unixové systémové nástroje kompletně offline s hlavičkami &lt;unistd.h&gt;, &lt;fcntl.h&gt;, &lt;dirent.h&gt;, &lt;poll.h&gt;, &lt;sys/stat.h&gt;, &lt;sys/time.h&gt;, &lt;signal.h&gt;, &lt;regex.h&gt;, &lt;fnmatch.h&gt; a &lt;getopt.h&gt;.","f1_badge":"unistd.h &#183; fcntl.h &#183; dirent.h &#183; poll.h &#183; regex.h &#183; getopt.h","f2_title":"C11/C17 &lt;stdatomic.h&gt; a &lt;complex.h&gt; připraveny offline","f2_desc":"Experimentujte s bez zámků pracujícími atomickými čítači (atomic_int, atomic_fetch_add, memory_order_acq_rel) a nativní komplexní aritmetikou C17 (&lt;complex.h&gt;) přímo v zařízení.","f2_badge":"&lt;stdatomic.h&gt; &#183; &lt;complex.h&gt; &#183; Čisté GNU C17","f3_title":"Automatická kompilace -pthread a IPC v Cloud C","f3_desc":"Sandbox aplikací na Androidu lokálně omezuje větvení procesů a některá jaderná volání IPC. Jakmile váš C kód obsahuje &lt;pthread.h&gt;, &lt;semaphore.h&gt;, &lt;sys/socket.h&gt;, fork() nebo pipe(), SuperCode automaticky kompiluje na Linux Cloud C (-pthread -lm).","f3_badge":"&lt;pthread.h&gt; &#183; &lt;semaphore.h&gt; &#183; &lt;sys/socket.h&gt; &#183; fork / pipe","f4_title":"Vícesouborové POSIX balíčkování se zachováním #line","f4_desc":"I při odeslání vícesouborových projektů .c a .h do Cloud C vkládá SuperCode standardní direktivy #line, takže každé varování či chyba syntaxe ukazuje přesně na váš lokální soubor a číslo řádku.","f4_badge":"Vícesouborový cloudový balíček &#183; Přesné lokální mapování řádků","f5_title":"Prototypování unixového CLI s &lt;getopt.h&gt; + // @args","f5_desc":"Vytvářejte autentické POSIX nástroje příkazového řádku pomocí getopt() a getopt_long() a předávejte testovací přepínače jako // @args -r -n 16 -o out.log přímo ze začátku zdrojového souboru.","f5_badge":"getopt / getopt_long &#183; Testování přepínačů // @args","f6_title":"Integrovaný Shell, Git a nasazení na server přes SFTP","f6_desc":"Prototypujte svůj POSIX démon nebo CLI nástroj na Androidu, sledujte revize ve vizuálním Gitu a nasazujte přímo na svůj linuxový VPS nebo univerzitní server přes vestavěného klienta SFTP.","f6_badge":"Shell Runner &#183; Vizuální Git &#183; Atomické vzdálené ukládání SFTP","workflow_title":"Jak v SuperCode funguje automatické směrování POSIX úloh","workflow_lead":"Pište standardní POSIX C kód&#8212;SuperCode automaticky zvolí offline kompilaci nebo spuštění v Linuxu s `-pthread`.","wf1_title":"Vložte standardní C17 a POSIX systémové hlavičky","wf1_desc":"Pracujte s deskriptory souborů, procházením adresářů, regexy nebo parsery getopt() pomocí standardních POSIX hlaviček.","wf2_title":"Úlohy pro soubory, regex a atomické operace běží offline","wf2_desc":"Programy využívající unistd.h, fcntl.h, dirent.h, regex.h, getopt.h nebo stdatomic.h se sestaví a spustí lokálně bez sítě.","wf3_title":"Vlákna, semafory a sokety se přepnou do Linux C","wf3_desc":"Vložení &lt;pthread.h&gt;, &lt;semaphore.h&gt;, &lt;sys/socket.h&gt;, fork() nebo pipe() aktivuje Linux Cloud C s přepínači -pthread -lm.","wf4_title":"Opravujte varování s přesností 1:1 na lokální soubor a řádek","wf4_desc":"Diagnostika kompilátoru se mapuje přímo na vaše lokální karty .c a .h bez ohledu na offline či cloudové spuštění.","wf_foot_note":"Bez ručních přepínačů -pthread &#183; Vícesouborové rozbalení hlaviček &#183; Připraveno pro SFTP nasazení na Linux","table_h2":"Matice podpory POSIX a systémového C v SuperCode","snippet_p":"<strong>POSIX C Systems Studio v SuperCode</strong> přináší vývoj v C17 ve stylu Unixu na telefony a tablety Android. Programátoři mohou offline kompilovat <code>unistd.h</code>, <code>fcntl.h</code>, <code>dirent.h</code>, <code>poll.h</code>, <code>getopt.h</code>, <code>regex.h</code> a <code>stdatomic.h</code>, zatímco vícesouborové projekty s <code>pthread.h</code>, semafory, rourami a sokety se plynule přepnou do POSIX Cloud C s přesnou diagnostikou lokálních řádků.","table_caption":"ÚROVNĚ PODPORY POSIX C HLAVIČEK A SYSTÉMOVÝCH VOLÁNÍ V SUPERCODE NA ANDROIDU","th_0":"Systémová oblast","th_1":"Klíčové hlavičky a primitivy","th_2":"Úroveň spuštění","th_3":"Více souborů .c/.h?","th_4":"Přepínače linkeru","tr1_c0":"POSIX soubory a adresářové I/O","tr1_c1":"unistd.h, fcntl.h, dirent.h, sys/stat.h, poll.h","tr1_c2":"100% offline C17","tr1_c3":"Ano (až 350 souborů)","tr1_c4":"Auto `-std=gnu17 -lm`","tr2_c0":"CLI, glob a regex","tr2_c1":"getopt.h, regex.h, fnmatch.h, sys/time.h, signal.h","tr2_c2":"100% offline C17","tr2_c3":"Ano + `// @args`","tr2_c4":"Auto `-std=gnu17 -lm`","tr3_c0":"Atomika a DSP matematika","tr3_c1":"stdatomic.h, complex.h, stdint.h, inttypes.h","tr3_c2":"100% offline C17","tr3_c3":"Ano (cache `.o`)","tr3_c4":"Auto `-std=gnu17 -lm`","tr4_c0":"POSIX vlákna a synchronizace","tr4_c1":"pthread.h, semaphore.h, mutexy, podmínkové proměnné","tr4_c2":"Auto POSIX Cloud C","tr4_c3":"Ano (mapování `#line`)","tr4_c4":"Auto `-pthread -lm`","tr5_c0":"Procesy a sokety","tr5_c1":"sys/socket.h, netinet/in.h, arpa/inet.h, fork, pipe","tr5_c2":"Auto POSIX Cloud C","tr5_c3":"Ano (mapování `#line`)","tr5_c4":"Auto `-pthread -lm`","faq_lead":"Otázky ke cvičením z operačních systémů, linkování `pthread`, `fork()` a programování soketů na Androidu.","faq1_q":"Mohu kompilovat `&lt;unistd.h&gt;`, `&lt;dirent.h&gt;` a `&lt;getopt.h&gt;` kompletně offline?","faq1_a":"Ano. Základní POSIX hlavičky včetně `unistd.h`, `fcntl.h`, `dirent.h`, `poll.h`, `regex.h`, `fnmatch.h`, `getopt.h`, `sys/stat.h`, `sys/time.h`, `signal.h` a `stdatomic.h` jsou zabudované přímo v offline C17 sysrootu.","faq2_q":"Musím při použití `&lt;pthread.h&gt;` nebo `&lt;semaphore.h&gt;` ručně přidávat `-pthread`?","faq2_a":"Ne. SuperCode automaticky rozpozná `&lt;pthread.h&gt;` i `&lt;semaphore.h&gt;` a předá kompilátoru POSIX Cloud C přepínače `-pthread -lm` bez nutnosti cokoli nastavovat.","faq3_q":"Proč se `fork()`, `pipe()` a `&lt;sys/socket.h&gt;` spouštějí v režimu POSIX Cloud C?","faq3_a":"Bezpečnostní politiky SELinux v moderním Androidu blokují v sandboxu mobilních aplikací vytváření hierarchií procesů přes `fork()` i nízkoúrovňové vazby soketů. Přesměrováním těchto úloh do izolovaného linuxového kontejneru poběží standardní učebnicový kód bez úprav.","faq4_q":"Když má vícesouborový `pthread` projekt překlep v `worker.h`, ukáže chyba správný soubor a řádek?","faq4_a":"Ano. Vícesouborový bundler v SuperCode generuje pro každou vloženou hlavičku i jednotku `.c` standardní C značky `#line`, takže se diagnostika namapuje 1:1 na `worker.h` a jeho přesné číslo řádku.","cta_h2":"Řešte úlohy z OS a systémového C kdekoli na Androidu.","cta_desc":"Nainstalujte si SuperCode IDE zdarma z Google Play &#8212; offline POSIX hlavičky, plynulá sestavení -pthread a SFTP v jedné 40,2 MB aplikaci."},"cpp_comp_stl":{"metaTitle":"Aplikace pro soutěžní programování na Androidu — offline C++20 STL a rychlý std::cin | SuperCode","metaDesc":"Trénujte Codeforces, LeetCode, AtCoder, CSES a USACO offline na Androidu. Plná GNU C++20 STL, rozdělená konzole 55:45 pro std::cin, telemetrie času (µs) a paměti (KB) a 20s ochrana smyček.","hero_tag":"OFFLINE GNU C++20 STL &#183; SOUTĚŽNÍ KONZOLE 55:45 &#183; TELEMETRIE &#181;S A KB","hero_h1":"<span class=\"text-gradient\">Offline C++20 a STL aréna</span> pro soutěžní programátory.","hero_desc":"Řešte úlohy z Codeforces, AtCoder, LeetCode, CSES i USACO kdekoli&#8212;třeba v letadle nebo při dojíždění. SuperCode spojuje <strong>offline GNU C++20 (<code>-std=gnu++2a</code>)</strong> a kompletní <strong>STL</strong> s <strong>dvoupanelovou konzolí 55:45 pro <code>std::cin</code></strong> a <strong>telemetrií času běhu a špičkové paměti</strong>.","cpp1_s1":"Plná offline STL","cpp1_s2":"Soutěžní dělený pohled","cpp1_s3":"Statistiky času a paměti","cpp1_s4":"Pojistka proti smyčkám","wb_eyebrow":"PROSTŘEDÍ PRO SOUTĚŽNÍ C++20 STL, &lt;BIT&gt; A VÍCEKROKOVÝ STD::CIN","sec_cap_title":"Navrženo pro rychlost, ergonomii soutěží a spolehlivost offline","sec_cap_lead":"Už žádné čekání ve frontách pomalých webových vyhodnocovačů jen kvůli ověření ukázkových testů nebo ladění chyby o jedničku.","f1_title":"100% offline GNU C++20 STL a intrinsics z &lt;bit&gt;","f1_desc":"Všechny soutěžní stálice fungují offline: vector, priority_queue, deque, set, multiset, map, unordered_map, bitset, &lt;algorithm&gt;, &lt;numeric&gt; (std::gcd, std::lcm) i C++20 &lt;bit&gt; (std::popcount, std::bit_width, std::countl_zero).","f1_badge":"Kontejnery STL &#183; &lt;algorithm&gt; &#183; &lt;numeric&gt; &#183; C++20 &lt;bit&gt;","f2_title":"Rychlé vkládání do std::cin, nebufferované výzvy a [EOF]","f2_desc":"Vložte vícepřípadové soutěžní vstupy přímo do konzole, testujte čistě ios::sync_with_stdio(false) a klepnutím na Odeslat na prázdném řádku pošlete [EOF] řešením s while (cin &gt;&gt; n).","f2_badge":"Víceřádkové vkládání vzorů &#183; Signál [EOF] &#183; Nebufferovaný stdout","f3_title":"Rozdělený pohled 55:45 na šířku pro tablety i telefony","f3_desc":"Otočte telefon, skládací zařízení nebo tablet a pište kód v 55% panelu editoru, zatímco vstupy a výstupy sledujete vedle v 45% terminálu&#8212;při otevření softwarové klávesnice se plynule přizpůsobí.","f3_badge":"Dva panely 55:45 &#183; Optimalizováno pro skládačky a tablety","f4_title":"Telemetrie doby běhu (&#181;s/ms) a špičkové paměti (KB/MB)","f4_desc":"Odhalte nechtěná úzká hrdla O(N^2) nebo příliš velké DP tabulky ještě před odevzdáním. Každé spuštění vypíše v patičce konzole přesný návratový kód, čas běhu a špičkovou spotřebu paměti.","f4_badge":"Návratový kód &#183; Čas &#181;s / ms &#183; Špičková paměť KB / MB","f5_title":"20sekundová pojistka proti nekonečné smyčce a zahlcení výstupem","f5_desc":"Napsali jste while (lo &lt; hi) bez aktualizace mid nebo zapomněli na visited[] v DFS? 20s CPU watchdog a limit výstupu zacyklený proces okamžitě zastaví bez ztráty jediného znaku kódu.","f5_badge":"20s CPU watchdog &#183; Ochrana výstupu &#183; Nulové zamrznutí UI","f6_title":"Přesměrování souborů .in a .out pro USACO a olympiády","f6_desc":"Vložte problem.in do pracovního prostoru a použijte freopen(\"problem.in\", \"r\", stdin) nebo std::ifstream/ofstream&#8212;vygenerované soubory .out se ihned synchronizují zpět do složky ke kontrole.","f6_badge":"Připraveno pro freopen() &#183; Auto-synchronizace .in / .out","workflow_title":"Soutěžní postup: od zadání úlohy k ověřenému řešení","workflow_lead":"Iterujte nad ukázkovými vstupy během sekund bez plýtvání mobilních dat nebo čekání ve vzdálených frontách.","wf1_title":"Otevřete soutěžní šablonu se zkratkami symbolů C++20","wf1_desc":"Začněte ze souboru s rychlým I/O v C++20 a využijte 21klávesovou lištu tažením nahoru (::, &lt;&lt;, &gt;&gt;, {}, [], &amp;) i AST doplňování std::.","wf2_title":"Kompilujte lokálně i v režimu letadlo","wf2_desc":"Kompilujte jednosouborové řešení offline s nulovou latencí serveru&#8212;v metru, autobuse i při cestě na soutěž.","wf3_title":"Vkládejte vícepřípadové testovací vstupy živě","wf3_desc":"Vložte ukázkové testy z Codeforces nebo AtCoder do std::cin (nebo čtěte z problem.in) a ihned zkontrolujte výstup.","wf4_title":"Ověřte čas a paměť před odevzdáním vyhodnocovači","wf4_desc":"Zkontrolujte návratový kód 0, čas v milisekundách a paměť v KB/MB, pak čistý formátovaný kód jedním klepnutím zkopírujte a odevzdejte.","wf_foot_note":"Podpora strukturovaných vazeb, generických lambd a 64bitového long long &#183; Kopírování jedním klepnutím","table_h2":"Soutěžní C++20 aréna SuperCode vs. jiné mobilní možnosti","snippet_p":"<strong>Soutěžní C++20 studio v SuperCode</strong> vybavuje účastníky olympiád, Codeforces, LeetCode a USACO rychlým offline kompilátorem GNU C++20 STL pro Android. Nabízí dvoupanelovou soutěžní konzoli 55:45, nebufferovaný živý <code>std::cin</code> s ovládáním EOF, telemetrii času běhu i špičkové paměti a 20sekundovou pojistku proti nekonečným smyčkám.","table_caption":"SROVNÁNÍ PROSTŘEDÍ PRO SOUTĚŽNÍ PROGRAMOVÁNÍ V C++ NA ANDROIDU","th_0":"Požadavek soutěže","th_1":"SuperCode C++20 aréna","th_2":"Staré C++11 mobilní aplikace","th_3":"Webová IDE v prohlížeči","th_4":"Běžné poznámkové editory","tr1_c0":"Standard C++ a &lt;bit&gt;","tr1_c1":"Offline GNU C++20 (`popcount`, `ranges`, `[a,b]`)","tr1_c2":"Zaseknuté na C++98 / C++11","tr1_c3":"Zpoždění front během soutěžních večerů","tr1_c4":"Bez kompilátoru","tr2_c0":"Vstup testovacích případů","tr2_c1":"Živý vkládatelný `std::cin` + `[EOF]` + `freopen`","tr2_c2":"Neohrabané vyskakovací okno","tr2_c3":"Jedno dávkové pole","tr2_c4":"Žádný","tr3_c0":"Statistiky času a paměti","tr3_c1":"Vestavěná patička telemetrie `&#181;s/ms` a `KB/MB`","tr3_c2":"Pouze text výstupu","tr3_c3":"Často skryté","tr3_c4":"Žádné","tr4_c0":"Chyba TLE v binárním vyhledávání","tr4_c1":"20s CPU watchdog smyčku čistě ukončí","tr4_c2":"Zasekne celou aplikaci Android","tr4_c3":"Chyba serveru po 10–15 s","tr4_c4":"Není relevantní","tr5_c0":"Ergonomie dvou panelů","tr5_c1":"Rozdělení na šířku 55:45 + 21klávesová C++ lišta","tr5_c2":"Zastaralé UI jen na výšku","tr5_c3":"Stísněný mobilní prohlížeč","tr5_c4":"Výchozí klávesnice","faq_lead":"Odpovědi pro soutěžící na Codeforces, LeetCode, AtCoder, ICPC a USACO programující na Androidu.","faq1_q":"Fungují offline prvky C++20 jako strukturované vazby `auto [u, w]`, `std::popcount` a `std::ranges::sort`?","faq1_a":"Ano. Lokální kompilátor C++ v SuperCode běží v režimu GNU C++20 (`-std=gnu++2a`), takže strukturované vazby, `constexpr if`, generické lambdy, `&lt;bit&gt;`, `&lt;ranges&gt;` i `std::gcd` / `std::lcm` se kompilují 100% offline.","faq2_q":"Mohu v SuperCode používat `ios::sync_with_stdio(false); cin.tie(nullptr);`?","faq2_a":"Ano! Standardní idiomy pro rychlé I/O v soutěžním programování fungují čistě jak s vloženými víceřádkovými testovacími vstupy, tak s přesměrováním souborů přes `freopen()`.","faq3_q":"Jak otestuji úlohy čtoucí vstup až do konce souboru (`while (cin &gt;&gt; x)`)?","faq3_a":"Vložte testovací řádky do vstupní lišty živé konzole a odešlete je; poté ještě jednou klepněte na Odeslat s prázdným vstupním polem, čímž předáte `[EOF]` a vypíší se konečné výsledky.","faq4_q":"Ukáže mi SuperCode, jak rychle mé C++ řešení běželo a kolik paměti spotřebovalo?","faq4_a":"Ano. Každé spuštění zobrazí souhrnný odznak s návratovým kódem procesu, dobou běhu (`&#181;s` nebo `ms`) a špičkovou spotřebou paměti (`KB` nebo `MB`).","cta_h2":"Zlepšujte svůj C++20 rating kdekoli offline.","cta_desc":"Získejte SuperCode IDE zdarma na Google Play &#8212; plná C++20 STL, dělená soutěžní konzole 55:45 a mikrosekundová telemetrie."},"cpp_modern_20":{"metaTitle":"Moderní kompilátor C++20 pro Android — Ranges, Concepts a chytré ukazatele | SuperCode","metaDesc":"Nechte zastaralé mobilní aplikace s C++11 za sebou. Pište moderní C++20 offline na Androidu s , , , , optional/variant, chytrými ukazateli a souběžností /.","hero_tag":"C++20 RANGES &amp; CONCEPTS &#183; RAII CHYTRÉ UKAZATELE &#183; &lt;THREAD&gt; &amp; &lt;LATCH&gt;","hero_h1":"Pište skutečné <span class=\"text-gradient\">moderní C++20, Ranges &amp; chytré ukazatele</span> na Androidu.","hero_desc":"Zastaralé aplikace jako CppDroid zamrzly v éře C++11 před více než deseti lety. SuperCode přináší na Android skutečné <strong>offline C++20</strong>&#8212;včetně <strong><code>&lt;ranges&gt;</code>, <code>&lt;concepts&gt;</code>, <code>&lt;span&gt;</code>, <code>std::optional</code>, <code>std::variant</code>, RAII chytrých ukazatelů</strong> a plynulé <strong>souběžnosti přes <code>-pthread</code></strong>.","cpp2_s1":"&amp; koncepty C++20","cpp2_s2":"unique &amp; shared_ptr","cpp2_s3":"span &#183; optional &#183; variant","cpp2_s4":"thread &#183; latch &#183; barrier","wb_eyebrow":"PRACOVNÍ PROSTŘEDÍ PRO MODERNÍ C++20 RANGES, RAII CHYTRÉ UKAZATELE &amp; SOUBĚŽNOST","sec_cap_title":"Produkční idiomy moderního C++&#8212;ne zastaralé podmnožiny z roku 2013","sec_cap_lead":"Procvičujte čisté vlastnictví RAII, zero-copy pohledy, omezené šablony a synchronizační primitivy C++20 na moderním hardwaru Android.","f1_title":"Líné pipeline &lt;ranges&gt; &amp; omezení &lt;concepts&gt;","f1_desc":"Skládejte přehledné datové pipeline pomocí std::views::filter, transform, take, drop a reverse a nahraďte kryptické chyby SFINAE čitelnými klauzulemi requires a &lt;concepts&gt; z C++20.","f1_badge":"std::ranges &#183; std::views &#183; &lt;concepts&gt; &#183; klauzule requires","f2_title":"Zero-copy pohledy &amp; algebraické typy","f2_desc":"Pište API bez alokací pomocí std::span a std::string_view, bezpečně modelujte volitelné či součtové typy přes std::optional, std::variant a std::any a čistě formátujte text s &lt;format&gt; a &lt;charconv&gt;.","f2_badge":"&lt;span&gt; &#183; &lt;string_view&gt; &#183; &lt;optional&gt; &#183; &lt;variant&gt; &#183; &lt;format&gt;","f3_title":"RAII chytré ukazatele &amp; moderní OOP hierarchie","f3_desc":"Zbavte se úniků z ručního new/delete pomocí std::make_unique, std::make_shared, std::weak_ptr, kontrol virtual override/final, move konstruktorů, výchozího operátoru &lt;=&gt; a raw řetězcových literálů R\"(...)\".","f3_badge":"unique_ptr &#183; shared_ptr &#183; &lt;=&gt; Spaceship &#183; R\"(...)\"","f4_title":"Plynulá souběžnost v C++20 (&lt;thread&gt;, &lt;latch&gt;, &lt;barrier&gt;)","f4_desc":"Prototypujete vícevláknové fronty producent–konzument? Vložení &lt;thread&gt;, &lt;future&gt;, &lt;semaphore&gt;, &lt;latch&gt; nebo &lt;barrier&gt; automaticky přesměruje projekt do Cloud C++20 (-pthread) s lokální diagnostikou řádků 1:1.","f4_badge":"&lt;thread&gt; &#183; &lt;future&gt; &#183; &lt;semaphore&gt; &#183; &lt;latch&gt; &#183; &lt;barrier&gt;","f5_title":"AST automatické doplňování na operátorech ::, -&gt; a .","f5_desc":"Procházejte hluboké hierarchie tříd, jmenné prostory std:: a dereference chytrých ukazatelů (ptr-&gt;) offline&#8212;náš AST engine rozpoznává metody tříd, pole i API kontejnerů STL přímo při psaní.","f5_badge":"std:: &#183; ptr-&gt; &#183; obj. &#183; Offline AST inteligence","f6_title":"Formátovač C++20 na 1 klepnutí &amp; Radar syntaktických chyb","f6_desc":"Udržujte složité hlavičky šablon, zachycení v lambdách i vnořené jmenné prostory přehledné na displeji telefonu díky okamžitému offline formátování a atomickému kroku Zpět.","f6_badge":"Offline C++ formátovač &#183; Jednokrokové Zpět &#183; 8 motivů","workflow_title":"Jak prototypovat moderní architekturu C++20 na Androidu","workflow_lead":"Pište idiomatické C++20 offline a při potřebě snadno spouštějte vícevláknové úlohy.","wf1_title":"Pište omezené šablony &amp; RAII třídy","wf1_desc":"Používejte hlavičky C++20 (&lt;ranges&gt;, &lt;concepts&gt;, &lt;memory&gt;, &lt;span&gt;, &lt;optional&gt;, &lt;variant&gt;) bez nutnosti nastavovat jakékoli příznaky kompilátoru.","wf2_title":"Doplňujte členy chytrých ukazatelů &amp; formátujte bloky","wf2_desc":"Prohlížejte členy tříd a STL pomocí doplňování -&gt; a :: a klepnutím na Formátovat zarovnejte víceřádkové pohledy i lambdy.","wf3_title":"Kompilujte &amp; ověřujte jedno- i vícesouborové OOP offline","wf3_desc":"Spouštějte čisté moduly C++20 lokálně během milisekund díky inkrementálnímu cachování objektů podle překladové jednotky.","wf4_title":"Testujte vícevláknové primitivy bez úprav sestavení","wf4_desc":"Kdykoli potřebujete paralelní běh, vložte &lt;thread&gt;, &lt;future&gt; nebo &lt;latch&gt;&#8212;SuperCode automaticky připojí -pthread.","wf_foot_note":"Vytvořeno pro Android 8.0&#8211;15+ &#183; Nahrazuje opuštěné 32bitové aplikace C++11 &#183; Včetně vizuálního Git","table_h2":"SuperCode moderní C++20 vs. zastaralé C++ kompilátory pro Android","snippet_p":"<strong>Moderní C++20 IDE v SuperCode</strong> posouvá vývoj v C++ na Androidu daleko za možnosti zastaralých mobilních kompilátorů C++11. Vývojáři mohou psát offline kód v C++20 s využitím <code>std::ranges</code>, konceptů, <code>std::format</code>, <code>std::span</code>, <code>std::optional</code>, <code>std::variant</code> a RAII chytrých ukazatelů, a navíc využít plynulou cloudovou kompilaci s <code>-pthread</code> pro <code>std::thread</code>, future, latch a barrier.","table_caption":"PODPORA MODERNÍHO JAZYKA C++20 NA ANDROIDU","th_0":"Funkce moderního C++","th_1":"SuperCode C++20 Studio","th_2":"Zastaralé aplikace (např. CppDroid)","th_3":"Online webové spouštěče","th_4":"Čisté mobilní CLI","tr1_c0":"&lt;ranges&gt; &amp; &lt;concepts&gt;","tr1_c1":"Podporováno offline (-std=gnu++2a)","tr1_c2":"Nepodporováno (zamrzlo v C++11)","tr1_c3":"Vyžaduje internet","tr1_c4":"Ruční instalace balíčků","tr2_c0":"optional / variant / span","tr2_c1":"Plné typy C++17 &amp; C++20","tr2_c2":"Chybí nebo experimentální","tr2_c3":"Podporováno online","tr2_c4":"Podporováno","tr3_c0":"Kompatibilita s Android OS","tr3_c1":"64bitová nativní podpora Android 8.0&#8211;15+","tr3_c2":"Nefunkční či stažené na novém Androidu","tr3_c3":"Karta mobilního prohlížeče","tr3_c4":"Ruční nastavení","tr4_c0":"&lt;thread&gt;, &lt;latch&gt;, &lt;barrier&gt;","tr4_c1":"Automatické `-pthread` + mapování řádků 1:1","tr4_c2":"Selhává při linkování nebo padá","tr4_c3":"Často omezovaný výkon CPU","tr4_c4":"Ruční příznak `-pthread`","tr5_c0":"AST doplňování `-&gt;` &amp; `::`","tr5_c1":"Vestavěné offline AST + 21klávesová lišta","tr5_c2":"Zastaralý základní seznam klíčových slov","tr5_c3":"Rozhraní pro desktop","tr5_c4":"Bez dotykového UI","faq_lead":"Otázky ohledně podpory knihoven C++17/C++20, přechodu z CppDroid, raw řetězcových literálů a `&lt;thread&gt;`.","faq1_q":"Proč přejít ze starších aplikací jako CppDroid na SuperCode?","faq1_a":"Zastaralým aplikacím z doby před deseti lety chybí hlavičky C++17 a C++20 (`&lt;optional&gt;`, `&lt;variant&gt;`, `&lt;string_view&gt;`, `&lt;span&gt;`, `&lt;ranges&gt;`, `&lt;concepts&gt;`) a na moderních 64bitových zařízeních s Android 14/15 často ani nejdou nainstalovat. SuperCode nabízí aktivně udržované 64bitové prostředí C++20.","faq2_q":"Fungují raw řetězcové literály C++ `R\"(...)\"` při skenování vícesouborových hlaviček?","faq2_a":"Ano. Skener závislostí C++ v SuperCode rozumí raw řetězcovým literálům C++11/20 (`R\"delim(...)delim\"`) i oddělovačům číslic pomocí apostrofu (`1'000'000`), takže text `#include` uvnitř raw řetězců nikdy nespustí falešné hledání hlaviček.","faq3_q":"Jsou `std::unique_ptr`, `std::shared_ptr`, `std::optional` a `std::variant` 100% offline?","faq3_a":"Ano&#8212;všechny hlavičky `&lt;memory&gt;`, `&lt;optional&gt;`, `&lt;variant&gt;`, `&lt;any&gt;`, `&lt;span&gt;`, `&lt;string_view&gt;`, `&lt;ranges&gt;`, `&lt;concepts&gt;` i `&lt;charconv&gt;` se kompilují zcela offline přímo ve vašem zařízení.","faq4_q":"Jak na Androidu běží `&lt;thread&gt;`, `std::async`, `&lt;latch&gt;` a `&lt;barrier&gt;`?","faq4_a":"Když váš projekt v C++ obsahuje hlavičky souběžnosti jako `&lt;thread&gt;`, `&lt;future&gt;`, `&lt;semaphore&gt;`, `&lt;latch&gt;` nebo `&lt;barrier&gt;`, SuperCode projekt automaticky sbalí se značkami `#line` a odešle do cloudové vrstvy C++20 (`-pthread`).","cta_h2":"Přejděte na skutečné moderní C++20 na Androidu.","cta_desc":"Stáhněte si SuperCode IDE zdarma na Google Play &#8212; offline C++20 rozsahy, chytré ukazatele a 21 vícesouborových šablon projektů."},"cpp_multifile":{"metaTitle":"Vícesouborové C++ IDE pro Android — Linker .cpp/.hpp & 21 šablon CMake | SuperCode","metaDesc":"Sestavujte vícesouborové projekty .cpp, .hpp a .inl v C++20 offline na Androidu. Obsahuje 21 kompletních vícesouborových startovacích projektů CMake, automatické parsování CMakeLists.txt/Makefile a inkrementální cache objektů.","hero_tag":"21 VÍCESOUBOROVÝCH PROJEKTŮ CMAKE &#183; .CPP / .HPP / .INL &#183; INKREMENTÁLNÍ CACHE","hero_h1":"Sestavujte <span class=\"text-gradient\">vícesouborové projekty .cpp / .hpp &amp; CMake</span> na Androidu.","hero_desc":"Navrhujte v mobilu skutečný vícetřídní C++ software. SuperCode obsahuje <strong>21 kompletních vícesouborových startovacích projektů C++ pro CMake</strong>, podporuje <strong><code>.cpp</code>, <code>.cc</code>, <code>.hpp</code> a <code>.inl</code></strong> napříč podsložkami, nativně parsuje <strong><code>CMakeLists.txt</code></strong> a cachuje nezměněné objektové jednotky.","cpp3_s1":"Startovací projekty CMake","cpp3_s2":"Přípony souborů C++","cpp3_s3":"Max. souborů v projektu","cpp3_s4":"&amp; inkrementální cache .o","wb_eyebrow":"PRACOVNÍ PROSTŘEDÍ PRO 21 VÍCESOUBOROVÝCH ŠABLON .CPP / .HPP &amp; SESTAVENÍ CMAKE","sec_cap_title":"Vše potřebné pro semestrální OOP projekty &amp; modulární C++ repozitáře","sec_cap_lead":"Rozdělte rozhraní do hlaviček `.hpp`, implementace do jednotek `.cpp` a inline šablony do souborů `.inl` s chytrostí sestavení jako na desktopu.","f1_title":"21 připravených vícesouborových C++ projektů CMake","f1_desc":"Vygenerujte strukturovaný vícesouborový projekt (.cpp + .h/.hpp + CMakeLists.txt) jedním klepnutím&#8212;od OOP bankovních a skladových systémů přes návrhové vzory, grafové a stromové knihovny až po parsery a CLI nástroje, spolu s 8 rychlými jednosouborovými ukázkami.","f1_badge":"21 vícesouborových projektů + 8 jednosouborových ukázek","f2_title":"Plná podpora .cpp, .cc, .cxx, .hpp, .hh, .inl &amp; .ipp","f2_desc":"Reálné C++ projekty volně kombinují různé konvence pojmenování. Resolver hlaviček a zdrojů v SuperCode páruje hlavičky .hpp či .hh s jednotkami .cpp, .cc nebo .cxx a sleduje vložení šablon .inl / .ipp až do 350 souborů.","f2_badge":".cpp &#183; .cc &#183; .cxx &#183; .hpp &#183; .hh &#183; .inl &#183; .ipp","f3_title":"Automatický engine grafu CMakeLists.txt &amp; Makefile","f3_desc":"Čte přímo CMakeLists.txt (project, set, include_directories, add_library, add_executable) i recepty Makefile&#8212;nebo přejde na bezkonfigurační linkování #include \"...\" ve složkách, když chcete psát kód co nejrychleji.","f3_badge":"Nativní parser CMakeLists.txt &#183; Bezkonfigurační záloha","f4_title":"Spouštějte přímo z hlaviček .hpp nebo karet tříd .cpp","f4_desc":"Upravujete include/Entity.hpp nebo src/Renderer.cpp? Klepněte na Spustit bez přepínání karet&#8212;arbitr vstupního bodu v SuperCode projde graf projektu k main.cpp a spustí cílový binární soubor.","f4_badge":"Chytré směrování hlavička -&gt; main.cpp","f5_title":"Inkrementální cache objektů pro každou překladovou jednotku","f5_desc":"Kompilovat 15 tříd C++ od nuly při každém překlepu zbytečně vybíjí baterii a zdržuje. SuperCode ukládá zkompilované objekty .o podle překladové jednotky a znovu přeloží jen soubory ovlivněné vaší poslední úpravou.","f5_badge":"Tranzitivní hash hlaviček &#183; Rychlé inkrementální linkování","f6_title":"Vizuální správa verzí Git &amp; přibližné hledání souborů","f6_desc":"Přeskakujte mezi desítkami souborů .hpp a .cpp během milisekund pomocí fuzzy vyhledávače, kontrolujte barevné sjednocené diffy, řešte konflikty sloučení vizuálně a nahrávejte commity na GitHub.","f6_badge":"Vizuální Git &#183; Sjednocený diff &#183; Fuzzy vyhledávač (50 tis. uzlů)","workflow_title":"Jak vytvořit &amp; sestavit vícesouborový C++ projekt na Androidu","workflow_lead":"Spusťte vícetřídní pracovní prostor CMake během sekund nebo importujte stávající Git repozitář.","wf1_title":"Vygenerujte startovací projekt CMake nebo naklonujte Git","wf1_desc":"Vyberte jednu z 21 vícesouborových šablon C++ (včetně CMakeLists.txt a hlaviček) nebo naklonujte svůj repozitář.","wf2_title":"Pište třídy s AST doplňováním std::, :: a -&gt;","wf2_desc":"Přepínejte plynule mezi deklaracemi v include/*.hpp a implementacemi v src/*.cpp s živou synchronizací bufferu.","wf3_title":"Kompilujte změněné jednotky inkrementálně offline","wf3_desc":"SuperCode rozparsuje CMakeLists.txt (nebo vazby #include), znovu použije uložené jednotky .o, slinkuje binárku a vypíše výstup.","wf4_title":"Odešlete čisté commity na GitHub nebo exportujte dokumentaci","wf4_desc":"Připravte upravené soubory .hpp/.cpp vizuálně v Git nebo exportujte klíčové moduly jako barevně zvýrazněná PDF A4.","wf_foot_note":"Podporuje #pragma once &amp; klasické include guardy &#183; Živé překrytí neuložených karet","table_h2":"SuperCode vícesouborové C++ Studio vs. běžné mobilní editory","snippet_p":"<strong>Vícesouborový tvůrce projektů C++ v SuperCode</strong> kompiluje reálné architektury ze souborů <code>.cpp</code>, <code>.cc</code>, <code>.hpp</code> a <code>.inl</code> offline na Androidu. Obsahuje 21 vícesouborových startovacích projektů CMake, automaticky parsuje cíle <code>CMakeLists.txt</code> a <code>Makefile</code>, vyhledá <code>main()</code> i z karet hlaviček a cachuje objektové soubory pro rychlé inkrementální sestavení.","table_caption":"SROVNÁNÍ SCHOPNOSTÍ VÍCESOUBOROVÉHO C++ &amp; CMAKE NA ANDROIDU","th_0":"Funkce projektu","th_1":"SuperCode C++20 Studio","th_2":"Jednosouborové C++ aplikace","th_3":"Cloudové webové sandboxy","th_4":"Ruční nastavení CLI","tr1_c0":"Startovací šablony","tr1_c1":"21 vícesouborových projektů CMake + 8 ukázek","tr1_c2":"1–3 jednosouborová dema","tr1_c3":"Prázdný main.cpp","tr1_c4":"Žádné","tr2_c0":"Přípony souborů","tr2_c1":"`.cpp .cc .cxx .hpp .hh .h .inl .ipp`","tr2_c2":"`.cpp` &amp; `.h` v 1 složce","tr2_c3":"Základní `.cpp` / `.h`","tr2_c4":"Ruční pravidla","tr3_c0":"Podpora CMakeLists.txt","tr3_c1":"Vestavěný parser cílů &amp; grafu vložení","tr3_c2":"Ignorováno","tr3_c3":"Placený nebo kontejnerový tarif","tr3_c4":"Vyžaduje CLI cmake","tr4_c0":"Rychlost inkrementálního sestavení","tr4_c1":"Cache objektů `.o` podle hashe obsahu TU","tr4_c2":"Překompiluje vše","tr4_c3":"Studená vzdálená kompilace","tr4_c4":"Podporováno","tr5_c0":"Git &amp; UI pro konflikty","tr5_c1":"Vestavěný vizuální Git + sjednocený diff","tr5_c2":"Vyžaduje externí aplikaci","tr5_c3":"Vyžaduje GitHub OAuth","tr5_c4":"Pouze CLI git","faq_lead":"Otázky k 21 šablonám projektů C++, souborům `.hpp`/`.inl`, `#pragma once` a CMake na Androidu.","faq1_q":"Co obsahují startovací vícesouborové projekty C++ (21 šablon) v SuperCode?","faq1_a":"Každá z 21 šablon projektů vytvoří čistou složku s modulárními hlavičkami `.h`/`.hpp`, implementačními soubory `.cpp`, vstupním souborem `main.cpp` a standardním `CMakeLists.txt`&#8212;takže můžete okamžitě spouštět, studovat nebo upravovat funkční vícetřídní architekturu.","faq2_q":"Mohu vzít projekt CMake vytvořený v SuperCode a otevřít ho v CLion nebo VS Code na notebooku?","faq2_a":"Ano! Protože generované projekty používají standardní soubory `CMakeLists.txt` a přenositelnou adresářovou strukturu ISO/GNU C++20, otevřou se přes Git zcela bez problémů v desktopových IDE bez uzamčení k proprietárnímu formátu.","faq3_q":"Podporuje SuperCode knihovny tvořené jen hlavičkami a implementační soubory šablon `.inl` / `.ipp`?","faq3_a":"Ano. Jak hlavičky s `#pragma once`, tak soubory šablon `.inl` / `.ipp` ve složce `include/` nebo vnořených podsložkách jsou sledovány skenerem závislostí i mezipamětí podle hashe obsahu.","faq4_q":"Co když při práci offline přejmenuji nebo rozdělím soubor `.cpp`?","faq4_a":"Jak parser `CMakeLists.txt`, tak bezkonfigurační prohledávač `#include` při příštím spuštění automaticky přeindexují váš pracovní prostor a nově přidané či přejmenované soubory `.cpp` a `.hpp` ihned zahrnou.","cta_h2":"Navrhujte vícetřídní projekty C++20 na Androidu.","cta_desc":"Nainstalujte si SuperCode IDE zdarma z Google Play &#8212; 21 vícesouborových šablon CMake, inkrementální cache .o a vizuální Git."},"cpp_learn":{"metaTitle":"Učte se C++ offline na Androidu — Zdarma C++20 aplikace pro začátečníky & studenty IT | SuperCode","metaDesc":"Učte se a procvičujte C++20 offline na Androidu bez registrace. Obsahuje 8 jednosouborových + 21 vícesouborových C++ šablon, 21klávesovou lištu symbolů C++ (::, ->, >), Radar chyb, formátovač na 1 klepnutí a export do PDF A4.","hero_tag":"BEZ PŘIHLÁŠENÍ &#183; 100% C++20 V REŽIMU LETADLO &#183; 29 STARTOVACÍCH ŠABLON","hero_h1":"Učte se &amp; procvičujte <span class=\"text-gradient\">C++ offline na Androidu</span> &#8212; bez nastavování.","hero_desc":"Přeskočte kvízové hříčky s výběrem odpovědí i platební brány za účet. Pište, kompilujte a laďte skutečné <strong>programy v C++20 100% offline</strong> s <strong>29 spustitelnými šablonami</strong>, <strong>21klávesovou lištou symbolů C++ (<code>::</code>, <code>-&gt;</code>, <code>&lt;&lt;</code>, <code>&gt;&gt;</code>)</strong>, <strong>Radarem chyb</strong> a <strong>exportem úkolů do PDF A4</strong>.","cpp4_s1":"Bez přihlášení či Wi-Fi","cpp4_s2":"8 ukázek + 21 projektů","cpp4_s3":"Lišta :: -&gt; &lt;&lt; &gt;&gt; {}","cpp4_s4":"Export úkolů do PDF","wb_eyebrow":"OFFLINE PRACOVNÍ PROSTŘEDÍ C++20 PRO ZAČÁTEČNÍKY I STUDENTY INFORMATIKY","sec_cap_title":"Navrženo tak, aby vás klávesnice telefonu při učení C++ nikdy nebrzdila","sec_cap_lead":"Od úplně prvního `std::cout &lt;&lt; \"Hello!\"` až po objektově orientované třídy, binární vyhledávací stromy a portfolia na GitHubu.","f1_title":"Žádná registrace &amp; kompilace i v režimu letadlo","f1_desc":"Stáhněte offline sadu nástrojů C++20 jednou a procvičujte kdekoli&#8212;v autobuse, metru, letadle nebo ve školních budovách bez Wi-Fi. Žádná povinná registrace účtu ani časovače tokenů na spuštění.","f1_badge":"100% offline C++20 &#183; Bez povinného účtu","f2_title":"8 jednosouborových ukázek + 21 vícesouborových projektů","f2_desc":"Začněte zlehka s 8 jednosouborovými příklady C++ (I/O, vektory, řazení, OOP třídy, rekurze) a s postupem studia plynule přejděte na 21 vícesouborových projektů .cpp/.h pro CMake.","f2_badge":"Celkem 29 vestavěných spustitelných šablon C++","f3_title":"21klávesová výsuvná lišta symbolů C++","f3_desc":"Běžné klávesnice telefonů schovávají ::, &lt;&lt;, &gt;&gt;, -&gt;, {} a ; tři vrstvy hluboko. SuperCode ukotví speciální výsuvnou lištu C++ přímo nad klávesnici, takže operátory proudů a závorky napíšete jedním klepnutím.","f3_badge":":: &#183; -&gt; &#183; &lt;&lt; &#183; &gt;&gt; &#183; {} &#183; [] &#183; ; &#183; #include","f4_title":"Radar chyb v reálném čase &amp; klikatelné řádky v diagnostice","f4_desc":"Zapomněli jste středník za uzavírací závorkou třídy nebo nespárovali závorku? Radar chyb podtrhává strukturální syntaktické chyby živě při psaní a hlášení kompilátoru vás přesunou přímo na přesný řádek.","f4_badge":"Živá kontrola syntaxe &#183; Přehledný skok na řádek","f5_title":"Offline formátovač na 1 klepnutí &amp; 8 šetrných motivů","f5_desc":"Klepnutím na Formátovat ihned srovnáte odsazení vnořených cyklů, bloků switch i tříd s atomickým krokem Zpět. Studujte pohodlně ve dne i v noci v 8 studiových motivech (jasných světlých i tmavých bez oslnění).","f5_badge":"Formátovač C++ na 1 klepnutí &#183; 8 světlých &amp; tmavých motivů","f6_title":"Nativní export úkolů do PDF A4 + růst do dalších jazyků","f6_desc":"Exportujte hotové úkoly z C++ jako čistá, barevně zvýrazněná PDF formátu A4 k odevzdání do školy&#8212;a používejte tutéž aplikaci i ve chvíli, kdy vaše studium přinese C17, Python, Java 17, SQL a Git.","f6_badge":"Export do PDF A4 &#183; Obsahuje také C17, Python, Java &amp; SQL","workflow_title":"Vašich prvních 5 minut učení C++ v SuperCode","workflow_lead":"Žádné cesty, kompilátory ani proměnné prostředí k nastavování&#8212;jen otevřete a programujte.","wf1_title":"Vyberte jednu z 8 ukázek nebo 21 projektů","wf1_desc":"Otevřete funkční příklad v C++ nebo vytvořte main.cpp v libovolné lokální složce&#8212;bez přihlášení.","wf2_title":"Pište kód pohodlně s 21klávesovou lištou C++","wf2_desc":"Vkládejte rychle std::cout &lt;&lt;, std::cin &gt;&gt;, složené závorky a středníky, zatímco Radar chyb hlídá překlepy.","wf3_title":"Otestujte živý vstup std::cin offline","wf3_desc":"Zadávejte v konzoli čísla a řetězce interaktivně a sledujte nebufferované výzvy a výstupy okamžitě.","wf4_title":"Naformátujte odsazení &amp; sdílejte úkol v PDF A4","wf4_desc":"Zkrášlete kód v C++ jedním klepnutím a vyexportujte barevně zvýrazněné PDF A4 pro vyučujícího nebo LMS.","wf_foot_note":"Úsporná aplikace 40,2 MB &#183; Rozhraní ve 32 jazycích &#183; Funguje na telefonech &amp; tabletech","table_h2":"SuperCode vs. herní kvízové aplikace &amp; online C++ kompilátory","snippet_p":"<strong>SuperCode</strong> je bezplatná offline aplikace pro programování v C++20 na Androidu určená začátečníkům, středoškolákům i vysokoškolákům IT oborů. Bez nuceného přihlášení nabízí kompilaci v režimu letadlo, 29 spustitelných jednosouborových i vícesouborových šablon C++, 21klávesovou lištu symbolů C++, Radar chyb, formátování jedním klepnutím a export úkolů do PDF A4.","table_caption":"UČENÍ C++ NA ANDROIDU: SROVNÁNÍ APLIKACÍ PRO STUDENTY","th_0":"Potřeba studenta","th_1":"Aplikace SuperCode C++20","th_2":"Herní kvízové aplikace","th_3":"Online IDE v prohlížeči","th_4":"Pouze notebook","tr1_c0":"Skutečné spouštění C++20","tr1_c1":"Plné offline GNU C++20 + STL + více souborů","tr1_c2":"Kvízy na doplňování mezer","tr1_c3":"Jednosouborové webové okno","tr1_c4":"Plné","tr2_c0":"Studium v režimu letadlo","tr2_c1":"100% offline po jednorázové instalaci nástrojů","tr2_c2":"Často vyžaduje předplatné/síť","tr2_c3":"Bez Wi-Fi nefunguje","tr2_c4":"Offline","tr3_c0":"Psaní na dotykové obrazovce","tr3_c1":"21klávesová lišta C++ (`:: -&gt; &lt;&lt; &gt;&gt;`) + AST","tr3_c2":"Minimum skutečného psaní","tr3_c3":"Těsná výchozí klávesnice","tr3_c4":"Fyzická klávesnice","tr4_c0":"Postup výukou","tr4_c1":"8 ukázek -&gt; 21 projektů CMake -&gt; Git","tr4_c2":"Po základech narazí na strop","tr4_c3":"Bez místních složek či Git","tr4_c4":"Plné","tr5_c0":"Export protokolů z cvičení","tr5_c1":"Vestavěné barevně zvýrazněné PDF A4","tr5_c2":"Nepodporováno","tr5_c3":"Ruční kopírování a vkládání","tr5_c4":"Dialog tisku","faq_lead":"Časté dotazy začátečníků, prváků na informatice a učitelů programování.","faq1_q":"Potřebuji notebook nebo zkušenosti s kódováním, abych se začal učit C++ v SuperCode?","faq1_a":"Nepotřebujete notebook ani zkušenosti s konfigurací. SuperCode nastaví celý kompilátor C++20 automaticky&#8212;stačí klepnout na jednu z 8 začátečnických ukázek C++, stisknout Spustit a postupně zkoušet upravovat jednotlivé řádky.","faq2_q":"Mohu na telefonu procvičovat vysokoškolské datové struktury (spojové seznamy, stromy, grafy, hašovací tabulky)?","faq2_a":"Ano! Jak datové struktury postavené na ukazatelích a třídách (spojové seznamy, binární vyhledávací stromy, haldy, trie), tak plné kontejnery C++20 STL (`vector`, `stack`, `queue`, `unordered_map`, `priority_queue`) běží 100% offline.","faq3_q":"Jak odevzdám svůj úkol `.cpp` do systémů Canvas, Blackboard nebo Google Classroom?","faq3_a":"Můžete buď sdílet soubory `.cpp`/`.hpp` přímo ze složky projektu na Androidu, nahrát složku na GitHub přes vizuální Git, nebo klepnout na Exportovat PDF a vygenerovat čistý barevně zvýrazněný dokument PDF A4.","faq4_q":"Mohu ve stejné aplikaci pro ostatní předměty spouštět také C, Python, Java a SQL?","faq4_a":"Ano. SuperCode obsahuje vyhrazená offline prostředí pro C17, C++20, Python 3.11/3.12, Java 17, JavaScript, Lua 5.4, PHP/Web a SQLite v jediném úsporném 40,2 MB studiu pro Android.","cta_h2":"Začněte psát skutečné C++20 offline ještě dnes.","cta_desc":"Stáhněte si SuperCode IDE zdarma na Google Play &#8212; bez registrace, 29 startovacích šablon C++ a export do PDF A4."},"jv_records_17":{"metaTitle":"Kompilátor Java 17 pro Android — Offline Records, Sealed třídy, Streams a Java 21+ | SuperCode","metaDesc":"Kompilujte a spouštějte moderní Java 17 offline na Androidu. Podporuje records, sealed třídy, switch -> výrazy, pattern matching, textové bloky a Streams — plus automatické cloudové virtuální thready v Java 21+.","hero_tag":"OFFLINE JAVA 17 LTS &#183; RECORDS &#183; SEALED &#183; CLOUD JAVA 21+","hero_h1":"Offline <span class=\"text-gradient\">Java 17 Records, Sealed třídy &amp; Streams</span> na Androidu.","hero_desc":"Přestaňte přepisovat moderní školní projekty jen kvůli zastaralým mobilním kompilátorům pro Java 8 nebo Java 11. SuperCode kompiluje <strong>LTS Java 17 100% offline</strong> &#8212; včetně typů <strong><code>record</code></strong>, <strong><code>sealed</code> hierarchií</strong>, výrazů <strong><code>switch -&gt;</code></strong>, textových bloků a virtuálních threadů v <strong>Cloud Java 21+</strong>.","jvr_s1":"100% Offline LTS","jvr_s2":"&amp; Sealed třídy","jvr_s3":"Switch -&gt; &amp; Time","jvr_s4":"Cloud Virtual Threads","wb_eyebrow":"MODERNÍ PRACOVNÍ PROSTOR PRO JAVA 17 &amp; CLOUD JAVA 21+","sec_cap_title":"Proč vývojáři přecházejí ze zastaralých mobilních kompilátorů Java 8/11","sec_cap_lead":"Pište expresivní moderní Javu bez zbytečného boilerplate kódu přímo na telefonu nebo tabletu se stejnou LTS syntaxí, jaká se učí na univerzitách a u backendových pohovorů.","f1_title":"Neměnné Java 17 Records &amp; kompaktní konstruktory","f1_desc":"Nahraďte 70 řádků boilerplate kódu s gettery, equals(), hashCode() a toString() jedinou deklarací record. Podporuje kompaktní kanonické konstruktory pro validaci, generické records, lokální records v metodách i implementaci rozhraní.","f1_badge":"record Order(...) &#183; Kompaktní validace &#183; Lokální Records","f2_title":"Sealed třídy &amp; algebraické doménové hierarchie","f2_desc":"Modelujte uzavřené stavové automaty, AST uzly a stavy plateb čistě pomocí deklarací sealed class a sealed interface v kombinaci s permits, final a non-sealed podtypy &#8212; s kompletní offline kontrolou při kompilaci.","f2_badge":"sealed interface &#183; permits &#183; Kontrola úplnosti při kompilaci","f3_title":"Šipkové výrazy Switch, Pattern Matching &amp; textové bloky","f3_desc":"Odstraňte chyby z propadávání větví pomocí switch (-&gt;) výrazů a yield hodnot, zužujte typy přímo přes if (obj instanceof Card c) pattern matching, odvozujte dlouhé generické typy pomocí var a vkládejte přehledné víceřádkové JSON/SQL \\\"\\\"\\\" textové bloky.","f3_badge":"switch -&gt; &#183; instanceof Pattern &#183; \\\"\\\"\\\" Textové bloky &#183; var","f4_title":"Moderní Streams (.toList()), java.time &amp; CompletableFuture","f4_desc":"Řetězte funkcionální transformace pomocí stručného Stream.toList() z Java 17, Stream.mapMulti(), Optional.ifPresentOrElse(), neměnných továrních metod Map.of(), aritmetiky LocalDate/Instant v java.time a asynchronních pipeline s CompletableFuture.","f4_badge":"Stream.toList() &#183; java.time &#183; CompletableFuture","f5_title":"Navrženo jako náhrada zastaralých mobilních aplikací Java 8 &amp; Java 11","f5_desc":"Řada starších aplikací pro Android odmítá klíčové slovo record, textové bloky nebo .toList() se syntaktickou chybou. SuperCode kompiluje plný cíl Java 17 lokálně v zařízení a nezměněný bajtkód ukládá do cache pro okamžité opakované spuštění.","f5_badge":"--release 17 &#183; 0ms Cache spuštění &#183; AST doplňování kódu","f6_title":"Automatické cloudové virtuální thready Java 21+ &amp; Record Patterns","f6_desc":"Zkoušíte virtuální thready Project Loom (Thread.ofVirtual(), Executors.newVirtualThreadPerTaskExecutor()), sekvenční kolekce nebo vnořenou dekonstrukci recordů? SuperCode detekuje konstrukce Java 21+ a automaticky projekt spustí v Cloud Java.","f6_badge":"Thread.ofVirtual() &#183; SequencedCollection &#183; Cloud Java 21+","workflow_title":"Jak kompilovat kód Java 17 &amp; Java 21+ na Androidu","workflow_lead":"Žádné proměnné prostředí JDK ani stahování Gradle wrapperu &#8212; otevřete soubor a kompilujte.","wf1_title":"Napište Java 17 Records, Sealed typy nebo stručné main()","wf1_desc":"Vytvořte soubor .java pomocí 21klávesové lišty symbolů pro Javu a offline AST doplňování pro java.util, java.time a java.util.stream.","wf2_title":"Automaticky formátujte složené závorky &amp; ověřujte syntaxi živě","wf2_desc":"Klepnutím na Formátovat čistě zarovnáte šipky ve switchi, records a textové bloky, zatímco Error Radar v reálném čase kontroluje neuzavřené oddělovače.","wf3_title":"Kompilujte Java 17 100% offline v milisekundách","wf3_desc":"Při prvním spuštění SuperCode jednou inicializuje offline Java 17 SDK; každý další build se kompiluje lokálně v zařízení se SHA-256 cache.","wf4_title":"Kdykoli přepněte do Cloud Java 21+","wf4_desc":"Použijte virtuální thready Java 21+ nebo komentáře // @cloud kdykoli chcete otestovat novější verze JDK s klikatelným 1:1 stack tracem v editoru.","wf_foot_note":"Plné offline Java 17 SDK &#183; SHA-256 cache bajtkódu &#183; Hybridní podpora Cloud Java 21+","table_h2":"SuperCode Java 17 Studio vs. zastaralé kompilátory Javy pro Android","snippet_p":"<strong>Kompilátor SuperCode Java 17 pro Android</strong> kompiluje a spouští moderní LTS Java 17 kompletně offline na telefonech a tabletech. Na rozdíl od starších mobilních kompilátorů zaseknutých na Java 8 nebo Java 11 podporuje offline records, sealed třídy, šipkové switch výrazy, pattern matching, textové bloky a Streams, plus cloudové virtuální thready Java 21+.","table_caption":"PODPORA MODERNÍCH JAZYKOVÝCH PRVKŮ JAVY NA ANDROIDU","th_0":"Jazykový prvek Javy","th_1":"SuperCode Java Studio","th_2":"Mobilní aplikace Java 8 / 11","th_3":"Webové sandboxy v prohlížeči","th_4":"Ruční CLI OpenJDK","tr1_c0":"Records &amp; Sealed typy","tr1_c1":"100% offline nativní podpora Java 17","tr1_c2":"Syntaktická chyba (nepodporováno)","tr1_c3":"Vyžaduje aktivní internet","tr1_c4":"Ruční CLI přepínače javac","tr2_c0":"Switch -&gt; &amp; textové bloky","tr2_c1":"Plný šipkový Switch, yield &amp; \\\"\\\"\\\" bloky","tr2_c2":"Chybí nebo jen částečné preview","tr2_c3":"Jednosouborové textové pole","tr2_c4":"Bez dotykové lišty symbolů","tr3_c0":"Stream.toList() &amp; var","tr3_c1":"Vestavěná standardní API Java 17","tr3_c2":"Jen zdlouhavé Collectors.toList()","tr3_c3":"Online latence při spuštění","tr3_c4":"Plné CLI","tr4_c0":"Virtuální thready Java 21+","tr4_c1":"Automatické směrování do Cloud Java 21+","tr4_c2":"Nepodporováno","tr4_c3":"Zřídka aktualizováno na 21+","tr4_c4":"2+ GB ruční root/proot","tr5_c0":"Latence opakovaného buildu","tr5_c1":"Téměř 0 ms zásah SHA-256 &#9889; cache","tr5_c2":"Znovu kompiluje od nuly","tr5_c3":"2s&#8211;5s síťová fronta","tr5_c4":"Ruční build skripty","faq_lead":"Odpovědi o offline podpoře jazyka Java 17, migraci z Jvdroid a funkcích Java 21+ na Androidu.","faq1_q":"Kompiluje SuperCode opravdu Java 17 records a sealed třídy bez internetu?","faq1_a":"Ano. Jakmile se při prvním spuštění inicializuje odlehčené offline Java 17 SDK, výrazy `record`, `sealed` / `permits`, `switch -&gt;`, pattern matching s `instanceof`, textové bloky (`\\\"\\\"\\\"`) a `Stream.toList()` se kompilují a spouštějí 100% offline i v režimu letadlo.","faq2_q":"Jak si SuperCode stojí jako moderní alternativa k mobilním aplikacím Java 8 nebo Java 11?","faq2_a":"Starší javové aplikace pro Android často selhávají u moderních univerzitních úloh a řešení na LeetCode, které používají `record` n-tice, `Stream.toList()` nebo switch výrazy. SuperCode podporuje plnou LTS Java 17 offline plus automatický fallback na Cloud Java 21+, Visual Git a vestavěné SQLite JDBC.","faq3_q":"Mohu používat `CompletableFuture`, `Optional` a `java.time` offline?","faq3_a":"Ano. Kompletní základní standardní knihovna &#8212; včetně `java.util.stream`, `java.util.concurrent.CompletableFuture`, `java.time.*`, `java.math.BigDecimal` a `java.nio.file` &#8212; běží nativně offline.","faq4_q":"Jak na svém telefonu s Androidem spustím virtuální thready z Java 21?","faq4_a":"Jednoduše napište `Thread.ofVirtual()` nebo `Executors.newVirtualThreadPerTaskExecutor()` (nebo na začátek souboru přidejte `// @cloud`) a klepněte na Spustit. SuperCode automaticky zabalí třídy projektu do Cloud Java 21+ a výstup streamuje zpět do vaší konzole.","cta_h2":"Přejděte na offline Java 17 na Androidu ještě dnes.","cta_desc":"Stáhněte si SuperCode IDE zdarma na Google Play &#8212; kompilujte Java 17 records, sealed třídy a Streams kdekoli."},"jv_multiclass":{"metaTitle":"Kompilace více tříd Java a knihoven .jar na Androidu — Offline balíčkové IDE | SuperCode","metaDesc":"Vytvářejte vícetřídní a vícebalíčkové projekty Java 17 offline na Androidu. Prohledejte až 500 souborů .java, automaticky načítejte vlastní knihovny libs/*.jar (až 30 MB), přibalujte resources/ a spouštějte znovu za ~0 ms přes SHA-256 cache.","hero_tag":"500 SOUBORŮ .JAVA &#183; LIBS/*.JAR &#183; CHYTRÉ MAIN() &#183; &#9889; 0MS CACHE","hero_h1":"Vytvářejte <span class=\"text-gradient\">vícebalíčkové projekty Java &amp; vlastní .jar</span> offline na Androidu.","hero_desc":"Skutečný objektově orientovaný software se nevejde do jediného souboru <code>Main.java</code>. SuperCode kompiluje až <strong>500 tříd <code>.java</code> napříč vnořenými balíčky</strong>, automaticky připojuje externí <strong>knihovny <code>libs/*.jar</code></strong>, načítá zdroje přes <strong><code>getResourceAsStream()</code></strong> a nezměněné buildy spouští znovu téměř za <strong><code>0ms</code></strong>.","jvm_s1":"Max. souborů .java","jvm_s2":"Načítání libs/*.jar","jvm_s3":"SHA-256 &#9889; Cache","jvm_s4":"Výběr main()","wb_eyebrow":"PRACOVNÍ PROSTOR PRO VÍCEBALÍČKOVOU OOP &amp; VLASTNÍ .JAR CLASSPATH","sec_cap_title":"Desktopová architektura balíčků Java bez zdlouhavého čekání na Gradle","sec_cap_lead":"Uspořádejte čistě doménové, servisní a repozitářové balíčky na Androidu bez boje se 4minutovou synchronizací Gradle nebo ručními příznaky `javac -cp`.","f1_title":"Prohledá až 500 souborů .java napříč vnořenými balíčky","f1_desc":"Organizujte projekty podle standardních konvencí Maven/Gradle (src/main/java/com/company/...) nebo v jednoduchých podsložkách. SuperCode prohledá až 500 souborů .java (limit 12 MB zdrojového kódu) a zkompiluje importy mezi balíčky v jednom průchodu.","f1_badge":"src/main/java &#183; Vnořené balíčky &#183; 500 souborů / 12 MB","f2_title":"Bezkonfigurační načítání classpath libs/*.jar &amp; lib/*.jar","f2_desc":"Potřebujete Gson, Apache Commons, org.json nebo vlastní školní knihovnu? Zkopírujte čistě javové soubory .jar (celkem až 30 MB) do složky libs/ nebo lib/ projektu a jejich balíčky ihned importujte offline.","f2_badge":"libs/*.jar &#183; lib/*.jar &#183; Classpath až 30 MB","f3_title":"SHA-256 cache uzávěru pro okamžité opětovné spuštění za ~0 ms","f3_desc":"SuperCode vypočítá kryptografický SHA-256 otisk všech zúčastněných zdrojů .java, otevřených neuložených bufferů i souborů .jar. Opakované testování s jinými vstupy do konzole zasáhne &#9889; Cache za ~0 ms bez rekompilace.","f3_badge":"SHA-256 hash uzávěru &#183; Odznak &#9889; Cache &#183; Okamžitý start","f4_title":"Chytrý výběr vstupního bodu main() z libovolné otevřené karty","f4_desc":"Upravujete rozhraní InvoiceRepository nebo pomocnou třídu TaxCalculator? Klepněte na Spustit &#9654; přímo tam, kde jste &#8212; SuperCode projde graf balíčků, najde třídu se vstupním bodem main() a automaticky sloučí i neuložené úpravy z karet.","f4_badge":"Spuštění z jakékoli karty &#183; Překryv neuložených bufferů","f5_title":"Automatické přibalení zdrojů resources/ na classpath","f5_desc":"Umístěte soubory .properties, .json, .csv, .xml nebo .txt do resources/ či src/main/resources/. Vaše třídy je načtou stejně čistě jako na desktopu pomocí Class.getResourceAsStream() nebo ClassLoader.getResource().","f5_badge":"resources/ &#183; src/main/resources/ &#183; getResourceAsStream","f6_title":"Fuzzy vyhledávání 50k uzlů, AST doplňování &amp; Visual Git","f6_desc":"Přepínejte mezi desítkami tříd Javy v milisekundách pomocí CamelCase fuzzy hledání (např. 'ICR' najde InvoiceController.java), refaktorujte s AST doplňováním a commitujte milníky přes vestavěný Visual Git.","f6_badge":"CamelCase skok na soubor &#183; AST nápověda členů &#183; Visual Git","workflow_title":"Jak strukturovat vícebalíčkové &amp; .jar projekty na Androidu","workflow_lead":"Nastavte si čistý vícebalíčkový OOP prostor s knihovnami .jar třetích stran ve čtyřech krocích.","wf1_title":"Vytvořte složky balíčků nebo naklonujte Git repozitář","wf1_desc":"Vytvořte v Průzkumníku vnořené složky balíčků (nebo naklonujte existující školní/GitHub Java repozitář přes Visual Git klienta v SuperCode).","wf2_title":"Přidejte volitelné soubory .jar třetích stran do libs/","wf2_desc":"Zkopírujte kompatibilní čistě javové archivy .jar do libs/ nebo lib/ a statické konfigurační soubory umístěte do resources/.","wf3_title":"Spusťte projekt bez opuštění pomocné třídy","wf3_desc":"Klepněte na Spustit &#9654; i při úpravě modelu nebo rozhraní &#8212; SuperCode automaticky určí main() a zkompiluje celý strom balíčků offline.","wf4_title":"Testujte okrajové případy okamžitě díky 0ms cache buildům","wf4_desc":"Spouštějte znovu s novými vstupy pro Scanner nebo CLI argumenty okamžitě díky SHA-256 cacheování bajtkódu.","wf_foot_note":"Až 500 zdrojů .java (12 MB) &#183; Limit 30 MB vlastních .jar &#183; Synchronizace neuložených karet","table_h2":"Srovnání podpory vícesouborových &amp; .jar projektů v Javě","snippet_p":"<strong>SuperCode Multi-Class Java IDE</strong> sestavuje skutečné vícebalíčkové projekty Java 17 offline na Androidu bez režie Gradle. Prohledává až 500 zdrojových souborů napříč vnořenými balíčky, automaticky načítá vlastní knihovny .jar z libs/, inteligentně volí vstupní třídy main() a zkompilované uzávěry ukládá do cache podle SHA-256 hashe pro téměř 0ms opakované spuštění.","table_caption":"SCHOPNOSTI BUILDU VÍCETŘÍDNÍ JAVY &amp; .JAR NA ANDROIDU","th_0":"Funkce projektu","th_1":"SuperCode Java 17 IDE","th_2":"Základní mobilní Java aplikace","th_3":"Online webové kompilátory","th_4":"Těžkopádné mobilní porty Gradle","tr1_c0":"Rozsah více balíčků","tr1_c1":"Až 500 souborů .java v src/main/java","tr1_c2":"Jediná složka nebo ruční seznam","tr1_c3":"1 soubor (pouze Main.java)","tr1_c4":"Vysoká spotřeba RAM &amp; úložiště","tr2_c0":"Vlastní knihovny .jar","tr2_c1":"Automaticky načítá libs/*.jar &amp; lib/*.jar (30 MB)","tr2_c2":"Nepodporováno nebo placený zámek","tr2_c3":"Nelze nahrát vlastní .jar","tr2_c4":"Vyžaduje online synchronizaci Maven","tr3_c0":"UX vstupního bodu","tr3_c1":"Chytrý výběr main() z jakékoli karty","tr3_c2":"Selže při aktivní pomocné kartě","tr3_c3":"Pevný název třídy Main","tr3_c4":"Ruční XML konfigurace spuštění","tr4_c0":"Zdroje na classpath","tr4_c1":"Automaticky připojí resources/ pro getResourceAsStream","tr4_c2":"Chybějící kořen classpath","tr4_c3":"Nepodporováno","tr4_c4":"Podporováno","tr5_c0":"Nezměněné spuštění","tr5_c1":"Téměř 0 ms zásah SHA-256 &#9889; cache","tr5_c2":"Plná rekompilace při každém klepnutí","tr5_c3":"Síťová fronta při každém klepnutí","tr5_c4":"Pomalý inkrementální daemon","faq_lead":"Časté dotazy ohledně struktury balíčků, přidávání externích knihoven .jar a určení metody main().","faq1_q":"Jak v SuperCode přidám externí knihovnu `.jar`, například Gson nebo Commons Lang?","faq1_a":"Vytvořte v kořenu projektu Java složku `libs` (nebo `lib`) a zkopírujte do ní soubor `.jar`. SuperCode automaticky přidá všechny archivy `.jar` v `libs/` (až do 30 MB) na classpath pro kompilaci i běh &#8212; bez jakýchkoli build skriptů.","faq2_q":"Co se stane, když stisknu Spustit během úpravy třídy Java, která nemá `main()`?","faq2_a":"Arbitr vstupních bodů v SuperCode projde zkompilované třídy projektu, automaticky vybere hlavní vstupní třídu obsahující `main()` a spustí ji &#8212; ušetří vám neustálé přepínání mezi kartami.","faq3_q":"Musím používat `src/main/java`, nebo fungují i jednoduché vícesouborové složky?","faq3_a":"Obojí funguje hladce! Můžete dát dva soubory `.java` vedle sebe do obyčejné složky bez deklarace `package`, přímo vytvořit podsložky `com.example.*`, nebo použít kompletní rozvržení `src/main/java` + `resources/` + `libs/`.","faq4_q":"Které soubory `.jar` fungují na Androidu offline?","faq4_a":"Jakákoli standardní čistě javová knihovna `.jar` cílící na Java 8, 11 nebo 17 (například `gson`, `org.json`, `commons-lang3`, `commons-csv` nebo univerzitní testovací knihovny) funguje 100% offline. Desktopové GUI archivy vyžadující okna AWT/Swing nejsou určeny pro mobilní konzole.","cta_h2":"Vytvářejte skutečné vícebalíčkové Java projekty na svém telefonu.","cta_desc":"Získejte SuperCode IDE zdarma na Google Play &#8212; buildy Java 17 až s 500 soubory, podpora libs/*.jar a 0ms spuštění z cache."},"jv_jdbc_sqlite":{"metaTitle":"Java SQLite JDBC & NIO.2 File I/O na Androidu — Offline databázové IDE | SuperCode","metaDesc":"Pište javové programy pro databáze a práci se soubory offline na Androidu. Připojte se přes vestavěné jdbc:sqlite bez nastavování Mavenu, prohlížejte .db soubory v SQL Studio, synchronizujte NIO.2 Files do složky a používejte HttpClient.","hero_tag":"VESTAVĚNÉ JDBC:SQLITE &#183; JAVA NIO.2 FILES &#183; HTTPCLIENT","hero_h1":"Offline <span class=\"text-gradient\">Java SQLite JDBC, NIO.2 File I/O &amp; HttpClient</span> na Androidu.","hero_desc":"Vytvářejte skutečné datové backendové projekty bez boje se závislostmi Mavenu na mobilu. SuperCode má <strong>přímo vestavěný <code>org.sqlite.JDBC</code></strong> &#8212; spouštějte <strong><code>jdbc:sqlite:app.db</code></strong> offline, prohlížejte stejnou databázi vizuálně v <strong>SQL Studio</strong> a synchronizujte <strong><code>java.nio.file.Files</code></strong> přímo do pracovního prostoru na Androidu.","jvj_s1":"Vestavěné SQLite","jvj_s2":"Bez Maven/Gradle","jvj_s3":"Sync do složky","jvj_s4":"Java HttpClient","wb_eyebrow":"PRACOVNÍ PROSTOR JAVA SQLITE JDBC, NIO.2 SYNC SOUBORŮ &amp; HTTPCLIENT","sec_cap_title":"Kompletní stack pro persistenci, File I/O a sítě v Java 17","sec_cap_lead":"Procvičujte univerzitní databázová cvičení, návrhový vzor DAO repozitáře, parsery CSV/JSON souborů i REST klienty v jediném uceleném prostředí pro Android.","f1_title":"Vestavěný offline ovladač SQLite JDBC bez nastavování","f1_desc":"Napište DriverManager.getConnection(\\\"jdbc:sqlite:campus.db\\\") nebo \\\"jdbc:sqlite::memory:\\\" a stiskněte Spustit. SuperCode předem registruje org.sqlite.JDBC offline &#8212; žádné hledání ovladačů .jar, triky s Class.forName() ani pom.xml.","f1_badge":"jdbc:sqlite:app.db &#183; :memory: &#183; Bez nastavování ovladače","f2_title":"PreparedStatement, ACID transakce &amp; dávkové DAO operace","f2_desc":"Osvojte si prevenci SQL injection pomocí parametrizovaných dotazů PreparedStatement, provádějte atomické vícetabulkové převody přes setAutoCommit(false) a rollback(), povolte PRAGMA foreign_keys a čtěte sloupce z ResultSetMetaData.","f2_badge":"PreparedStatement &#183; ACID Rollback &#183; executeBatch()","f3_title":"Propojení na 1 klepnutí s vizuálním SQL Studio v SuperCode","f3_desc":"Každý trvalý soubor .db nebo .sqlite3 vytvořený vaším kódem Java JDBC se ihned objeví ve stromu projektu. Klepnutím na něj zobrazíte schémata, indexy a tabulky v SQL Studio v režimech Box, Markdown, CSV a JSON.","f3_badge":"Sdílený prostor .db &#183; Vizuální náhled schémat &amp; tabulek","f4_title":"Plné Java NIO.2 &amp; klasické streamové File I/O","f4_desc":"Načítejte CSV datasety, aktualizujte konfigurace .properties a zapisujte strukturované reporty přes java.nio.file.Files (readString, writeString, readAllLines, createDirectories), FileChannel, BufferedReader a ObjectOutputStream &#8212; s živou synchronizací do složky.","f4_badge":"java.nio.file.Files &#183; Path.of() &#183; Trvalá synchronizace na disk","f5_title":"Standardní java.net.http.HttpClient &amp; lokální HttpServer","f5_desc":"Konzumujte REST JSON API pomocí moderního HttpClient v Javě (synchronní send() nebo neblokující sendAsync() s CompletableFuture, vlastními timeouty a hlavičkami) nebo rozjeďte lehké routy přes com.sun.net.httpserver.HttpServer.","f5_badge":"java.net.http.HttpClient &#183; sendAsync &#183; HttpServer","f6_title":"Přesná diagnostika SQLException &amp; IOException","f6_desc":"Když máte překlep v názvu SQL sloupce nebo chybí cesta k CSV, SuperCode odfiltruje interní rámce reflexe, takže stack trace přehledně zvýrazní přesné číslo řádku ve vašem DAO nebo parseru.","f6_badge":"Filtrovaný stack trace &#183; Přesná diagnostika řádku","workflow_title":"Jak vytvořit projekt Java + SQLite JDBC na Androidu","workflow_lead":"Přejděte z prázdné složky k trvalé databázi JDBC a vizuální kontrole SQL během několika sekund.","wf1_title":"Připojte se přes DriverManager.getConnection(\\\"jdbc:sqlite:...\\\")","wf1_desc":"Otevřete libovolný soubor .java a připojte se k relativnímu názvu databáze (např. jdbc:sqlite:store.db) &#8212; ovladač se automaticky načte offline.","wf2_title":"Spouštějte DDL, parametrizované INSERTy &amp; JOINy","wf2_desc":"Provádějte CREATE TABLE, dávkové INSERTy a SELECT JOINy offline nebo načítejte doprovodné .csv soubory přes Files.readAllLines().","wf3_title":"Prohlédněte si vytvořený soubor .db v SQL Studio","wf3_desc":"Klepněte na synchronizovaný soubor store.db v Průzkumníku a prohlížejte tabulky, spouštějte ad-hoc SQL dotazy nebo exportujte výsledky do Markdownu/CSV.","wf4_title":"Exportujte reporty nebo commitněte svůj DAO projekt","wf4_desc":"Ověřte exportované CSV/JSON soubory v editoru, vytiskněte zdrojový kód do A4 PDF nebo commitněte vícetřídní DAO repozitář přes Visual Git.","wf_foot_note":"Předinstalované offline org.sqlite.JDBC &#183; Synchronizace reálných souborů &#183; Doprovodné SQL IDE","table_h2":"Podpora Java databází &amp; File I/O napříč mobilními platformami","snippet_p":"<strong>SuperCode Java SQLite &amp; File I/O Studio</strong> obsahuje vestavěný offline ovladač org.sqlite.JDBC pro Android zcela bez nastavování Mavenu nebo Gradle. Vývojáři mohou spouštět parametrizované SQLite dotazy, sdílet soubory .db přímo s vizuálním SQL Studio v SuperCode, číst a zapisovat soubory projektu přes Java NIO.2 Files a testovat REST API pomocí HttpClient.","table_caption":"MOŽNOSTI JAVA JDBC, FILE I/O &amp; HTTP NA ANDROIDU","th_0":"Backendová funkce","th_1":"SuperCode Java 17 IDE","th_2":"Běžné mobilní Java aplikace","th_3":"Webové Java kompilátory","th_4":"Desktopový Maven setup","tr1_c0":"Ovladač SQLite JDBC","tr1_c1":"Vestavěný offline jdbc:sqlite (0 nastavování)","tr1_c2":"Chybí (ClassNotFoundException)","tr1_c3":"Bez trvalé lokální DB","tr1_c4":"Vyžaduje pom.xml + stažení","tr2_c0":"Vizuální prohlížení DB","tr2_c1":"Otevření na 1 klepnutí v SQL Studio","tr2_c2":"Nutný externí prohlížeč DB","tr2_c3":"Žádné","tr2_c4":"Samostatný GUI plugin pro DB","tr3_c0":"Java NIO.2 File I/O","tr3_c1":"Plný sync Files.readString/writeString do složky","tr3_c2":"Omezený dočasný sandbox","tr3_c3":"Reset dočasného kontejneru","tr3_c4":"Plné","tr4_c0":"HTTP REST klient","tr4_c1":"Vestavěný java.net.http.HttpClient &amp; Server","tr4_c2":"Jen starší HttpURLConnection","tr4_c3":"Odchozí síť blokována","tr4_c4":"Plné","tr5_c0":"Offline spolehlivost","tr5_c1":"100% offline běh JDBC + NIO.2","tr5_c2":"Závisí na pluginu","tr5_c3":"Vyžaduje internet","tr5_c4":"Offline po stažení Maven cache","faq_lead":"Dotazy ohledně JDBC connection stringů, trvalých `.db` souborů, cest NIO.2 a `HttpClient` na Androidu.","faq1_q":"Potřebuji pro SQLite v Javě volat `Class.forName(\\\"org.sqlite.JDBC\\\")` nebo přidat Maven závislost?","faq1_a":"Ne! SuperCode obsahuje a automaticky registruje `org.sqlite.JDBC` ihned po instalaci. Stačí naimportovat `java.sql.*` a zavolat `DriverManager.getConnection(\\\"jdbc:sqlite:mydb.db\\\")` &#8212; okamžitě to funguje 100% offline.","faq2_q":"Kam se ukládají soubory `.db`, `.csv` a `.txt`, když je můj Java program zapíše?","faq2_a":"Relativní cesty jako `jdbc:sqlite:inventory.db` nebo `Path.of(\\\"report.csv\\\")` se vyhodnocují přímo vůči složce aktivního projektu a ihned po dokončení běhu se synchronizují zpět do vašeho pracovního prostoru na Androidu.","faq3_q":"Mohu naplnit SQLite databázi v SQL Studio od SuperCode a poté ji dotazovat z Javy?","faq3_a":"Ano! To je jeden z nejoblíbenějších postupů v SuperCode: navrhněte tabulky a vložte testovací data v SQL Studio (`schema.sql` -&gt; `app.db`), a pak ve stejné složce otevřete svou `.java` DAO třídu a plynule dotazujte `jdbc:sqlite:app.db`.","faq4_q":"Funguje `java.net.http.HttpClient` pro testování REST API?","faq4_a":"Ano. Standardní `HttpClient`, `HttpRequest` a `HttpResponse` z Java 11/17 fungují ihned pro HTTPS REST požadavky, když je zařízení online, zatímco operace JDBC a NIO.2 se soubory běží kompletně offline.","cta_h2":"Programujte Java databáze &amp; datové pipeline se soubory offline na Androidu.","cta_desc":"Stáhněte si SuperCode IDE zdarma na Google Play &#8212; vestavěné SQLite JDBC, synchronizace Java NIO.2 a vizuální SQL Studio."},"jv_learn_apcs":{"metaTitle":"Učte se Javu a procvičujte AP CS / DSA offline na Androidu — Zdarma | SuperCode","metaDesc":"Bezplatná offline aplikace pro Javu na Androidu pro začátečníky, studenty AP Computer Science A a přípravu na DSA pohovory. Spouštějte stručné void main(), interaktivní Scanner(System.in), 8 šablon a exportujte úkoly do A4 PDF.","hero_tag":"BEZ PŘIHLÁŠENÍ &#183; AP CS A &amp; DSA &#183; STRUČNÉ VOID MAIN() &#183; A4 PDF","hero_h1":"Učte se <span class=\"text-gradient\">Javu, AP Computer Science A &amp; DSA</span> offline na Androidu.","hero_desc":"Přeskočte kvízové kartičky a pište od první minuty spustitelný kód v Javě. Procvičujte se <strong>stručnými skripty <code>void main()</code></strong>, interaktivním vstupem <strong><code>Scanner(System.in)</code></strong>, <strong>8 vestavěnými šablonami Javy</strong>, přesnými <strong>ukazateli chyb <code>^~~~</code></strong> a jednoklepnutím exportujte <strong>úkoly do A4 PDF</strong> &#8212; 100% offline.","jvl_s1":"100% offline aplikace","jvl_s2":"Šablony Javy","jvl_s3":"Lišta symbolů Javy","jvl_s4":"Export úkolů","wb_eyebrow":"PROSTŘEDÍ PRO ZAČÁTEČNÍKY V JAVĚ, AP CS A &amp; LEETCODE DSA","sec_cap_title":"Navrženo pro začátečníky, výuku AP CS a přípravu na pohovory","sec_cap_lead":"Dostatečně přívětivé pro váš první `System.out.println`, a přitom dost výkonné pro více-třídní OOP, datové struktury, SQL databáze a Git.","f1_title":"Stručné void main() bez úvodního balastu","f1_desc":"Začátečníci by neměli klopýtat o public static void main(String[] args), než se naučí proměnné a cykly. SuperCode podporuje stručné metody void main() nejvyšší úrovně i klasické více-třídní OOP definice.","f1_badge":"Stručné void main() &#183; Plynulá cesta k OOP","f2_title":"100% připraveno na AP Computer Science A i VŠ kurzy CS1/CS2","f2_desc":"Procvičujte offline všechna témata AP CS A Free-Response (FRQ): práci se String, metody Math, 1D a 2D pole, ArrayList&lt;E&gt;, návrh tříd, dědičnost, polymorfismus, rekurzi, binární vyhledávání a merge sort.","f2_badge":"AP CS A Java Subset &#183; 2D pole &#183; Dědičnost &amp; FRQ","f3_title":"Kompletní Java Collections pro LeetCode a DSA pohovory","f3_desc":"Trénujte klouzavé okno, Dijkstrův algoritmus, trie a dynamické programování kdekoli offline s HashMap, HashSet, TreeMap, TreeSet, PriorityQueue, ArrayDeque, Collections a Arrays &#8212; včetně telemetrie času v ms a paměti.","f3_badge":"PriorityQueue &#183; HashMap &#183; ArrayDeque &#183; Telemetrie ms/KB","f4_title":"Živý stream Scanner(System.in) a bezpečný System.exit()","f4_desc":"Interaktivní CLI úlohy se v terminálu na rozdělené obrazovce přirozeně pozastaví u každého Scanner.nextLine() či nextInt() (s vyhrazeným tlačítkem [EOF]) a volání System.exit(0) program bezpečně ukončí bez pádu aplikace.","f4_badge":"Streamovaný System.in &#183; Tlačítko [EOF] &#183; Bezpečný System.exit()","f5_title":"Přesné ukazatele chyb ^~~~, 8 šablon a 21klávesová lišta","f5_desc":"Diagnostika překladače podtrhne přesný sloupec pomocí `^~~~` a uvede jasná čísla řádků. Pište `{`, `}`, `[`, `]`, `;`, `-&gt;` i běžné snippety na displeji telefonu bleskově díky výsuvné 21klávesové liště Javy a 8 ukázkám.","f5_badge":"Ukazatele sloupců ^~~~ &#183; 21klávesová lišta &#183; 8 spustitelných ukázek","f6_title":"Formátování Javy jedním klepnutím a export úkolů do A4 PDF","f6_desc":"Srovnejte odsazení vnořených if/for jedním klepnutím, čtěte pohodlně v 8 tmavých i světlých studiových motivech a exportujte hotové úkoly `.java` jako ostré A4 PDF připravené pro Canvas či Google Classroom.","f6_badge":"Auto-odsazení jedním klepnutím &#183; 8 šetrných motivů &#183; Uložit jako .pdf","workflow_title":"Jak se začít učit Javu offline na telefonu","workflow_lead":"Bez registrace, bez reklam přerušujících psaní a bez potřeby stolního počítače.","wf1_title":"Vyberte vestavěnou šablonu Javy nebo vytvořte Hello.java","wf1_desc":"Otevřete jednu z 8 připravených ukázek Javy (cykly, OOP třídy, kolekce, rekurze) nebo napište stručný skript `void main()`.","wf2_title":"Pište plynule s chytrými závorkami a našeptávačem","wf2_desc":"Používejte výsuvné klávesy pro `;`, `{}` a `[]`, zatímco offline AST doplňování navrhuje metody `String`, `ArrayList` a `Math`.","wf3_title":"Kompilujte offline a zadávejte vstupy pro Scanner živě","wf3_desc":"Klepněte na Spustit &#9654; pro okamžitý výstup, otestujte interaktivní `Scanner(System.in)` a opravte překlepy podle nápovědy `^~~~`.","wf4_title":"Naformátujte kód a exportujte úkol do A4 PDF","wf4_desc":"Klepněte na Formátovat pro čisté odsazení, pak exportujte A4 PDF podklad nebo pošlete studentské portfolio na GitHub přes Visual Git.","wf_foot_note":"Bez registrace &#183; Funguje 100% v režimu Letadlo &#183; Telefony, skládací mobily i Chromebooky","table_h2":"SuperCode vs. kvízové aplikace a online Java sandboxy pro studenty","snippet_p":"<strong>SuperCode</strong> je bezplatná offline aplikace pro programování v Javě na Androidu určená začátečníkům, studentům AP Computer Science A i uchazečům připravujícím se na DSA pohovory. Nabízí stručné spouštění void main(), živý interaktivní vstup Scanner(System.in), přesné ukazatele chyb, 8 spustitelných šablon Javy, 21klávesovou lištu symbolů a export úkolů do A4 PDF.","table_caption":"VÝUKA JAVY A PROCVIČOVÁNÍ DSA NA ANDROIDU","th_0":"Požadavek studenta","th_1":"SuperCode Java aplikace","th_2":"Gamifikované kvízy","th_3":"Webové Java sandboxy","th_4":"Zastaralé mobilní Java IDE","tr1_c0":"Jednoduchost od prvního dne","tr1_c1":"Stručné void main() + 8 startovacích šablon","tr1_c2":"Jen klikání na možnosti a/b/c","tr1_c3":"Rozvleklá třída Main","tr1_c4":"Složitý průvodce projektem","tr2_c0":"Studium offline v autobuse či letadle","tr2_c1":"100% offline Java 17 + Collections","tr2_c2":"Paywall / vyžaduje Wi-Fi","tr2_c3":"Bez internetu nefunguje","tr2_c4":"Zastaralá syntaxe Java 8/11","tr3_c0":"Interaktivní konzole","tr3_c1":"Živý stream Scanner + [EOF] + bezpečný exit()","tr3_c2":"Statické předvyplněné pole","tr3_c3":"Dávkový stdin před spuštěním","tr3_c4":"Při System.exit() spadne","tr4_c0":"Odevzdávání úkolů","tr4_c1":"Formátování 1 klepnutím + nativní A4 PDF + Git","tr4_c2":"Žádný export souborů","tr4_c3":"Pouze kopírování textu","tr4_c4":"Pouze surový soubor .java","tr5_c0":"Využití napříč předměty","tr5_c1":"Spouští i Python, C/C++, JS, SQL a HTML","tr5_c2":"Jedna výuková trať","tr5_c3":"Samostatné webové karty","tr5_c4":"Aplikace jen pro Javu","faq_lead":"Odpovědi pro začátečníky v Javě, studenty AP Computer Science A, učitele a uchazeče o práci.","faq1_q":"Mohu v SuperCode studovat na zkoušku AP Computer Science A bez Wi-Fi?","faq1_a":"Ano! Každá třída v Javě, pole, `ArrayList`, metoda řetězců, hierarchie dědičnosti i rekurzivní vzor ze zkoušky AP Computer Science A se na vašem telefonu či tabletu zkompilují a spustí 100% offline.","faq2_q":"Proč mi `Scanner(System.in)` na webových kompilátorech selhává při čtení více řádků a jak to řeší SuperCode?","faq2_a":"Mnoho online kompilátorů vyžaduje zadání všech vstupů naslepo před spuštěním. SuperCode streamuje `System.in` interaktivně v reálném čase &#8212; nejprve vypíše výzvu, počká na každý váš řádek a nabízí tlačítko `[EOF]` pro cykly `while (sc.hasNext())`.","faq3_q":"Musím si před psaním kódu v Javě vytvořit účet nebo se přihlásit?","faq3_a":"Nikdy. SuperCode se otevře přímo do pracovního prostoru bez jakékoli registrace, takže studenti i třídy mohou začít programovat okamžitě.","faq4_q":"Mohu později přejít ze stručného `void main()` na standardní více-třídní Java balíčky?","faq4_a":"Ano. Stručné `void main()` je volitelné usnadnění pro rychlá cvičení &#8212; jakmile napíšete standardní soubory `public class Main`, více tříd `.java`, rozhraní nebo databázové projekty `jdbc:sqlite`, SuperCode je zkompiluje bez přepínání režimů.","cta_h2":"Začněte procvičovat Javu a DSA offline zdarma.","cta_desc":"Stáhněte si SuperCode IDE na Google Play &#8212; bez přihlášení, 8 šablon Javy, živý vstup Scanner a export do A4 PDF."},"js_node_core":{"metaTitle":"Spouštějte základní moduly Node.js offline na Androidu — fs, path, stream, zlib & ESM | SuperCode","metaDesc":"Spouštějte 29+ základních modulů Node.js (node:fs, fs/promises, path, buffer, events, stream, zlib, crypto, readline, util) 100% offline na Androidu. Podpora ESM, CommonJS, package.json exports a synchronizace složek.","hero_tag":"29+ OFFLINE MODULŮ NODE &#183; ESM + COMMONJS &#183; REÁLNÁ SYNC FS","hero_h1":"Spouštějte <span class=\"text-gradient\">29+ základních modulů Node.js (<code>fs</code>, <code>path</code>, <code>stream</code>, <code>zlib</code>)</span> offline na Androidu.","hero_desc":"Pište na telefonu reálnou backendovou automatizaci a skripty pro zpracování souborů bez balastu Linux chroot. SuperCode obsahuje <strong>29+ základních Node.js API 100% offline</strong> &#8212; s podporou <strong><code>import</code> (ESM)</strong> i <strong><code>require()</code> (CommonJS)</strong>, <strong><code>package.json</code> subpath exports</strong> a přímé <strong>synchronizace složek přes <code>node:fs</code></strong>.","jsn_s1":"Offline Node API","jsn_s2":"Reálná sync složek","jsn_s3":"&amp; package.json","jsn_s4":"Auto http/net burst","wb_eyebrow":"PROSTŘEDÍ PRO OFFLINE ZÁKLADNÍ MODULY NODE.JS &amp; PACKAGE.JSON","sec_cap_title":"Backendové JS skriptování a práce se soubory bez tření v terminálu","sec_cap_lead":"Automatizujte převody JSON/CSV, komprimujte artefakty sestavení, testujte modulární knihovny a spouštějte CLI nástroje offline během milisekund.","f1_title":"29+ vestavěných modulů Node.js připravených offline","f1_desc":"Importujte standardní moduly s prefixem `node:` i bez něj bez nastavování: fs, fs/promises, path, path/posix, buffer, events, stream, stream/promises, stream/web, zlib, crypto, util, assert, url, querystring, readline, string_decoder, timers, timers/promises, perf_hooks, os, process a diagnostics_channel.","f1_badge":"node:fs &#183; path &#183; buffer &#183; events &#183; stream &#183; zlib &#183; util","f2_title":"Reálná synchronizace prostoru s node:fs a fs/promises","f2_desc":"Používejte readFileSync, writeFile, appendFile, mkdir({ recursive: true }), readdir, stat a copyFile přímo nad reálnými soubory projektu. Vygenerované balíky JSON, Markdown dokumenty, CSV a archivy `.gz` se objeví přímo ve vaší složce v Androidu.","f2_badge":"fs.readFileSync &#183; fs/promises &#183; Trvalé I/O složek","f3_title":"Bezproblémová souhra ES Modules (.mjs) a CommonJS (.cjs)","f3_desc":"Pište moderní ES Moduly s `import` / `export` a top-level `await`, udržujte CommonJS nástroje s `require()` a `module.exports` a importujte konfigurační soubory `.json` nativně napříč vnořenými adresáři.","f3_badge":"import / export &#183; require() &#183; .mjs / .cjs / .json","f4_title":"Podpora package.json exports, podcest a #imports","f4_desc":"Strukturujte čisté vícesouborové balíčky přes `package.json`: SuperCode vyhodnocuje `\\\"type\\\": \\\"module\\\"`, `\\\"main\\\"`, podmíněné mapy `\\\"exports\\\"` i interní `#internal/*` subpath importy &#8212; dokonce i napříč neuloženými kartami editoru.","f4_badge":"package.json &#183; Podmíněné exports &#183; Importy #subpath","f5_title":"Binární Buffery, EventEmitter, Streamy a Zlib","f5_desc":"Zpracovávejte na mobilu efektivně binární protokoly i velké textové proudy pomocí `Buffer.alloc`/`concat` (UTF-8, hex, base64, base64url), `EventEmitter`, `Readable`/`Writable`/`Transform` `pipeline()` a `zlib.gzipSync`/`gunzipSync`.","f5_badge":"Buffer &#183; EventEmitter &#183; stream.pipeline &#183; gzipSync","f6_title":"Automatický cloudový Node.js fallback pro sockety a workery","f6_desc":"Když skript potřebuje systémové TCP/HTTP listenery nebo víceprocesové spouštění (`node:http`, `https`, `net`, `tls`, `dns`, `dgram`, `child_process`, `worker_threads`), SuperCode váš lokální strom modulů automaticky zabalí a odešle do Cloud Node.js.","f6_badge":"http &#183; net &#183; worker_threads &#183; Trasování řádků 1:1","workflow_title":"Jak na Androidu tvořit vícesouborové Node.js skripty","workflow_lead":"Spouštějte reálné skripty pro soubory, streamy a CLI bez instalace gigabajtů terminálových balíčků.","wf1_title":"Vytvořte v projektu soubory .js, .mjs nebo .cjs","wf1_desc":"Začněte samostatným skriptem nebo přidejte `package.json` s `\\\"type\\\": \\\"module\\\"` pro syntaxi ES Modulů v souborech `.js`.","wf2_title":"Importujte libovolné z 29+ offline Node Core API","wf2_desc":"Čtěte lokální `.json`/`.csv` soubory, pracujte s cestami přes `node:path`, transformujte streamy nebo komprimujte výstupy přes `node:zlib`.","wf3_title":"Spusťte offline a komunikujte přes node:readline","wf3_desc":"Skript běží během milisekund v izolované konzoli workera s živým interaktivním stdin, `process.env` a zpětnou vazbou testů `assert`.","wf4_title":"Prohlédněte zapsané soubory a commitněte přes Visual Git","wf4_desc":"Otevřete vygenerované soubory přímo v editoru SuperCode nebo nahrajte svůj modulární JS balíček na GitHub pomocí Visual Git.","wf_foot_note":"29+ offline modulů Node Core &#183; Overlay neuložených karet &#183; Auto-přepnutí do Cloud Node.js","table_h2":"SuperCode Offline Node Core vs. webové JS boxy a terminály","snippet_p":"<strong>SuperCode Offline Node.js Core Studio</strong> spouští přes 29 standardních modulů Node.js přímo na Androidu bez internetu a složitého nastavování terminálu. Vývojáři mohou importovat node:fs, fs/promises, path, buffer, events, stream, zlib, crypto a util v ES Modulech i CommonJS včetně vyhodnocování package.json exports a reálné synchronizace složek v Androidu.","table_caption":"SROVNÁNÍ NODE.JS A MODULÁRNÍHO JAVASCRIPTU NA ANDROIDU","th_0":"Funkce Node / modulů","th_1":"SuperCode JS &amp; Node Studio","th_2":"WebView JS aplikace","th_3":"Online Node sandboxy","th_4":"Ruční CLI terminál","tr1_c0":"Offline základní moduly","tr1_c1":"29+ vestavěných (fs, path, buffer, stream, zlib, crypto)","tr1_c2":"Jen API prohlížeče (bez fs/path)","tr1_c3":"0 % offline (jen s internetem)","tr1_c4":"Ruční pkg install nodejs","tr2_c0":"Systémy modulů","tr2_c1":"ESM (import) i CommonJS (require) + JSON","tr2_c2":"Jediný tag `&lt;script&gt;`","tr2_c3":"Podporováno online","tr2_c4":"Podporováno","tr3_c0":"Směrování package.json","tr3_c1":"Respektuje type:module, exports &amp; #imports","tr3_c2":"Ignorováno","tr3_c3":"Dočasný kontejner","tr3_c4":"Podporováno","tr4_c0":"Reálné souborové I/O projektu","tr4_c1":"Přímá sync čtení/zápisu složek Androidu","tr4_c2":"Blokováno WebView","tr4_c3":"Po zavření karty zmizí","tr4_c4":"Navigace cestami v CLI","tr5_c0":"Ergonomie psaní na dotyk. displeji","tr5_c1":"AST doplňování + Prettier formát + Visual Git","tr5_c2":"Základní textarea","tr5_c3":"Stísněný mobilní prohlížeč","tr5_c4":"Bez GUI editoru a řešení konfliktů","faq_lead":"Dotazy k podporovaným modulům `node:*`, cestám `fs`, `package.json` a npm balíčkům na Androidu.","faq1_q":"Které základní moduly Node.js fungují v SuperCode 100% offline?","faq1_a":"Přes 29 standardních modulů běží zcela offline, včetně `fs`, `fs/promises`, `path`, `path/posix`, `buffer`, `events`, `stream`, `stream/promises`, `stream/web`, `zlib`, `crypto`, `readline`, `util`, `assert`, `url`, `querystring`, `string_decoder`, `timers`, `timers/promises`, `perf_hooks`, `os`, `process` a `console`.","faq2_q":"Uloží `fs.writeFileSync('out.json', data)` reálný soubor do mé složky v Androidu?","faq2_a":"Ano! Operace se souborovým systémem čtou přímo z otevřené složky projektu (včetně neuložených karet editoru) a každý vytvořený či upravený soubor synchronizují přímo zpět do vašeho adresáře v Androidu.","faq3_q":"Mohu používat jak prefixy `node:fs`, tak klasické `require('fs')`?","faq3_a":"Ano. Moderní syntaxe ES Modulů `import fs from 'node:fs/promises'` i klasické volání CommonJS `const fs = require('fs')` se mapují na úplně stejné vestavěné offline implementace.","faq4_q":"Co se stane, když můj skript importuje `node:http`, `net` nebo `worker_threads`?","faq4_a":"Moduly vyžadující systémové serverové sockety či podprocesy (`http`, `https`, `net`, `tls`, `dns`, `child_process`, `worker_threads`) jsou automaticky rozpoznány a spuštěny přes vícesouborový bundler Cloud Node.js v SuperCode &#8212; a lokální full-stack HTTP náhledy jsou k dispozici také ve Web IDE aplikace SuperCode.","cta_h2":"Skriptujte s reálnými moduly Node.js kdekoli offline.","cta_desc":"Stáhněte si SuperCode IDE zdarma na Google Play &#8212; 29+ offline Node API, duální ESM/CommonJS a reálná sync složek přes fs."},"js_es2024_async":{"metaTitle":"ES2024 JavaScript runner pro Android — Offline top-level await, Fetch & konzole | SuperCode","metaDesc":"Spouštějte moderní ES2024 JavaScript offline na Androidu bez HTML balastu. Podporuje top-level await, asynchronní generátory, BigInt, structuredClone, Fetch, console.table() a ochranu před nekonečnou smyčkou pod 1 ms.","hero_tag":"OFFLINE ES2024 &#183; TOP-LEVEL AWAIT &#183; CONSOLE.TABLE &#183; OCHRANA &lt;1 MS","hero_h1":"Offline <span class=\"text-gradient\">ES2024 JavaScript, top-level <code>await</code> &amp; asynchronní konzole</span> na Androidu.","hero_desc":"Zahoďte zastaralé mobilní ES5 aplikace a zbytečné HTML obaly. SuperCode spouští samostatný <strong>ES2024 JavaScript</strong> v izolovaném workeru na pozadí &#8212; s podporou <strong>top-level <code>await</code></strong>, <strong><code>for await...of</code></strong>, <strong><code>BigInt</code></strong>, <strong><code>structuredClone</code></strong>, <strong><code>console.table()</code></strong> a <strong>ukončením nekonečné smyčky do &lt;1 ms</strong>.","jse_s1":"Top-level await","jse_s2":"Ochrana smyček","jse_s3":"Čistá JS konzole","jse_s4":"Doběh event loopu","wb_eyebrow":"SAMOSTATNÉ PROSTŘEDÍ PRO ASYNCHRONNÍ ES2024 &amp; IZOLACI WORKERU","sec_cap_title":"Navrženo nad rámec zastaralého ES5 Rhino a WebView na hlavním vlákně","sec_cap_lead":"Testujte moderní asynchronní orchestraci, neměnné klonování stavu a síťové fetch pipeline s okamžitou odezvou a dokonale plynulým UI.","f1_title":"Spouštějte čisté skripty .js a .mjs bez HTML balastu","f1_desc":"Chcete otestovat asynchronní retry pomocníka, regex parser nebo stavový reducer? Vytvořte jediný soubor `.js` či `.mjs` a klepněte na Spustit &#9654; &#8212; bez tagů `&lt;script&gt;`, prázdných HTML stránek nebo titěrných mobilních DevTools.","f1_badge":"Přímý běh .js / .mjs &#183; Připnutá dělená konzole","f2_title":"Moderní syntaxe ES2024, která poráží staré ES5 aplikace","f2_desc":"Mnoho JS aplikací na Play Store používá dekádu staré enginy, které nezvládnou `const`, arrow funkce ani `async`. SuperCode spouští offline top-level `await`, asynchronní generátory (`async function*`), privátní `#fields`, `BigInt`, `WeakRef`, `structuredClone`, `Object.groupBy` i `Array.at()`.","f2_badge":"Top-level await &#183; Privátní #Fields &#183; BigInt &#183; WeakRef","f3_title":"Inteligentní doběh event loopu a mikroúkolů","f3_desc":"Asynchronní kód se nikdy předčasně neukončí dříve, než se vyhodnotí vaše Promises: worker sleduje aktivní `setTimeout`, `setInterval`, `queueMicrotask` i `timers/promises` a nechá event loop čistě doběhnout.","f3_badge":"Promise.allSettled &#183; timers/promises &#183; Čistý doběh","f4_title":"Izolované vlákno workera a zastavení nekonečné smyčky pod 1 ms","f4_desc":"Běh JavaScriptu na hlavním UI vlákně v běžných editorech při chybném `while (true) {}` zamrzne celou aplikaci. SuperCode izoluje běh do samostatného workera na pozadí, takže klepnutí na Zastavit &#9632; (nebo 15s watchdog) smyčku ukončí pod 1 ms.","f4_badge":"Worker mimo UI &#183; Zastavení &lt;1 ms &#183; Bez sekání editoru","f5_title":"Standardní Fetch API, AbortController a Web Streams","f5_desc":"Prototypujte živé API klienty pomocí standardních `fetch()`, `Headers`, `Request`, `Response`, `AbortController` / `AbortSignal.timeout()`, `URL`, `URLSearchParams`, `TextEncoder`/`TextDecoder` a `ReadableStream`.","f5_badge":"fetch() &#183; AbortController &#183; URL &#183; ReadableStream","f6_title":"ASCII console.table(), přesné časovače a chyby 1:1","f6_desc":"Zobrazujte pole objektů přehledně v tabulce `console.table()`, profilujte horké funkce pomocí `console.time()` a submilisekundového `performance.now()` a trasujte výjimky na přesné řádky kódu.","f6_badge":"console.table() &#183; performance.now() &#183; Stack trace 1:1","workflow_title":"Jak v SuperCode prototypovat asynchronní ES2024 skripty","workflow_lead":"Od rychlých jednořádkových testů po asynchronní generátorové pipeline v nerušivém děleném zobrazení.","wf1_title":"Otevřete libovolný samostatný soubor JavaScriptu","wf1_desc":"Pište ES2024 kód přímo s 21klávesovou JS/TS lištou symbolů (`=&gt;`, `?.`, `??`, `` ` ``, `${}`) a offline AST doplňováním.","wf2_title":"Použijte top-level await, časovače nebo Fetch","wf2_desc":"Řetězte Promises, iterátory `for await...of`, `structuredClone` nebo požadavky `fetch()` s časovými limity `AbortController`.","wf3_title":"Spouštějte v izolaci workera bez zamrznutí","wf3_desc":"Sledujte živý výstup konzole ve spodním nebo 55:45 horizontálním panelu &#8212; a jakoukoli zacyklenou smyčku ukončete pod `&lt;1 ms`.","wf4_title":"Měřte rychlost a formátujte kód jedním klepnutím","wf4_desc":"Porovnávejte milisekundovou telemetrii mezi běhy a uhlaďte vnořené asynchronní callbacky vestavěným JS formátovačem.","wf_foot_note":"Vyhrazený worker na pozadí &#183; 15s CPU watchdog &#183; Plná kompatibilita ES6&#8211;ES2024","table_h2":"SuperCode ES2024 Worker vs. zastaralé mobilní JS aplikace","snippet_p":"<strong>SuperCode ES2024 JavaScript Runner</strong> spouští samostatný moderní JavaScript na Androidu uvnitř izolovaného workera na pozadí bez HTML balastu. Na rozdíl od zastaralých mobilních ES5 aplikací podporuje top-level await, asynchronní generátory, Promise.allSettled, BigInt, structuredClone, Fetch s AbortController, console.table(), automatický doběh event loopu i ukončení nekonečné smyčky pod milisekundu.","table_caption":"SROVNÁNÍ SAMOSTATNÉHO JAVASCRIPT RUNTIME NA ANDROIDU","th_0":"Parametr runtime","th_1":"SuperCode ES2024 Worker","th_2":"Staré ES5 mobilní JS aplikace","th_3":"HTML WebView zápisníky","th_4":"Online REPL sandboxy","tr1_c0":"Standard ECMAScript","tr1_c1":"Moderní ES2024 + top-level await offline","tr1_c2":"Zastaralé ES5 / částečné ES6","tr1_c3":"Svázáno s cyklem HTML stránky","tr1_c4":"Moderní (pouze online)","tr2_c0":"Ochrana před nekonečnou smyčkou","tr2_c1":"Izolovaný worker (ukončení &lt;1 ms bez záseku)","tr2_c2":"Zamrzne nebo shodí celou aplikaci","tr2_c3":"Zablokuje UI vlákno WebView","tr2_c4":"Zamrznutí karty prohlížeče","tr3_c0":"Async a event loop","tr3_c1":"Automatický doběh Promises, mikroúkolů i timerů","tr3_c2":"Bez nativního async/await","tr3_c3":"Ruční inspekce v DevTools","tr3_c4":"Podporováno","tr4_c0":"Diagnostika konzole","tr4_c1":"ASCII console.table(), časovače a řádky 1:1","tr4_c2":"Jen prostý textový výpis","tr4_c3":"Skryté `[object Object]`","tr4_c4":"Zpožděno sítí","tr5_c0":"Nutný balast kódu","tr5_c1":"0 řádků (přímý běh .js / .mjs)","tr5_c2":"0 řádků","tr5_c3":"Vyžaduje obal index.html","tr5_c4":"Nutné přihlášení k účtu","faq_lead":"Časté dotazy k syntaxi ES2024, top-level `await`, `fetch()` a ochraně před nekonečnými smyčkami.","faq1_q":"Mohu v SuperCode spouštět soubory JavaScriptu přímo bez vytváření HTML souboru?","faq1_a":"Ano! SuperCode má vyhrazený samostatný konzolový engine pro JavaScript oddělený od HTML5 Web IDE. Stačí otevřít libovolný soubor `.js`, `.mjs` nebo `.cjs` a klepnout na Spustit &#9654;.","faq2_q":"Jak mohu použít top-level `await`, aniž bych kód balil do `async function main()`?","faq2_a":"Uložte soubor jako `.mjs` (nebo v `package.json` nastavte `\\\"type\\\": \\\"module\\\"`, případně napište top-level `await` přímo ve skriptu ES Modulu) &#8212; SuperCode vyhodnotí top-level `await` nativně a počká na dokončení všech Promises.","faq3_q":"Co se stane, když na telefonu omylem napíšu nekonečnou smyčku `while (true)`?","faq3_a":"Váš editor i neuložené soubory zůstanou 100% plynulé, protože skripty běží v izolovaném vlákně workera na pozadí. Klepněte na Zastavit &#9632; (nebo nechte zasáhnout 15sekundový CPU watchdog) a worker se ukončí pod 1 milisekundu.","faq4_q":"Funguje uvnitř samostatných JavaScriptových skriptů `fetch()`?","faq4_a":"Ano. Standardní `fetch()`, `Headers`, `Request`, `Response` a `AbortController` jsou zabudovány přímo v runtime workera pro testování živých HTTPS API, kdykoli má zařízení připojení.","cta_h2":"Spouštějte moderní ES2024 JavaScript bez HTML přítěže.","cta_desc":"Získejte SuperCode IDE zdarma na Google Play &#8212; izolovaný ES2024 worker, top-level await, console.table() a ochrana smyček &lt;1 ms."},"js_crypto_sec":{"metaTitle":"JavaScript Web Crypto a node:crypto na Androidu — Offline AES-GCM, SHA-512 a HMAC | SuperCode","metaDesc":"Prototypujte a auditujte kryptografii offline v JavaScriptu na Androidu. Využijte W3C crypto.subtle a node:crypto pro šifrování AES-256-GCM, hashování SHA-256/512, constant-time JWT HMAC, PBKDF2 a UUID.","hero_tag":"OFFLINE CRYPTO.SUBTLE + NODE:CRYPTO &#183; AES-256-GCM &#183; SHA-512","hero_h1":"Izolovaný <span class=\"text-gradient\">JavaScript Web Crypto &amp; <code>node:crypto</code></span> sandbox na Androidu.","hero_desc":"Nikdy nevkládejte ostré JWT tokeny, podpisové klíče webhooků ani šifrovací testovací vektory do nedůvěryhodných webových nástrojů. SuperCode spouští <strong>W3C <code>crypto.subtle</code></strong> i <strong><code>node:crypto</code> 100% offline</strong> &#8212; s podporou <strong>AES-256-GCM</strong>, <strong>SHA-256/512</strong>, <strong>PBKDF2</strong> a <strong><code>timingSafeEqual</code></strong>.","jsc_s1":"GCM &#183; CBC &#183; CTR","jsc_s2":"Hash a HMAC","jsc_s3":"Odvozování klíčů","jsc_s4":"Subtle + node:crypto","wb_eyebrow":"OFFLINE PRACOVNÍ PROSTŘEDÍ NODE:CRYPTO &amp; W3C SUBTLECRYPTO","sec_cap_title":"Produkční kryptografická primitiva přímo v telefonu","sec_cap_lead":"Pište přenositelné bezpečnostní utility napříč standardy prohlížeče/edge (`crypto.subtle`) a konvencemi backendu Node.js (`node:crypto`) s nulovým připojením k internetu.","f1_title":"Vestavěné W3C crypto.subtle i Node.js node:crypto","f1_desc":"Pište bezpečnostní moduly napříč běhovými prostředími pomocí `globalThis.crypto.subtle` (`crypto.webcrypto`) i klasických backendových volání Node (`import crypto from 'node:crypto'`) &#8212; bez polyfillů či instalace externích npm balíčků.","f1_badge":"crypto.subtle &#183; crypto.webcrypto &#183; node:crypto","f2_title":"Autentizované šifrování AES-128/192/256 (GCM, CBC, CTR)","f2_desc":"Šifrujte a dešifrujte data offline pomocí `createCipheriv` / `createDecipheriv` nebo `crypto.subtle.encrypt` / `decrypt`. Plná podpora `getAuthTag()` a `setAuthTag()` umožňuje přesné ověření integrity AEAD šifrového textu.","f2_badge":"aes-256-gcm &#183; aes-256-cbc &#183; aes-256-ctr &#183; AuthTag","f3_title":"Hashe SHA-256/512, HMAC webhooky a timingSafeEqual","f3_desc":"Ověřujte HMAC-SHA256 hlavičky webhooků ve stylu GitHub/Stripe, sestavujte HS256/HS512 JWT verifikátory bez závislostí s `base64url` Buffery a předcházejte časovým postranním útokům pomocí `crypto.timingSafeEqual(a, b)`.","f3_badge":"createHash &#183; createHmac &#183; base64url &#183; timingSafeEqual","f4_title":"Odvozování klíčů PBKDF2 a CSPRNG náhodnost","f4_desc":"Odvozujte silné 256bitové klíče z přístupových frází pomocí `pbkdf2`, `pbkdf2Sync` nebo `subtle.deriveBits` a generujte kryptograficky bezpečné soli, IV nonce a UUID v4 přes `randomBytes()`, `getRandomValues()` a `randomUUID()`.","f4_badge":"pbkdf2Sync &#183; randomBytes &#183; getRandomValues &#183; randomUUID","f5_title":"100% izolovaný audit citlivých tokenů a dat","f5_desc":"Kontrolujete při incidentu bearer tokeny, OAuth PKCE `S256` code challenge nebo šifrované konfigurace? Zapněte režim Letadlo a auditujte vše lokálně na Androidu bez úniku telemetrie.","f5_badge":"Nulový síťový únik &#183; PKCE S256 &#183; Audit JWT","f6_title":"Kontrolní součty souborů a šifrované zálohy s node:fs","f6_desc":"Kombinujte `node:crypto` přímo s `node:fs` a `node:zlib`, generujte SHA-256 manifesty integrity napříč složkami projektu nebo šifrujte lokální JSON/SQLite snapshoty před nahráním přes SFTP.","f6_badge":"SHA-256 součty souborů &#183; Skripty šifrovaného trezoru","workflow_title":"Jak prototypovat a ověřovat kryptografii offline v SuperCode","workflow_lead":"Ověřujte hashe, HMAC podpisy a AES-GCM payloady lokálně ve čtyřech přehledných krocích.","wf1_title":"Zvolte node:crypto nebo standardní globalThis.crypto.subtle","wf1_desc":"Otevřete soubor `.mjs` nebo `.js` &#8212; ihned jsou k dispozici synchronní i proudová kryptografická API Node i Web Crypto postavené na Promises.","wf2_title":"Vygenerujte CSPRNG nonce a odvoďte klíče","wf2_desc":"Vytvořte kryptografická IV, soli či UUID a převeďte přístupové fráze na 32bajtové klíče AES-256 offline.","wf3_title":"Spusťte šifrování, podepisování nebo constant-time ověření","wf3_desc":"Klepněte na Spustit &#9654; a během milisekund zkontrolujte výstupy v hex/base64url, autentizační tagy i výsledky ověření `timingSafeEqual`.","wf4_title":"Uložte kontrolní součty nebo šifrované artefakty do složky","wf4_desc":"Ukládejte soubory `.sha256` nebo šifrovaná data přímo do pracovního prostoru pro verzování přes Git nebo přenos přes SFTP.","wf_foot_note":"100% lokální kryptografický běh na zařízení &#183; Nulové externí npm závislosti","table_h2":"SuperCode Offline JS Crypto vs. online debuggery tokenů a hashů","snippet_p":"<strong>SuperCode JavaScript Crypto Sandbox</strong> poskytuje W3C Web Crypto (crypto.subtle) i Node.js node:crypto offline na Androidu. Bezpečnostní inženýři a backendoví vývojáři mohou testovat autentizované šifrování AES-256-GCM, hashování souborů SHA-256 a SHA-512, constant-time HMAC ověřování JWT, odvozování klíčů PBKDF2 i generování kryptografických UUID zcela izolovaně na zařízení.","table_caption":"SROVNÁNÍ MOBILNÍCH JAVASCRIPT KRYPTOGRAFICKÝCH A BEZPEČNOSTNÍCH SANDBOXŮ","th_0":"Bezpečnostní funkce","th_1":"SuperCode JS Crypto Studio","th_2":"Online JWT / Hash weby","th_3":"Základní WebView JS aplikace","th_4":"Desktopové Node CLI","tr1_c0":"Soukromí tajných klíčů","tr1_c1":"100% offline izolovaně v telefonu","tr1_c2":"Riziko úniku přes prohlížeč/síť","tr1_c3":"Nezabezpečený HTTP WebView původ","tr1_c4":"100% lokální","tr2_c0":"Node Crypto API","tr2_c1":"Vestavěné node:crypto (Cipheriv, HMAC, PBKDF2)","tr2_c2":"Nelze programovat","tr2_c3":"Chybí (`require` selhává)","tr2_c4":"Vestavěné","tr3_c0":"W3C Web Crypto","tr3_c1":"Plné crypto.subtle + randomUUID offline","tr3_c2":"Závislé na prohlížeči","tr3_c3":"Na file:// často vypnuté","tr3_c4":"Vestavěné (Node 19+)","tr4_c0":"Binární kódování","tr4_c1":"Plný Buffer (hex, base64, base64url, utf8)","tr4_c2":"Ruční převod kopírováním","tr4_c3":"Pouze neohrabané `atob`/`btoa`","tr4_c4":"Plný Buffer","tr5_c0":"Hashování souborů projektu","tr5_c1":"Hashujte a šifrujte reálné soubory ve složkách","tr5_c2":"Nahrání souboru třetí straně","tr5_c3":"Bez přístupu k lokálním souborům","tr5_c4":"Plná podpora","faq_lead":"Odpovědi k offline Web Crypto, šifrám `node:crypto`, ověřování JWT a bezpečnosti tajných klíčů.","faq1_q":"Proč `crypto.subtle` funguje v SuperCode offline, když v běžných WebView aplikacích na Androidu často selhává?","faq1_a":"Prohlížeče omezují `window.crypto.subtle` na nezabezpečených stránkách `file://`. Samostatný JavaScript worker v SuperCode vystavuje `globalThis.crypto.subtle` (`crypto.webcrypto`) i `node:crypto` nativně offline bez omezení secure-contextu.","faq2_q":"Které režimy šifry AES a hashovací algoritmy jsou podporovány offline?","faq2_a":"Můžete spouštět `aes-128`, `aes-192` a `aes-256` v režimech `GCM` (s 16bajtovými autentizačními tagy), `CBC` a `CTR`, spolu s hashi a HMAC pro `SHA-1`, `SHA-256`, `SHA-384`, `SHA-512` a `MD5`.","faq3_q":"Funguje `Buffer.toString('base64url')` pro tvorbu a ověřování JWT?","faq3_a":"Ano! Implementace `Buffer` v SuperCode podporuje kódování i dekódování `utf8`, `hex`, `base64` a RFC 4648 `base64url` ihned po instalaci &#8212; psaní JWT a OAuth PKCE `S256` skriptů bez závislostí je tak hračka.","faq4_q":"Odesílají se při běhu `node:crypto` po síti jakékoli klíče nebo data?","faq4_a":"Nikdy. Veškeré operace `node:crypto` a `crypto.subtle` běží 100% lokálně na vašem Android zařízení a fungují i se zcela vypnutou Wi-Fi a mobilními daty.","cta_h2":"Testujte a auditujte JavaScript kryptografii 100% offline.","cta_desc":"Stáhněte si SuperCode IDE zdarma na Google Play &#8212; duální Web Crypto a node:crypto, AES-256-GCM a izolovaná bezpečnost."},"js_learn_dsa":{"metaTitle":"Naučte se JavaScript a procvičujte DSA offline na Androidu — Zdarma | SuperCode","metaDesc":"Bezplatná offline aplikace pro JavaScript na Androidu pro začátečníky i přípravu na pohovory LeetCode. Obsahuje 6 JS šablon, 21klávesovou lištu symbolů pro šipkové funkce, AST doplňování, formátovač JSON a živý vstup prompt().","hero_tag":"BEZ PŘIHLÁŠENÍ &#183; 6 JS ŠABLON &#183; LIŠTA =&gt; &#183; FORMÁTOVAČ JSON","hero_h1":"Naučte se <span class=\"text-gradient\">JavaScript a procvičujte LeetCode DSA</span> offline na Androidu.","hero_desc":"Ovládněte reálný ES6&#8211;ES2024 JavaScript kdekoli bez předplatného kvízů či nutnosti Wi-Fi. Otevřete <strong>6 spustitelných JS šablon</strong>, pište šipkové funkce snadno s <strong>21klávesovou lištou <code>=&gt;</code> / <code>${}</code></strong>, formátujte nepřehledný <strong>JS a JSON</strong> jedním klepnutím a trénujte algoritmy v režimu Letadlo.","jsl_s1":"Offline JS zdarma","jsl_s2":"Startovací šablony","jsl_s3":"Lišta =&gt; a ${}","jsl_s4":"Formátovač JS/JSON","wb_eyebrow":"PROSTŘEDÍ PRO ES6+, LEETCODE DSA A FORMÁTOVAČ JSON","sec_cap_title":"Navrženo pro rychlé psaní palcem a řešení úloh na mobilu","sec_cap_lead":"Ať už píšete svůj první cyklus `for`, nebo před frontendovým pohovorem drtíte grafy a dynamické programování, SuperCode vám neklade překážky.","f1_title":"Bez přihlašování a 100% běh v režimu Letadlo","f1_desc":"Spusťte SuperCode a rozjeďte JavaScript během sekund &#8212; bez nucené registrace e-mailem, bez herních životů a bez internetu v metru, autobuse či letadle.","f1_badge":"Okamžitý start &#183; Bez účtu &#183; 100% Offline","f2_title":"6 vestavěných spustitelných JavaScript šablon","f2_desc":"Prozkoumejte základy jazyka v praxi s vestavěnými šablonami včetně `arrays.js` (`map`/`filter`/`reduce`), `destructuring.js`, `async.js` (`Promise`/`await`), algoritmů `primes.js`, uzávěrů (closures) a tříd ES6.","f2_badge":"arrays.js &#183; async.js &#183; destructuring.js &#183; primes.js","f3_title":"21klávesová lišta JS/TS s tahem nahoru (`=&gt;`, `?.`, `${}`)","f3_desc":"Mobilní klávesnice schovávají zpětné apostrofy a složené závorky do tří vrstev. Speciální lišta JS/TS v SuperCode dává `=&gt;`, `?.`, `===`, `` ` ``, `${}`, `{}`, `[]`, `()` a `;` přímo nad palce s tahem nahoru pro sekundární znaky.","f3_badge":"=&gt; &#183; ?. &#183; === &#183; ` &#183; ${} &#183; Automatické párování závorek","f4_title":"Offline AST doplňování a živý radar syntaktických chyb","f4_desc":"Objevujte při psaní offline standardní metody `Array`, `Map`, `Set`, `String`, `Object`, `Promise` a `JSON`. Radar chyb zvýrazní nespárované závorky či neukončené šablonové řetězce dřív, než klepnete na Spustit.","f4_badge":"Offline AST nápověda &#183; Živý radar závorek a syntaxe","f5_title":"Formátovač JS, TypeScriptu a JSON na 1 klepnutí ve stylu Prettier","f5_desc":"Pracujete s jednořádkovým API JSONem nebo hluboce zanořeným řešením z pohovoru? Klepněte na Formátovat a srovnejte `.js`, `.mjs`, `.ts` i `.json` atomicky v jednom kroku Zpět.","f5_badge":"Formátovač JS / TS / JSON &#183; Přísný validátor JSON","f6_title":"Živý vstup prompt() / readline a cesta k plnému Web IDE","f6_desc":"Přijímejte interaktivní vstupy pro CLI hry a cvičení přes `prompt()` nebo `node:readline` &#8212; a až budete připraveni na práci s DOM, otevřete projekty `.html`/`.css`/`.js` v živém Web IDE v SuperCode.","f6_badge":"Interaktivní Stdin &#183; Přechod na HTML5/CSS3/DOM a Git","workflow_title":"Jak se učit JavaScript a trénovat DSA úlohy na Androidu","workflow_lead":"Rychlá smyčka úpravy, spuštění a benchmarku navržená přímo pro telefony, skládačky a tablety.","wf1_title":"Načtěte vestavěnou JS šablonu nebo vytvořte solution.js","wf1_desc":"Vyberte z Příkladu kódu `arrays.js`, `destructuring.js` nebo `async.js`, případně začněte nový soubor pro procvičování LeetCode.","wf2_title":"Pište čistý ES2024 kód rychlostí desktopu","wf2_desc":"Vkládejte `=&gt;`, `` `${}` `` a `===` jedním klepnutím, zatímco AST doplňování navrhuje metody `Map`, `Set` a `Array`.","wf3_title":"Testujte a měřte výkon pomocí console.table / time","wf3_desc":"Spouštějte kód offline v milisekundách, zkoumejte okrajové případy přes `console.table()` a zastavte nechtěnou nekonečnou smyčku za `&lt;1 ms`.","wf4_title":"Naformátujte JSON/JS, exportujte PDF nebo nahrajte na GitHub","wf4_desc":"Upravte vzhled kódu jedním klepnutím, exportujte studijní poznámky do A4 PDF nebo sestavte plné HTML/CSS/JS portfolio s vizuálním Gitem.","wf_foot_note":"8 optických tmavých a světlých motivů &#183; Rozdělená konzole 55:45 na šířku tabletu","table_h2":"SuperCode JS Coding App vs. kartičkové aplikace a editory v prohlížeči","snippet_p":"<strong>SuperCode</strong> je bezplatná offline aplikace pro programování v JavaScriptu na Androidu pro začátečníky, studenty bootcampů i přípravu na algoritmické pohovory LeetCode. Bez nutnosti přihlášení spojuje 6 spustitelných JS šablon, 21klávesovou lištu symbolů, offline AST doplňování, formátování JS a JSON jedním klepnutím a interaktivní konzolový vstup.","table_caption":"VÝUKA JAVASCRIPTU A PROCVIČOVÁNÍ ALGORITMŮ NA ANDROIDU","th_0":"Funkce pro učení","th_1":"SuperCode JS Coding App","th_2":"Kvízové aplikace s předplatným","th_3":"Editory v mobilním prohlížeči","th_4":"Prohlížeče JSON","tr1_c0":"Praktické programování","tr1_c1":"Plné offline ES2024 + 29 základních Node API","tr1_c2":"Výběr slov z možností","tr1_c3":"Sekající se karta prohlížeče","tr1_c4":"Stromové zobrazení jen pro čtení","tr2_c0":"Studium offline na cestách","tr2_c1":"100% offline bez registrace","tr2_c2":"Zamčeno za přihlášením/platbou","tr2_c3":"Vyžaduje stálé Wi-Fi","tr2_c4":"Offline","tr3_c0":"Psaní symbolů na mobilu","tr3_c1":"Speciální 21klávesová lišta =&gt; / ?. / `${}`","tr3_c2":"Minimální psaní kódu","tr3_c3":"Přepínání kláves na 3 klepnutí","tr3_c4":"Bez lišty pro kód","tr4_c0":"Formátování kódu a JSON","tr4_c1":"Formátovač JS / TS / JSON na 1 klepnutí + radar","tr4_c2":"Žádné","tr4_c3":"Těžký webový balík","tr4_c4":"Pouze JSON (bez spouštění JS)","tr5_c0":"Další růst v ekosystému","tr5_c1":"Zahrnuje HTML/CSS/PHP Web IDE, SQL a Git","tr5_c2":"Slepá ulička po úvodním kurzu","tr5_c3":"Žádný lokální Git ani SFTP","tr5_c4":"Jednoúčelový nástroj","faq_lead":"Časté dotazy začátečníků v JavaScriptu, studentů bootcampů a zájemců o pohovory.","faq1_q":"Je SuperCode pro začátek učení JavaScriptu offline úplně zdarma?","faq1_a":"Ano! Zdarma a bez přihlášení můžete vytvářet neomezeně souborů `.js`, `.mjs`, `.json` a `.html`, spouštět všech 6 vestavěných JS šablon, používat 21klávesovou lištu symbolů, formátovat kód a spouštět offline skripty ES2024 + Node core.","faq2_q":"Mohu SuperCode používat na Androidu jako offline formátovač a validátor JSON?","faq2_a":"Ano. Otevřete nebo vložte jakýkoli soubor `.json` (i několikaněkolikamegabajtová data), v Radaru chyb zkontrolujte přesné řádky/sloupce syntaktických chyb a klepnutím na Formátovat jej jedním krokem odsaďte či vyčistěte.","faq3_q":"Spouští SuperCode také HTML, CSS a DOM JavaScript, když chci tvořit weby?","faq3_a":"Rozhodně. Kdykoli se budete chtít posunout od konzolového JS k vizuálním webovým stránkám, vestavěné Web IDE v SuperCode zobrazí náhled vícesouborového HTML5, CSS3, DOM JavaScriptu i offline PHP + SQLite na reálném lokálním HTTP serveru.","faq4_q":"Mohu si procvičovat i syntaxi TypeScriptu?","faq4_a":"SuperCode nabízí plné zvýrazňování syntaxe TypeScriptu (`.ts` / `.tsx`), AST povědomí o symbolech, 21klávesovou lištu JS/TS a formátování jedním klepnutím, plus samostatné offline spouštění ES2024 `.js`/`.mjs`.","cta_h2":"Začněte programovat v JavaScriptu offline na Androidu ještě dnes.","cta_desc":"Stáhněte si SuperCode IDE zdarma na Google Play &#8212; bez přihlášení, 6 JS šablon, lišta =&gt; a formátování JSON/JS na 1 klepnutí."},"web_php_pdo":{"metaTitle":"Spouštějte PHP 8.2 a PDO SQLite offline na Androidu — PHP Server & IDE bez nastavování | SuperCode","metaDesc":"Spouštějte vícesouborové weby v PHP 8.2 a PDO SQLite 100% offline na Androidu. Podporuje $_GET, $_POST, trvalé $_SESSION, nahrávání $_FILES do 24 MB, password_hash() a JSON API bez KSWEB či nastavování CLI.","hero_tag":"OFFLINE PHP 8.2 &#183; PDO SQLITE &#183; $_SESSION &#183; BEZ NASTAVOVÁNÍ DAEMONŮ","hero_h1":"Spouštějte <span class=\"text-gradient\">PHP 8.2 a PDO SQLite offline</span> na Androidu bez nastavování serveru.","hero_desc":"Přestaňte bojovat s LAMP daemony na pozadí, rozbitými rozšířeními v <code>php.ini</code> nebo čistě frontendovými editory, které vypisují syrové tagy <code>&lt;?php</code>. V našem <strong>fullstackovém Web &amp; PHP IDE pro Android</strong> klepněte na Spustit u libovolného <code>.php</code> projektu a spouštějte <strong>PHP 8.2</strong>, trvalé ověřování <strong><code>$_SESSION</code></strong>, 24MB nahrávání souborů a databáze <strong><code>PDO('sqlite:app.db')</code></strong> nad reálným původem <code>localhost</code> HTTP.","php_s1":"Offline engine","php_s2":"SQLite ACID ready","php_s3":"Multipart $_FILES","php_s4":"Okamžitý DocumentRoot","wb_eyebrow":"OFFLINE PROSTŘEDÍ PHP 8.2, $_SESSION AUTH A PDO SQLITE","sec_cap_title":"Vše potřebné pro tvorbu reálných dynamických PHP backendů v telefonu","sec_cap_lead":"Od vysokoškolských webových projektů a prototypů REST API po kompletní CRUD administrace &#8212; navrženo pro práci v režimu Letadlo.","f1_title":"Moderní syntaxe PHP 8.2 a vícesouborové vkládání do 32 úrovní","f1_desc":"Navrhujte čisté backendové architektury s výrazy match v PHP 8.2, šipkovými funkcemi (fn() =&gt;), constructor property promotion, jmennými prostory a vnořenými include, require a require_once až do hloubky 32 úrovní.","f1_badge":"PHP 8.2 &#183; match &#183; fn() =&gt; &#183; Hloubka 32 require_once","f2_title":"Vestavěné PDO('sqlite:app.db') a ACID transakce","f2_desc":"Připojte PHP skripty přímo k lokálním SQLite databázím pomocí new PDO('sqlite:app.db') &#8212; včetně připravených dotazů ? a :named proti SQL injection, PDO::FETCH_ASSOC a beginTransaction() / commit() / rollBack().","f2_badge":"Bez úprav php.ini &#183; Prepared Statements &#183; ACID","f3_title":"Trvalé $_SESSION, $_COOKIE a Bcrypt autentizace","f3_desc":"Vytvářejte offline reálné přihlašování, nákupní košíky a toky chráněné proti CSRF. SuperCode uchovává stav $_SESSION a $_COOKIE napříč přesměrováními (header('Location: ...')) a obsahuje nativní password_hash() i password_verify().","f3_badge":"session_start() &#183; password_hash() &#183; HTTP přesměrování","f4_title":"$_GET, $_POST, JSON REST API a vlastní hlavičky","f4_desc":"Zpracovávejte parametry URL dotazu, urlencoded HTML formuláře i surové JSON payloady z php://input a vracejte vlastní HTTP stavové kódy i hlavičky header('Content-Type: application/json') pro frontendové fetch() klienty.","f4_badge":"$_GET / $_POST &#183; php://input &#183; JSON REST endpointy","f5_title":"Multipart nahrávání $_FILES až do 24 MB","f5_desc":"Testujte formuláře &lt;input type=\"file\"&gt; pomocí fotoaparátu nebo výběru souborů na Androidu. Ověřujte MIME metadata v $_FILES a ukládejte nahrané obrázky či dokumenty přímo do pracovního prostoru přes move_uploaded_file() až do 24 MB.","f5_badge":"multipart/form-data &#183; Fotoaparát/Úložiště &#183; Limit 24 MB","f6_title":"Bohatá jádrová rozšíření: mbstring, PCRE a JSON","f6_desc":"Zpracovávejte mezinárodní UTF-8 řetězce pomocí mb_strlen() a mb_substr(), ověřujte vstupy přes preg_match() a preg_replace(), formátujte časové značky a spouštějte vícesouborové aplikace bez vybíjení baterie daemonem na pozadí.","f6_badge":"mbstring &#183; preg_* &#183; json_encode &#183; Okamžitý start","workflow_title":"Jak spustit projekt PHP 8.2 + SQLite offline na Androidu","workflow_lead":"Bez root oprávnění, bez nastavování přesměrování portů a bez spouštění samostatného databázového daemonu.","wf1_title":"Vytvořte nebo naklonujte vícesouborový PHP projekt","wf1_desc":"Založte složku projektu se soubory index.php, includes/db.php a assets/ &#8212; SuperCode automaticky nastaví kořen projektu jako kořen lokálního webového serveru.","wf2_title":"Připojte se k lokální databázi SQLite","wf2_desc":"Inicializujte tabulky přímo z PHP PDO nebo si app.db předem připravte a vizuálně prohlédněte v integrovaném SQL Studiu v SuperCode.","wf3_title":"Testujte formuláře, sessions a Fetch API přes localhost","wf3_desc":"Klepnutím na Spustit &#9654; otevřete živý náhled prohlížeče nad reálným lokálním HTTP původem, odešlete POST/souborové formuláře a sledujte časy PHP požadavků v kartě Net.","wf4_title":"Smažte cookies na 1 klepnutí nebo publikujte přes SFTP","wf4_desc":"Kdykoli vymažte aktivní $_SESSION cookies z lišty náhledu pro nové otestování přihlášení a pak ověřené PHP soubory nasaďte přímo na svůj Linux server přes SFTP/FTPS.","wf_foot_note":"100% offline PHP 8.2 + PDO SQLite &#183; Sdílený pracovní prostor se SQL Studiem a SFTP klientem","table_h2":"SuperCode Offline PHP 8.2 Studio vs. jiné možnosti PHP na Androidu","snippet_p":"<strong>Offline PHP 8.2 &amp; PDO Server v SuperCode</strong> promění jakýkoli telefon či tablet s Androidem v lokální PHP vývojové studio bez konfigurace. Spouštějte vícesouborové PHP 8.2 skripty, trvalé toky $_SESSION, multipart nahrávání souborů, bcrypt autentizaci, JSON API a ACID dotazy PDO('sqlite:app.db') nad reálným localhost HTTP původem bez ručního nastavování daemonů.","table_caption":"SROVNÁNÍ OFFLINE PHP SERVERŮ A IDE PRO ANDROID","th_0":"PHP funkce","th_1":"SuperCode PHP 8.2 Studio","th_2":"KSWEB / LAMP daemony","th_3":"Terminálové CLI php -S","th_4":"Editory Spck / TrebEdit","tr1_c0":"Nastavení a DocumentRoot","tr1_c1":"Spuštění na 1 klepnutí pro složku bez konfigurace","tr1_c2":"Ruční vhost, porty a služba na pozadí","tr1_c3":"Ruční instalace balíčků + CLI přepínače","tr1_c4":"Nedokáže spouštět PHP (pouze frontend)","tr2_c0":"PHP 8.2 + Include soubory","tr2_c1":"match, fn(), OOP a require_once do hloubky 32","tr2_c2":"Podporováno (liší se dle placeného tarifu)","tr2_c3":"Podporováno přes ruční CLI","tr2_c4":"Vypisuje syrový text &lt;?php","tr3_c0":"Offline SQL databáze","tr3_c1":"Vestavěné PDO('sqlite:...') + SQL Studio","tr3_c2":"Těžkopádné nastavení daemonu na pozadí","tr3_c3":"Ruční propojení rozšíření a CLI","tr3_c4":"Bez backendové databáze","tr4_c0":"Formuláře, $_SESSION a soubory","tr4_c1":"Trvalé $_SESSION + 24 MB $_FILES","tr4_c2":"Podporováno v externím prohlížeči","tr4_c3":"Bez integrovaného UI DevTools","tr4_c4":"Pouze statické HTML formuláře","tr5_c0":"Editor, Git a SFTP","tr5_c1":"Jednotný AST editor + DevTools + Git + SFTP","tr5_c2":"Vyžaduje samostatný editor kódu","tr5_c3":"Pouze terminálový nano/vim","tr5_c4":"Pouze frontendový Git, bez PHP","faq_lead":"Odpovědi na časté dotazy ohledně běhu PHP 8.2, PDO SQLite, sessions a nahrávání souborů offline na Androidu.","faq1_q":"Spouští SuperCode PHP 8.2 zcela offline bez internetu?","faq1_a":"Ano. Engine PHP 8.2 i databázový ovladač PDO SQLite v SuperCode běží 100% lokálně na vašem Android zařízení &#8212; můžete tvořit a testovat vícestránkové PHP weby, přihlašovací formuláře i JSON API v režimu Letadlo.","faq2_q":"Proč zvolit SuperCode místo KSWEB nebo spouštění `php -S` v terminálové aplikaci?","faq2_a":"Samostatné serverové daemony vyžadují ruční cesty virtuálních hostitelů, drží služby na pozadí a nutí vás přepínat mezi třemi aplikacemi (editor, server, prohlížeč). SuperCode sjednocuje AST editaci PHP, automatické HTTP směrování od kořene projektu, Web DevTools, SQL Studio a SFTP publikování v jednom lehkém IDE.","faq3_q":"Může frontendový JavaScript volat moje lokální soubory `.php` pomocí `fetch()`?","faq3_a":"Ano! Protože váš pracovní prostor běží nad reálným původem `localhost` HTTP/1.1, `await fetch('/api/tasks.php', { method: 'POST', ... })` funguje hladce s JSON hlavičkami, cookies i měřením času v síťové kartě DevTools.","faq4_q":"Mohu si prohlédnout SQLite soubor `.db` vytvořený z PHP `new PDO('sqlite:app.db')`?","faq4_a":"Okamžitě. Klepněte na `app.db` v průzkumníku souborů SuperCode a prohlédněte si jeho tabulky, schéma a řádky v Unicode rámečcích nebo ve formátu Markdown uvnitř SQL Studia.","cta_h2":"Tvořte a testujte dynamické PHP 8.2 + SQL aplikace kdekoli offline.","cta_desc":"Stáhněte si SuperCode IDE zdarma na Google Play &#8212; bez nastavování daemonů, vestavěné PDO SQLite a živé Web DevTools."},"web_html_preview":{"metaTitle":"Editor HTML5, CSS3 a JS pro Android — lokální HTTP server a náhled 3 viewportů | SuperCode","metaDesc":"Navrhujte a testujte responzivní weby offline na Androidu. SuperCode spojuje AST editor HTML5/CSS3/JS a rekurzivní formátovač na 1 klepnutí se skutečným lokálním HTTP serverem, přepínačem Mobil/Tablet 768dp/Desktop a exportem do PNG.","hero_tag":"SKUTEČNÝ LOKÁLNÍ HTTP/1.1 &#183; MOBIL / TABLET 768DP / DESKTOP &#183; REKURZIVNÍ FORMÁTOVAČ","hero_h1":"Pište <span class=\"text-gradient\">HTML5, CSS3 a ES Modules</span> se živým responzivním náhledem ve 3 viewportech.","hero_desc":"Základní prohlížeče HTML pro Android otevírají soubory přes <code>file://</code> &#8212; tím rozbíjejí <code>&lt;script type=&quot;module&quot;&gt;</code>, <code>fetch()</code> i webové úložiště a omezují vás na úzkou šířku telefonu. SuperCode servíruje vaši složku přes <strong>skutečný HTTP/1.1 server <code>localhost</code></strong> s okamžitým přepínáním viewportů <strong>Mobil, Tablet (768dp) a Desktop</strong>.","html_s1":"HTTP MIME typy","html_s2":"Mobil/768dp/Desktop","html_s3":"Přetáčení médií","html_s4":"Snímek celé stránky","wb_eyebrow":"LOKÁLNÍ HTTP/1.1, RESPONZIVNÍ BREAKPOINTY A WORKBENCH PRO ES MODULES","sec_cap_title":"Proč frontendoví vývojáři přecházejí ze základních mobilních prohlížečů HTML","sec_cap_lead":"Skutečná sémantika původu (origin) prohlížeče, reálné testování více breakpointů a snadné formátování na telefonech, skládacích zařízeních i tabletech.","f1_title":"Skutečný lokální HTTP/1.1 server (65+ MIME typů)","f1_desc":"Dejte sbohem chybám CORS s „origin null“. Servírování ze skutečného původu localhost HTTP/1.1 odemyká nativní importy &lt;script type=\"module\"&gt;, fetch('./data.json'), localStorage, IndexedDB, SVG sprity i webové fonty .woff2.","f1_badge":"Skutečný localhost Origin &#183; 65+ MIME typů &#183; Bez blokování CORS","f2_title":"Přepínač 3 responzivních viewportů v Dynamic Islandu","f2_desc":"Ověřte si, jak se chová CSS Grid, Flexbox a @media queries na různých obrazovkách, aniž byste potřebovali tři zařízení. Klepnutím na přetahovatelný Dynamic Island přepínejte živě mezi rozložením Mobil, Tablet (768dp) a širokým Desktopem.","f2_badge":"Breakpointy Mobil &#183; Tablet (768dp) &#183; Desktop","f3_title":"Rekurzivní formátovač HTML + &lt;style&gt; + &lt;script&gt; na 1 klepnutí","f3_desc":"Jednosouborové prototypy zůstanou vzorně čisté: jediné klepnutí na Formátovat přehledně odsadí vnořené elementy HTML5 a současně rekurzivně naformátuje vložená pravidla CSS uvnitř &lt;style&gt; i kód JavaScript uvnitř bloků &lt;script&gt;.","f3_badge":"Jednotný formátovač HTML + CSS + JS","f4_title":"Streamování médií HTTP 206 a 3D shadery WebGL","f4_desc":"Testujte interaktivní přehrávače &lt;video&gt; a &lt;audio&gt; se skutečným přetáčením po bajtových rozsazích HTTP 206 Partial Content nebo vykreslujte Three.js, 3D modely .glb/.gltf, HTML5 Canvas a vlastní WebGL GLSL shadery při plynulé snímkové frekvenci.","f4_badge":"HTTP 206 Range Seeking &#183; WebGL GLSL &#183; .glb / .gltf","f5_title":"3 vestavěné webové šablony a AST automatické doplňování","f5_desc":"Začněte ihned se 3 připravenými vícesekčními webovými šablonami, pište tagy i vlastnosti CSS bleskově díky offline AST doplňování a 21klávesové liště symbolů a prohlížejte si propojené styly napříč složkami bez jediného zádrhelu.","f5_badge":"3 webové šablony &#183; AST HTML/CSS/JS &#183; 21klávesová lišta","f6_title":"Export makety celé stránky do PNG ve vysokém DPI","f6_desc":"Potřebujete poslat postup návrhu klientovi, lektorovi nebo do GitHub PR? Pořiďte ostrý snímek celé stránky ve formátu PNG (až 2560px) přímo z libovolného aktivního viewportu Mobil, Tablet či Desktop.","f6_badge":"PNG až 2560px &#183; Připraveno pro klienty i zadání","workflow_title":"Jak tvořit a testovat responzivní weby přímo na telefonu","workflow_lead":"Přejděte od prázdného stylopisu k ověřenému responzivnímu rozložení pro 3 breakpointy během minut.","wf1_title":"Vyberte vestavěnou webovou šablonu nebo otevřete složku","wf1_desc":"Spusťte jednu ze 3 vestavěných startovacích šablon HTML5/CSS3/JS nebo otevřete libovolný vícesložkový frontendový repozitář z lokálního úložiště či z Git.","wf2_title":"Pište čisté HTML5, CSS Grid a ES Modules","wf2_desc":"Upravujte propojené karty .html, .css a .js s offline AST návrhy a pak klepnutím na Formátovat srovnejte HTML i bloky &lt;style&gt; a &lt;script&gt; najednou.","wf3_title":"Přepínejte živě Mobil, Tablet (768dp) a Desktop","wf3_desc":"Klepněte na Spustit &#9654; a přepínejte viewporty na přetahovatelném Dynamic Islandu, abyste ověřili navigační menu, typografii i breakpointy gridu.","wf4_title":"Exportujte snímky ve vysokém rozlišení nebo pushněte na GitHub","wf4_desc":"Uložte si ostrý PNG náhled každého breakpointu do portfolia nebo odešlete hotový web přímo na GitHub Pages.","wf_foot_note":"Funguje 100% offline &#183; Podporuje ES Modules, webové fonty, Canvas, WebGL a rozsahové požadavky médií","table_h2":"SuperCode Web Studio vs. Spck, TrebEdit a základní prohlížeče HTML","snippet_p":"<strong>SuperCode HTML5, CSS3 &amp; JavaScript Studio</strong> servíruje mobilní webové projekty ze skutečného původu localhost HTTP/1.1 s více než 65 MIME typy namísto omezených cest file://. Prohlížejte si ES Modules, IndexedDB, WebGL a video streamy HTTP 206 napříč viewporty Mobil, Tablet 768dp a Desktop s rekurzivním formátováním na jedno klepnutí a snímkem celé stránky do PNG.","table_caption":"SROVNÁNÍ EDITORŮ HTML5, CSS3 A RESPONZIVNÍCH NÁHLEDŮ PRO ANDROID","th_0":"Frontendová funkce","th_1":"SuperCode Web Studio","th_2":"Spck / TrebEdit","th_3":"Základní file:// prohlížeče","th_4":"Online webová hřiště","tr1_c0":"Protokol lokálního serveru","tr1_c1":"Skutečný Localhost HTTP/1.1 (65+ MIME typů)","tr1_c2":"Omezený lokální náhled (bez PHP/206)","tr1_c3":"Nefunkční file:// CORS blokuje ESM","tr1_c4":"Pouze cloud (offline nefunguje)","tr2_c0":"Testování responzivity","tr2_c1":"Mobil / Tablet 768dp / Desktop na 1 klepnutí","tr2_c2":"Základní přepínač mobil/desktop","tr2_c3":"Pouze pevná šířka telefonu","tr2_c4":"Stísněný rozdělený iframe","tr3_c0":"Formátování kódu","tr3_c1":"Rekurzivní HTML + &lt;style&gt; + &lt;script&gt; na 1 klepnutí","tr3_c2":"Jednojazyčné nebo ruční","tr3_c3":"Bez formátovače","tr3_c4":"Vyžaduje internet","tr4_c0":"Média, WebGL a WASM","tr4_c1":"HTTP 206 přetáčení + WebGL + .wasm stream","tr4_c2":"Částečná statická aktiva","tr4_c3":"Selhává u range a module požadavků","tr4_c4":"Limity velikosti nahrání","tr5_c0":"Přechod na backend","tr5_c1":"Obsahuje offline PHP 8.2, PDO SQL a SFTP","tr5_c2":"Strop čistě na frontendu","tr5_c3":"Pouze statické HTML","tr5_c4":"Placený tarif kontejneru","faq_lead":"Časté dotazy k úpravám HTML5/CSS3/JS, ES Modules a náhledům responzivních viewportů na Androidu.","faq1_q":"Proč mi `&lt;script type=\"module\"&gt;` nebo `fetch('./data.json')` v jiných HTML editorech selhával?","faq1_a":"Prohlížeče blokují ES Modules a `fetch()` na URL `file://` kvůli přísným bezpečnostním pravidlům CORS. SuperCode automaticky servíruje váš projekt přes skutečný původ `localhost` HTTP/1.1 se správnými hlavičkami MIME, takže moderní JS moduly i načítání JSON fungují nativně offline.","faq2_q":"Jak mohu na displeji smartphonu zobrazit náhled CSS media queries pro Tablet a Desktop?","faq2_a":"V živém webovém náhledu v SuperCode klepněte na ikonu viewportu na plovoucím Dynamic Islandu a okamžitě přepněte mezi viewportem Mobil, Tablet (`768dp`) a široký Desktop &#8212; vaše pravidla `@media` se spustí přesně.","faq3_q":"Formátuje formátovač na 1 klepnutí také CSS uvnitř `&lt;style&gt;` a JS uvnitř `&lt;script&gt;`?","faq3_a":"Ano. Rekurzivní formátovač HTML v SuperCode parsuje vložené bloky `&lt;style&gt;` a `&lt;script&gt;` uvnitř souborů `.html` a přehledně odsadí všechny tři jazyky jediným klepnutím.","faq4_q":"Mohu offline používat lokální videa `.mp4`, fonty `.woff2` a 3D modely `.glb`?","faq4_a":"Ano. Lokálně je předkonfigurováno přes 65 typů MIME včetně `font/woff2`, `model/gltf-binary`, `image/svg+xml` a streamování bajtových rozsahů HTTP `206 Partial Content` pro plynulé přetáčení `&lt;video&gt;` a `&lt;audio&gt;`.","cta_h2":"Navrhujte responzivní weby v HTML5, CSS3 a JS kdekoli.","cta_desc":"Získejte SuperCode IDE zdarma na Google Play &#8212; skutečný lokální HTTP/1.1 náhled, přepínač 3 viewportů a rekurzivní formátování na 1 klepnutí."},"web_devtools_wasm":{"metaTitle":"Mobilní Web DevTools konzole, síťový log, DOM REPL a WASM na Androidu | SuperCode","metaDesc":"Ladění mobilních webových aplikací bez kabelu k počítači. SuperCode integruje roztažitelnou konzoli DevTools (All/Error/Warn/Net), monitor časování HTTP, živý asynchronní DOM JS REPL a nativní streamování WebAssembly (.wasm) na Androidu.","hero_tag":"ALL / ERROR / WARN / NET &#183; ŽIVÝ DOM REPL &#183; STREAMOVÁNÍ WEBASSEMBLY","hero_h1":"Mobilní studio <span class=\"text-gradient\">Web DevTools, síťového monitoru a WASM</span> pro Android.","hero_desc":"Mobilní prohlížeče pro Android odstraňují panel F12 DevTools přesně ve chvíli, kdy potřebujete odhalit tichou chybu <code>fetch()</code>, chybu rozložení nebo binární modul <code>.wasm</code>. SuperCode vestavuje <strong>roztažitelnou konzoli Web DevTools, časovač HTTP sítě, živý DOM JS REPL a server <code>application/wasm</code></strong> přímo do vašeho mobilního náhledu.","dev_s1":"All/Error/Warn/Net","dev_s2":"Živý async DOM JS","dev_s3":"Streamovaný kompilátor","dev_s4":"Telemetrie HTTP sítě","wb_eyebrow":"MOBILNÍ KONZOLE DEVTOOLS, ČASOVÁNÍ SÍTĚ, DOM REPL A WASM WORKBENCH","sec_cap_title":"Diagnostika prohlížeče desktopové třídy bez připojování k USB ladění","sec_cap_lead":"Sledujte každé varování konzole, zkoumejte cyklický stav JS, měřte latenci API a streamujte binární WebAssembly v telefonu.","f1_title":"Roztažitelná zásuvka DevTools a živý odznak chyb","f1_desc":"Vytáhněte rozdělovací úchyt DevTools přímo pod vykreslenou webovou stránkou. Okamžitě filtrujte logy na kartách All, Error, Warn a Net, zatímco živý odznak na plovoucím ostrově vás upozorní v okamžiku, kdy dojde k nezachycené výjimce.","f1_badge":"All / Error / Warn / Net &#183; Plynule nastavitelná výška","f2_title":"Monitor časování sítě HTTP, fetch() a PHP","f2_desc":"Přepněte na kartu Net a kontrolujte každý soubor stránky, ES modul, binární WASM i požadavek PHP API v reálném čase &#8212; přehledně ve formátu METHOD /path -&gt; status &#183; ms &#183; bytes, aby chyby 404 a pomalé přenosy vynikly na první pohled.","f2_badge":"Telemetrie METHOD /path -&gt; status &#183; ms &#183; bytes","f3_title":"Interaktivní živý DOM a asynchronní Promise JS REPL","f3_desc":"Zadejte libovolný výraz do řádku &gt; Run JavaScript... a dotazujte se či upravujte živé elementy DOM, testujte přepínání CSS tříd, kontrolujte localStorage nebo vyhodnocujte asynchronní fetch() Promises přímo nad běžící stránkou.","f3_badge":"&gt; Run JavaScript... &#183; Automatické vyhodnocení Promise","f4_title":"Bezpečný výpis DOM elementů (&lt;div#app.card&gt;) a cyklických objektů","f4_desc":"Už žádné nicneříkající [object HTMLDivElement] ani pády při cyklických odkazech v JSON. SuperCode serializuje živé uzly DOM jako čitelné deskriptory &lt;tag#id.class&gt; a bezpečně formátuje vnořené objekty, Map, Set i odkazy [Circular].","f4_badge":"Formátování &lt;div#id.class&gt; &#183; Odolné vůči cyklickým grafům","f5_title":"Nativní streamované spouštění WebAssembly (.wasm)","f5_desc":"Spouštějte zkompilované moduly .wasm z Rustu, C, C++, Zigu nebo AssemblyScriptu téměř nativní rychlostí. Náš lokální HTTP server doručuje soubory .wasm s přesnými hlavičkami application/wasm, takže WebAssembly.instantiateStreaming(fetch(...)) funguje bez kopírování.","f5_badge":"application/wasm &#183; WebAssembly.instantiateStreaming()","f6_title":"Záznam nezachycených chyb a odmítnutých Promise bez nastavování","f6_desc":"Ještě předtím, než přidáte příkazy console.log, SuperCode zachytí rané události životního cyklu stránky a zaznamená syntaktické chyby, běhové TypeError i selhání unhandledrejection Promise s přesným názvem skriptu, řádkem a sloupcem.","f6_badge":"Raný lifecycle hook &#183; Přesný stack trace Řádek:Sloupec","workflow_title":"Jak ladit JS, síťová volání a WebAssembly na Androidu","workflow_lead":"Bez bookmarkletových triků, bez kabelu ke vzdálenému desktopu a bez ručního vkládání script tagů.","wf1_title":"Spusťte svůj webový nebo WASM projekt přes lokální HTTP","wf1_desc":"Otevřete vstupní soubor .html, .js nebo .php a klepněte na Spustit &#9654; &#8212; hooky DevTools i síťová telemetrie se připojí automaticky.","wf2_title":"Otevřete roztažitelný panel DevTools a filtrujte logy","wf2_desc":"Klepněte na odznak DevTools (zobrazuje živý počet chyb) a přepínejte mezi kartami All, Error, Warn a Net při libovolném nastavení výšky panelu.","wf3_title":"Dotazujte se živého stavu DOM a spouštějte async výrazy","wf3_desc":"Zadáváním živých JS příkazů do spodního vstupu REPL kontrolujte uzly DOM (&lt;section#hero.active&gt;), klíče úložiště nebo exporty WASM.","wf4_title":"Vraťte se na řádek v editoru a znovu ověřte","wf4_desc":"Přejetím od levého okraje se ihned vrátíte na kartu se zdrojovým kódem, provedete opravu a znovu spustíte jediným klepnutím.","wf_foot_note":"Bez vkládání cizích CDN skriptů &#183; Funguje 100% offline v režimu Letadlo","table_h2":"SuperCode Mobile DevTools vs. mobilní prohlížeče a bookmarklety","snippet_p":"<strong>SuperCode Mobile Web DevTools &amp; WASM Studio</strong> přináší diagnostiku prohlížeče desktopové úrovně přímo na Android. Filtrujte logy All, Error, Warn a časování HTTP sítě v roztažitelném panelu, zkoumejte serializované DOM elementy a cyklické objekty v interaktivním asynchronním JavaScript REPL a kompilujte binární moduly .wasm přes nativní WebAssembly.instantiateStreaming().","table_caption":"SROVNÁNÍ MOBILNÍHO LADĚNÍ WEBU A WEBASSEMBLY NA ANDROIDU","th_0":"Diagnostická funkce","th_1":"SuperCode Web DevTools","th_2":"Android Chrome Mobile","th_3":"Eruda / CDN bookmarklety","th_4":"Základní HTML náhledové aplikace","tr1_c0":"Konzole a odznak chyb","tr1_c1":"Vestavěné All / Error / Warn / Net + odznak","tr1_c2":"Skryté bez PC a USB adb","tr1_c3":"Vyžaduje ruční script tag","tr1_c4":"Jen prostý text alert/log","tr2_c0":"Časování HTTP sítě","tr2_c1":"Živě METHOD /path -&gt; status &#183; ms &#183; B","tr2_c2":"Vyžaduje připojení k PC DevTools","tr2_c3":"Pouze částečný XHR hook","tr2_c4":"Nepodporováno","tr3_c0":"Živý JS DOM REPL","tr3_c1":"Interaktivní REPL + řešení Promise","tr3_c2":"Vyžaduje kabel k PC","tr3_c3":"Funguje jen online","tr3_c4":"Nepodporováno","tr4_c0":"DOM a cyklické objekty","tr4_c1":"&lt;div#app.card&gt; + bezpečný serializátor [Circular]","tr4_c2":"Vyžaduje kabel k PC","tr4_c3":"Těžkopádný injektovaný balík","tr4_c4":"Řetězce [object Object]","tr5_c0":"WebAssembly (.wasm)","tr5_c1":"Offline streamovací server application/wasm","tr5_c2":"Vyžaduje externí webhosting","tr5_c3":"Neopraví file:// MIME","tr5_c4":"Selhává na MIME / CORS kontrole","faq_lead":"Dotazy ohledně kontroly chyb konzole, sledování HTTP požadavků, spouštění DOM JS příkazů a provádění `.wasm` offline.","faq1_q":"Musím vkládat `&lt;script src=\"eruda.js\"&gt;` nebo být online, aby DevTools fungovaly?","faq1_a":"Ne! Web DevTools konzole, síťový monitor i interaktivní JavaScript REPL v SuperCode jsou vestavěné nativně přímo do offline náhledového enginu &#8212; bez externích CDN skriptů a 100% funkční i v režimu Letadlo.","faq2_q":"Mohu spouštět binární soubory WebAssembly `.wasm` zkompilované z Rustu nebo C/C++?","faq2_a":"Ano. Umístěte binární soubor `.wasm` do složky projektu a načtěte jej pomocí `WebAssembly.instantiateStreaming(fetch('./module.wasm'))` &#8212; SuperCode servíruje `.wasm` s přesným typem MIME `application/wasm`.","faq3_q":"Co se stane, když zaloguji element DOM nebo objekt s cyklickými odkazy?","faq3_a":"Elementy DOM se přehledně vykreslí jako souhrny `&lt;tag#id.class&gt;` a cyklické odkazy objektů se bezpečně detekují jako `[Circular]`, aniž by došlo k výjimce `JSON.stringify`.","faq4_q":"Zachycuje karta Net kromě statických souborů a `fetch()` také volání PHP backendu?","faq4_a":"Ano. Každé statické aktivum, ES modul, binární `.wasm`, volání `fetch()` / `XMLHttpRequest` i lokální spuštění koncového bodu `.php` se zobrazí na kartě Net včetně stavového kódu HTTP, latence v milisekundách a velikosti přenosu v bajtech.","cta_h2":"Sledujte konzoli, síť i WebAssembly přímo na telefonu.","cta_desc":"Stáhněte si SuperCode IDE zdarma na Google Play &#8212; vestavěné Web DevTools, živý DOM REPL a offline streamování WASM."},"web_sftp_deploy":{"metaTitle":"Úpravy a nasazování živých webů z Androidu — lokální staging na SFTP, FTPS a Git | SuperCode","metaDesc":"Spravujte a nasazujte produkční weby v HTML, CSS, JS, WASM a PHP ze svého telefonu Android. Prohlížejte si vzdálené karty SFTP/FTPS lokálně na vyžádání, ukládejte pomocí 3fázových atomických transakcí nebo pushujte na GitHub Pages.","hero_tag":"SFTP (SSH KLÍČE) &#183; FTPS (TLS 1.3) &#183; VZDÁLENÝ NÁHLED NA VYŽÁDÁNÍ &#183; VIZUÁLNÍ GIT","hero_h1":"Otestujte lokálně a poté <span class=\"text-gradient\">upravujte a nasazujte živé weby</span> přes SFTP, FTPS a Git.","hero_desc":"Ať už řešíte naléhavý produkční hotfix v PHP z vlaku nebo publikujete statické portfolio na GitHub Pages, SuperCode přímo propojuje <strong>lokální HTTP/PHP staging</strong> s <strong>SFTP přes SSH klíče, FTPS s TLS 1.3 a vizuálním Git</strong> &#8212; včetně <strong>vzdáleného náhledu stránek na vyžádání</strong> a <strong>3fázového atomického ukládání na server</strong>.","dep_s1":"Klíče Ed25519 / RSA","dep_s2":"Explicitní/implicitní FTPS","dep_s3":"Atomické vzdálené uložení","dep_s4":"Push na GitHub Pages","wb_eyebrow":"ŽIVÝ VZDÁLENÝ NÁHLED SFTP, ATOMICKÉ UKLÁDÁNÍ A WORKBENCH PRO GIT PAGES","sec_cap_title":"Bezpečné produkční webové operace navržené pro mobilní sítě","sec_cap_lead":"Zkontrolujte náhled před přepsáním, přestůjte výpadky mobilního signálu bez úhony a spravujte VPS i statické hostingy z jednoho prostoru.","f1_title":"Připojení Linux VPS a sdílených hostingů přes SFTP, FTPS a FTP","f1_desc":"Připojte se přímo k serverům Nginx/Apache VPS přes SFTP s hardwarově chráněnými klíči SSH (Ed25519, RSA, ECDSA) nebo k hostingům cPanel/Plesk přes explicitní/implicitní FTPS (TLS 1.3) a standardní FTP.","f1_badge":"SFTP &#183; FTPS (TLS 1.3) &#183; Trezor Android KeyStore","f2_title":"Lokální náhled vzdálených karet HTML a PHP na 1 klepnutí","f2_desc":"Otevřete vzdálený soubor .html nebo .php ze stromu serveru a klepněte na Spustit &#9654;. SuperCode vykreslí stránku lokálně a transparentně na vyžádání stáhne z vašeho serveru související styly, skripty a obrázky.","f2_badge":"Testujte vzdálené úpravy lokálně &#183; Stažení aktiv na vyžádání","f3_title":"3fázové atomické ukládání brání poškození živých stránek","f3_desc":"Přímé přepsání živého index.php na kolísavé mobilní Wi-Fi může zanechat neúplný soubor a způsobit výpadek HTTP 500. SuperCode nahraje dočasný sesterský soubor, ověří přesný počet bajtů a teprve pak jej atomicky přejmenuje.","f3_badge":"Žádné napůl zapsané produkční soubory &#183; Bezpečné na 4G/5G","f4_title":"Plně offline PHP 8.2 a lokální staging pro 3 viewporty","f4_desc":"Naklonujte nebo stáhněte složku webu do telefonu, vyvíjejte routy PHP 8.2 + PDO SQLite a rozložení CSS Grid napříč viewporty Mobil/Tablet/Desktop v režimu Letadlo a pak nahrajte ověřené změny.","f4_badge":"Workflow Offline staging -&gt; Produkční synchronizace","f5_title":"Vizuální Git klient pro GitHub, Cloudflare a Netlify Pages","f5_desc":"Nasazujete JAMstack, statické HTML5 nebo aplikace WASM? Zkontrolujte barevné sjednocené diffy řádek po řádku, selektivně připravte soubory (stage), commitněte a pushněte přímo na GitHub, GitLab či Bitbucket pro spuštění CI/CD buildů Pages.","f5_badge":"Barevný Unified Diff &#183; HTTPS PAT &#183; Git Push na 1 klepnutí","f6_title":"Souběžné přenosy složek a navázání přerušeného přenosu","f6_desc":"Publikujte celé adresáře dist/, assets/ nebo media rychle díky frontám s více spojeními, živým přehledem propustnosti, úpravou vzdálených oprávnění chmod a automatickým navázáním přerušených přenosů.","f6_badge":"Fronta paralelního nahrávání &#183; Navázání &#183; Vzdálené chmod","workflow_title":"Jak otestovat, bezpečně upravit a publikovat živý web z Androidu","workflow_lead":"Dva čisté nasazovací postupy &#8212; přímé SFTP/FTPS pro PHP/VPS hostingy nebo vizuální Git pro Pages.","wf1_title":"Připojte webhosting nebo naklonujte Git repozitář","wf1_desc":"Přidejte svůj VPS/cPanel server do správce SFTP/FTPS (se šifrovaným klíčem SSH nebo heslem) nebo naklonujte repozitář GitHub Pages.","wf2_title":"Zobrazte vzdálené či lokální stránky napříč 3 viewporty","wf2_desc":"Upravujte HTML, CSS, JS nebo PHP s AST doplňováním a klepnutím na Spustit &#9654; zkontrolujte vykreslení Mobil/Tablet/Desktop i logy DevTools před publikováním.","wf3_title":"Ověřte změny přes Unified Diff nebo atomické nahrání","wf3_desc":"Ukládejte vzdálené karty SFTP/FTPS pomocí 3fázového atomického přejmenování, aby návštěvníci nikdy nenarazili na neúplný soubor, nebo zkontrolujte barevné Git diffy.","wf4_title":"Odešlete do produkce a potvrďte stav sítě","wf4_desc":"Pushněte commity pro spuštění GitHub/Cloudflare Pages nebo souběžně synchronizujte složky s aktivy na produkční server.","wf_foot_note":"Hardwarově chráněné šifrování údajů &#183; Podporuje SFTP, explicitní/implicitní FTPS (TLS 1.3), FTP a Git HTTPS","table_h2":"SuperCode Full-Stack Deploy vs. samostatné FTP aplikace a webové panely","snippet_p":"<strong>SuperCode Full-Stack Web SFTP &amp; Git Studio</strong> umožňuje vývojářům testovat, prohlížet a nasazovat produkční weby přímo z Androidu. Připojte vzdálené servery přes SFTP s SSH klíči nebo FTPS s TLS 1.3, prohlížejte si vzdálené stránky HTML a PHP lokálně na vyžádání, ukládejte změny přes 3fázové atomické transakce nebo pushujte statické buildy na GitHub Pages.","table_caption":"SROVNÁNÍ MOBILNÍ SPRÁVY A NASAZOVÁNÍ WEBŮ","th_0":"Požadavek nasazení","th_1":"SuperCode Web + SFTP + Git","th_2":"Samostatné FTP aplikace pro Android","th_3":"cPanel UI v mobilním prohlížeči","th_4":"Pouze desktop / notebook","tr1_c0":"Vzdálený náhled webu","tr1_c1":"Lokální spuštění na 1 klepnutí + stažení aktiv na vyžádání","tr1_c2":"Nutné ručně stáhnout celý web","tr1_c3":"Bez lokálního staging náhledu","tr1_c4":"Ruční SSH tunel / synchronizace","tr2_c0":"Ukládání odolné vůči výpadkům","tr2_c1":"3fázové atomické nahrání + ověření + přejmenování","tr2_c2":"Přímý přepis riskuje oříznutí souboru","tr2_c3":"Vypršení relace smaže úpravy","tr2_c4":"Závisí na editoru","tr3_c0":"Backendový staging PHP","tr3_c1":"100% offline PHP 8.2 + PDO SQLite","tr3_c2":"Pouze prohlížeč prostého textu","tr3_c3":"Upravuje přímo živou produkci","tr3_c4":"Vyžaduje lokální stack","tr4_c0":"Git a statický hosting","tr4_c1":"Vestavěný vizuální Git + barevný Unified Diff","tr4_c2":"Neobsahuje Git klienta","tr4_c3":"Bez workflow pro Git diff","tr4_c4":"Plnohodnotný Git","tr5_c0":"Protokoly a zabezpečení","tr5_c1":"SFTP (SSH klíče) + FTPS TLS 1.3 + KeyStore","tr5_c2":"Často chybí TLS 1.3 nebo DevTools","tr5_c3":"Pouze autentizace cookie prohlížeče","tr5_c4":"Plné SSH","faq_lead":"Časté dotazy k úpravám vzdálených webů přes SFTP/FTPS, předcházení poškozeným nahráním a pushování na GitHub Pages.","faq1_q":"Jak funguje náhled vzdálené stránky přes SFTP nebo FTP bez stahování celého serveru?","faq1_a":"Když klepnete na Spustit u otevřené vzdálené karty `.html` nebo `.php`, SuperCode ji vykreslí v lokálním náhledovém serveru a automaticky na vyžádání stáhne ze vzdáleného serveru jen odkazované relativní soubory CSS, JS, fonty a obrázky.","faq2_q":"Co se stane, když telefon ztratí mobilní signál přesně při ukládání vzdáleného souboru `index.php`?","faq2_a":"Váš živý produkční soubor zůstane nedotčený! 3fázové atomické ukládání v SuperCode zapíše nejprve do dočasného souboru, ověří 100% shodu nahraného počtu bajtů a teprve potom provede atomické přejmenování na straně serveru.","faq3_q":"Podporuje SuperCode jak sdílený webhosting cPanel/Plesk, tak linuxové SSH VPS servery?","faq3_a":"Ano. Použijte SFTP (s heslem nebo privátními klíči Ed25519/RSA) pro cloudové VPS instance jako DigitalOcean, AWS Lightsail, Hetzner nebo Linode a FTPS (TLS 1.3) či FTP pro cPanel a sdílený hosting.","faq4_q":"Mohu zdarma vytvořit a publikovat statický web v HTML/CSS/JS nebo WASM na GitHub Pages?","faq4_a":"Ano. Napište a otestujte web offline na lokálním HTTP serveru SuperCode, poté změny commitněte a pushněte přímo do svého repozitáře GitHub Pages pomocí vestavěného vizuálního Git klienta.","cta_h2":"Spravujte a nasazujte živé weby s jistotou přímo z kapsy.","cta_desc":"Stáhněte si SuperCode IDE zdarma na Google Play &#8212; sjednocený staging pro Web a PHP, atomické SFTP/FTPS a vizuální Git."},"sql_db_viewer":{"metaTitle":"Otevírejte a dotazujte soubory .db, .sqlite a .sqlite3 offline na Androidu | SuperCode SQLite 3.54.1","metaDesc":"Otevírejte, zkoumejte a upravujte soubory .db, .sqlite, .sqlite3, .db3 a .s3db 100% offline na Androidu se SQLite 3.54.1. Automatický import CSV/TSV/JSON až do 8 MB a export v 9 režimech (Box, Markdown, JSON, CSV).","hero_tag":"SQLITE 3.54.1 OFFLINE &#183; .DB / .SQLITE / .DB3 &#183; 9 REŽIMŮ VÝSTUPU &#183; IMPORT CSV/JSON","hero_h1":"Otevírejte, zkoumejte a dotazujte <span class=\"text-gradient\">.db, .sqlite a .sqlite3</span> soubory offline na Androidu.","hero_desc":"Potřebujete zkontrolovat binární soubor <code>.db</code> aplikace, převést surový export <code>.csv</code> nebo <code>.json</code> na relační tabulku, nebo spustit ostré dotazy <code>UPDATE</code> bez nahrávání citlivých dat do cloudu? SuperCode integruje <strong>offline SQLite 3.54.1</strong> s inspekcí schématu na 1 klepnutí a <strong>9 formátovanými režimy výstupu</strong>.","dbv_s1":"Offline SQLite","dbv_s2":"Box/MD/JSON/CSV","dbv_s3":"Import CSV/TSV/JSON","dbv_s4":".db/.sqlite/.db3+","wb_eyebrow":"INSPEKTOR BINÁRNÍCH .DB, AUTO-IMPORT CSV/JSON A WORKBENCH S 9 REŽIMY VÝSTUPU","sec_cap_title":"Víc než jen tabulka jen pro čtení &#8212; Plnohodnotná offline SQLite stanice","sec_cap_lead":"Zkoumejte interní metadata, provádějte parametrizované úpravy, převádějte ploché soubory na SQL tabulky a exportujte čisté reporty během sekund.","f1_title":"Inspektor na 1 klepnutí pro .db, .sqlite, .sqlite3, .db3 a .s3db","f1_desc":"Klepněte na libovolnou binární databázi SQLite v Průzkumníku SuperCode nebo ji otevřete z úložiště Androidu. SuperCode ověří binární hlavičku a automaticky vypíše statistiky stránek .dbinfo, počty v .tables a kompletní DDL .schema.","f1_badge":".db &#183; .sqlite &#183; .sqlite3 &#183; .db3 &#183; .s3db","f2_title":"9 přepínatelných formátů .mode (Box, Markdown, JSON, CSV+)","f2_desc":"Formátujte výsledky pro jakýkoli cíl: ostré Unicode box mřížky a ASCII tabulky pro čtení na mobilu, Markdown tabulky do dokumentace na GitHubu, JSON pole pro API, CSV/tabulátory do tabulkových procesorů, SQL insert dumpy nebo svislé řádkové karty.","f2_badge":"box &#183; table &#183; markdown &#183; json &#183; csv &#183; tabs &#183; insert &#183; line &#183; list","f3_title":"Přímý .import --csv, --tsv a --json bez šablonového kódu","f3_desc":"Přeskočte zdlouhavé psaní CREATE TABLE. Spusťte .import --csv sales.csv sales nebo .import --json users.json users (až 8 MB) a SuperCode automaticky odvodí názvy sloupců, takže můžete ihned používat JOIN a agregace.","f3_badge":"Auto tvorba tabulek &#183; CSV / TSV / JSON až 8 MB","f4_title":"Automaticky připojené databáze pracovního prostoru pro .sql skripty","f4_desc":"Mějte queries.sql přímo vedle souboru app.db vašeho projektu. SuperCode automaticky rozpozná a připojí databázi pracovního prostoru (nebo následuje explicitní příkazy .open), takže migrace schématu i úpravy se ukládají přímo na disk.","f4_badge":"Trvalé zápisy na disk &#183; Podpora více DB přes .open","f5_title":"Přímý export do souboru přes .once do složky projektu","f5_desc":"Zkombinujte libovolný režim výstupu s .once &lt;filename&gt; &#8212; například .mode markdown + .once report.md nebo .mode csv + .once clean_leads.csv &#8212; a zapište výsledky dotazu přímo do souboru v pracovním prostoru připraveného ke sdílení.","f5_badge":"Export přes .once &#183; Okamžité reporty a dumpy","f6_title":"100% soukromí v zařízení se SQLite 3.54.1","f6_desc":"Záznamy zákazníků, offline databáze mobilních aplikací ani finanční CSV nikdy neopustí vaše zařízení. Každá inspekce, tvorba indexu, VACUUM i dotaz běží lokálně uvnitř integrovaného SQLite 3.54.1.","f6_badge":"Nulové nahrávání do cloudu &#183; Offline jádro SQLite 3.54.1","workflow_title":"Jak zkontrolovat soubor `.db` nebo dotazovat dataset CSV/JSON na Androidu","workflow_lead":"Otevřete stávající binární databáze nebo vytvořte nové ze surových souborů ve čtyřech rychlých krocích.","wf1_title":"Otevřete jakýkoli soubor .db, .sqlite nebo .sqlite3 na jedno klepnutí","wf1_desc":"Vyberte databázový soubor v pracovním prostoru a okamžitě zobrazte souhrn .dbinfo, seznam .tables a schéma CREATE TABLE / INDEX.","wf2_title":"Nebo importujte surové soubory CSV, TSV a JSON do tabulek","wf2_desc":"Spusťte v .sql skriptu příkaz .import --csv data.csv my_table a automaticky vytvořte i naplňte relační sloupce ze souborů až do 8 MB.","wf3_title":"Spouštějte SQL dotazy a přepínejte mezi 9 formáty výstupu","wf3_desc":"Pište příkazy SELECT, JOIN, UPDATE nebo ALTER s AST doplňováním SQL a prohlížejte čisté Unicode box nebo Markdown mřížky.","wf4_title":"Exportujte čisté výsledky zpět do pracovního prostoru","wf4_desc":"Použijte .once s režimem csv, json, markdown nebo insert pro uložení čistých analytických výstupů přímo do složky projektu.","wf_foot_note":"Integrovaný SQLite 3.54.1 &#183; Bez nutnosti účtu &#183; Plné ACID transakce pro čtení i zápis","table_h2":"SuperCode SQLite 3.54.1 Studio vs. základní prohlížeče `.db` pro Android","snippet_p":"<strong>Offline prohlížeč a editor databází SQLite v SuperCode</strong> otevírá binární soubory .db, .sqlite, .sqlite3, .db3 a .s3db na Androidu na jedno klepnutí pomocí SQLite 3.54.1. Zkoumejte schémata a metadata offline, automaticky importujte soubory CSV, TSV a JSON až do 8 MB a formátujte výsledky dotazů v 9 přepínatelných režimech výstupu.","table_caption":"SROVNÁNÍ PROHLÍŽEČŮ .DB A SQL EDITORŮ PRO ANDROID","th_0":"Možnosti SQLite","th_1":"SuperCode SQL Studio","th_2":"Základní DB prohlížeče","th_3":"Mobilní tabulkové aplikace","th_4":"Online SQLite prohlížeče","tr1_c0":"Verze jádra","tr1_c1":"Offline SQLite 3.54.1 (moderní JSONB/FTS5)","tr1_c2":"Zastaralý systémový SQLite 3.2x","tr1_c3":"Není relační SQL engine","tr1_c4":"Nahrává soukromé .db na web","tr2_c0":"Audit schématu na 1 klepnutí","tr2_c1":"Auto .dbinfo + .tables + plné .schema DDL","tr2_c2":"Pouze ruční výběr tabulek","tr2_c3":"Neotevře binární .db/.db3","tr2_c4":"Paměťové limity prohlížeče","tr3_c0":"Formátování výstupu","tr3_c1":"9 režimů (box, markdown, json, csv, insert+)","tr3_c2":"Pevná stísněná mřížka buněk","tr3_c3":"Pouze tabulkové buňky","tr3_c4":"Základní HTML tabulka","tr4_c0":"Import CSV / TSV / JSON","tr4_c1":"Automaticky tvoří SQL tabulky až do 8 MB","tr4_c2":"Vzácně nebo jako placený doplněk","tr4_c3":"Otevře jen jeden plochý list","tr4_c4":"Vyžaduje nahrání přes internet","tr5_c0":"Integrace s kódem","tr5_c1":"Dotazy nad stejným .db z Python, PHP, Java a Lua","tr5_c2":"Izolovaný samostatný prohlížeč","tr5_c3":"Žádná","tr5_c4":"Žádná","faq_lead":"Odpovědi k otevírání souborů `.db`/`.sqlite3`, importu datasetů CSV/JSON a exportu formátovaných výsledků offline.","faq1_q":"Které přípony databázových souborů SQLite umí SuperCode otevřít přímo?","faq1_a":"SuperCode rozpozná soubory `.db`, `.sqlite`, `.sqlite3`, `.db3` a `.s3db` na jedno klepnutí a automaticky spustí offline inspekci `.dbinfo`, `.tables` a `.schema`.","faq2_q":"Proč je integrovaný SQLite 3.54.1 důležitý oproti běžným prohlížečům SQLite pro Android?","faq2_a":"Většina prohlížečů DB na Androidu spoléhá na starší systémové sestavení SQLite v telefonu, které postrádá tabulky `STRICT`, `RETURNING`, `JSONB`, moderní klauzule rámců oken a novější plánovač dotazů. SuperCode dodává konzistentně SQLite 3.54.1 napříč zařízeními s Android 8.0+.","faq3_q":"Mohu importovat soubor `.csv` nebo `.json`, aniž bych nejprve psal `CREATE TABLE`?","faq3_a":"Ano! Spusťte `.import --csv filename.csv tablename` (nebo `--tsv` / `--json`) až do 8 MB &#8212; pokud tabulka `tablename` ještě neexistuje, SuperCode automaticky vytvoří schéma tabulky z hlaviček CSV nebo klíčů JSON objektů.","faq4_q":"Jak exportuji výsledek SQL dotazu do Markdown tabulky nebo CSV souboru?","faq4_a":"Přidejte `.mode markdown` (nebo `.mode csv` / `.mode json` / `.mode insert`) následované `.once output.md` těsně nad příkaz `SELECT` a klepněte na Spustit &#8212; soubor se okamžitě objeví v průzkumníku projektu.","cta_h2":"Otevírejte, dotazujte a exportujte jakýkoli soubor SQLite `.db` offline.","cta_desc":"Stáhněte si SuperCode IDE zdarma na Google Play &#8212; SQLite 3.54.1, 9 formátů výstupu a okamžitý import CSV/JSON."},"sql_analytics":{"metaTitle":"Offline aplikace pro procvičování SQL na Androidu — Window funkce, CTE, JSONB a FTS5 | SuperCode","metaDesc":"Procvičujte reálné analytické SQL a uspějte u technických pohovorů offline na Androidu. Spouštějte Window funkce (OVER, LAG, DENSE_RANK), rekurzivní CTE, JSONB ->/->>, FTS5 bm25() vyhledávání a MEDIAN/STDDEV s 6 SQL šablonami.","hero_tag":"WINDOW OVER() &#183; WITH RECURSIVE &#183; JSONB &#183; FTS5 BM25() &#183; MEDIAN A STDDEV","hero_h1":"Procvičujte <span class=\"text-gradient\">Window funkce, CTE, JSONB a FTS5</span> v SQL offline na Androidu.","hero_desc":"Překonejte kvízové SQL aplikace s doplňováním slov. SuperCode dává datovým analytikům, studentům informatiky i uchazečům o práci <strong>skutečný offline analytický SQL engine</strong> s podporou okenních rámců <strong><code>OVER (PARTITION BY ...)</code></strong>, stromů <strong><code>WITH RECURSIVE</code></strong>, cestových operátorů <strong>JSONB</strong>, fulltextového vyhledávání <strong>FTS5 <code>bm25()</code></strong> a vestavěných funkcí <strong><code>MEDIAN()</code> / <code>PERCENTILE()</code> / <code>STDDEV()</code></strong>.","ana_s1":"Window funkce","ana_s2":"-&gt; / -&gt;&gt; + json_each","ana_s3":"Vyhledávání bm25()","ana_s4":"Startovací SQL laby","wb_eyebrow":"WORKBENCH PRO ANALYTICKÉ WINDOW FUNKCE, FTS5 VYHLEDÁVÁNÍ A JSONB","sec_cap_title":"Navrženo pro pohovory v datovém inženýrství, univerzitní DBMS cvičení a analytiku","sec_cap_lead":"Každá moderní SQL konstrukce zkoušená na datových pohovorech FAANG/LeetCode &#8212; s odezvou v milisekundách i v režimu letadlo.","f1_title":"Window funkce, LAG/LEAD a klouzavé rámce","f1_desc":"Řešte úlohy top-N ve skupině, sesionizaci, retenční kohorty a 7denní klouzavé průměry offline pomocí ROW_NUMBER(), DENSE_RANK(), NTILE(), LAG(), LEAD() a ROWS BETWEEN UNBOUNDED PRECEDING AND CURRENT ROW.","f1_badge":"ROW_NUMBER &#183; DENSE_RANK &#183; LAG/LEAD &#183; Klauzule rámců","f2_title":"Rekurzivní CTE (WITH RECURSIVE), STRICT a RETURNING","f2_desc":"Generujte kalendářní osy, procházejte hierarchické organizační struktury a hrany grafů pomocí WITH RECURSIVE, vynucujte striktní datové typy tabulkami STRICT a získejte změněné řádky v jediném kroku přes UPSERT ... RETURNING *.","f2_badge":"WITH RECURSIVE &#183; STRICT typy &#183; UPSERT RETURNING","f3_title":"Nativní JSON / JSONB (-&gt;, -&gt;&gt;) a json_each()","f3_desc":"Ukládejte binární JSONB payloady a dotazujte vnořené atributy operátory -&gt; a -&gt;&gt;. Rozbalujte JSON pole do relačních řádků pomocí json_each() nebo json_tree() a skládejte vnořené JSON výstupy pomocí json_group_object().","f3_badge":"Binární JSONB &#183; -&gt; / -&gt;&gt; &#183; Rozbalení json_each()","f4_title":"Fulltextové vyhledávání FTS5 (bm25) a prostorové Geopoly","f4_desc":"Stavte rychlé vyhledávače offline pomocí CREATE VIRTUAL TABLE ... USING fts5(...) s logickým a prefixovým vyhledáváním, hodnocením relevance bm25() a highlight() &#8212; plus vícerozměrné indexy R*Tree a polygonové dotazy Geopoly.","f4_badge":"FTS5 &#183; Řazení bm25() &#183; highlight() &#183; R*Tree/Geopoly","f5_title":"MEDIAN(), PERCENTILE(), STDDEV() a READ_STDIN()","f5_desc":"Standardní SQLite postrádá statistické agregace &#8212; SuperCode přidává nativní funkce MEDIAN(), PERCENTILE(x, p) a STDDEV() i interaktivní výrazy READ_STDIN('Prompt: ') pro dynamické testování parametrizovaných dotazů.","f5_badge":"MEDIAN &#183; PERCENTILE &#183; STDDEV &#183; Interaktivní READ_STDIN()","f6_title":"6 spustitelných startovacích SQL šablon a export do A4 PDF","f6_desc":"Spusťte 6 vestavěných SQL lab šablon (Joiny, Window analytika, Rekurzivní CTE, JSONB, FTS5, Triggery a Pohledy) bez přihlášení a exportujte SQL úkoly se zvýrazněnou syntaxí přímo do A4 PDF.","f6_badge":"6 SQL labů &#183; Bez přihlášení &#183; Export do A4 PDF","workflow_title":"Jak procvičovat SQL pohovory a analytiku offline na telefonu","workflow_lead":"Procvičování SQL na cestách s okamžitou odezvou Unicode tabulek a nulovou závislostí na Wi-Fi.","wf1_title":"Vyberte jednu ze 6 vestavěných šablon analytického SQL","wf1_desc":"Otevřete nový soubor .sql a klepněte na Šablony pro načtení ukázkových schémat předvyplněných realistickými daty prodejů, zaměstnanců, JSON nebo FTS5.","wf2_title":"Pište složitá CTE, Joiny a klauzule OVER() rychle","wf2_desc":"Zadávejte apostrofy, závorky, -&gt; i * snadno na 21klávesové liště s offline doplňováním SQL klíčových slov a identifikátorů.","wf3_title":"Prohlížejte seřazené mřížky a submilisekundové časy","wf3_desc":"Klepněte na Spustit &#9654; pro zobrazení čistých Unicode box tabulek, interaktivně testujte hraniční případy pomocí READ_STDIN() a dolaďujte okenní oddíly.","wf4_title":"Uložte studijní poznámky jako Markdown nebo A4 PDF","wf4_desc":"Exportujte výstupy dotazů přes .mode markdown + .once notes.md nebo vytiskněte svá .sql řešení do A4 PDF k odevzdání na univerzitě.","wf_foot_note":"100% připraveno pro režim letadlo &#183; 6 vestavěných SQL šablon &#183; 8 tmavých i světlých motivů","table_h2":"SuperCode SQL Analytics Studio vs. herní SQL kvízové aplikace","snippet_p":"<strong>Offline analytické a tréninkové SQL studio v SuperCode</strong> vybavuje studenty i datové inženýry na Androidu moderními analytickými možnostmi SQLite 3.54.1. Pište Window funkce, WITH RECURSIVE CTE, tabulky STRICT, klauzule UPSERT RETURNING, JSONB cestové dotazy, FTS5 bm25() fulltextové vyhledávání a statistiky MEDIAN/PERCENTILE/STDDEV 100% offline se 6 vestavěnými šablonami.","table_caption":"SROVNÁNÍ NÁSTROJŮ PRO MOBILNÍ TRÉNINK SQL A PŘÍPRAVU NA POHOVORY","th_0":"Funkce pro trénink SQL","th_1":"SuperCode SQL Studio","th_2":"Herní SQL kvízové appky","th_3":"Zastaralé SQLite appky","th_4":"Online LeetCode/DB Fiddle","tr1_c0":"Window funkce a CTE","tr1_c1":"Plné OVER(), LAG/LEAD a WITH RECURSIVE","tr1_c2":"Doplňovačky s výběrem možností","tr1_c3":"Často selhává u klauzulí rámců","tr1_c4":"Vyžaduje aktivní internet","tr2_c0":"Vyhledávání JSONB a FTS5","tr2_c1":"Nativní -&gt;/-&gt;&gt;, json_each a FTS5 bm25()","tr2_c2":"Není pokryto","tr2_c3":"Chybí FTS5 / JSONB","tr2_c4":"Liší se podle webového jádra","tr3_c0":"Statistické agregace","tr3_c1":"Vestavěné MEDIAN(), PERCENTILE(), STDDEV()","tr3_c2":"Jen základní AVG / SUM","tr3_c3":"Chybí v čistém SQLite","tr3_c4":"Závislé na dialektu","tr4_c0":"Vlastní datasety","tr4_c1":"Libovolné schéma + import 8 MB CSV/JSON","tr4_c2":"Uzamčeno na přednastavené tabulky","tr4_c3":"Pouze ruční SQL inserty","tr4_c4":"Relace se při obnovení smaže","tr5_c0":"Offline a předplatné","tr5_c1":"100% offline jádro + 6 šablon zdarma","tr5_c2":"Paywally a denní životy","tr5_c3":"Reklamy / zastaralé UI","tr5_c4":"Nefunguje v metru ani letadle","faq_lead":"Časté dotazy studentů SQL, datové vědy i uchazečů o backendové pohovory.","faq1_q":"Mohu procvičovat úlohy typu LeetCode s Window funkcemi (`DENSE_RANK`, `LAG`, průběžné součty) offline?","faq1_a":"Ano! Každá standardní SQL window funkce (`ROW_NUMBER`, `RANK`, `DENSE_RANK`, `NTILE`, `LAG`, `LEAD`, `FIRST_VALUE`, `LAST_VALUE`, `NTH_VALUE`) i specifikace rámců `ROWS`/`RANGE`/`GROUPS` funguje 100% offline.","faq2_q":"Podporuje SuperCode funkce `MEDIAN()`, `PERCENTILE()` a `STDDEV()` přímo v SQL?","faq2_a":"Ano. Zatímco základní SQLite statistické agregace postrádá, SuperCode předregistrovává nativní funkce `MEDIAN(col)`, `PERCENTILE(col, 95)` a `STDDEV(col)`, takže datoví analytici spočítají rozdělení v jediném příkazu `SELECT`.","faq3_q":"Jak uvnitř dotazu `.sql` funguje `READ_STDIN()`?","faq3_a":"Napište do souboru `.sql` například `WHERE department = READ_STDIN('Department name: ')` a klepněte na Spustit &#8212; SuperCode vás interaktivně vyzve v ukotvené konzoli, takže můžete parametrizované dotazy spouštět znovu bez úpravy kódu.","faq4_q":"Jsou zapnuté moduly fulltextového vyhledávání FTS5 a prostorové R*Tree / Geopoly?","faq4_a":"Ano. Jak `USING fts5(...)` (včetně `bm25()`, `highlight()` a `snippet()`), tak prostorová rozšíření `USING rtree(...)` / Geopoly jsou zkompilovány přímo do offline jádra SQLite 3.54.1 v SuperCode.","cta_h2":"Ovládněte Window funkce, CTE a analytické SQL kdekoli.","cta_desc":"Stáhněte si SuperCode IDE zdarma na Google Play &#8212; 6 startovacích SQL šablon, offline SQLite 3.54.1 a přehledný výstup v Unicode tabulkách."},"sql_mysql_compat":{"metaTitle":"Spouštějte dotazy MySQL a PostgreSQL na Androidu — Offline kompatibilita + MySQL 8.0 | SuperCode","metaDesc":"Spouštějte školní úlohy v MySQL a PostgreSQL na telefonu s Androidem. Provádějte AUTO_INCREMENT, SERIAL, ENUM, ILIKE, SHOW TABLES, DESCRIBE a 50+ funkcí offline, plus Cloud MySQL 8.0 pro uložené procedury a DELIMITER.","hero_tag":"OFFLINE KOMPATIBILITA MYSQL/PG &#183; 50+ SKALÁRNÍCH FUNKCÍ &#183; CLOUD MYSQL 8.0 PROCEDURY","hero_h1":"Spouštějte <span class=\"text-gradient\">úlohy v MySQL a PostgreSQL</span> na Androidu &#8212; offline i v Cloud MySQL 8.0.","hero_desc":"Vysokoškolské učebnice a backendové kurzy učí <code>AUTO_INCREMENT</code>, <code>ENGINE=InnoDB</code>, <code>SHOW TABLES</code>, <code>DESCRIBE</code>, <code>SERIAL</code> a <code>ILIKE</code> &#8212; syntaxi, na které běžné SQLite aplikace selhávají. SuperCode spouští běžné <strong>DDL pro MySQL a PostgreSQL a 50+ funkcí offline</strong> a plynule přepíná na <strong>Cloud MySQL 8.0</strong> pro uložené procedury s <code>DELIMITER</code>.","my_s1":"Offline DDL shimy","my_s2":"Vestavěné funkce","my_s3":"Cloudové procedury","my_s4":"Admin příkazy","wb_eyebrow":"OFFLINE KOMPATIBILITA MYSQL/POSTGRES A WORKBENCH CLOUD MYSQL 8.0","sec_cap_title":"Přeneste učebnicovou syntaxi MySQL a PostgreSQL plynule do telefonu","sec_cap_lead":"Přestaňte ručně přepisovat každý řádek s `AUTO_INCREMENT`, `DATE_FORMAT()` nebo `DESCRIBE` jen kvůli otestování úkolu offline.","f1_title":"Offline kompatibilita DDL pro MySQL a PostgreSQL","f1_desc":"Vložte skripty schémat obsahující INT PRIMARY KEY AUTO_INCREMENT, SERIAL, BIGSERIAL, UNSIGNED, ENUM('draft','live') nebo ENGINE=InnoDB DEFAULT CHARSET=utf8mb4 &#8212; SuperCode je čistě přizpůsobí pro okamžité offline spuštění.","f1_badge":"AUTO_INCREMENT &#183; SERIAL &#183; ENUM &#183; ENGINE=InnoDB","f2_title":"SHOW TABLES, DESCRIBE, SHOW CREATE a TRUNCATE","f2_desc":"Prohlížejte schémata přesně těmi příkazy, které znáte z přednášek MySQL: SHOW TABLES, DESCRIBE users (nebo DESC users), SHOW COLUMNS FROM orders, SHOW CREATE TABLE products i TRUNCATE TABLE logs fungují offline.","f2_badge":"SHOW TABLES &#183; DESCRIBE &#183; SHOW CREATE TABLE &#183; TRUNCATE","f3_title":"50+ vestavěných skalárních funkcí MySQL a Postgres","f3_desc":"Spouštějte DATE_FORMAT(), DATEDIFF(), NOW(), CURDATE(), CONCAT_WS(), LPAD(), RPAD(), REVERSE(), SUBSTRING_INDEX(), UUID(), MD5(), SHA256() a REGEXP_REPLACE() offline bez kompilace jakýchkoli rozšíření.","f3_badge":"Krypto &#183; Regex &#183; Datum/čas &#183; Řetězcové funkce offline","f4_title":"PostgreSQL ILIKE a filtrování bez ohledu na velikost písmen","f4_desc":"Pište přehledné dotazy v PostgreSQL pomocí porovnávání vzorů ILIKE, standardních výrazů COALESCE/NULLIF/CASE, klauzulí RETURNING a JSON operátorů -&gt; / -&gt;&gt; přímo ve svém mobilním pracovním prostoru.","f4_badge":"ILIKE &#183; RETURNING &#183; Cestové operátory -&gt; / -&gt;&gt;","f5_title":"Přepnutí na Cloud MySQL 8.0 pro uložené procedury","f5_desc":"Řešíte pokročilá DBMS cvičení vyžadující DELIMITER //, CREATE PROCEDURE, CREATE FUNCTION, parametry IN/OUT/INOUT, kurzory, CALL nebo MySQL JSON_TABLE? Spusťte je proti skutečnému enginu Cloud MySQL 8.0.","f5_badge":"Cloud MySQL 8.0 &#183; DELIMITER &#183; CREATE PROCEDURE &#183; CALL","f6_title":"Chytré směrování obou jader a zvýrazňování syntaxe","f6_desc":"Pište vše v jednom sjednoceném .sql editoru s AST doplňováním, 9 režimy zobrazení výsledků, přesnou diagnostikou SQL chyb na úrovni řádku a nativním exportem do A4 PDF pro odevzdání protokolů.","f6_badge":"Sjednocené .sql Studio &#183; Přesná diagnostika &#183; A4 PDF","workflow_title":"Jak spouštět skripty MySQL a PostgreSQL na Androidu","workflow_lead":"Procvičujte každodenní dotazy offline a zavolejte Cloud MySQL 8.0, kdykoli se objeví uložené procedury.","wf1_title":"Vložte nebo napište schéma MySQL / PostgreSQL","wf1_desc":"Pište standardní skripty CREATE TABLE s AUTO_INCREMENT, SERIAL, ENUM nebo ENGINE=InnoDB bez ručního překladu do SQLite.","wf2_title":"Spouštějte offline dotazy a 50+ vestavěných funkcí","wf2_desc":"Klepněte na Spustit &#9654; offline pro vykonání SHOW TABLES, DESCRIBE, ILIKE, DATE_FORMAT(), CONCAT_WS(), SHA256() i více-tabulkových JOINů.","wf3_title":"Spouštějte uložené procedury na Cloud MySQL 8.0","wf3_desc":"Když váš skript definuje bloky CREATE PROCEDURE, FUNCTION nebo DELIMITER, spusťte jej přes Cloud MySQL 8.0 a zkontrolujte výstupy CALL.","wf4_title":"Exportujte čistá schémata a mřížky dotazů do školy","wf4_desc":"Formátujte výsledky v režimu box nebo markdown a exportujte čistý A4 PDF report pro váš univerzitní LMS.","wf_foot_note":"Offline vrstva kompatibility MySQL/Postgres + reálný Cloud MySQL 8.0 na vyžádání","table_h2":"SuperCode Hybrid MySQL/Postgres Studio vs. mobilní SQL alternativy","snippet_p":"<strong>Studio kompatibility MySQL a PostgreSQL v SuperCode</strong> umožňuje studentům a backendovým vývojářům spouštět učebnicové SQL úlohy na Androidu. Provádějte AUTO_INCREMENT, SERIAL, ENUM, ILIKE, SHOW TABLES, DESCRIBE a 50+ vestavěných krypto, regex a datumových funkcí offline, a pak plynule přepněte na Cloud MySQL 8.0 pro uložené procedury, bloky DELIMITER a JSON_TABLE.","table_caption":"MATICE MOŽNOSTÍ PRO VÝUKU MYSQL A POSTGRESQL NA ANDROIDU","th_0":"Požadavek SQL dialektu","th_1":"SuperCode Hybrid SQL Studio","th_2":"Obyčejné SQLite appky","th_3":"Vzdálení SSH / MySQL klienti","th_4":"Webové MySQL kompilátory","tr1_c0":"AUTO_INCREMENT a SERIAL","tr1_c1":"Běží transparentně offline","tr1_c2":"Chyba syntaxe u AUTO_INCREMENT","tr1_c3":"Vyžaduje živý vzdálený DB host","tr1_c4":"Bez internetu nefunguje","tr2_c0":"SHOW TABLES a DESCRIBE","tr2_c1":"Nativní offline podpora","tr2_c2":"Vyžaduje obchůzky přes PRAGMA","tr2_c3":"Pouze online","tr2_c4":"Pouze online","tr3_c0":"Datumové, regex a krypto fce","tr3_c1":"50+ vestavěných offline (DATE_FORMAT, SHA256+)","tr3_c2":"Jen minimum základních funkcí","tr3_c3":"Závisí na vzdáleném serveru","tr3_c4":"Omezeno na relaci","tr4_c0":"Uložené procedury / CALL","tr4_c1":"Plynulý engine Cloud MySQL 8.0","tr4_c2":"V SQLite nepodporováno","tr4_c3":"Vyžaduje vlastní MySQL server","tr4_c4":"Často blokuje DELIMITER","tr5_c0":"Offline ukládání","tr5_c1":"Ukládá .db a .sql lokálně v telefonu","tr5_c2":"Pouze lokálně","tr5_c3":"Nulové offline spouštění","tr5_c4":"Po vypršení relace smaže tabulky","faq_lead":"Otázky k offline spouštění syntaxe MySQL a PostgreSQL oproti uloženým procedurám v Cloud MySQL 8.0.","faq1_q":"Mohu spouštět MySQL skripty `CREATE TABLE ... AUTO_INCREMENT ENGINE=InnoDB` bez internetu?","faq1_a":"Ano! Offline vrstva kompatibility SQL v SuperCode transparentně překládá běžné DDL klauzule MySQL a PostgreSQL (`AUTO_INCREMENT`, `SERIAL`, `BIGSERIAL`, `UNSIGNED`, `ENUM`, `ENGINE=InnoDB`, `CHARSET`), takže se vaše schéma i dotazy spustí offline.","faq2_q":"Fungují `SHOW TABLES`, `DESCRIBE table_name` a `TRUNCATE TABLE` offline?","faq2_a":"Ano. Při studiu kurzu MySQL si nemusíte pamatovat `.schema` ani `PRAGMA table_info(...)` &#8212; `SHOW TABLES`, `DESCRIBE` / `DESC`, `SHOW CREATE TABLE` a `TRUNCATE TABLE` fungují přímo offline.","faq3_q":"Jak na Androidu běží uložené procedury MySQL (`CREATE PROCEDURE` a `DELIMITER //`)?","faq3_a":"Protože procedurální rutiny `BEGIN ... END` a `DELIMITER` vyžadují serverový procedurální engine, SuperCode tyto skripty plynule směruje do Cloud MySQL 8.0 a streamuje sady výsledků příkazu `CALL` přímo zpět do konzole.","faq4_q":"Které další funkce MySQL a PostgreSQL jsou dostupné offline?","faq4_a":"Offline je vestavěno přes 50 skalárních funkcí, včetně `DATE_FORMAT`, `DATEDIFF`, `NOW`, `CURDATE`, `CONCAT_WS`, `LPAD`, `RPAD`, `SUBSTRING_INDEX`, `ILIKE`, `REGEXP_REPLACE`, `UUID`, `MD5`, `SHA256`, `MEDIAN` a `STDDEV`.","cta_h2":"Zvládněte školní úlohy z MySQL a PostgreSQL přímo z Androidu.","cta_desc":"Stáhněte si SuperCode IDE zdarma na Google Play &#8212; offline kompatibilita MySQL/Postgres plus procedury v Cloud MySQL 8.0."},"sql_polyglot_db":{"metaTitle":"Polyglotní SQLite IDE pro Android — Dotazujte jeden .db v SQL, Python, PHP, Java a Lua | SuperCode","metaDesc":"Vytvářejte reálné databázové aplikace offline na Androidu. Naplňte app.db v SQL Studiu a připojte se ke stejnému souboru SQLite z Python 3.11 sqlite3, PHP 8.2 PDO, Java 17 JDBC a Lua 5.4 — plus upravujte vícejgigabajtové .sql dumpy.","hero_tag":"1 SDÍLENÝ .DB SOUBOR &#183; SQL + PYTHON + PHP + JAVA + LUA &#183; EDITOR GB .SQL DUMPŮ","hero_h1":"Jeden sdílený soubor <code>.db</code> pro <span class=\"text-gradient\">SQL, Python, PHP, Java 17 a Lua</span> offline.","hero_desc":"Jednojazyčné mobilní aplikace izolují data v soukromých sandboxech. V SuperCode navrhnete a zaindexujete <strong><code>app.db</code></strong> v <strong>SQL Studiu</strong> a pak k téže <strong>databázi v pracovním prostoru přistupujete offline</strong> z <strong>Python 3.11 (<code>sqlite3</code>)</strong>, <strong>PHP 8.2 (<code>PDO</code>)</strong>, <strong>Java 17 (<code>jdbc:sqlite:</code>)</strong> a <strong>Lua 5.4 (<code>lsqlite3</code>)</strong> &#8212; nebo otevíráte vícegigabajtové <code>.sql</code> dumpy bez pádů.","poly_s1":"1 sdílený .db soubor","poly_s2":"Ovladače bez konfigurace","poly_s3":"Editor .sql dumpů","poly_s4":"Živá synchronizace disku","wb_eyebrow":"POLYGLOTNÍ DATABÁZE PROSTORU: WORKBENCH PRO SQL + PYTHON + PHP + JAVA + LUA","sec_cap_title":"Vytvářejte kompletní víceslužbové architektury v jediné složce projektu","sec_cap_lead":"Žádné stahování ovladačů, žádné potíže s classpath a žádné ruční kopírování souborů mezi oddělenými mobilními aplikacemi.","f1_title":"Sdílený .db v pracovním prostoru se živým auditem v SQL Studiu","f1_desc":"Každý runtime pracuje přímo s vaší reálnou složkou projektu. Vložte řádky ze skriptu Python nebo Java DAO, přepněte na kartu .sql a okamžitě ověřte zapsané záznamy příkazem SELECT v režimu box.","f1_badge":"Jednotný adresář projektu &#183; Okamžitý audit napříč kartami","f2_title":"Python 3.11 sqlite3 a Pandas read_sql_query()","f2_desc":"Spouštějte ETL pipeline, scrapery v BeautifulSoup nebo prototypy ve Flasku zapisující do sqlite3.connect('app.db') &#8212; pak tabulky načtěte pomocí pandas.read_sql_query() a exportujte grafy Matplotlib přímo do pracovního prostoru.","f2_badge":"sqlite3 Stdlib &#183; pandas.read_sql_query() &#183; Grafy","f3_title":"Webové dashboardy v PHP 8.2 new PDO('sqlite:app.db')","f3_desc":"Proměňte libovolný dataset SQLite v interaktivní webovou aplikaci HTML5 + PHP 8.2 offline. Odesílejte formuláře přes $_POST do app.db pomocí připravených dotazů a sledujte časy HTTP v Web DevTools.","f3_badge":"PHP 8.2 PDO &#183; Full-Stack CRUD &#183; Localhost HTTP","f4_title":"Java 17 JDBC bez Gradle a blesková Lua 5.4 lsqlite3","f4_desc":"Napište DriverManager.getConnection(\"jdbc:sqlite:app.db\") v Java 17 s org.sqlite.JDBC již v offline classpath, nebo skriptujte herní a automatizační stavy v Lua 5.4 přes require('lsqlite3').","f4_badge":"Java 17 jdbc:sqlite &#183; Lua 5.4 lsqlite3 &#183; Nulové nastavení","f5_title":"Prohlížejte a upravujte vícegigabajtové .sql dumpy pomocí regexu","f5_desc":"Stáhli jste si obří 2GB zálohu mysqldump nebo pg_dump v .sql? Editor velkých souborů se stránkováním z disku v SuperCode plynule otevírá vícegigabajtové .sql soubory s více než 30 kódováními, regexovým Hledat/Nahradit a skokem na bajtový offset.","f5_badge":"Stránkované GB+ .sql dumpy &#183; Regex Hledat/Nahradit","f6_title":"Verzujte migrace schémat v Git a synchronizujte přes SFTP","f6_desc":"Sledujte migrace schema.sql vedle kódu v Python, PHP a Java ve Visual Git, nebo stahujte a nahrávejte produkční databáze SQLite a zálohy .sql přes SFTP a FTPS.","f6_badge":"Visual Git správa schémat &#183; Synchronizace .db záloh přes SFTP","workflow_title":"Jak vytvořit polyglotní SQLite aplikaci na Androidu","workflow_lead":"Jedna složka projektu, jeden soubor `app.db` a pět offline běhových prostředí v dokonalé souhře.","wf1_title":"Navrhněte tabulky, indexy a počáteční data v SQL Studiu","wf1_desc":"Vytvořte app.db ve složce projektu pomocí SQLite 3.54.1 DDL, typů STRICT, indexů FTS5 nebo importů CSV/JSON.","wf2_title":"Zapisujte nebo zpracovávejte záznamy přes Python, Java nebo Lua","wf2_desc":"Připojte se k 'app.db' přes Python sqlite3, Java jdbc:sqlite:app.db nebo Lua lsqlite3 bez instalace ovladačů.","wf3_title":"Servírujte dynamické webové UI přes lokální PHP PDO","wf3_desc":"Otevřete dashboard.php a pomocí new PDO('sqlite:app.db') vykreslete responzivní grafy a CRUD formuláře v prohlížeči se 3 viewporty.","wf4_title":"Auditujte živé tabulky nebo čistěte GB zálohy .sql","wf4_desc":"Klepněte kdykoli na app.db pro kontrolu stavu v 9 výstupních režimech nebo otevřete vícegigabajtové .sql dumpy v editoru velkých souborů.","wf_foot_note":"Nulová konfigurace ovladačů &#183; Python 3.11 + PHP 8.2 + Java 17 + Lua 5.4 + SQLite 3.54.1 offline","table_h2":"SuperCode Polyglotní SQLite Studio vs. jednojazyčná mobilní IDE","snippet_p":"<strong>Polyglotní SQLite Studio v SuperCode</strong> propojuje pět offline běhových prostředí s jedinou sdílenou databází .db na Androidu. Navrhujte schémata a indexy v SQL Studiu a dotazujte tentýž ACID soubor offline z Python 3.11 sqlite3, PHP 8.2 PDO, Java 17 JDBC a Lua 5.4 lsqlite3, zatímco upravujete vícegigabajtové .sql dumpy.","table_caption":"SROVNÁNÍ VÍCEJAZYČNÉHO VÝVOJE SQLITE APLIKACÍ NA ANDROIDU","th_0":"Vývojářský workflow","th_1":"SuperCode Polyglot IDE","th_2":"Jednojazyčná mobilní IDE","th_3":"Samostatné DB prohlížeče","th_4":"Cloudová IDE v prohlížeči","tr1_c0":"Sdílený .db v pracovním prostoru","tr1_c1":"SQL + Python + PHP + Java 17 + Lua offline","tr1_c2":"Zamčeno na 1 jazyk","tr1_c3":"Pouze SQL tabulka (bez kódu)","tr1_c4":"Vyžaduje placený cloudový VM","tr2_c0":"Java SQLite JDBC","tr2_c1":"Předinstalované jdbc:sqlite: (bez Maven/Gradle)","tr2_c2":"Ruční hledání .jar a parametrů","tr2_c3":"Nepodporováno","tr2_c4":"Pomalý start kontejneru","tr3_c0":"PHP PDO + Web UI","tr3_c1":"Offline PHP 8.2 PDO + HTTP ve 3 viewportech","tr3_c2":"Bez PHP serveru","tr3_c3":"Nepodporováno","tr3_c4":"Vyžaduje internet","tr4_c0":"Python + Data Science","tr4_c1":"sqlite3 + Pandas read_sql + Matplotlib","tr4_c2":"Bez SQL IDE a PHP náhledu","tr4_c3":"Nepodporováno","tr4_c4":"Dočasné úložiště","tr5_c0":"Vícegigabajtové .sql dumpy","tr5_c1":"Stránkovaný GB editor + Regex nahrazení","tr5_c2":"Padá při načtení &gt;50 MB textu","tr5_c3":"Neumí upravovat surové .sql dumpy","tr5_c4":"Karta prohlížeče zamrzne","faq_lead":"Často kladené dotazy ke sdílení souborů `.db` napříč jazyky a úpravám obřích `.sql` dumpů na Androidu.","faq1_q":"Musím si pro použití `jdbc:sqlite:app.db` v Java 17 stahovat soubor `.jar`?","faq1_a":"Ne! SuperCode má ovladač SQLite JDBC předinstalovaný přímo v offline classpath pro Java 17 &#8212; stačí napsat `DriverManager.getConnection(\"jdbc:sqlite:app.db\")` a klepnout na Spustit.","faq2_q":"Mohou Python, PHP, Java a Lua opravdu číst a zapisovat do naprosto stejného souboru `app.db`?","faq2_a":"Ano. Pokud jsou vaše soubory `.sql`, `.py`, `.php`, `.java` a `.lua` ve stejné složce pracovního prostoru (nebo odkazují na stejnou relativní cestu), všechny čtou a zapisují ACID transakce do totožného souboru `app.db` na disku.","faq3_q":"Jak v SuperCode použít SQLite ve skriptech Lua 5.4?","faq3_a":"Zavolejte `local sqlite3 = require('lsqlite3')` a `local db = sqlite3.open('app.db')`. Vestavěný `lsqlite3` je integrován přímo v offline běhovém prostředí Lua 5.4 v SuperCode se startem pod milisekundu.","faq4_q":"Otevře SuperCode databázový dump `.sql` o velikosti přes 1 GB bez pádu telefonu?","faq4_a":"Ano. Editor velkých souborů v SuperCode streamuje obří soubory `.sql`, `.csv` a `.log` přímo po stránkách z disku, místo aby je celé načítal do RAM &#8212; včetně regexového hledání/nahrazování a detekce kódování.","cta_h2":"Propojte SQL, Python, PHP, Java a Lua s jednou offline databází.","cta_desc":"Stáhněte si SuperCode IDE zdarma na Google Play &#8212; polyglotní SQLite studio, integrované ovladače a editace .sql v řádu GB."},"lua_game_oop":{"metaTitle":"Aplikace pro herní skriptování Lua na Androidu — Metatabulky, korutiny a příprava pro Love2D/Luau | SuperCode","metaDesc":"Procvičujte herní skriptování v Lua offline na Androidu za ~400µs. Prototypujte OOP třídy s metatabulkami, stavové automaty z korutin a modulární logiku pro Luau/Roblox i Love2D s AST doplňováním . vs : a 8 startovními skripty.","hero_tag":"NATIVNÍ LUA 5.4.7 &#183; OOP METATABULKY &#183; KORUTINOVÉ AUTOMATY &#183; ~400&#181;s","hero_h1":"Prototypujte <span class=\"text-gradient\">herní logiku Lua, metatabulky a korutiny</span> offline na Androidu.","hero_desc":"Ovládněte skriptovací vzory pro <strong>Roblox (Luau), Love2D, Defold a Solar2D</strong> kdekoli vás napadne myšlenka. Spouštějte <strong>nativní Lua 5.4.7</strong> za <strong>~400 mikrosekund</strong> s plným <strong>OOP přes metatabulky</strong>, kooperativními <strong>korutinami</strong> a <strong>AST doplňováním rozlišujícím metody <code>.</code> vs <code>:</code></strong>.","lgo_s1":"Nativní Lua 5.4.7","lgo_s2":"OOP přes metatabulky","lgo_s3":"Korutinové automaty","lgo_s4":"AST hlídač metod","wb_eyebrow":"INTERAKTIVNÍ WORKBENCH PRO HERNÍ LOGIKU LUA, METATABULKY A KORUTINY","sec_cap_title":"Vytvořeno pro herní skriptéry, moddery a nezávislé vývojáře prototypů","sec_cap_lead":"Desktopové herní enginy zabírají gigabajty, přitom 90 % vývoje herních mechanik stojí na čisté architektuře tabulek, metatabulkách, stavových automatech a matematice.","f1_title":"OOP třídy přes metatabulky a přetěžování vektorových operátorů","f1_desc":"Tvořte znovupoužitelné třídy Entity, Inventory a Vec2 pomocí __index, __newindex, konstruktorů __call, ladění __tostring a aritmetických metametod (__add, __sub, __mul, __eq) přesně jako v produkčních Lua enginech.","f1_badge":"__index &#183; __call &#183; __add &#183; Vlastní hierarchie tříd","f2_title":"Kooperativní korutinové stavové automaty (coroutine.*)","f2_desc":"Skriptujte vícefázové souboje s bossy, dialogové stromy, časové osy cutscén a časovače cooldownů přehledně pomocí coroutine.create, resume, yield, wrap a status &#8212; bez zamotaných pyramid zpětných volání.","f2_badge":"coroutine.yield &#183; Dialogové a AI automaty &#183; Běh ~400&#181;s","f3_title":"Offline AST doplňování rozlišující metody (. vs :)","f3_desc":"Záměna tečkových funkcí (Vec2.new) a dvojtečkových metod (player:take_damage()) je nejčastější chyba v Lua. Offline AST engine v SuperCode rozlišuje . od : jak ve standardní knihovně Lua, tak ve vašich tabulkách.","f3_badge":"Brání chybám nil self &#183; AST pro tabulky","f4_title":"Modulární složky entit a komponent přes require()","f4_desc":"Čleňte výpočty boje, tabulky lootu a chování nepřátel do samostatných modulů ve složkách src/, core/ a modules/ &#8212; přesně podle struktury Roblox ModuleScripts a projektů Love2D.","f4_badge":"Vícesouborové require() &#183; Podpora neuložených karet","f5_title":"8 spustitelných startovních skriptů včetně adventure.lua","f5_desc":"Otevřete vestavěný výběr šablon a ihned offline prozkoumejte adventure.lua, metatables.lua, tables.lua a guess.lua, včetně živých tahových vstupů přes io.read().","f5_badge":"adventure.lua &#183; metatables.lua &#183; Živé io.read()","f6_title":"Ochrana proti nekonečné herní smyčce a telemetrie paměti","f6_desc":"Experimentujete na mobilu se smyčkou while game.running do? Izolovaný limit paměti VM a časový limit běhu čistě zastaví zacyklené ticky a zobrazí statistiky v mikrosekundách a kilobajtech.","f6_badge":"Bezpečná smyčka &#183; Čas v &#181;s &#183; Telemetrie KB VM","workflow_title":"Jak procvičovat logiku herního skriptování na telefonu","workflow_lead":"Vytvořte, otestujte a vylaďte základní herní systémy cestou do práce a pak čisté Lua moduly jednoduše přeneste do PC enginu.","wf1_title":"Načtěte vestavěný herní skript nebo vytvořte moduly entit","wf1_desc":"Začněte z adventure.lua či metatables.lua nebo si v pracovním prostoru uspořádejte nové soubory jako player.lua, combat.lua a main.lua.","wf2_title":"Pište třídy s metatabulkami a doplňováním metod po dvojtečce","wf2_desc":"Napište : na instancích entit pro návrhy metod s parametrem self a klepnutím na Formátovat zarovnejte vnořené konstruktory tabulek.","wf3_title":"Simulujte tahy a ticky korutin za ~400 mikrosekund","wf3_desc":"Klepněte na Spustit &#9654; a otestujte vzorce boje, RNG šance dropu i živé volby hráče přes io.read() s odezvou pod milisekundu.","wf4_title":"Synchronizujte čisté Lua moduly do Love2D, Defold nebo na GitHub","wf4_desc":"Commitněte oddělené herní moduly přes Visual Git, aby si je váš desktopový projekt Love2D, Defold nebo Luau čistě stáhl.","wf_foot_note":"100% offline Lua 5.4.7 &#183; 8 startovních šablon &#183; 21klávesová lišta symbolů Lua","table_h2":"Herní Lua laboratoř SuperCode vs. běžné mobilní editory Lua","snippet_p":"<strong>Herní skriptovací studio Lua v SuperCode</strong> umožňuje vývojářům na Androidu prototypovat herní systémy offline v nativní Lua 5.4.7 se startem pod milisekundu. Procvičujte OOP s metatabulkami, přetěžování vektorových operátorů a korutinové stavové automaty pro Roblox/Luau i Love2D s AST doplňováním tečky versus dvojtečky, vícesouborovým <code>require()</code> a osmi vestavěnými Lua skripty.","table_caption":"SROVNÁNÍ MOBILNÍHO HERNÍHO SKRIPTOVÁNÍ A PROCVIČOVÁNÍ LUA","th_0":"Potřeba při skriptování her","th_1":"SuperCode Lua 5.4 Studio","th_2":"Zastaralé mobilní Lua aplikace","th_3":"Online Lua REPLy","th_4":"Pouze PC herní engine","tr1_c0":"Metatabulky a korutiny","tr1_c1":"Plná Lua 5.4.7 OOP + coroutine.yield (~400 &#181;s)","tr1_c2":"Zastaralá podmnožina Lua 5.2","tr1_c3":"Síťová latence při každém spuštění","tr1_c4":"Plný engine","tr2_c0":"Bezpečnost tečky vs. dvojtečky","tr2_c1":"Offline AST rozlišuje funkce . vs. metody :","tr2_c2":"Pouze prostý text","tr2_c3":"Bez AST doplňování","tr2_c4":"Desktopový plugin","tr3_c0":"Modulární ModuleScripts","tr3_c1":"Vícesložkové require() + chytré směrování main.lua","tr3_c2":"Jednosouborový poznámkový blok","tr3_c3":"Okno pro jeden snippet","tr3_c4":"Podporováno","tr4_c0":"Interaktivní testování tahů","tr4_c1":"Živá konzole io.read() + 8 vestavěných šablon","tr4_c2":"Statický vstup nebo žádný","tr4_c3":"Bez interaktivního stdin","tr4_c4":"GUI okno","tr5_c0":"Offline práce na cestách","tr5_c1":"100% připraveno pro režim Letadlo + Visual Git synchronizace","tr5_c2":"Liší se / zamčeno reklamami","tr5_c3":"Bez Wi-Fi nefunguje","tr5_c4":"Nevejde se do kapsy","faq_lead":"Odpovědi na dotazy k učení Lua pro Roblox/Luau, Love2D, metatabulkám a korutinám na Androidu.","faq1_q":"Přenese se procvičování Lua 5.4 v SuperCode přímo do Robloxu (Luau) a Love2D?","faq1_a":"Ano! Základní Lua tabulky, uzávěry, lexikální rozsah platnosti, metatabulky (`__index`, `__add`), korutiny, matematika a modulární skripty `return M` tvoří přesně ten základ, který sdílí Roblox Luau, Love2D, Defold, Solar2D i doplňky pro World of Warcraft či Garry's Mod.","faq2_q":"Umí SuperCode přímo vykreslovat 3D světy Robloxu nebo OpenGL okna Love2D?","faq2_a":"SuperCode se zaměřuje na rychlou oddělenou herní logiku, datově řízené RPG systémy, ukládání inventáře v SQLite/JSON a prototypování algoritmů v nativní konzoli &#8212; můžete tak doladit klíčové modulární skripty kdekoli a přes Git je synchronizovat do desktopového rendereru.","faq3_q":"Jak SuperCode pomáhá předcházet chybám metod `.` vs `:` v Lua OOP?","faq3_a":"Když napíšete `entity:` oproti `Entity.`, offline AST doplňování v SuperCode kontextově filtruje návrhy tak, abyste ihned viděli instanční metody definované dvojtečkou odděleně od statických funkcí modulu.","faq4_q":"Jsou součástí i startovní herní skripty pro offline studium?","faq4_a":"Ano. Přímo v aplikaci je integrováno osm spustitelných šablon Lua &#8212; včetně `adventure.lua`, `guess.lua`, `metatables.lua` a `tables.lua` &#8212; a všechny fungují 100% offline.","cta_h2":"Posuňte své herní skriptování v Lua kdekoli.","cta_desc":"Stáhněte si SuperCode IDE zdarma na Google Play &#8212; nativní ~400&#181;s Lua 5.4.7, OOP přes metatabulky, korutiny a 8 vestavěných šablon."},"lua_ext_mods":{"metaTitle":"Lua cjson, lsqlite3, lfs a socket.http na Androidu — 11+ vestavěných modulů | SuperCode","metaDesc":"Načítejte cjson, lsqlite3, lfs (LuaFileSystem), crypto/sha2, regex, base64, socket.http a inspect offline na Androidu bez nastavování luarocks v nativním Lua 5.4.7 IDE SuperCode.","hero_tag":"BEZ LUAROCKS &#183; CJSON &#183; LSQLITE3 &#183; LFS &#183; CRYPTO &#183; SOCKET.HTTP","hero_h1":"11+ <span class=\"text-gradient\">vestavěných offline modulů Lua</span> připravených přes <code>require()</code>.","hero_desc":"Standardní Lua je záměrně minimalistická a kompilace C modulů na telefonu bývá bolestivá. SuperCode proto přímo do svého offline běhového prostředí <strong>Lua 5.4.7</strong> integruje <strong><code>cjson</code>, <code>lsqlite3</code>, <code>lfs</code>, <code>crypto</code>, <code>regex</code>, <code>base64</code>, <code>socket.http</code> a <code>inspect</code></strong>.","lem_s1":"Vestavěných modulů","lem_s2":"a dkjson Pretty","lem_s3":"lsqlite3 :named","lem_s4":"Bez kompilace C","wb_eyebrow":"WORKBENCH PRO ROZŠIŘUJÍCÍ MODULY LUA V PLNÉ VÝBAVĚ","sec_cap_title":"Reálné skriptování v Lua daleko za hranicí holé standardní knihovny","sec_cap_lead":"Vytvářejte REST klienty, lokální editory uložených her v SQLite, dávkové nástroje pro adresáře a JSON skripty ve stylu OpenResty/Redis, aniž byste sáhli na kompilátor C.","f1_title":"Serializace cjson a dkjson ihned po vybalení","f1_desc":"Parsujte a generujte JSON payloady okamžitě offline pomocí require('cjson') nebo require('dkjson') &#8212; včetně cjson.encode_pretty() pro čitelné konfigurační soubory a ladění API.","f1_badge":"cjson.encode &#183; encode_pretty &#183; cjson.decode","f2_title":"Vestavěný databázový engine lsqlite3 / sqlite3","f2_desc":"Otevírejte :memory: nebo trvalé soubory .db v pracovním prostoru přes require('lsqlite3') nebo require('sqlite3'). Podporuje připravené dotazy, vazbu pojmenovaných parametrů :named, iterátory db:nrows() a ACID transakce.","f2_badge":"lsqlite3 &#183; Trvalá synchronizace .db &#183; Sdíleno se SQL IDE","f3_title":"Automatizace souborů a adresářů s LuaFileSystem (lfs)","f3_desc":"Automatizujte dávkové přejmenování a audity assetů napříč složkou projektu pomocí require('lfs') &#8212; včetně lfs.dir(), lfs.mkdir(), lfs.currentdir() a kontroly velikosti či času v lfs.attributes().","f3_badge":"lfs.dir &#183; lfs.mkdir &#183; lfs.attributes","f4_title":"Bezpečnostní sada crypto, sha2, md5 a base64","f4_desc":"Podepisujte webhooky, ověřujte kontrolní součty souborů a generujte unikátní ID offline pomocí SHA-256, SHA-512, MD5, HMAC s klíčem, crypto.uuid() a kódování/dekódování Base64 podle RFC.","f4_badge":"SHA-256/512 &#183; HMAC &#183; crypto.uuid() &#183; base64","f5_title":"socket.http, plný regex a inspect tabulek","f5_desc":"Testujte živá REST API přes require('socket.http'), spouštějte plné PCRE/POSIX regulární výrazy přes require('regex'), když vzory Lua nestačí, a přehledně vypisujte vnořené tabulky pomocí require('inspect').","f5_badge":"socket.http &#183; Plný regex &#183; inspect(table)","f6_title":"Cloudové Lua směrování pro C moduly lpeg a luv","f6_desc":"Pracujete s PEG parsery v lpeg nebo asynchronními smyčkami libuv v luv? SuperCode automaticky zabalí moduly vašeho projektu do cloudového Lua runtime a namapuje tracebacky 1:1 do editoru.","f6_badge":"Cloud lpeg a luv &#183; Automatické balení více souborů","workflow_title":"Jak tvořit datově řízené nástroje v Lua na Androidu","workflow_lead":"Spojte JSON, SQLite, automatizaci souborového systému a SQL inspekci v jednom jednotném pracovním prostoru.","wf1_title":"Importujte kterýkoli z 11+ vestavěných modulů napřímo","wf1_desc":"Napište standardní require('cjson'), require('lsqlite3'), require('lfs') nebo require('crypto') na začátek souboru .lua &#8212; bez jakékoli instalace.","wf2_title":"Čtěte a zapisujte reálné soubory JSON a SQLite offline","wf2_desc":"Spusťte skript během milisekund; všechny soubory .db, .json nebo .log zapsané na disk se ihned propíšou do stromu projektu v Průzkumníku.","wf3_title":"Prohlížejte databáze lsqlite3 vizuálně napříč nástroji","wf3_desc":"Klepněte v Průzkumníku na vygenerovaný soubor .db a procházejte schémata či spouštějte analytické dotazy v 9režimovém SQL Studiu SuperCode.","wf4_title":"Využijte specializované C moduly v cloudu, když je třeba","wf4_desc":"Pokud skript importuje externí C moduly jako lpeg nebo luv, spusťte jej online s automatickým zabalením všech souborů modulu.","wf_foot_note":"Předinstalovaná offline rozšíření &#183; Nulové chyby gcc/luarocks &#183; Sdílená synchronizace pracovního prostoru","table_h2":"Vestavěné Lua moduly SuperCode vs. holá Lua a mobilní porty","snippet_p":"<strong>SuperCode IDE pro Android</strong> dodává nativní Lua 5.4.7 s více než jedenácti předintegrovanými rozšiřujícími moduly dostupnými offline přes <code>require()</code> &#8212; včetně <code>cjson</code>, <code>dkjson</code>, <code>lsqlite3</code>, <code>lfs</code> (LuaFileSystem), <code>crypto</code>, <code>sha2</code>, <code>md5</code>, <code>base64</code>, <code>regex</code>, <code>socket.http</code> a <code>inspect</code> &#8212; čímž odpadá mobilní kompilace přes luarocks.","table_caption":"MATICE DOSTUPNOSTI ROZŠIŘUJÍCÍCH MODULŮ LUA PRO ANDROID","th_0":"Rozšiřující modul","th_1":"Název pro require()","th_2":"Offline stav v SuperCode","th_3":"Standardní Lua CLI","th_4":"Aplikace Java LuaJ","tr1_c0":"Rychlý JSON + Pretty Print","tr1_c1":"cjson / dkjson","tr1_c2":"Vestavěné offline","tr1_c3":"Vyžaduje luarocks gcc","tr1_c4":"Chybí","tr2_c0":"Vestavěné SQLite 3","tr2_c1":"lsqlite3 / sqlite3","tr2_c2":"Vestavěné offline (:named + .db)","tr2_c3":"Vyžaduje hlavičky C","tr2_c4":"Chybí","tr3_c0":"Souborový systém a adresáře","tr3_c1":"lfs","tr3_c2":"Vestavěné offline (dir/mkdir/attr)","tr3_c3":"Vyžaduje luarocks","tr3_c4":"Chybí","tr4_c0":"Hashování, HMAC a UUID","tr4_c1":"crypto / sha2 / md5 / base64","tr4_c2":"Vestavěné offline","tr4_c3":"Externí knihovna C","tr4_c4":"Chybí","tr5_c0":"HTTP, Regex a ladění","tr5_c1":"socket.http / regex / inspect","tr5_c2":"Vestavěné (+ Cloud lpeg/luv)","tr5_c3":"Ruční sestavení","tr5_c4":"Chybí","faq_lead":"Časté dotazy k používání cjson, lsqlite3, LuaFileSystem a modulů luarocks na Androidu.","faq1_q":"Musím si pro použití `cjson`, `lsqlite3` nebo `lfs` instalovat luarocks nebo kompilátor C?","faq1_a":"Ne. Všech 11+ základních aliasů rozšíření (`cjson`, `dkjson`, `lsqlite3`, `sqlite3`, `lfs`, `crypto`, `sha2`, `md5`, `base64`, `regex`, `socket.http` a `inspect`) je předintegrováno přímo v SuperCode a ihned funguje přes `require()`.","faq2_q":"Může `lsqlite3` sdílet stejný soubor `.db` s Pythonem, PHP nebo SQL IDE v SuperCode?","faq2_a":"Ano! Databáze `.db` vytvořená pomocí `lsqlite3` ve složce projektu je standardní binární soubor SQLite 3, který lze přímo dotazovat v SQL Studiu SuperCode, Python `sqlite3`, PHP `PDO` nebo Java JDBC.","faq3_q":"Podporuje `cjson` formátovaný výpis pretty-print pro konfigurační soubory?","faq3_a":"Ano. Kromě standardního `cjson.encode()` a `cjson.decode()` nabízí SuperCode funkci `cjson.encode_pretty()`, takže můžete čistě odsazený JSON kontrolovat nebo ukládat offline.","faq4_q":"Co se stane, když můj skript vyžaduje `lpeg` nebo `luv`?","faq4_a":"Když jste připojeni k internetu, SuperCode rozpozná specializované nativní C moduly jako `lpeg` nebo `luv` a automaticky přesměruje celý váš vícesouborový projekt do svého cloudového prostředí Lua.","cta_h2":"Spouštějte Lua 5.4 v plné výbavě na Androidu.","cta_desc":"Získejte SuperCode IDE zdarma na Google Play &#8212; nativní Lua 5.4.7 s vestavěnými cjson, lsqlite3, lfs, crypto a socket.http."},"lua_54_modern":{"metaTitle":"Interpret Lua 5.4 pro Android — 64bitové bitové operátory,  a vícesložkové require() | SuperCode","metaDesc":"Přejděte ze zastaralých mobilních aplikací s Lua 5.2 na skutečný nativní Lua 5.4.7 pro Android. Spouštějte 64bitové bitové operátory, celočíselné dělení //, proměnné  a , string.pack, utf8 a vícesložkové require().","hero_tag":"SKUTEČNÝ NATIVNÍ LUA 5.4.7 &#183; 64BIT. BITOVÉ OPERACE &#183; &lt;CONST&gt; &amp; &lt;CLOSE&gt; &#183; VÍCE SLOŽEK","hero_h1":"Skutečný <span class=\"text-gradient\">nativní Lua 5.4.7</span> vs. zastaralé mobilní aplikace s Lua 5.2.","hero_desc":"Většina Lua aplikací na Google Play obaluje opuštěné javové enginy LuaJ 5.2, které selhávají na moderní syntaxi. SuperCode spouští <strong>skutečný nativní Lua 5.4.7</strong> offline &#8212; odemyká <strong>64bitové bitové operace (<code>&amp; | ~ &lt;&lt; &gt;&gt;</code>)</strong>, <strong>celočíselné dělení <code>//</code></strong>, <strong><code>&lt;const&gt;</code> / <code>&lt;close&gt;</code></strong> a vícesložkové <strong><code>require()</code></strong> bez nastavování.","l54_s1":"Nativní VM","l54_s2":"// &amp; bitové operace","l54_s3":"RAII dle rozsahu","l54_s4":"Auto package.path","wb_eyebrow":"PRACOVNÍ PROSTŘEDÍ PRO MODERNÍ SYNTAXI LUA 5.4.7 A VÍCESLOŽKOVÉ BALÍČKY","sec_cap_title":"Každé moderní vylepšení jazyka Lua 5.3 a 5.4, plně offline","sec_cap_lead":"Pište moderní, učebnicově přesný kód v Lua 5.4 a vícesložkové balíčky bez obcházení syntaktických chyb.","f1_title":"Nativní 64bitová celá čísla, dělení // a bitové operátory","f1_desc":"Manipulujte s bitovými maskami, příznaky, hashi a souřadnicemi dlaždic přímo pomocí &amp;, |, ~ (XOR/NOT), &lt;&lt;, &gt;&gt; a celočíselného dělení // &#8212; na přesných 64bitových celých číslech se znaménkem místo nepřesných floatů.","f1_badge":"&amp; | ~ &lt;&lt; &gt;&gt; &#183; // celočíselné dělení &#183; 64bit. math.type()","f2_title":"&lt;const&gt; při kompilaci a deterministický úklid &lt;close&gt;","f2_desc":"Vynuťte neměnné lokální proměnné při kompilaci pomocí &lt;const&gt; a navazujte deterministické metametody __close přes &lt;close&gt;, aby se otevřené soubory, zámky a SQLite dotazy uvolnily automaticky při opuštění bloku nebo chybě.","f2_badge":"local x &lt;const&gt; &#183; local f &lt;close&gt; &#183; __close RAII","f3_title":"Binární string.pack / unpack a vestavěné utf8","f3_desc":"Kódujte a dekódujte binární struktury s určením endianity pomocí string.pack, string.unpack a string.packsize a bezpečně procházejte vícejazyčné Unicode řetězce s utf8.codes, utf8.len a utf8.char.","f3_badge":"string.pack / unpack &#183; utf8.codes &#183; Generační GC","f4_title":"Automatický package.path napříč 6 standardními podsložkami","f4_desc":"SuperCode automaticky konfiguruje package.path pro kořen projektu i složky src/, lib/, modules/, core/ a utils/ (pro ?.lua i ?/init.lua) a načítá uložené soubory i neuložené karty editoru.","f4_badge":"src/ &#183; lib/ &#183; modules/ &#183; core/ &#183; utils/ &#183; ?/init.lua","f5_title":"Chytré vyhledání vstupního bodu main.lua / init.lua","f5_desc":"Upravujete podmodul končící na return M? Klepněte na Spustit &#9654; přímo v core/codec.lua bez přepínání karet &#8212; SuperCode najde vstupní skript main.lua nebo init.lua vašeho projektu a plynule ho spustí.","f5_badge":"Spuštění z libovolné karty modulu &#183; Auto-detekce vstupu","f6_title":"Klikací stack trace 1:1 a generační GC","f6_desc":"Běžte na generačním garbage collectoru Lua 5.4.7 s nízkou latencí, studeným startem pod milisekundu a klikacím výpisem zásobníku, který skočí přímo na přesný soubor a řádek napříč složkami.","f6_badge":"Trasování napříč moduly &#183; ~400 &#181;s studený start","workflow_title":"Jak strukturovat vícesouborové balíčky Lua 5.4 na Androidu","workflow_lead":"Přejděte čistě od jednoho skriptu ke strukturovanému vícesložkovému projektu v Lua.","wf1_title":"Vytvořte modulární složky (src/, lib/, core/)","wf1_desc":"Umístěte vstupní bod do main.lua a uspořádejte znovupoužitelné moduly do src/, lib/, modules/, core/ nebo utils/ &#8212; bez úprav LUA_PATH.","wf2_title":"Pište kód s 64bit. bitovými operacemi, &lt;const&gt; a &lt;close&gt;","wf2_desc":"Využívejte moderní konstrukce //, &gt;&gt;, &amp;, &lt;const&gt; a &lt;close&gt; s živou kontrolou syntaxe Error Radar a offline formátováním Lua.","wf3_title":"Spouštějte z main.lua nebo z podmodulu","wf3_desc":"Stiskněte Spustit i při úpravě knihovního souboru s return M &#8212; automatika spustí main.lua včetně neuložených změn.","wf4_title":"Verzujte a publikujte čisté balíčky Lua","wf4_desc":"Zkontrolujte rozdíly v celém stromu modulů ve Visual Git a odešlete je přímo na GitHub, GitLab nebo vzdálený server přes SFTP.","wf_foot_note":"Skutečný C runtime Lua 5.4.7 &#183; Podpora ?.lua a ?/init.lua &#183; Synchronizace neuložených bufferů","table_h2":"Nativní Lua 5.4.7 (SuperCode) vs. zastaralé aplikace LuaJ 5.2 pro Android","snippet_p":"<strong>Nativní interpret Lua 5.4.7 v SuperCode</strong> překonává staré aplikace s LuaJ 5.2 pro Android tím, že spouští skutečný 64bitový Lua 5.4 offline za ~400 mikrosekund. Podporuje celočíselné dělení (<code>//</code>), bitové operátory, proměnné <code>&lt;const&gt;</code> a <code>&lt;close&gt;</code>, <code>string.pack</code>, <code>utf8</code> a vícesložkové směrování <code>require()</code>.","table_caption":"LUA 5.4.7 VS. ZASTARALÉ MOBILNÍ INTERPRETY LUA","th_0":"Jazyková funkce","th_1":"SuperCode (nativní Lua 5.4.7)","th_2":"Aplikace Java LuaJ 5.2 pro Android","th_3":"Jednosouborová webová dema","th_4":"Desktopový Lua 5.4","tr1_c0":"Bitové operace a dělení //","tr1_c1":"Nativní &amp; | ~ &lt;&lt; &gt;&gt; a 64bit. //","tr1_c2":"Chyba syntaxe (vyžaduje bit32)","tr1_c3":"Pouze online","tr1_c4":"Podporováno","tr2_c0":"&lt;const&gt; a &lt;close&gt; RAII","tr2_c1":"Plná podpora Lua 5.4 (__close)","tr2_c2":"Nepodporováno","tr2_c3":"Liší se dle webu","tr2_c4":"Podporováno","tr3_c0":"Binární pack a UTF-8","tr3_c1":"Vestavěné string.pack/unpack + utf8","tr3_c2":"Chybí","tr3_c3":"Pouze online","tr3_c4":"Podporováno","tr4_c0":"Vícesložkové require()","tr4_c1":"Auto-napojení root, src/, lib/, core/, utils/","tr4_c2":"Selhává na relativních cestách","tr4_c3":"Pouze jeden soubor","tr4_c4":"Ruční LUA_PATH","tr5_c0":"Spuštění z karty modulu","tr5_c1":"Auto-spuštění main.lua / init.lua","tr5_c2":"Spustí modul a nic nevypíše","tr5_c3":"Nelze použít","tr5_c4":"Ruční cíl v CLI","faq_lead":"Dotazy k bitovým operátorům v Lua 5.4, proměnným `&lt;close&gt;` a vícesložkovému `require()` na Androidu.","faq1_q":"Proč `//` a `&amp;` v jiných Lua aplikacích pro Android hlásí syntaktickou chybu?","faq1_a":"Mnoho starších mobilních aplikací používá LuaJ, javový port zamrzlý kolem verze Lua 5.2, tedy před zavedením nativních 64bitových celých čísel, dělení `//` a bitových operátorů v Lua 5.3/5.4. SuperCode spouští skutečný nativní Lua 5.4.7.","faq2_q":"Jak funguje vícesouborové `require()` bez nastavování `LUA_PATH`?","faq2_a":"SuperCode automaticky nastaví `package.path` pro vyhledávání v kořenu projektu i ve složkách `src/`, `lib/`, `modules/`, `core/` a `utils/` pro `?.lua` i `?/init.lua` &#8212; a před spuštěním dokonce synchronizuje neuložené otevřené karty.","faq3_q":"Co se stane, když stisknu Spustit při úpravě `lib/math_ext.lua` místo `main.lua`?","faq3_a":"Pokud aktivní soubor vrací tabulku modulu (`return M`) a v kořenu projektu existuje `main.lua` nebo `init.lua`, SuperCode automaticky spustí vstupní skript, abyste nemuseli neustále přepínat karty.","faq4_q":"Funguje `&lt;close&gt;` v Lua 5.4, i když uvnitř bloku dojde k chybě?","faq4_a":"Ano. Stejně jako ve standardním desktopovém Lua 5.4.7 každá lokální proměnná označená `&lt;close&gt;` deterministicky zavolá metametodu `__close(self, err)` své metatabulky, ať blok skončí běžně, nebo přes `error()`.","cta_h2":"Vyzkoušejte skutečný nativní Lua 5.4.7 na Androidu.","cta_desc":"Nainstalujte si SuperCode IDE zdarma z Google Play &#8212; 64bitové bitové operace, proměnné &lt;close&gt; a bezproblémové vícesložkové require()."},"lua_learn":{"metaTitle":"Naučte se Lua offline na Androidu — Zdarma aplikace, formátovač a export PDF | SuperCode","metaDesc":"Učte se programovat v Lua offline na telefonu nebo tabletu s Androidem. Bez přihlášení — obsahuje 8 spustitelných ukázek Lua, živý vstup io.read(), našeptávání . vs :, formátovač na 1 klepnutí a export do A4 PDF.","hero_tag":"BEZ PŘIHLÁŠENÍ &#183; 100% OFFLINE &#183; 8 UKÁZEK LUA &#183; FORMÁTOVAČ A A4 PDF","hero_h1":"Naučte se <span class=\"text-gradient\">programovat v Lua offline</span> na svém Android telefonu.","hero_desc":"Přeskočte registrační zdi, cloudové fronty i kvízové doplňovačky. Pište skutečný kód <strong>Lua 5.4</strong> v <strong>režimu Letadlo</strong> s <strong>8 spustitelnými ukázkami</strong>, živým vstupem <strong><code>io.read()</code></strong>, <strong>formátovačem Lua na 1 klepnutí</strong> a <strong>exportem do A4 PDF se zvýrazněním syntaxe</strong>.","lln_s1":"Běh v režimu Letadlo","lln_s2":"Startovací skripty","lln_s3":"Formátovač Lua","lln_s4":"Export úkolů","wb_eyebrow":"OFFLINE PROSTŘEDÍ PRO VÝUKU LUA PRO ZAČÁTEČNÍKY","sec_cap_title":"Vše, co samouci a studenti potřebují ke zvládnutí Lua","sec_cap_lead":"Lua je proslulá čistou a čitelnou syntaxí &#8212; a se SuperCode je psaní, formátování i ladění Lua na dotykovém displeji přirozené.","f1_title":"Okamžité spuštění v režimu Letadlo bez přihlášení","f1_desc":"Spusťte SuperCode a proveďte své první print('Hello, Lua!') za méně než sekundu &#8212; bez zakládání účtu, bez internetu a s odezvou ~400 mikrosekund na každé klepnutí na Spustit &#9654;.","f1_badge":"Bez registrace &#183; Funguje v letadle i při dojíždění","f2_title":"8 spustitelných ukázek Lua přímo na liště nástrojů","f2_desc":"Prozkoumejte praktické šablony pro proměnné, cykly, hádací hry (guess.lua), jednotné tabulky (tables.lua), uzávěry, OOP metatabulky (metatables.lua) a textové adventury (adventure.lua).","f2_badge":"guess.lua &#183; tables.lua &#183; metatables.lua &#183; adventure.lua","f3_title":"Interaktivní konzole io.read() pro reálná cvičení","f3_desc":"Vytvářejte kalkulačky, kvízy a RPG nabídky, které se čistě pozastaví pro živý vstup uživatele přes io.read('*l') a tonumber() v přiblížitelné rozdělené konzoli.","f3_badge":"Živé vstupy stdin &#183; Nastavitelný zoom písma konzole","f4_title":"Offline formátovač bloků a tabulek Lua na 1 klepnutí","f4_desc":"Vnořené bloky if/then/elseif/end a víceřádkové tabulky Lua mohou být na malé obrazovce nepřehledné. Klepněte jednou na Formátovat a zarovnejte funkce, cykly, repeat/until i tabulky {} offline.","f4_badge":"100% offline formátovač Lua &#183; Čisté odsazení","f5_title":"Error Radar a vyhrazená řada symbolů Lua na klávesnici","f5_desc":"Odhalte chybějící end nebo then včas díky značkám Error Radar na okraji a pište operátory Lua (~=, .., #, --, {}, []) jedním klepnutím z výsuvné symbolové lišty.","f5_badge":"~= &#183; .. &#183; # &#183; -- přepínač komentářů &#183; Error Radar","f6_title":"Nativní export do A4 PDF se zvýrazněním syntaxe","f6_desc":"Odevzdáváte úkol ze skriptování nebo si ukládáte studijní materiály? Exportujte jakýkoli .lua skript přímo do ostrého neproporcionálního A4 PDF offline a prohlédněte si ho ve vestavěném prohlížeči PDF.","f6_badge":"Uložit jako .pdf &#183; 8 světlých a tmavých motivů šetrných k očím","workflow_title":"Začněte programovat v Lua na Androidu za méně než 60 sekund","workflow_lead":"Bez konfigurace, stahování SDK nebo příkazů v terminálu.","wf1_title":"Otevřete vestavěnou šablonu nebo vytvořte hello.lua","wf1_desc":"Načtěte jednu z 8 vestavěných ukázek Lua, abyste viděli práci s tabulkami a funkcemi, nebo založte nový soubor .lua.","wf2_title":"Pište rychle s ~=, .. a našeptáváním tabulek","wf2_desc":"Použijte 21klávesovou lištu symbolů a offline AST návrhy pro string./table./math. pro čistý kód bez překlepů.","wf3_title":"Spusťte offline a otestujte živé vstupy io.read()","wf3_desc":"Klepněte na Spustit &#9654; pro okamžitý výstup, odpovídejte živě v konzoli a při chybě si prohlédněte jasné tipy s čísly řádků.","wf4_title":"Automaticky formátujte a exportujte poznámky do A4 PDF","wf4_desc":"Klepnutím na Formátovat uhlaďte odsazení bloků a poté exportujte A4 PDF se zvýrazněním syntaxe nebo odešlete pokrok na GitHub.","wf_foot_note":"Lehká aplikace 40,2 MB &#183; 8 optických studiových motivů &#183; 32 jazyků rozhraní","table_h2":"SuperCode vs. kvízové aplikace a prosté textové editory Lua","snippet_p":"<strong>SuperCode</strong> je lehká, pro začátečníky přívětivá offline aplikace pro programování v Lua na Androidu bez nutnosti přihlášení. Spojuje nativní interpret Lua 5.4.7 a živou konzoli <code>io.read()</code> s osmi spustitelnými startovacími skripty, diagnostikou Error Radar, offline formátováním na jedno klepnutí a nativním exportem úkolů do A4 PDF.","table_caption":"VÝUKA LUA NA ANDROIDU: SROVNÁNÍ FUNKCÍ","th_0":"Výuková funkce","th_1":"SuperCode Lua Studio","th_2":"Herní kvízové aplikace","th_3":"Prosté textové editory","th_4":"Webová Lua hřiště","tr1_c0":"Offline spouštění","tr1_c1":"100% offline nativní Lua 5.4.7 (~400 &#181;s)","tr1_c2":"Zamčeno za loginem/sítí","tr1_c3":"Neumí spouštět skripty","tr1_c4":"Vyžaduje internet","tr2_c0":"Interaktivní vstup","tr2_c1":"Živá rozdělená konzole io.read()","tr2_c2":"Klepání na možnosti v testu","tr2_c3":"Žádný","tr2_c4":"Statický nebo rozbitý","tr3_c0":"Úprava kódu","tr3_c1":"Offline formátovač bloků a tabulek Lua na 1 klepnutí","tr3_c2":"Nelze použít","tr3_c3":"Ruční mezery","tr3_c4":"Zřídka součástí","tr4_c0":"Úkoly a poznámky","tr4_c1":"Vestavěný export A4 PDF (monospace) + prohlížeč","tr4_c2":"Žádné","tr4_c3":"Sdílení prostého textu","tr4_c4":"Pouze tisk z prohlížeče","tr5_c0":"Prostor pro růst","tr5_c1":"11+ modulů (cjson/SQLite), více souborů a Git","tr5_c2":"Končí u základní syntaxe","tr5_c3":"Bez runtime","tr5_c4":"Bez lokálních souborů","faq_lead":"Časté dotazy začátečníků a studentů učících se Lua offline na Androidu.","faq1_q":"Je Lua dobrý první programovací jazyk pro výuku na telefonu?","faq1_a":"Ano! Lua má jen 22 vyhrazených klíčových slov a místo složité interpunkce používá běžná anglická slova jako `function`, `then`, `and`, `or` a `end` &#8212; na mobilu se tak čte i píše mimořádně rychle.","faq2_q":"Funguje SuperCode úplně offline bez vytváření účtu?","faq2_a":"Na 100 %. Neexistuje žádná přihlašovací obrazovka a nativní engine Lua 5.4.7, 8 startovacích šablon, AST našeptávání, formátovač Lua i exportér do A4 PDF fungují offline v režimu Letadlo.","faq3_q":"Jak na Androidu rychle napsat `~=` (nerovná se) a `..` (spojení řetězců)?","faq3_a":"Dotyková programovací lišta v SuperCode sedí přímo nad klávesnicí a nabízí vyhrazené operátory Lua, závorky, klávesy odsazení a přepínač komentářů `--`, takže nikdy nehledáte ve vedlejších rozloženích symbolů.","faq4_q":"Mohu ve stejné aplikaci přejít od začátečnických skriptů k vícesouborovým hrám nebo SQLite nástrojům?","faq4_a":"Ano. Kdykoli budete připraveni, můžete projekty rozdělit do složek pomocí `require()`, využít vestavěné moduly `cjson` a `lsqlite3` a odesílat repozitáře přes Visual Git.","cta_h2":"Napište svůj první skript v Lua offline ještě dnes.","cta_desc":"Stáhněte si SuperCode IDE zdarma na Google Play &#8212; bez registrace, s 8 šablonami Lua, offline formátovačem a exportem do PDF."},"sh_noroot_runner":{"metaTitle":"Spouštějte .sh Shell skripty na Androidu bez rootu — Žádné Permission denied | SuperCode","metaDesc":"Spouštějte linuxové skripty .sh a .bash přímo ze složek sdíleného úložiště Androidu bez rootu a bez chyb 'chmod +x: Permission denied'. Podporuje set -euo pipefail, getopts, read -p a vkládání více skriptů přes source.","hero_tag":"BEZ ROOTU &#183; BEZ PERMISSION DENIED &#183; SYNCHRONIZACE $PWD &#183; ŽIVÝ VSTUP READ STDIN","hero_h1":"Spouštějte <span class=\"text-gradient\"><code>.sh</code> Shell skripty na Androidu bez rootu</span> a bez chyb <code>chmod</code>.","hero_desc":"Pokus o spuštění <code>./script.sh</code> v interním úložišti Androidu běžně selže s chybou <strong><code>Permission denied</code></strong> kvůli připojení <code>noexec</code> na úrovni OS. SuperCode spouští skripty <strong><code>.sh</code>, <code>.bash</code>, <code>.zsh</code> a <code>.ksh</code></strong> čistě bez rootu a kotví <strong><code>$PWD</code></strong> k vaší skutečné složce.","snr_s1":"Žádné chyby chmod","snr_s2":"Sync reálné složky","snr_s3":"Živá konzole stdin","snr_s4":"Chybové řádky 1:1","wb_eyebrow":"PROSTŘEDÍ PRO SPOUŠTĚNÍ .SH SKRIPTŮ NA ANDROIDU BEZ ROOTU","sec_cap_title":"Proč běžné terminálové aplikace na `/sdcard` selhávají &#8212; a jak to řeší SuperCode","sec_cap_lead":"Pište skripty v pohodlných sdílených složkách projektů, snadno předávejte CLI přepínače a spouštějte bezpečně bez rootování zařízení.","f1_title":"Bezpečné obejití omezení noexec ve sdíleném úložišti (bez rootu)","f1_desc":"Android připojuje /storage/emulated/0 a Stažené soubory s příznakem noexec, což blokuje chmod +x a ./script.sh. SuperCode zprostředkuje spuštění v čistém sandboxu bez rootu a plynule zrcadlí soubory vašeho pracovního prostoru.","f1_badge":"Bez rootu &#183; Funguje ve sdílených složkách projektu","f2_title":"set -euo pipefail, trap, getopts a aritmetika","f2_desc":"Pište seriózní automatizační skripty se striktními příznaky chyb (set -euo pipefail), úklidovými háčky EXIT/ERR trap, smyčkami příznaků getopts, aritmetikou (( count++ )), funkcemi a heredoc šablonami &lt;&lt;EOF.","f2_badge":"set -euo pipefail &#183; trap &#183; getopts &#183; &lt;&lt;EOF","f3_title":"Direktivy # @args pro CLI a interaktivní vstup read -p","f3_desc":"Testujte poziční argumenty ($1, $@) bez opakovaného psaní obalových příkazů přidáním # @args --env prod na začátek skriptu a odpovídejte na živé výzvy read -r -p přímo v rozdělené konzoli.","f3_badge":"Přepínače # @args &#183; Živý read -p stdin &#183; 6 šablon","f4_title":"Propojení více souborů přes source a směrování main.sh","f4_desc":"Rozdělte sdílené logování a konfigurační proměnné do lib/common.sh pomocí source nebo tečky (.). Klepnutí na Spustit uvnitř pomocného souboru automaticky vybere a spustí main.sh nebo run.sh.","f4_badge":"source ./lib.sh &#183; Auto směrování main.sh / run.sh","f5_title":"Diagnostika $LINENO 1:1 a tlačítko Stop pro celý strom procesů","f5_desc":"Syntaktické chyby shellu a řádky s nenulovým návratovým kódem se mapují 1:1 zpět na otevřený soubor skriptu, zatímco 120sekundový hlídač stromu procesů umožní jediným klepnutím čistě ukončit zaseknuté podprocesy.","f5_badge":"Přesné mapování řádků &#183; Čisté ukončení subshellů","f6_title":"Offline formátovač Shellu na 1 klepnutí a nápověda expanzí","f6_desc":"Automaticky odsaďte vnořené bloky if/elif/fi, case/esac a while/done offline jediným klepnutím spolu s AST nápovědou expanze parametrů ${var:-default} a rychlými klávesami | &amp;&amp; &gt;&amp;2.","f6_badge":"Offline .sh formátovač &#183; ${var:-default} AST","workflow_title":"Jak upravovat a spouštět skripty `.sh` na Androidu bez rootu","workflow_lead":"Od staženého souboru `.sh` k čistému spuštění na čtyři klepnutí.","wf1_title":"Otevřete libovolný `.sh` skript ve sdíleném úložišti nebo projektu","wf1_desc":"Otevřete složku ve Stažených souborech nebo Dokumentech &#8212; není třeba skripty přesouvat do skrytých soukromých složek aplikací ani spouštět chmod.","wf2_title":"Naformátujte bloky a nastavte volitelné CLI argumenty","wf2_desc":"Klepnutím na Formátovat srovnejte odsazení a volitelně přidejte řádek komentáře `# @args` pro předání přepínačů `$1` / `getopts`.","wf3_title":"Spusťte offline se živým stdin pro read a synchronizací souborů","wf3_desc":"Klepnutím na Spustit &#9654; skript ihned proveďte, reagujte na interaktivní výzvy `read` a sledujte, jak se výstupní soubory synchronizují zpět do Průzkumníka.","wf4_title":"Odešlete ověřené skripty na linuxové servery nebo na Git","wf4_desc":"Po lokálním otestování nahrajte skripty přes SFTP (se zachováním spustitelných bitů 0755) nebo je commitněte do repozitáře přes Visual Git.","wf_foot_note":"Podporuje .sh &#183; .bash &#183; .zsh &#183; .ksh &#183; 6 vestavěných startovacích šablon Shellu","table_h2":"SuperCode bezrootový spouštěč `.sh` vs. obcházení v běžném terminálu","snippet_p":"<strong>Spouštěč Shell skriptů SuperCode</strong> provádí linuxové skripty <code>.sh</code>, <code>.bash</code>, <code>.zsh</code> a <code>.ksh</code> na Androidu bez root přístupu a bez chyb <code>Permission denied</code> ve sdíleném úložišti. Nabízí skutečnou synchronizaci <code>$PWD</code> projektové složky, <code>set -euo pipefail</code>, <code>getopts</code>, živý stdin pro <code>read -p</code>, propojování více skriptů i offline formátování.","table_caption":"SPOUŠTĚNÍ SHELL SKRIPTŮ .SH NA ANDROIDU: SROVNÁNÍ","th_0":"Požadavek na Shell","th_1":"SuperCode .sh Studio","th_2":"Běžné CLI ve sdíleném úložišti","th_3":"Skriptovací aplikace vyžadující root","th_4":"Prosté editory kódu","tr1_c0":"Vyžaduje root?","tr1_c1":"100% běh bez rootu","tr1_c2":"Selže s Permission denied","tr1_c3":"Vyžaduje odemčený/rootnutý OS","tr1_c4":"Nelze spustit","tr2_c0":"$PWD ve sdílené složce","tr2_c1":"Spouští a synchronizuje přímo ve složce projektu","tr2_c2":"Blokováno připojením noexec","tr2_c3":"Rizikový zápis do celého systému","tr2_c4":"Pouze úpravy","tr3_c0":"CLI přepínače a stdin","tr3_c1":"Direktiva # @args + živá konzole read -p","tr3_c2":"Ruční psaní příkazů","tr3_c3":"Na pozadí bez kontroly","tr3_c4":"Žádné","tr4_c0":"Víceskriptové projekty","tr4_c1":"source ./lib.sh + směrování main.sh","tr4_c2":"Ruční cd a cesty","tr4_c3":"Jeden skript","tr4_c4":"Žádné","tr5_c0":"Formátování skriptů","tr5_c1":"Offline formátovač Shellu na 1 klepnutí + AST","tr5_c2":"Pouze text v nano / vi","tr5_c3":"Žádné","tr5_c4":"Pouze zvýraznění syntaxe","faq_lead":"Časté dotazy ke spouštění `.sh` skriptů bez rootu a řešení chyby `Permission denied` na Androidu.","faq1_q":"Proč při spuštění souboru `.sh` ze Stažených souborů na Androidu dostávám `Permission denied`?","faq1_a":"Z bezpečnostních důvodů připojuje Android sdílené uživatelské úložiště (`/sdcard`, `Downloads`, `Documents`) s příznakem souborového systému `noexec`, takže soubory tam nelze označit jako spustitelné ani přes `chmod +x`. SuperCode spouští skripty čistě ve svém nativním runtime a automaticky synchronizuje složku projektu.","faq2_q":"Vyžaduje SuperCode ke spouštění shell skriptů rootnutý telefon s Androidem?","faq2_a":"Ne. SuperCode funguje ihned po instalaci na standardních, nerootnutých telefonech, skládacích zařízeních a tabletech s Androidem 8.0+.","faq3_q":"Jak předám argumenty příkazového řádku, například `./deploy.sh --env staging`?","faq3_a":"Přidejte `# @args --env staging` poblíž začátku skriptu (nebo zadejte vstup interaktivně přes `read -p`) a SuperCode při spuštění předá tyto poziční parametry (`$1`, `$2`, `$@`) přímo vašemu skriptu.","faq4_q":"Může skript `.sh` vytvářet nové soubory nebo složky uvnitř mého pracovního prostoru?","faq4_a":"Ano. Všechny soubory, protokoly nebo archivy vytvořené relativně k `$PWD` během běhu se automaticky synchronizují zpět do vašeho aktivního adresáře projektu v Androidu.","cta_h2":"Spouštějte skripty `.sh` na Androidu snadno &#8212; bez rootu.","cta_desc":"Získejte SuperCode IDE zdarma na Google Play &#8212; upravujte, formátujte a spouštějte shell skripty čistě kdekoli."},"sh_awk_sed_grep":{"metaTitle":"Linux awk, sed, grep a curl pro Android (+ Cloud GNU Bash 5.2) | SuperCode","metaDesc":"Spouštějte offline textové pipeline awk, sed, grep, sort, uniq, bc -l, curl, tar/gzip a sha256sum nad reálnými soubory na Androidu — plus plynulý Cloud Ubuntu GNU Bash 5.2 pro declare -A a jq.","hero_tag":"OFFLINE AWK &#183; SED &#183; GREP &#183; CURL &#183; BC -L &#183; CLOUD UBUNTU BASH 5.2","hero_h1":"Ovládněte <span class=\"text-gradient\"><code>awk</code>, <code>sed</code>, <code>grep</code> &amp; Bash 5.2</span> textové pipeline na Androidu.","hero_desc":"Proměňte surové serverové logy a neuspořádaná CSV v čisté metriky přímo v telefonu. Řetězte offline pipeline <strong><code>awk</code>, <code>sed</code>, <code>grep</code>, <code>sort</code>, <code>uniq</code>, <code>bc -l</code>, <code>tar</code> a <code>sha256sum</code></strong> synchronizované s vaší složkou &#8212; s automatickým <strong>Ubuntu GNU Bash 5.2</strong> pro <code>declare -A</code> a <code>jq</code>.","sas_s1":"&amp; grep -E offline","sas_s2":"Desetinná matika &amp; curl","sas_s3":"tar &#183; gzip &#183; base64","sas_s4":"declare -A &amp; jq","wb_eyebrow":"INTERAKTIVNÍ LINUXOVÝ WORKBENCH PRO TEXTOVÉ PIPELINE &amp; GNU BASH 5.2","sec_cap_title":"Klasická unixová síla pro práci s daty v dotykovém IDE","sec_cap_lead":"Proč psát 80 řádků zbytečného kódu, když pětiřádková pipeline `grep | sed | awk | sort` zpracuje log během milisekund?","f1_title":"Offline proudové enginy awk, sed &amp; grep / egrep","f1_desc":"Extrahujte zachytávací skupiny regexů pomocí sed -E, počítejte součty a průměry v awk a filtrujte strukturované logy přes grep -E, cut, tr, head, tail a column &#8212; 100% offline.","f1_badge":"awk &#183; sed -E &#183; grep -E &#183; cut &#183; tr &#183; column","f2_title":"Agregační roury &amp; přesná aritmetika bc -l","f2_desc":"Vytvářejte frekvenční histogramy pomocí sort -nr | uniq -c | wc -l, ukládejte mezivýsledky přes tee na disk a počítejte procenta či poměry latence v plovoucí řádové čárce offline přes bc -l.","f2_badge":"sort &#183; uniq -c &#183; wc &#183; tee &#183; bc -l matematika","f3_title":"Nástroje find, xargs, tar/gzip, curl &amp; kontrolní součty","f3_desc":"Dávkově zpracovávejte vnořené stromy pomocí find a xargs, komprimujte snímky přes tar a gzip, kódujte tokeny přes base64, ověřujte otisky pomocí sha256sum/md5sum a testujte endpointy přes curl.","f3_badge":"find &#183; xargs &#183; tar/gzip &#183; sha256sum &#183; curl","f4_title":"Automatický Cloud Ubuntu GNU Bash 5.2","f4_desc":"Používáte funkce GNU Bash 5 jako asociativní pole declare -A, regex shodu [[ $str =~ $pat ]], substituci procesů &lt;(...) nebo filtrování JSON přes jq? SuperCode je čistě přesměruje do Ubuntu Bash 5.2.","f4_badge":"Ubuntu GNU Bash 5.2 &#183; declare -A &#183; [[ =~ ]] &#183; jq","f5_title":"Přímé napojení na GB prohlížeč souborů &amp; SQL Studio","f5_desc":"Vyřízněte z obřího výpisu serveru pomocí awk/sed čistý soubor .csv, klepněte na něj v Průzkumníku a okamžitě ho importujte a dotazujte okenními funkcemi v SQL Studiu v SuperCode.","f5_badge":"Log -&gt; awk CSV -&gt; Offline SQL Studio Pipeline","f6_title":"Rozdělení tabletu 55:45 &amp; lišta symbolů pro roury","f6_desc":"Vkládejte |, &gt;, &gt;&gt;, 2&gt;&amp;1, $1 a jednoduché či dvojité uvozovky jedním klepnutím bez krkolomného psaní, zatímco široké tabulkové výpisy přehledně sledujete v režimu 55:45 na šířku.","f6_badge":"1 klepnutí | &amp;&amp; 2&gt;&amp;1 &#183; Zoom konzole 7sp&#8211;26sp","workflow_title":"Jak analyzovat logy a CSV pomocí Shell pipeline na Androidu","workflow_lead":"Opakovatelné skriptované zpracování dat uložené přímo vedle projektových souborů.","wf1_title":"Vložte surové soubory `.log`, `.csv` nebo `.json` do složky","wf1_desc":"Otevřete libovolnou složku projektu s výpisy logů či datasety &#8212; doprovodné soubory se automaticky připojí relativně k `$PWD`.","wf2_title":"Pište vícefázové roury s plným Undo a formátováním","wf2_desc":"Na rozdíl od křehkých jednořádkových příkazů v terminálu upravujte víceřádkové pipeline s `\\\\` v plnohodnotném editoru kódu se zvýrazněním syntaxe.","wf3_title":"Spouštějte lokálně offline nebo v GNU Bash 5.2","wf3_desc":"Standardní POSIX pipeline běží offline během milisekund, zatímco skripty s `declare -A` a `jq` plynule běží na Ubuntu Bash 5.2.","wf4_title":"Prohlížejte synchronizované reporty, archivy a součty","wf4_desc":"Každé přesměrované CSV, archiv `.tar.gz` nebo seznam kontrolních součtů se ihned objeví ve stromu souborů workspace.","wf_foot_note":"Offline POSIX nástroje + Cloud Ubuntu GNU Bash 5.2 &#183; Automatická synchronizace workspace","table_h2":"SuperCode Text Pipeline Studio vs. mobilní alternativy shellu","snippet_p":"<strong>SuperCode Linux Pipeline Studio</strong> přináší na Android offline skriptování v <code>awk</code>, <code>sed</code>, <code>grep</code>, <code>sort</code>, <code>uniq</code>, <code>cut</code>, <code>tr</code>, <code>bc -l</code>, <code>curl</code>, <code>tar</code>, <code>gzip</code> a <code>sha256sum</code> s automatickou synchronizací projektové složky a plynulým spouštěním asociativních polí a <code>jq</code> v Cloud Ubuntu GNU Bash 5.2.","table_caption":"SROVNÁNÍ ZPRACOVÁNÍ TEXTU V LINUXU &amp; BASH 5.2 NA ANDROIDU","th_0":"Možnosti pipeline","th_1":"SuperCode Shell Studio","th_2":"Základní shell Android OS","th_3":"Online Bash kompilátory","th_4":"Ruční CLI terminál","tr1_c0":"Offline awk / sed / grep","tr1_c1":"Plné spouštění se syncem workspace","tr1_c2":"Blokováno na sdíleném úložišti","tr1_c3":"Vyžaduje internet","tr1_c4":"Vyžaduje instalaci balíčků","tr2_c0":"Matematika, hashe &amp; archivy","tr2_c1":"bc -l, sha256sum, md5sum, base64, tar/gzip","tr2_c2":"Jen částečná sada","tr2_c3":"Dočasný kontejner","tr2_c4":"Podporováno","tr3_c0":"GNU Bash 5.2 (declare -A)","tr3_c1":"Auto-směrování do Ubuntu GNU Bash 5.2 + jq","tr3_c2":"Nepodporováno (mksh)","tr3_c3":"Jen jeden soubor","tr3_c4":"Ruční instalace","tr4_c0":"Úprava víceřádkových skriptů","tr4_c1":"Plný AST editor + 1-klepnutím Shell formátovač","tr4_c2":"Bez editoru","tr4_c3":"Základní webové pole","tr4_c4":"Drobný terminálový vi/nano","tr5_c0":"Navazující analytika","tr5_c1":"Vestavěný GB prohlížeč &amp; SQL Studio","tr5_c2":"Žádná","tr5_c3":"Žádná","tr5_c4":"Oddělené nástroje","faq_lead":"Odpovědi ohledně kompatibility `awk`, `sed`, `grep`, `bc -l`, `curl` a GNU Bash 5.2 na Androidu.","faq1_q":"Fungují `awk`, `sed`, `grep`, `sort` a `sha256sum` offline bez internetu?","faq1_a":"Ano! Standardní POSIX pipeline pro text, archivy a kontrolní součty (`awk`, `sed`, `grep`, `egrep`, `sort`, `uniq`, `wc`, `cut`, `tr`, `find`, `xargs`, `tar`, `gzip`, `base64`, `md5sum`, `sha256sum`, `bc -l`) běží lokálně offline na vašem zařízení.","faq2_q":"Proč asociativní pole `declare -A` selhávají ve výchozím shellu Androidu a jak je spouští SuperCode?","faq2_a":"Systémový shell Androidu vychází z POSIX/`mksh`, nikoli z GNU Bash 5. Když SuperCode rozpozná syntaxi Bash (`#!/usr/bin/env bash` s `declare -A`, `[[ =~ ]]`, `mapfile` nebo `jq`) či `# @cloud`, automaticky skript spustí na Ubuntu GNU Bash 5.2.","faq3_q":"Může můj skript `awk` nebo `sed` číst lokální soubor `.csv` a uložit nový soubor?","faq3_a":"Ano. Relativní vstupní cesty a přesměrování výstupu (`&gt; cleaned.csv` nebo `| tee out.txt`) pracují přímo s vaším workspace a nově zapsané soubory okamžitě synchronizují zpět do složky v Androidu.","faq4_q":"Co když má můj surový serverový log přes 1 GB?","faq4_a":"Otevřete vícegigabajtové logy přímo v diskově stránkovaném editoru velkých souborů SuperCode pro okamžité prohlížení bez sekání a globální proudové nahrazování regexem!","cta_h2":"Spouštějte reálné pipeline `awk`, `sed` &amp; Bash 5.2 na Androidu.","cta_desc":"Stáhněte si SuperCode IDE zdarma na Google Play &#8212; offline POSIX textové nástroje, Ubuntu Bash 5.2 a stránkování GB logů."},"sh_kotlin_ide":{"metaTitle":"Kotlin vývojářská appka & .kt / .kts kompilátor pro Android — OOP & DSA | SuperCode","metaDesc":"Pište, formátujte a kompilujte Kotlin (.kt a .kts) na telefonu či tabletu Android. Nabízí offline AST doplňování, 21klávesovou lištu -> / ?: / ?., formátovač na 1 klepnutí, víceřádkový stdin a rychlé spuštění.","hero_tag":"KOMPILÁTOR KOTLIN .KT &amp; .KTS &#183; OFFLINE AST &amp; FORMÁTOVAČ &#183; LIŠTA S 21 KLÁVESAMI","hero_h1":"Moderní <span class=\"text-gradient\">Kotlin editor &amp; <code>.kt</code> kompilátor</span> pro Android.","hero_desc":"Procvičujte idiomatické <strong>Kotlin OOP, modely <code>data class</code>, hierarchie <code>sealed interface</code> a DSA algoritmy k pohovorům</strong> bez tahání 16GB notebooku. Využijte <strong>offline Kotlin AST doplňování</strong>, <strong>formátovač na 1 klepnutí</strong>, <strong>rychlé klávesy <code>-&gt;</code> / <code>?:</code> / <code>?.</code></strong> a svižnou cloudovou kompilaci.","skt_s1":"Kotlin kompilátor","skt_s2":"21klávesová Kotlin lišta","skt_s3":"Offline formátovač","skt_s4":"Víceřádková DSA lišta","wb_eyebrow":"INTERAKTIVNÍ WORKBENCH PRO KOTLIN OOP, DSA KOLEKCE &amp; .KTS","sec_cap_title":"Navrženo pro Android vývojáře, studenty informatiky &amp; přípravu na Kotlin pohovory","sec_cap_lead":"Psaní expresivních null-safety a lambda operátorů Kotlinu na běžné mobilní klávesnici je pomalé &#8212; dotykový profil Kotlinu v SuperCode mění vše.","f1_title":"Čistá kompilace moderního Kotlinu (.kt &amp; .kts)","f1_desc":"Spouštějte samostatné programy s main() a skripty .kts využívající data class, value class, sealed interface, singletony object, rozšiřující funkce, generika, destrukturování a vyčerpávající větvení when.","f1_badge":"data class &#183; sealed interface &#183; Rozšiřující funkce","f2_title":"Funkcionální kolekce, sekvence &amp; lambdy","f2_desc":"Řešte úlohy s datovými strukturami idiomaticky pomocí mapNotNull, groupBy, associateBy, windowed, fold, líných builderů sequence { yield() } a odkazů na funkce ::.","f2_badge":"Kotlin kolekce &#183; Líné sequence {} &#183; :: odkazy","f3_title":"21klávesová Kotlin lišta (-&gt;, ?:, ?., ::, {})","f3_desc":"Vkládejte lambda šipky (-&gt;), Elvis operátory (?:), bezpečná volání (?.), reference metod (::), šablony řetězců (${}) a složené závorky jedním klepnutím v Kotlin profilu klávesnice SuperCode.","f3_badge":"-&gt; &#183; ?: &#183; ?. &#183; :: &#183; ${} &#183; Bez hledání znaků","f4_title":"Offline Kotlin AST našeptávač &amp; podpora .gradle.kts","f4_desc":"Upravujte soubory .kt, .kts a build.gradle.kts offline s AST doplňováním identifikátorů a standardní knihovny, doplněným ostrým zvýrazněním syntaxe v 8 tmavých i světlých motivech.","f4_badge":".kt &#183; .kts &#183; .gradle.kts &#183; Offline AST nápověda","f5_title":"Trvalá víceřádková stdin lišta pro Kotlin DSA","f5_desc":"Procvičujete LeetCode, Codeforces nebo technické pohovory v Kotlinu? Mějte víceřádkové vstupy pro readln() / readlnOrNull() připnuté ve stdin liště a rychle laďte hraniční případy.","f5_badge":"Připnutý víceřádkový readln() &#183; Skok 1:1 na chybu","f6_title":"Offline Kotlin formátovač na 1 klepnutí &amp; Git/PDF workflow","f6_desc":"Naformátujte třídy Kotlinu, řetězené lambdy kolekcí a Gradle DSL bloky 100% offline jedním klepnutím &#8212; pak pošlete DSA repozitář přes Visual Git nebo exportujte studijní poznámky do A4 PDF.","f6_badge":"Offline Kotlin formátovač &#183; Visual Git &#183; A4 PDF","workflow_title":"Jak procvičovat Kotlin &amp; řešit DSA úlohy na Androidu","workflow_lead":"Rychlá zpětná vazba úprava-formátování-kompilace navržená pro telefony, skládačky a tablety.","wf1_title":"Vytvořte soubor `.kt` nebo `.kts` ve svém workspace","wf1_desc":"Uspořádejte příklady k pohovorům či Kotlin experimenty do čistých složek &#8212; úpravy i formátování fungují 100% offline.","wf2_title":"Pište idiomatický null-safe a funkcionální kód","wf2_desc":"Používejte rychlé klávesy `-&gt;`, `?:`, `?.` a `::` spolu s offline AST doplňováním a pak klepněte na Formátovat pro čisté zarovnání lambd.","wf3_title":"Kompilujte a testujte s víceřádkovými vstupy `readln()`","wf3_desc":"Zadejte ukázkové testovací případy do trvalé stdin lišty a klepněte na Spustit &#9654; pro rychlou cloudovou kompilaci Kotlinu a diagnostiku 1:1.","wf4_title":"Commitujte na GitHub nebo porovnejte s offline Java 17","wf4_desc":"Odesílejte svá Kotlin řešení přes Visual Git nebo otestujte doprovodné JVM algoritmy zcela offline v Java 17 IDE v SuperCode.","wf_foot_note":"Podporuje .kt &#183; .kts &#183; .gradle.kts &#183; Offline AST &amp; formátovač + Cloud Kotlin Runner","table_h2":"SuperCode Kotlin aplikace vs. webové playgroundy &amp; desktopová IDE","snippet_p":"<strong>SuperCode Kotlin Coding Studio</strong> umožňuje vývojářům na Androidu a studentům psát, formátovat a kompilovat kód <code>.kt</code> a <code>.kts</code> na telefonech i tabletech. Spojuje offline Kotlin AST doplňování, speciální 21klávesovou lištu symbolů (<code>-&gt;</code>, <code>?:</code>, <code>?.</code>, <code>::</code>), offline formátování jedním klepnutím, trvalý víceřádkový <code>stdin</code> a Visual Git.","table_caption":"UČENÍ &amp; PROCVIČOVÁNÍ KOTLINU NA ANDROIDU: SROVNÁNÍ","th_0":"Kotlin workflow","th_1":"SuperCode Kotlin Studio","th_2":"Webový Kotlin Playground","th_3":"Obyčejné mobilní editory","th_4":"Desktopové Android Studio","tr1_c0":"Pohodlí psaní na mobilu","tr1_c1":"21klávesová lišta (-&gt; ?: ?. ::) + Offline AST","tr1_c2":"Stísněné pole v prohlížeči","tr1_c3":"Bez lišty symbolů Kotlinu","tr1_c4":"Fyzická klávesnice","tr2_c0":"Formátování kódu","tr2_c1":"100% offline 1-klepnutím Kotlin &amp; .gradle.kts","tr2_c2":"Pouze online","tr2_c3":"Žádné","tr2_c4":"Offline","tr3_c0":"Testování DSA přes stdin","tr3_c1":"Trvalá víceřádková stdin lišta pro readln()","tr3_c2":"Omezené / ruční argumenty","tr3_c3":"Nelze kompilovat","tr3_c4":"Podporováno","tr4_c0":"Lokální soubory &amp; Git","tr4_c1":"Plný strom projektu + Visual Git + A4 PDF","tr4_c2":"Dočasný jediný úryvek","tr4_c3":"Pouze lokální soubory","tr4_c4":"10 GB+ disku &amp; RAM","tr5_c0":"Doprovodné offline JVM","tr5_c1":"Obsahuje 100% offline Java 17 + SQLite","tr5_c2":"Pouze Kotlin úryvek","tr5_c3":"Žádné","tr5_c4":"Plné SDK","faq_lead":"Časté dotazy ohledně kompilace souborů `.kt` / `.kts`, offline úprav a sestavování APK.","faq1_q":"Vyžaduje kompilace Kotlinu v SuperCode připojení k internetu?","faq1_a":"Úpravy, zvýraznění syntaxe, AST našeptávač, formátování `.kt`/`.gradle.kts`, Visual Git i export do A4 PDF fungují 100% offline. Kompilace a spuštění kódu `.kt` a `.kts` využívá rychlý cloudový kompilátor Kotlinu SuperCode (zatímco Java 17 kompiluje 100% offline přímo v zařízení).","faq2_q":"Mohu v Kotlinu předat víceřádkový testovací vstup do `readln()` nebo `Scanner`?","faq2_a":"Ano! Napište nebo vložte víceřádkové testovací vstupy do trvalé vstupní lišty `stdin` v konzoli ještě před klepnutím na Spustit &#8212; soutěžní programování i příprava na pohovory jsou tak hračkou.","faq3_q":"Umí SuperCode sestavit celé vícemodulové Gradle Android `.apk` balíčky?","faq3_a":"SuperCode je navrženo pro samostatné programování v Kotlinu (`.kt`/`.kts`), OOP modelování, funkcionální pipeline, procvičování DSA a správu souborů `.gradle.kts` přes Git &#8212; nikoli pro mnohagigabajtové balení `.apk` pomocí Android SDK.","faq4_q":"Mohu formátovat soubory `build.gradle.kts` offline?","faq4_a":"Ano. Zdrojové soubory `.kt`/`.kts` i skripty Gradle Kotlin DSL `.gradle.kts` jsou plně podporovány offline zvýrazňovačem syntaxe i formátovačem kódu na jedno klepnutí v SuperCode.","cta_h2":"Procvičujte moderní Kotlin kdekoli na Androidu.","cta_desc":"Nainstalujte si SuperCode IDE zdarma z Google Play &#8212; spouštěč Kotlin .kt/.kts, 21klávesová lišta symbolů, offline formátovač a Visual Git."},"sh_devops_sftp":{"metaTitle":"Linux DevOps appka pro Android — .sh skripty, SFTP (0755), GB logy & Git | SuperCode","metaDesc":"Zvládejte pohotovostní úkoly Linux sysadmina a DevOps přímo z Androidu. Testujte .sh pipeline lokálně, prohlížejte vícegigabajtové logy, commitujte přes Visual Git a upravujte vzdálené skripty přes SFTP se zachováním POSIX práv 0755.","hero_tag":"POHOTOVOSTNÍ LINUX DEVOPS &#183; SFTP 0755 ATOMICKÉ ULOŽENÍ &#183; GB PROHLÍŽEČ LOGŮ &#183; VISUAL GIT","hero_h1":"Kapesní <span class=\"text-gradient\">pracovní stanice Linux DevOps</span>: Shell, SFTP, GB logy &amp; Git.","hero_desc":"Přestaňte během incidentů přepínat mezi čtyřmi oddělenými mobilními aplikacemi. Otestujte <strong><code>.sh</code> skripty</strong> lokálně nanečisto, prohlížejte <strong>vícegigabajtové produkční logy</strong> bez sekání, commitujte IaC opravy ve <strong>Visual Gitu</strong> a ukládejte přes <strong>SFTP</strong> pomocí <strong>3fázového atomického zápisu se zachováním POSIX práv <code>0755</code></strong>.","sdo_s1":"POSIX práva zachována","sdo_s2":"SSH Keystore SFTP","sdo_s3":"Stránkovaný prohlížeč logů","sdo_s4":"Vizuální Diff &amp; Push","wb_eyebrow":"INTEGROVANÝ WORKBENCH PRO LINUX SYSADMINY, SFTP &amp; GB LOGY","sec_cap_title":"Vytvořeno pro SRE, sysadminy &amp; stavitele vlastních homelabů","sec_cap_lead":"Každý detail je odolný vůči nestabilní mobilní síti, obřím výpisům logů a nechtěnému poškození oprávnění na vzdálených linuxových serverech.","f1_title":"3fázové atomické ukládání přes SFTP se zachováním POSIX 0755","f1_desc":"Uložení živého /usr/local/bin/backup.sh přes kolísající mobilní data váš skript nezkrátí ani mu neodstraní příznak +x. SuperCode zapíše do přípravného souboru, ověří integritu, atomicky přejmenuje a zachová přesná práva 0755/0644.","f1_badge":"Žádné napůl zapsané konfigurace &#183; POSIX 0755 zachováno","f2_title":"Hardwarově chráněný trezor SSH klíčů &amp; hostitelů s AES-256","f2_desc":"Připojujte se k serverům Ubuntu, Debian, Rocky či Alpine přes SFTP, FTPS a FTP pomocí soukromých klíčů Ed25519/RSA šifrovaných přes Android Keystore AES-256, včetně souběžných přenosů a navazování.","f2_badge":"Klíče Ed25519 / RSA &#183; Keystore AES-256 &#183; Navazování","f3_title":"Test nanečisto pro .sh &amp; awk/sed před nasazením","f3_desc":"Nikdy nezkoušejte neověřené regexy na produkci! Ověřte svou logiku .sh, awk, sed, grep a set -euo pipefail lokálně na Androidu (nebo v Ubuntu GNU Bash 5.2), než ji uložíte zpět na server.","f3_badge":"Lokální sandboxový test &#183; Ověření v Bash 5.2","f4_title":"Vícegigabajtový prohlížeč serverových logů &amp; proudová anonymizace regexem","f4_desc":"Stáhněte si 2GB výpis z Nginxu, Dockeru nebo systemd journalu a listujte diskově stránkovanými bloky ve 120 Hz bez špiček paměti &#8212; nebo spusťte globální proudové nahrazení regexem pro skrytí tajných údajů v celém souboru.","f4_badge":"Okamžité stránkování GB+ &#183; Proudový regex $1 &#183; 34 znakových sad","f5_title":"Formátování YAML, JSON, Dockerfile, Makefile &amp; Nginx","f5_desc":"Upravujte docker-compose.yml, manifesty Kubernetes, playbooky Ansible, Dockerfiles, Makefiles, TOML a soubory .env se zvýrazněním syntaxe, Radarem chyb a offline formátováním na 1 klepnutí.","f5_badge":"YAML &#183; JSON &#183; Dockerfile &#183; Makefile &#183; .conf","f6_title":"Visual Git pro repozitáře Infrastructure-as-Code","f6_desc":"Udržujte GitOps čisté i z telefonu: prohlížejte barevné unifikované diffy řádek po řádku, připravujte hunky, řešte konflikty sloučení vedle sebe a posílejte podepsané HTTPS/token commity na GitHub, GitLab či Gitea.","f6_badge":"Barevný unifikovaný Diff &#183; Větvení &#183; Řešení konfliktů","workflow_title":"Workflow pro pohotovostní incidenty a úpravy konfigurací na Androidu","workflow_lead":"Diagnostikujte, otestujte nanečisto, atomicky nasaďte a commitněte do Gitu bez otevírání čtyř různých aplikací.","wf1_title":"Připojte se SSH klíčem a prozkoumejte produkční logy","wf1_desc":"Otevřete linuxový server v SFTP Průzkumníku a prohlížejte obří soubory `.log` v diskově stránkovaném GB prohlížeči nebo vyfiltrujte výřezy pomocí `grep`/`awk`.","wf2_title":"Upravte shellové hooky, Docker Compose nebo Nginx konfigurace","wf2_desc":"Upravujte soubory `.sh`, `.yml` či `.conf` s offline formátováním a před nahráním lokálně otestujte logiku shellové pipeline.","wf3_title":"Publikujte bezpečně přes SFTP se zachovaným 0755","wf3_desc":"Uložte přímo zpět na vzdálený hostitel &#8212; atomické ukládání zabrání částečnému zápisu a zachová spustitelná oprávnění `0755`.","wf4_title":"Commitněte změny infrastruktury do Git repozitáře","wf4_desc":"Zkontrolujte přesný unifikovaný diff ve Visual Gitu a odešlete svůj hotfix commit, aby produkce a správa verzí zůstaly v souladu.","wf_foot_note":"40,2 MB vše-v-jednom APK &#183; SFTP + FTPS + Visual Git + Shell + GB prohlížeč logů","table_h2":"SuperCode DevOps stanice vs. roztříštěné sysadmin aplikace","snippet_p":"<strong>SuperCode Linux DevOps Workstation</strong> sjednocuje lokální testování skriptů <code>.sh</code>, stránkování vícegigabajtových serverových logů, správu verzí Visual Git a vzdálené úpravy přes SFTP v jediné Android aplikaci. Sysadmini získají SSH ověřování chráněné Android Keystore AES-256, třífázové atomické vzdálené ukládání se zachováním POSIX spustitelných oprávnění <code>0755</code> a offline formátování YAML/Shellu.","table_caption":"SROVNÁNÍ MOBILNÍCH NÁSTROJŮ PRO LINUX DEVOPS &amp; SYSADMINY","th_0":"DevOps úkol","th_1":"SuperCode vše-v-jednom IDE","th_2":"Základní SFTP správci souborů","th_3":"Pouze SSH terminál","th_4":"Roztříštěná sada 4 aplikací","tr1_c0":"Bezpečnost vzdáleného uložení","tr1_c1":"3fázové atomické přejmenování + zachová POSIX 0755","tr1_c2":"Přímý přepis (při výpadku ořízne soubor)","tr1_c3":"Ruční vim swp","tr1_c4":"Ruční export/import","tr2_c0":"Test .sh před nasazením","tr2_c1":"Lokální non-root .sh + Cloud Bash 5.2 nanečisto","tr2_c2":"Skripty nelze spouštět","tr2_c3":"Běží živě na produkci!","tr2_c4":"Nepohodlné kopírování","tr3_c0":"Obří produkční logy 1 GB+","tr3_c1":"Okamžitý diskově stránkovaný prohlížeč + proudový regex","tr3_c2":"Zamrzne / spadne aplikace","tr3_c3":"Pomalé na mobilních datech","tr3_c4":"Selhává nad 50 MB","tr4_c0":"Úpravy IaC konfigurací","tr4_c1":"Offline formátování Shell, YAML, JSON &amp; Dockerfile","tr4_c2":"Obyčejné textové pole","tr4_c3":"Drobný terminálový nano","tr4_c4":"Nekonzistentní UI","tr5_c0":"Správa verzí GitOps","tr5_c1":"Vestavěný Visual Git Diff, Merge &amp; Push","tr5_c2":"Žádná","tr5_c3":"Pouze CLI git","tr5_c4":"Samostatný Git klient","faq_lead":"Dotazy linuxových sysadminů, SRE a homelab inženýrů používajících SuperCode na Androidu.","faq1_q":"Odebere úprava vzdáleného skriptu `.sh` přes SFTP jeho spustitelný bit `chmod 0755`?","faq1_a":"Nikdy. SuperCode před uložením zkontroluje stávající POSIX režim vzdáleného souboru a zachová `0755` (nebo vlastní oprávnění) v průběhu celého 3fázového atomického přejmenování.","faq2_q":"Jak SuperCode chrání mé soukromé SSH klíče a hesla k SFTP?","faq2_a":"Všechny přihlašovací údaje SFTP/FTPS, profily serverů i importované soukromé SSH klíče (`Ed25519`, `RSA`, `ECDSA`) jsou v zařízení šifrovány pomocí hardwarové ochrany Android Keystore AES-256.","faq3_q":"Co se stane, když mi vypadne mobilní signál uprostřed ukládání `nginx.conf`?","faq3_a":"Protože SuperCode nejprve nahrává do dočasného přípravného souboru a atomické přejmenování na straně serveru provede až po úspěšném ověření přenosu, váš živý `nginx.conf` nikdy nezůstane napůl zapsaný nebo prázdný.","faq4_q":"Mohu si prohlédnout 1,5GB serverový log stažený přes SFTP bez pádu telefonu?","faq4_a":"Ano! Editor velkých souborů v SuperCode připojuje vícegigabajtové soubory v diskově stránkovaných blocích místo načítání celého souboru do RAM, a to včetně globálního proudového nahrazování regexem.","cta_h2":"Noste kompletní Linux DevOps studio v kapse.","cta_desc":"Stáhněte si SuperCode IDE zdarma na Google Play &#8212; atomické ukládání SFTP, lokální .sh pipeline, stránkování GB logů a Visual Git."}};
